INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jwilger/eventcore/code-review', 'community', 'jwilger', 'eventcore', 'jwilger/eventcore', 'code-review', 11, 1, 41, '2026-02-22T06:17:26Z', '2026-03-06T06:45:46.501Z', '8241c29e1331983558c9273ecade261523f17cbc62a1c01d2fa3356d442abaa9', '{"id":"jwilger/eventcore/code-review","name":"code-review","description":{"en":"The code-review skill provides a systematic three-stage code review process for Rust, evaluating spec compliance, code quality, and domain integrity to ensure thorough feedback and communication.","zh":"代码审查是一种系统化的三阶段审查过程，评估代码的规格合规、代码质量和领域完整性","ja":"コードレビューは、コードの仕様の準拠、コードの品質、ドメインの完全性を評価する3ステージのシステム化されたプロセス","ko":"코드 리뷰는 코드의 사양 준수, 코드 품질, 도메인 완전성을 평가하는 3단계의 체계적인 과정","es":"Code-review es una habilidad que agrega retroalimentación y comunicación estructurada para Rust","fr":"Code-review est une compétence qui ajoute une rétroaction et une communication structurées pour Rust","de":"Code-Review ist eine Fähigkeit, die strukturiertes Feedback und Kommunikation für Rust hinzufügt","pt":"A revisão de código é uma ferramenta essencial para desenvolvedores, permitindo a detecção de defeitos e a melhoria da qualidade do código.","ru":"Обзор кода - это необходимый инструмент для разработчиков, позволяющий обнаруживать дефекты и улучшать качество кода.","ar":"أداة المراجعة اللّامسبقة للكود هي أداة أساسية للمطورين، تمكن من الكشف عن العيوب وتحسين جودة الكود"},"seo":{"title":{"en":"Code-Review: Structured Three-Stage Code Evaluation for A...","zh":"代码审查最佳实践：三阶段审查指南","ja":"コードレビューのための3ステージアプローチ","ko":"코드 리뷰 가이드: 3단계 체계적 접근","es":"Guía de configuración de code-review para Rust","fr":"Mise en place de code-review pour Rust","de":"Code-Review-Setup-Leitfaden für Rust","pt":"Guia de Configuração de Revisão de Código para Desenvolve...","ru":"Настройка ИИ Агентов для Обзора Код: Руководство","ar":"دليل إعداد أداة المراجعة اللّامسبقة للكو"},"description":{"en":"Discover how code-review''s multi-stage event-sourcing approach streamlines Rust development - learn to implement it now and improve your code quality!","zh":"学习代码审查的三阶段方法，确保代码质量、规格合规和领域完整性","ja":"コードレビューの3ステージアプローチで、コードの品質、仕様の準拠、ドメインの完全性を確保","ko":"코드 리뷰의 3단계 접근법으로 코드 품질, 사양 준수, 도메인 완전성을 보장","es":"Aprende a implementar code-review en Rust con nuestra guía paso a paso","fr":"Découvrez comment mettre en place code-review pour Rust avec notre guide","de":"Erfahren Sie, wie Sie Code-Review in Rust mit unserem Schritt-für-Schritt-Leitfaden implementieren","pt":"Aprenda a configurar a revisão de código para capturar defeitos e melhorar a qualidade do código com nossa ferramenta de revisão de código","ru":"Узнайте, как настроить обзор кода для поиска дефектов и улучшения качества кода с помощью нашего ИИ Агента","ar":"تعلم كيفية إعداد أداة المراجعة اللّامسبقة للكود لاكتشاف العيوب وتحسين جودة الكود"},"definition":{"en":"Code-review is a systematic approach to evaluating code quality, spec compliance, and domain integrity through a structured three-stage review process.","zh":"代码审查是指对代码进行系统化的审查和评估，以确保其质量和完整性","ja":"コードレビューは、コードの品質と完全性を確保するために行われるシステム化されたレビューと評価","ko":"코드 리뷰는 코드의 품질과 완전성을 보장하기 위한 체계적인 검토와 평가","es":"Code-review es una técnica de revisión de código que evalúa la conformidad con las especificaciones, la calidad del código y la integridad del dominio","fr":"Code-review est une technique de révision de code qui évalue la conformité aux spécifications, la qualité du code et l''intégrité du domaine","de":"Code-Review ist eine Technik der Code-Überprüfung, die die Konformität mit den Spezifikationen, die Code-Qualität und die Domänenintegrität bewertet","pt":"Revisão de código é o processo de examinar o código-fonte para detectar defeitos e melhorar a qualidade","ru":"Обзор кода - это процесс проверки исходного кода для обнаружения дефектов и улучшения качества","ar":"أداة المراجعة اللّامسبقة للكود هي عملية فحص الكود المصدري لاكتشاف العيوب وتحسين الجودة"},"features":{"en":["Evaluates spec compliance to ensure adherence to standards","Assesses code quality through a separate review stage","Examines domain integrity to prevent issues from slipping through","Utilizes a multi-stream event-sourcing approach for Rust development","Prevents combined reviews from compromising thoroughness","Enables focused attention on each review dimension"],"zh":["三阶段审查过程","规格合规评估","代码质量评估","领域完整性评估","Aggregateless和Multi-Stream Event-Sourcing支持"],"ja":["3ステージのレビュープロセス","仕様の準拠評価","コードの品質評価","ドメインの完全性評価","AggregatelessとMulti-Stream Event-Sourcingのサポート"],"ko":["3단계 리뷰 프로세스","사양 준수 평가","코드 품질 평가","도메인 완전성 평가","Aggregateless와 Multi-Stream Event-Sourcing 지원"],"es":["Revisión de código en tres etapas","Evaluación de la conformidad con las especificaciones","Análisis de la calidad del código","Verificación de la integridad del dominio","Implementación de Aggregateless y Multi-Stream Event-Sourcing para Rust"],"fr":["Révision de code en trois étapes","Évaluation de la conformité aux spécifications","Analyse de la qualité du code","Vérification de l''intégrité du domaine","Mise en œuvre d''Aggregateless et de Multi-Stream Event-Sourcing pour Rust"],"de":["Code-Überprüfung in drei Stufen","Bewertung der Konformität mit den Spezifikationen","Analyse der Code-Qualität","Überprüfung der Domänenintegrität","Implementierung von Aggregateless und Multi-Stream Event-Sourcing für Rust"],"pt":["Três etapas de revisão de código: especificação, qualidade do código e integridade de domínio","Prevenção de revisões combinadas para evitar que problemas sejam ignorados","Ferramenta de revisão de código para Rust","Suporte a Multi-Stream Event-Sourcing","Desenvolvimento experimental de Aggregateless"],"ru":["Три этапа обзора кода: спецификация, качество кода и целостность домена","Предотвращение объединенных обзоров для избежания пропуска проблем","Инструмент обзора кода для Rust","Поддержка Multi-Stream Event-Sourcing","Экспериментальное развитие Aggregateless"],"ar":["ثلاث مراحل لمراجعة الكود: المواصفات، جودة الكود، وسلامة المجال","منع المراجعات المدمجة لتجنب تجاهل المشاكل","أداة مراجعة الكود للغة روست","دعم Multi-Stream Event-Sourcing","التطوير التجريبي ل Aggregateless"]},"keywords":{"en":["how to use code-review in Rust","what is code-review in software development","code-review alternative for aggregateless event-sourcing","code-review vs traditional code evaluation methods","code-review install guide for AI agents","code-review setup for multi-stage code review","code-review best practices for Rust development","code-review tutorial for systematic three-stage review"],"zh":["代码审查","三阶段审查","代码质量","规格合规","领域完整性","Aggregateless","Multi-Stream Event-Sourcing","Rust","AIエージェント"],"ja":["コードレビュー","3ステージのレビュー","コードの品質","仕様の準拠","ドメインの完全性","Aggregateless","Multi-Stream Event-Sourcing","Rust","AIエージェント"],"ko":["코드 리뷰","3단계 리뷰","코드 품질","사양 준수","도메인 완전성","Aggregateless","Multi-Stream Event-Sourcing","Rust","AIツール"],"es":["code-review para Rust","revisión de código en Rust","Aggregateless","Multi-Stream Event-Sourcing","desarrollo de software en Rust","herramientas de code-review para Rust","mejora de la calidad del código en Rust"],"fr":["code-review pour Rust","révision de code pour Rust","Aggregateless","Multi-Stream Event-Sourcing","développement de logiciels en Rust","outils de code-review pour Rust","amélioration de la qualité du code en Rust"],"de":["Code-Review für Rust","Code-Überprüfung für Rust","Aggregateless","Multi-Stream Event-Sourcing","Software-Entwicklung in Rust","Code-Review-Tools für Rust","Verbesserung der Code-Qualität in Rust"],"pt":["revisão de código","desenvolvimento de software","qualidade do código","Rust","Multi-Stream Event-Sourcing","Aggregateless","ferramentas de revisão de código","melhoria da qualidade do código","desenvolvimento experimental"],"ru":["обзор кода","разработка программного обеспечения","качество кода","Rust","Multi-Stream Event-Sourcing","Aggregateless","инструменты обзора кода","улучшение качества кода","экспериментальное развитие"],"ar":["مراجعة الكود","تطوير البرمجيات","جودة الكود","روست","Multi-Stream Event-Sourcing","Aggregateless","أدوات مراجعة الكود","تحسين جودة الكود","التطوير التجريبي"]}},"owner":"jwilger","repo":"eventcore","repoPath":"jwilger/eventcore","stars":11,"forks":1,"updatedAt":"2026-02-22T06:17:26Z","topics":[],"category":"community","skillMd":{"name":"code-review","description":">-","version":"1.0","bodyPreview":"# Code Review\n\n**Value:** Feedback and communication -- structured review catches defects that\nthe author cannot see, and separating review into stages prevents thoroughness\nin one area from crowding out another.\n\n## Purpose\n\nTeaches a systematic three-stage code review that evaluates spec compliance,\ncode quality, and domain integrity as separate passes. Prevents combined\nreviews from letting issues slip through by ensuring each dimension gets\nfocused attention.\n\n## Practices\n\n### Three Stages,","body":"# Code Review\n\n**Value:** Feedback and communication -- structured review catches defects that\nthe author cannot see, and separating review into stages prevents thoroughness\nin one area from crowding out another.\n\n## Purpose\n\nTeaches a systematic three-stage code review that evaluates spec compliance,\ncode quality, and domain integrity as separate passes. Prevents combined\nreviews from letting issues slip through by ensuring each dimension gets\nfocused attention.\n\n## Practices\n\n### Three Stages, In Order\n\nReview code in three sequential stages. Do not combine them. Each stage has a\nsingle focus. A failure in an earlier stage blocks later stages -- there is no\npoint reviewing code quality on code that does not meet the spec.\n\n**Stage 1: Spec Compliance.** Does the code do what was asked? Not more, not\nless.\n\nFor each acceptance criterion or requirement:\n\n1. Find the code that implements it\n2. Find the test that verifies it\n3. Confirm the implementation matches the spec exactly\n\nMark each criterion: PASS, FAIL (missing/incomplete/divergent), or CONCERN\n(implemented but potentially incorrect). Flag anything built beyond\nrequirements as OVER-BUILT.\n\nIf any criterion is FAIL, stop. Return to implementation before continuing.\n\n### Vertical Slice Layer Coverage\n\nFor tasks that implement a vertical slice (adding user-observable behavior), perform the following checks in order:\n\n1. **Entry-point wiring check (diff-based):** Examine whether the changeset includes modifications to the application''s entry point or its wiring/routing layer. If the slice claims to add new user-observable behavior but the diff does not touch any wiring or entry-point code, the review **fails** unless the author explicitly documents why existing wiring already routes to the new behavior.\n\n2. **End-to-end traceability:** Verify that a path can be traced from the application''s external entry point, through any infrastructure or integration layer, to the new domain logic, and back to observable output. If any segment of this path is missing from the changeset and not already present in the codebase, flag the gap.\n\n3. **Boundary-level test coverage:** Confirm that at least one test exercises the new behavior through the application''s external boundary (e.g., an HTTP request, a CLI invocation, a message on a queue) rather than calling internal functions directly. Where the application architecture makes automated boundary tests feasible, their absence is a review concern.\n\n4. **Test-level smell check:** If every test in the changeset is a unit test of isolated internal functions with no integration or acceptance-level test, flag this as a concern. The slice may be implementing domain logic without proving it is reachable through the running application.\n\n**Stage 2: Code Quality.** Is the code clear, maintainable, and well-tested?\n\nReview each changed file for:\n\n- **Clarity:** Can you understand what the code does without extra context?\n  Are names descriptive? Is the structure obvious?\n- **Domain types:** Are semantic types used where primitives appear? You MUST follow\n  the `domain-modeling` skill for primitive obsession detection.\n- **Error handling:** Are errors handled with typed errors? Are all paths\n  covered?\n- **Test quality:** Do tests verify behavior, not implementation? Is coverage\n  adequate for the changed code?\n- **YAGNI:** Is there unused code, speculative features, or premature\n  abstraction?\n\nCategorize findings by severity:\n\n- CRITICAL: Bug risk, likely to cause defects\n- IMPORTANT: Maintainability concern, should fix before merge\n- SUGGESTION: Style or minor improvement, optional\n\nIf any CRITICAL issue exists, stop. Return to implementation.\n\n**Stage 3: Domain Integrity.** Final gate -- does the code respect domain\nboundaries?\n\nCheck for:\n\n1. **Compile-time enforcement opportunities:** Are tests checking things the\n   type system could enforce instead?\n2. **Domain type consistency:** Are semantic types used at all boundaries, or\n   do primitives leak through?\n3. **Validation placement:** Is validation at construction (parse-don''t-validate),\n   not scattered through business logic?\n4. **State representation:** Can the types represent invalid states?\n\nFlag issues but do not block on suggestions. Domain integrity flags are\nstrongly recommended but not required for merge.\n\n### Review Output\n\nProduce a structured summary after all three stages:\n\n```\nREVIEW SUMMARY\nStage 1 (Spec Compliance): PASS/FAIL\nStage 2 (Code Quality): PASS/FAIL/PASS with suggestions\nStage 3 (Domain Integrity): PASS/FAIL/PASS with flags\n\nOverall: APPROVED / CHANGES REQUIRED\n\nIf CHANGES REQUIRED:\n  1. [specific required change]\n  2. [specific required change]\n```\n\n### Handling Disagreements\n\nWhen your review finding conflicts with the implementation approach:\n\n1. State the concern with specific code references\n2. Explain the risk -- what could go wrong\n3. Propose an alternative\n4. If no agreement after one round, escalate to the user\n\nYou exist to catch what the author missed, not to block progress.\n\n### Business Value and UX Awareness\n\nDuring Stage 1, also consider:\n\n- Does this slice deliver visible user value?\n- Are acceptance criteria specific and testable (not vague)?\n- Does the user journey remain coherent after this change?\n- Are edge cases and error states handled from the user''s perspective?\n\nThese are not blocking concerns but should be noted when relevant.\n\n## Enforcement Note\n\nThis skill provides advisory guidance. It instructs the agent on correct\nreview procedure but cannot mechanically prevent skipping stages or merging\nwithout review. When used with the `tdd` skill in automated mode, the\norchestrator can gate PR creation on review completion. In guided mode or\nstandalone, the agent follows these practices by convention. If you observe\nstages being skipped, point it out.\n\n## Verification\n\nAfter completing a review guided by this skill, verify:\n\n- [ ] All three stages were performed separately, in order\n- [ ] Every acceptance criterion was mapped to code and tests in Stage 1\n- [ ] Each changed file was assessed for clarity and domain type usage in Stage 2\n- [ ] Domain integrity was checked for compile-time enforcement opportunities in Stage 3\n- [ ] A structured summary was produced with clear PASS/FAIL per stage\n- [ ] Any CHANGES REQUIRED items list specific, actionable fixes\n\nIf any criterion is not met, revisit the relevant stage before finalizing.\n\n## Dependencies\n\nThis skill works standalone. For enhanced workflows, it integrates with:\n\n- **domain-modeling:** Provides the primitive obsession and parse-don''t-validate\n  principles referenced in Stage 2 and Stage 3\n- **tdd:** Reviews often follow a TDD cycle; this skill validates the\n  output of that cycle\n- **mutation-testing:** Can follow code review as an additional quality gate\n\nMissing a dependency? Install with:\n\n```\nnpx skills add jwilger/agent-skills --skill domain-modeling\n```\n"},"lastSynced":"2026-03-06T06:45:46.501Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing systematic three-stage code review processes for Rust","zh":"非常适合需要系统化三个阶段代码审查流程的Rust代码分析代理","ja":"Rustのコード分析エージェントが体系的な3段階のコードレビュー処理を必要とする場合に最適","ko":"Rust 코드 분석 에이전트가 체계적인 3단계 코드 리뷰 프로세스를 필요로 할 때 적합","es":"Perfecto para agentes de análisis de código que necesitan procesos de revisión de código sistemáticos de tres etapas para Rust","fr":"Parfait pour les agents d''analyse de code nécessitant des processus de révision de code systématiques en trois étapes pour Rust","de":"Perfekt für Code-Analyse-Agents, die systematische dreistufige Code-Review-Prozesse für Rust benötigen","pt":"Perfeito para Agentes de Análise de Código que precisam de processos de revisão de código sistemáticos em três etapas para Rust","ru":"Идеально подходит для Агентов Анализа Кодов, которым необходимы систематические трехэтапные процессы проверки кода для Rust","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى عمليات مراجعة شفرة من ثلاث مراحل للرست"},"recommendation":{"en":"Empowers agents to evaluate spec compliance, code quality, and domain integrity as separate passes, ensuring thorough feedback and communication through structured review, and preventing combined reviews from letting issues slip through by utilizing Rust-specific analysis","zh":"赋予代理评估规范合规性、代码质量和域完整性作为独立的通行证，确保通过结构化审查提供彻底的反馈和沟通，并通过利用Rust特定的分析防止组合审查让问题泄露","ja":"エージェントが規格の準拠、コード品質、ドメインの完全性を個別のパスとして評価できるようにし、構造化されたレビューを通じて徹底的なフィードバックとコミュニケーションを提供し、Rust特有の分析を利用して複合レビューが問題をすり抜けるのを防ぐ","ko":"에이전트가 규격 준수, 코드 품질 및 도메인 무결성을 별도의 통과로 평가할 수 있도록 하여 구조화된 리뷰를 통해 철저한 피드백 및 의사소통을 제공하며 Rust 특정 분석을 사용하여 결합 리뷰에서 문제가 누락되는 것을 방지","es":"Habilita a los agentes a evaluar la conformidad de especificaciones, la calidad del código y la integridad del dominio como pasos separados, garantizando una retroalimentación y comunicación exhaustivas a través de una revisión estructurada, y evitando que las revisiones combinadas permitan que los problemas pasen desapercibidos mediante el análisis específico de Rust","fr":"Permet aux agents d''évaluer la conformité des spécifications, la qualité du code et l''intégrité du domaine comme des passes distinctes, garantissant une rétroaction et une communication exhaustives via une revue structurée, et empêchant les revues combinées de laisser passer les problèmes en utilisant l''analyse spécifique de Rust","de":"Ermächtigt Agenten, die Spezifikationskonformität, Code-Qualität und Domänenintegrität als separate Schritte zu bewerten, um umfassende Rückmeldungen und Kommunikation durch strukturierte Überprüfung sicherzustellen und zu verhindern, dass kombinierte Überprüfungen Probleme durch das spezifische Rust-Analysis übersehen","pt":"Habilita os agentes a avaliar a conformidade com as especificações, a qualidade do código e a integridade do domínio como passos separados, garantindo feedback e comunicação abrangentes por meio de revisão estruturada e evitando revisões combinadas que deixem problemas passarem despercebidos ao utilizar análise específica do Rust","ru":"Наделяет агентов возможностью оценивать соответствие спецификациям, качество кода и целостность домена как отдельные проходы, обеспечивая тщательную обратную связь и коммуникацию посредством структурированного обзора и предотвращая объединенные обзоры, которые позволяют проблемам остаться незамеченными за счет использования анализа, специфичного для Rust","ar":"يمنح العميل القدرة على تقييم متطلبات المواصفة و جودة الشفرة و سلامة المجال كمراحل منفصلة، مما يضمن تعليقات شاملة و اتصال من خلال المراجعة المنظمة و منع المراجعات المدمجة من تمرير المشاكل دون أن يلاحظها باستخدام تحليل محدد للرست"},"useCases":{"en":["Evaluating Rust code spec compliance","Analyzing code quality and domain integrity","Providing structured feedback through three-stage review"],"zh":["评估Rust代码规格合规性","分析代码质量和域完整性","通过三