INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jwilger/eventcore/code-review', 'code-review', 'jwilger', 'eventcore', 'community', 'code-review jwilger eventcore community The code-review skill provides a systematic three-stage code review process for Rust, evaluating spec compliance, code quality, and domain integrity to ensure thorough feedback and communication. 代码审查是一种系统化的三阶段审查过程，评估代码的规格合规、代码质量和领域完整性 コードレビューは、コードの仕様の準拠、コードの品質、ドメインの完全性を評価する3ステージのシステム化されたプロセス 코드 리뷰는 코드의 사양 준수, 코드 품질, 도메인 완전성을 평가하는 3단계의 체계적인 과정 Code-review es una habilidad que agrega retroalimentación y comunicación estructurada para Rust Code-review est une compétence qui ajoute une rétroaction et une communication structurées pour Rust Code-Review ist eine Fähigkeit, die strukturiertes Feedback und Kommunikation für Rust hinzufügt A revisão de código é uma ferramenta essencial para desenvolvedores, permitindo a detecção de defeitos e a melhoria da qualidade do código. Обзор кода - это необходимый инструмент для разработчиков, позволяющий обнаруживать дефекты и улучшать качество кода. أداة المراجعة اللّامسبقة للكود هي أداة أساسية للمطورين، تمكن من الكشف عن العيوب وتحسين جودة الكود how to use code-review in Rust what is code-review in software development code-review alternative for aggregateless event-sourcing code-review vs traditional code evaluation methods code-review install guide for AI agents code-review setup for multi-stage code review code-review best practices for Rust development code-review tutorial for systematic three-stage review 代码审查 三阶段审查 代码质量 规格合规 领域完整性 Aggregateless Multi-Stream Event-Sourcing Rust AIエージェント Evaluates spec compliance to ensure adherence to standards Assesses code quality through a separate review stage Examines domain integrity to prevent issues from slipping through Utilizes a multi-stream event-sourcing approach for Rust development Prevents combined reviews from compromising thoroughness Enables focused attention on each review dimension Code-review is a systematic approach to evaluating code quality, spec compliance, and domain integrity through a structured three-stage review process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('go-go-golems/docmgr/cursor-diary', 'community', 'go-go-golems', 'docmgr', 'go-go-golems/docmgr', 'cursor-diary', 0, 0, 41, '2026-03-07T12:46:33.480Z', '2026-03-07T12:55:21.636Z', 'e009a06340edba395ba57385379a8f4e2ee8626a473f8c961007c1081eb7b2c7', '{"id":"go-go-golems/docmgr/cursor-diary","name":"cursor-diary","description":{"en":"Cursor-diary helps developers maintain a reproducible workflow by recording exact commands and file paths. It benefits developers working on complex projects.","zh":"Cursor Diary是一种记录步骤的工具，帮助开发者提高代码复现性和审查效率","ja":"Cursor Diaryはステップを記録するツールで、開発者がコードの再現性とレビューの効率を高めるのに役立つ","ko":"Cursor Diary는 개발자가 코드 재현성과 검토 효율성을 높이는 데 도움이 되는 단계 기록 도구입니다","es":"Cursor Diary es una herramienta que te permite mantener un diario de implementación paso a paso, enfocada en la reproducibilidad y eficiencia de revisión","fr":"Cursor Diary est un outil qui vous permet de maintenir un journal d''implémentation étape par étape, axé sur la reproductibilité et l''efficacité de révision","de":"Cursor Diary ist ein Werkzeug, das es Ihnen ermöglicht, ein Schritt-für-Schritt-Implementierungstagebuch zu führen, das auf Reproduzierbarkeit und Überprüfungseffizienz ausgerichtet ist","pt":"O Cursor-Diary é uma ferramenta que ajuda a manter um diário de implementação passo a passo, focado na reproducibilidade e eficiência de revisão","ru":"ИИ Агент Cursor-Diary помогает поддерживать журнал реализации шаг за шагом, ориентированный на воспроизводимость и эффективность проверки","ar":"وكيل Cursor-Diary يساعد على الحفاظ على دفتر يوميات تنفيذ خطوة بخطوة, يركز على إعادة الإنتاجية وفعالية المراجعة"},"seo":{"title":{"en":"Cursor-Diary: Reproducible Workflow Setup Guide | AI Agen...","zh":"Cursor Diary 设置指南 - AI智能工具","ja":"Cursor Diary 導入ガイド - AIエージェント","ko":"Cursor Diary 설정 가이드 - AI 에이전트","es":"Guía de configuración de Cursor Diary para Agents de Inte...","fr":"Guide de mise en route de Cursor Diary pour les Outils d''...","de":"Einrichtungsleitfaden für Cursor Diary in KI-Tools","pt":"Guia de Configuração do Cursor-Diary para Desenvolvedores","ru":"Настройка ИИ Агента Cursor-Diary: Руководство","ar":"دليل إعداد وكيل Cursor-Diary للبرمجة"},"description":{"en":"Unlock efficient development with cursor-diary. Learn how to create a step-by-step implementation diary and boost review efficiency. Get started now!","zh":"了解Cursor Diary的技术细节和工作流程，提高代码复现性和审查效率","ja":"Cursor Diaryの技術的詳細とワークフローを学び、コードの再現性とレビューの効率を高める","ko":"Cursor Diary의 기술적 세부 사항과 워크플로우를 익히고 코드 재현성 및 검토 효율성 향상","es":"Aprende a implementar Cursor Diary para mejorar la reproducibilidad y eficiencia en tus proyectos de desarrollo con Agents de Inteligencia Artificial","fr":"Découvrez comment mettre en place Cursor Diary pour améliorer la reproductibilité et l''efficacité dans vos projets de développement avec les Outils d''Intelli...","de":"Erfahren Sie, wie Sie Cursor Diary einrichten, um die Reproduzierbarkeit und Effizienz in Ihren Entwicklungsprojekten mit KI-Tools zu verbessern","pt":"Aprenda a configurar o Cursor-Diary para melhorar a reproducibilidade e eficiência de revisão no seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить ИИ Агент Cursor-Diary для повышения воспроизводимости и эффективности проверки в вашем рабочем процессе разработки","ar":"تعرف على كيفية إعداد وكيل Cursor-Diary لتحسين الإعادة الإنتاجية وفعالية المراجعة في تدفق عملك التطويري"},"definition":{"en":"Cursor-diary is a workflow tool that enables developers to maintain a step-by-step implementation diary for reproducibility and review efficiency.","zh":"Cursor Diary是一种记录开发步骤的工具，用于提高代码复现性和审查效率","ja":"Cursor Diaryはコードの再現性とレビューの効率を高めるためのステップ記録ツール","ko":"Cursor Diary는 코드 재현성과 검토 효율성을 높이는 데 사용되는 단계 기록 도구입니다","es":"Cursor Diary es un diario de implementación que registra cada paso del proceso de desarrollo para garantizar la reproducibilidad","fr":"Cursor Diary est un journal d''implémentation qui enregistre chaque étape du processus de développement pour garantir la reproductibilité","de":"Cursor Diary ist ein Implementierungstagebuch, das jeden Schritt des Entwicklungsprozesses aufzeichnet, um die Reproduzierbarkeit zu gewährleisten","pt":"O que é Cursor-Diary? Uma ferramenta de diário de implementação para desenvolvedores","ru":"Что такое ИИ Агент Cursor-Diary? Инструмент для ведения журнала реализации для разработчиков","ar":"ما هو وكيل Cursor-Diary? أداة لدفتر يوميات التنفيذ للبرمجة"},"features":{"en":["Creates a diary document using docmgr tickets with `docmgr doc add` command","Records tiny steps with frequent updates for efficient review","Supports reproducibility with exact commands and file paths","Enables efficient validation with clear intent and prose paragraphs","Integrates with commit hashes for version control"],"zh":["支持创建文档","记录每个步骤","提高代码复现性","提高审查效率","支持docmgr tickets","使用CLI命令"],"ja":["ドキュメントの作成をサポート","各ステップを記録","コードの再現性を高める","レビューの効率を高める","docmgr ticketsをサポート","CLIコマンドを使用"],"ko":["문서 생성 지원","각 단계 기록","코드 재현성 향상","검토 효율성 향상","docmgr tickets 지원","CLI 명령 사용"],"es":["Creación de un diario de implementación con comandos exactos y rutas de archivo","Registro de hashes de commits para garantizar la reproducibilidad","Uso de docmgr tickets para agregar documentos de referencia","Implementación de una revisión eficiente con validación de pasos","Compatibilidad con la creación de documentos de diario antes de la exploración","Uso de CLI para agregar documentos de referencia"],"fr":["Création d''un journal d''implémentation avec des commandes exactes et des chemins de fichiers","Enregistrement des hashes de commits pour garantir la reproductibilité","Utilisation de tickets docmgr pour ajouter des documents de référence","Mise en œuvre d''une révision efficace avec validation des étapes","Compatibilité avec la création de documents de journal avant l''exploration","Utilisation de la CLI pour ajouter des documents de référence"],"de":["Erstellung eines Implementierungstagebuchs mit exakten Befehlen und Dateipfaden","Aufzeichnung von Commit-Hashes zur Gewährleistung der Reproduzierbarkeit","Verwendung von docmgr-Tickets zum Hinzufügen von Referenzdokumenten","Implementierung einer effizienten Überprüfung mit Validierung der Schritte","Kompatibilität mit der Erstellung von Tagebuchdokumenten vor der Exploration","Verwendung der CLI zum Hinzufügen von Referenzdokumenten"],"pt":["Criação de um diário de implementação passo a passo","Foco na reproducibilidade com comandos exatos, caminhos de arquivo e hashes de commit","Melhoria da eficiência de revisão com validação e verificação","Integração com o gerenciador de documentos para adicionar tickets","Uso de comandos CLI para adicionar e gerenciar diários"],"ru":["Создание журнала реализации шаг за шагом","Фокус на воспроизводимости с точными командами, путями файлов и хэшами коммитов","Повышение эффективности проверки с помощью проверки и верификации","Интеграция с менеджером документов для добавления тикетов","Использование команд CLI для добавления и управления журналами"],"ar":["إنشاء دفتر يوميات تنفيذ خطوة بخطوة","التركيز على إعادة الإنتاجية باستخدام أوامر دقيقة ومسارات الملفات وأرقام الهاش للالتزام","تحسين فعالية المراجعة من خلال التحقق والتحقق","التكامل مع مدير المستندات لإضافة التذاكر","استخدام أوامر CLI لإضافة وإدارة دفاتر اليوميات"]},"keywords":{"en":["how to use cursor-diary","cursor-diary setup guide","reproducible workflow tools","cursor-diary vs documentation tools","cursor-diary install","efficient review processes","step-by-step implementation diary","what is cursor-diary","cursor-diary alternative","cursor-diary workflow optimization"],"zh":["Cursor Diary","AI智能工具","代码复现性","审查效率","docmgr tickets","CLI命令","开发工具","代码记录","步骤记录"],"ja":["Cursor Diary","AIエージェント","コードの再現性","レビューの効率","docmgr tickets","CLIコマンド","開発ツール","コード記録","ステップ記録"],"ko":["Cursor Diary","AI 에이전트","코드 재현성","검토 효율성","docmgr tickets","CLI 명령","개발 도구","코드 기록","단계 기록"],"es":["Cursor Diary","Agents de Inteligencia Artificial","desarrollo de software","reproducibilidad","eficiencia de revisión","docmgr tickets","CLI","implementación de diario","registro de comandos","validación de pasos"],"fr":["Cursor Diary","Outils d''Intelligence Artificielle","développement de logiciels","reproductibilité","efficacité de révision","tickets docmgr","CLI","implémentation de journal","enregistrement de commandes","validation des étapes"],"de":["Cursor Diary","KI-Tools","Softwareentwicklung","Reproduzierbarkeit","Überprüfungseffizienz","docmgr-Tickets","CLI","Implementierung von Tagebuch","Aufzeichnung von Befehlen","Validierung der Schritte"],"pt":["Cursor-Diary","diário de implementação","reproducibilidade","eficiência de revisão","desenvolvimento de software","ferramentas de desenvolvimento","CLI","gerenciador de documentos"],"ru":["ИИ Агент Cursor-Diary","журнал реализации","воспроизводимость","эффективность проверки","разработка программного обеспечения","инструменты разработки","CLI","менеджер документов"],"ar":["وكيل Cursor-Diary","دفتر يوميات التنفيذ","إعادة الإنتاجية","فعالية المراجعة","برمجة","أدوات التطوير","CLI","مدير المستندات"]}},"owner":"go-go-golems","repo":"docmgr","repoPath":"go-go-golems/docmgr","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.480Z","topics":[],"category":"community","skillMd":{"name":"cursor-diary","description":"Keep a tiny-step implementation diary during coding sessions (what changed, why, commands run, failures, and what was learned), with docmgr integration (doc add/relate/changelog). Use when the user asks to keep a diary, write a dev log, or document work step-by-step.","bodyPreview":"# Cursor Diary\n\n## Overview\n\nMaintain a step-by-step implementation diary as you work, focused on reproducibility (exact commands, file paths, commit hashes) and review efficiency (what to check + how to validate).\n\n## Workflow\n\n### 1) Bootstrap\n- Create a diary doc early (before exploration if possible).\n  - If using docmgr tickets: `docmgr doc add --ticket TICKET-ID --doc-type reference --title \"Diary\"`\n\n### 2) Record each tiny step (frequently)\n- Write 1–2 short prose paragraphs first (intent","body":"# Cursor Diary\n\n## Overview\n\nMaintain a step-by-step implementation diary as you work, focused on reproducibility (exact commands, file paths, commit hashes) and review efficiency (what to check + how to validate).\n\n## Workflow\n\n### 1) Bootstrap\n- Create a diary doc early (before exploration if possible).\n  - If using docmgr tickets: `docmgr doc add --ticket TICKET-ID --doc-type reference --title \"Diary\"`\n\n### 2) Record each tiny step (frequently)\n- Write 1–2 short prose paragraphs first (intent + what it unlocked).\n- Include exact commands, key outputs, and versions when relevant.\n- Capture failures verbatim (errors are valuable).\n\n### 3) Keep code ↔ docs consistent (docmgr loop)\n- Implement + format + test.\n- Commit code (record hash).\n- Update diary with the commit hash + rationale.\n- Relate files to the diary with absolute paths: `docmgr doc relate --doc <diary-path> --file-note \"/abs/path:why it matters\"`\n- Update ticket changelog per step: `docmgr changelog update --ticket TICKET-ID --entry \"Step N: ...\" --file-note \"/abs/path:reason\"`\n- Commit docs separately (e.g., `Diary: record Step N`).\n\n## Output template\n- Use the diary template in `references/diary.md` (copy/paste) as the canonical structure.\n\n## Notes\n- Prefer many small steps over a few big ones.\n- Always include: “What was tricky to build” + “What warrants a second pair of eyes” when behavior changes.\n"},"lastSynced":"2026-03-07T12:55:21.636Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing reproducible workflow management and exact command tracking.","zh":"非常适合需要可复现的工作流管理和精确命令跟踪的开发代理。","ja":"開発エージェントが再現可能なワークフローマネジメントと正確なコマンド追跡が必要な場合に最適です。","ko":"재현 가능한 워크플로우 관리와 정확한 명령 추적이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo reproducible y un seguimiento de comandos exacto.","fr":"Parfait pour les agents de développement nécessitant une gestion de flux de travail reproductible et un suivi de commande exact.","de":"Perfekt für Entwicklungssagenten, die eine reproduzierbare Workflow-Verwaltung und eine exakte Befehlsverfolgung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de fluxo de trabalho reprodutível e rastreamento de comandos exatos.","ru":"Идеально для агентов разработки, которым необходим управление рабочим процессом с воспроизводимыми результатами и точным отслеживанием команд.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إدارة تدفق عمل قابلة للتكرار وتحديد أوامر دقيقة."},"recommendation":{"en":"Empowers agents to maintain a step-by-step implementation diary, ensuring reproducibility via exact commands, file paths, and commit hashes, while enhancing review efficiency through clear validation and checking guidelines using tools like docmgr.","zh":"赋予代理维护一步一步的实现日记的能力，通过精确的命令、文件路径和提交哈希来确保可复现性，同时通过清晰的验证和检查指南（使用docmgr等工具）来提高审查效率。","ja":"エージェントがステップバイステップの実装日誌を維持する能力を付与し、正確なコマンド、ファイルパス、コミットハッシュを使用して再現性を確保し、docmgrなどのツールを使用した明確な検証とチェックガイドラインを通じてレビュー効率を向上させる。","ko":"에이전트가 단계별 구현 일지를 유지할 수 있는 능력을 부여하여 정확한 명령, 파일 경로 및 커밋 해시를 사용하여 재현성을 보장하고 docmgr 등의 도구를 사용한 명확한 검증 및 검사 지침을 통해 검토 효율성을 향상합니다.","es":"Habilita a los agentes a mantener un diario de implementación paso a paso, asegurando la reproducibilidad a través de comandos exactos, rutas de archivo y hashes de confirmación, mientras mejora la eficiencia de revisión a través de una validación y directrices de verificación claras utilizando herramientas como docmgr.","fr":"Permet aux agents de maintenir un journal d''implémentation étape par étape, assurant la reproductibilité via des commandes exactes, des chemins de fichiers et des hashes de validation, tout en améliorant l''efficacité de la revue via une validation et des lignes directrices de vérification claires en utilisant des outils comme docmgr.","de":"Ermöglicht es Agenten, ein schrittweises Implementierungstagebuch zu führen, wodurch die Reproduzierbarkeit durch exakte Befehle, Dateipfade und Commit-Hashes sichergestellt wird, während die Überprüfungseffizienz durch klare Validierungs- und Prüfrichtlinien unter Verwendung von Tools wie docmgr verbessert wird.","pt":"Habilita os agentes a manter um diário de implementação passo a passo, garantindo a reprodutibilidade por meio de comandos exatos, caminhos de arquivos e hashes de confirmação, além de melhorar a eficiência da revisão por meio de diretrizes de validação e verificação claras usando ferramentas como docmgr.","ru":"Наделяет агентов возможностью вести журнал реализации шаг за шагом, гарантируя воспроизводимость посредством точных команд, путей файлов и хэшей коммитов, а также повышает эффективность проверки за счет четких руководств по проверке и валидации с помощью инструментов như docmgr.","ar":"يمنح الوكيل القدرة على الاحتفاظ بمذكرة تنفيذ خطوة بخطوة ، مما يضمن إمكانية الإعادة الإنتاج من خلال أوامر دقيقة ومسارات الملفات وأرقام التجزئة للالتزام ، بالإضافة إلى تحسين كفاءة المراجعة من خلال إرشادات التحقق والتحقق الواضحة باستخدام أدوات مثل docmgr."},"useCases":{"en":["Recording complex project workflows for future reference","Generating detailed change logs with commit hashes","Streamlining code review processes with clear validation steps"],"zh":["记录复杂项目工作流以供将来参考","使用提交哈希生成详细的更改日志","通过清晰的验证步骤简化代码审查过程"],"ja":["将来参照できるように複雑なプロジェクトのワークフローを記録する","コミットハッシュを使用して詳細な変更ログを生成する","明確な検証ステップを使用してコードレビューのプロセスを合理化する"],"ko":["将来 참조할 수 있도록 복잡한 프로젝트 워크플ロー 기록","커밋 해시를 사용하여 자세한 변경 로그 생성","명확한 검증 단계를 사용하여 코드 검토 프로세스簡素化"],"es":["Grabación de flujos de trabajo de proyecto complejos para referencia futura","Generación de registros de cambios detallados con hashes de confirmación","Optimización de los procesos de revisión de código con pasos de validación claros"],"fr":["Enregistrement de flux de travail de projet complexes pour référence future","Génération de journaux de modifications détaillés avec des hashes de validation","Optimisation des processus d''examen de code avec des étapes de validation claires"],"de":["Aufzeichnung komplexer Projekt-Workflows für zukünftige Referenzen","Erzeugung detaillierter Änderungsprotokolle mit Commit-Hashes","Optimierung von Code-Review-Prozessen mit klaren Validierungsschritten"],"pt":["Gravar fluxos de trabalho de projetos complexos para referência futura","Gerar registros de alterações detalhados com hashes de confirmação","Otimizar processos de revisão de código com etapas de validação claras"],"ru":["Запись сложных рабочих процессов проектов для будущей справки","Генерация подробных журналов изменений с хэнями коммитов","Оптимизация процессов проверки кода с четкими шагами валидации"],"ar":["تسجيل تدفقات عمل مشاريع معقدة لم参考 مستقبلي","_generating سجلات تغييرات مفصلة بأرقام التجزئة للالتزام","تحسين عمليات مراجعة الكود بخطوات التحقق الواضحة"]},"limitations":{"en":["Requires docmgr for integrated ticket management","Manual effort needed for frequent step recording","Limited to development workflows with command-line interfaces"],"zh":["需要docmgr进行集成的票据管理","需要手动努力来频繁地记录步骤","仅限于具有命令行接口的开发工作流"],"ja":["統合されたチケット管理のためにdocmgrを必要とする","頻繁にステップを記録するために手動の労力を必要とする","コマンドラインインターフェイスを持つ開発ワークフローに限定される"],"ko":["統合된 티켓 관리를 위해 docmgr 필요","빈번하게 단계를 기록하기 위해 수동적인 노력 필요","명령줄 인터페이스를 갖춘 개발 워크플로에만 제한"],"es":["Requiere docmgr para la gestión de tickets integrada","Se necesita esfuerzo manual para la grabación frecuente de pasos","Limitado a flujos de trabajo de desarrollo con interfaces de línea de comandos"],"fr":["Nécessite docmgr pour la gestion de tickets intégrée","Un effort manuel est nécessaire pour l''enregistrement fréquent d''étapes","Limité aux flux de travail de développement avec des interfaces de ligne de commande"],"de":["Benötigt docmgr für die integrierte Ticketverwaltung","Manueller Aufwand ist erforderlich für die häufige Aufzeichnung von Schritten","Begrenzt auf Entwicklung-Workflows mit Befehlszeilen-Schnittstellen"],"pt":["Exige docmgr para gerenciamento de tíquetes integrado","Esforço manual necessário para gravação frequente de etapas","Limitado a fluxos de trabalho de desenvolvimento com interfaces de linha de comando"],"ru":["Требует docmgr для интегрированного управления тикетами","Необходим ручной труд для частой записи шагов","Ограничен рабочими процессами разработки с командной строкой"],"ar":["يتطلب docmgr لإدارة التذاكر المتكاملة","يحتاج إلى جهد يدوي لتسجيل الخطوات المتكررة","محدود بالتدفقات العملية للتطوير مع واجهات سطر الأوامر"]},"version":4},"contentHash":"e009a06340edba395ba57385379a8f4e2ee8626a473f8c961007c1081eb7b2c7","qualityScore":41}');
