INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('markus41/claude/restapi', 'restapi', 'markus41', 'claude', 'community', 'restapi markus41 claude community The restapi skill provides comprehensive REST API design and implementation capabilities for AI agents, supporting API endpoint design, HTTP request/response handling, and OpenAPI documentation. REST API Skill 提供了全面的 REST API 设计和实现能力，包括 API 端点设计、HTTP 请求/响应处理等 REST API Skill は、API エンドポイントの設計、HTTP リクエスト/レスポンスの処理など、包括的な REST API の設計と実装能力を提供します REST API Skill은 API 엔드포인트 디자인, HTTP 요청/응답 처리 등을 포함한 포괄적인 REST API 디자인 및 구현 기능을 제공합니다 El skill de REST API proporciona capacidades de diseño y implementación de API REST para la plataforma de la flota de agentes de inteligencia artificial Golden Armada. Le skill REST API fournit des capacités de conception et de mise en œuvre d''API REST pour la plate-forme de flotte d''agents d''intelligence artificielle Golden Armada. Der REST-API-Skill bietet umfassende REST-API-Design- und Implementierungsfähigkeiten für die Golden Armada KI-Agenten-Flottenplattform. A habilidade REST API fornece capacidades abrangentes de design e implementação de REST API para a plataforma Golden Armada AI Agent Fleet. Навык REST API предоставляет всесторонние возможности проектирования и реализации REST API для платформы Golden Armada AI Agent Fleet. يتمتع مهارات REST API بقدرات شاملة لتصميم وتنفيذ REST API لمنصة Golden Armada AI Agent Fleet. how to use restapi restapi setup guide restapi vs graphql restapi install what is restapi restapi alternative restapi design principles restapi implementation for ai agents restapi and openapi documentation restapi api testing REST API 设计 API 设计原则 HTTP 请求/响应处理 API 身份验证 OpenAPI 文档 AIエージェント REST API REST API 实现 Supports API endpoint design using nouns and plural naming conventions Handles HTTP request/response handling for API interactions Provides API authentication capabilities for secure interactions Generates OpenAPI documentation for API testing and validation Allows for nested resource naming for complex API structures Supports API testing for validation and quality assurance restapi is a skill that provides comprehensive REST API design and implementation capabilities for the Golden Armada AI Agent Fleet Platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agoudbg/Cosmosh/google-cl-author', 'community', 'agoudbg', 'Cosmosh', 'agoudbg/Cosmosh', 'google-cl-author', 3, 0, 41, '2026-03-07T11:45:21Z', '2026-03-07T12:49:19.754Z', 'fa6fb07db6da0106f399b50fe7a1c6109d4f7cb2799d534a5876a0455ed8ad5f', '{"id":"agoudbg/Cosmosh/google-cl-author","name":"google-cl-author","description":{"en":"The google-cl-author skill helps developers prepare review-friendly changelists and respond to review feedback efficiently, supporting technologies like SSH, SFTP, and bash.","zh":"Google CL Author Skill 是一种用于高效处理代码审查和反馈响应的工具，支持 SSH 和 SFTP","ja":"Google CL Author Skill は、コードレビューとフィードバック対応を効率化するためのツールで、SSH と SFTP をサポート","ko":"Google CL Author Skill은 코드 리뷰와 피드백 응대를 효율적으로 처리하는 도구로 SSH와 SFTP를 지원","es":"Google-cl-author es una habilidad que ayuda a los desarrolladores a preparar listas de cambios y responder a comentarios de revisión de manera eficiente. Soporta SSH, SFTP y terminal","fr":"Google-cl-author est une compétence qui aide les développeurs à préparer des listes de modifications et à répondre aux commentaires de révision de manière efficace. Prend en charge SSH, SFTP et terminal","de":"Google-cl-author ist eine Fähigkeit, die Entwicklern hilft, Änderungslisten vorzubereiten und Kommentare von Reviewern effizient zu beantworten. Unterstützt SSH, SFTP und Terminal","pt":"O google-cl-author é uma ferramenta para preparar changelists e responder a feedback de revisão de forma eficiente, com suporte a SSH e SFTP","ru":"google-cl-author - это инструмент для подготовки changelists и ответов на отзывы рецензентов, с поддержкой SSH и SFTP","ar":"google-cl-author هو أداة لتحضير changelists والرد على تعليقات المراجعين بفعالية، مع دعم SSH و SFTP"},"seo":{"title":{"en":"google-cl-author: Efficient Changelist Management for AI ...","zh":"Google CL Author Skill 设置指南 - 高效处理代码审查","ja":"Google CL 