INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Neko-Protocol/Neko-DApp/commit-work', 'commit-work', 'Neko-Protocol', 'Neko-DApp', 'community', 'commit-work Neko-Protocol Neko-DApp community The commit-work skill helps developers create commits that are easy to review and safe to ship, following Conventional Commits standards. It benefits developers working on collaborative projects. Commit Work 技术通过确保提交的代码仅包含预期的变化、逻辑上分割的提交和描述变更的提交消息，优化代码提交和审查流程 Commit Work 技術は、予期された変更のみを含む、論理的に分割されたコミットと変更の説明を含むコミットメッセージにより、コードレビューを安全に_shipする Commit Work 설정을 통해 코드 제출과 검토를 최적화하여 안전하고 신뢰할 수 있는 코드를 제출 Commit-work permite crear commits que son fáciles de revisar y seguros de enviar, con cambios intencionados y mensajes descriptivos Commit-work permet de créer des commits qui sont faciles à revoir et sûrs à envoyer, avec des changements intentionnels et des messages descriptifs Commit-work ermöglicht das Erstellen von Commits, die leicht zu überprüfen und sicher zu senden sind, mit beabsichtigten Änderungen und beschreibenden Nachrichten O Commit-Work ajuda a criar commits fáceis de revisar e seguros para enviar, utilizando Conventional Commits e seguindo as melhores práticas. Commit-Work помогает создавать коммиты, которые легко проверить и безопасно отправить, используя Conventional Commits и следуя лучшим практикам. يساعد Commit-Work في إنشاء إلتزامات سهلة المراجعة وأمنة للنشر، باستخدام Conventional Commits واتباع أفضل الممارسات. how to use commit-work what is commit-work commit-work alternative commit-work vs git commit-work setup guide conventional commits tutorial commit-work install safe and reviewable commits Commit Work 代码提交 代码审查 Conventional Commits AIエージェント 代码优化 安全提交 Ensures only intended changes are included in commits Supports logically scoped commits with optional splitting Enforces Conventional Commits style for commit messages Allows specification of commit style, including max subject length and required scopes Provides a workflow checklist for commit creation commit-work is a skill that enables developers to make logical and scoped commits with descriptive messages, following specific commit styles and rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thisisartium/pm-starter-kit/synthesize-inbox-entry', 'community', 'thisisartium', 'pm-starter-kit', 'thisisartium/pm-starter-kit', 'synthesize-inbox-entry', 2, 2, 41, '2026-03-05T21:50:00Z', '2026-03-06T13:08:13.651Z', '0c8703bbcb815df71ce6c02e98a69af9c73d612048e3b64b4fa40f63767ac3f4', '{"id":"thisisartium/pm-starter-kit/synthesize-inbox-entry","name":"synthesize-inbox-entry","description":{"en":"The synthesize-inbox-entry skill turns raw notes or conversation text into a compliant inbox entry in planning/inbox/ using the template at planning/templates/inbox_synthesis.md, benefiting developers and users alike.","zh":"synthesize-inbox-entry 技术可以自动将原始笔记或对话文本转换为 planning/inbox/ 模板的入站项","ja":"synthesize-inbox-entry は会話テキストを planning/inbox/ テンプレートに準拠したインボックスエントリに自動変換します","ko":"synthesize-inbox-entry 기술은 대화 로그를 정리된 인박스 항목으로 자동 변환합니다","es":"Synthesize-inbox-entry es una habilidad que convierte notas y conversaciones en entradas de bandeja de entrada estructuradas. Utiliza plantillas personalizadas para organizar la información","fr":"Synthesize-inbox-entry est une compétence qui transforme les notes et les conversations en entrées de boîte de réception structurées. Elle utilise des modèles personnalisés pour organiser les informations","de":"Synthesize-inbox-entry ist eine Fähigkeit, die Notizen und Gespräche in strukturierte Posteingangs-Einträge umwandelt. Sie verwendet benutzerdefinierte Vorlagen, um die Informationen zu organisieren","pt":"O synthesize-inbox-entry é uma habilidade que transforma notas cruas em entradas de caixa de entrada compatíveis usando um modelo de template","ru":"synthesize-inbox-entry - это навык, который преобразует сырые заметки в совместимые записи входящих сообщений с помощью шаблона","ar":"synthesize-inbox-entry هو مهارة تقوم بتحويل الملاحظات الخام إلى مدخلات صندوق الوارد المتوافق