INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thisisartium/pm-starter-kit/synthesize-inbox-entry', 'synthesize-inbox-entry', 'thisisartium', 'pm-starter-kit', 'community', 'synthesize-inbox-entry thisisartium pm-starter-kit community The synthesize-inbox-entry skill turns raw notes or conversation text into a compliant inbox entry in planning/inbox/ using the template at planning/templates/inbox_synthesis.md, benefiting developers and users alike. synthesize-inbox-entry 技术可以自动将原始笔记或对话文本转换为 planning/inbox/ 模板的入站项 synthesize-inbox-entry は会話テキストを planning/inbox/ テンプレートに準拠したインボックスエントリに自動変換します synthesize-inbox-entry 기술은 대화 로그를 정리된 인박스 항목으로 자동 변환합니다 Synthesize-inbox-entry es una habilidad que convierte notas y conversaciones en entradas de bandeja de entrada estructuradas. Utiliza plantillas personalizadas para organizar la información Synthesize-inbox-entry est une compétence qui transforme les notes et les conversations en entrées de boîte de réception structurées. Elle utilise des modèles personnalisés pour organiser les informations Synthesize-inbox-entry ist eine Fähigkeit, die Notizen und Gespräche in strukturierte Posteingangs-Einträge umwandelt. Sie verwendet benutzerdefinierte Vorlagen, um die Informationen zu organisieren O synthesize-inbox-entry é uma habilidade que transforma notas cruas em entradas de caixa de entrada compatíveis usando um modelo de template synthesize-inbox-entry - это навык, который преобразует сырые заметки в совместимые записи входящих сообщений с помощью шаблона synthesize-inbox-entry هو مهارة تقوم بتحويل الملاحظات الخام إلى مدخلات صندوق الوارد المتوافقة باستخدام نموذج قالب how to use synthesize-inbox-entry synthesize-inbox-entry alternative synthesize-inbox-entry setup guide what is synthesize-inbox-entry synthesize-inbox-entry vs inbox management tools synthesize-inbox-entry install synthesize-inbox-entry AIエージェント 笔记整理 会话文本转换 planning/inbox/ 自动化工具 生产力提高 工作效率 技术文档 Uses planning/templates/inbox_synthesis.md template for inbox entry synthesis Accepts raw text, source context, author, date, and related links as inputs Preserves curated inputs from unstructured notes or conversation text Generates compliant inbox entries in planning/inbox/ Supports optional metadata like source context, author, and date synthesize-inbox-entry is a skill that converts raw text into a structured inbox entry using a predefined template.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryanallen/product-studio/generate-figma', 'community', 'ryanallen', 'product-studio', 'ryanallen/product-studio', 'generate-figma', 1, 0, 41, '2026-03-06T01:57:06Z', '2026-03-06T07:20:41.440Z', '5ea8e2738f8a437140d6ea33e00923d13b721f0233991aae8acf88fcd4a991cb', '{"id":"ryanallen/product-studio/generate-figma","name":"generate-figma","description":{"en":"The generate-figma skill orchestrates AI agents for design processes in Figma, benefiting teams and developers. It generates or updates designs using the Figma Console MCP.","zh":"generate-figma 是一个用于自动化 Figma 设计流程的 AI 工具，支持设计文件生成和更新","ja":"generate-figma は、Figma デザインプロセスを自動化する AI エージェントで、デザインファイルの生成と更新をサポートします","ko":"generate-figma는 피그마 디자인 프로세스를 자동화하는 AI 도구로 디자인 파일 생성과 업데이트를 지원합니다","es":"Generate-figma es un sistema de operaciones para equipos que orquesta agentes de IA especializados a través del proceso de diseño en Figma","fr":"Generate-figma est un système d''exploitation pour les équipes qui orchestre des agents d''IA spécialisés à travers le processus de conception dans Figma","de":"Generate-figma ist ein Betriebssystem für Teams, das spezialisierte KI-Agenten durch den Gestaltungsprozess in Figma orchestriert","pt":"O Generate Figma é um sistema de operações para equipes que orquestra agentes de IA especializados no processo de design","ru":"Generate Figma - это операционная система для команд, которая оркестрирует специализированные ИИ агенты в процессе дизайна","ar":"Generate Figma هو نظام تشغيل للفرق يorchestrate وكلاء ذكاء اصطناعي متخصصين في عملية التصميم"},"seo":{"title":{"en":"generate-figma: Figma Console MCP Setup Guide | AI Agent ...","zh":"Figma 设计自动化：generate-figma 设置指南","ja":"Figma デザイン自動化：generate-figma のベストプラクティス","ko":"피그마 디자인 자동화: generate-figma 사용법","es":"Guía de configuración de generate-figma para diseño autom...","fr":"Guide de 