INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryanallen/product-studio/generate-figma', 'generate-figma', 'ryanallen', 'product-studio', 'community', 'generate-figma ryanallen product-studio community The generate-figma skill orchestrates AI agents for design processes in Figma, benefiting teams and developers. It generates or updates designs using the Figma Console MCP. generate-figma 是一个用于自动化 Figma 设计流程的 AI 工具，支持设计文件生成和更新 generate-figma は、Figma デザインプロセスを自動化する AI エージェントで、デザインファイルの生成と更新をサポートします generate-figma는 피그마 디자인 프로세스를 자동화하는 AI 도구로 디자인 파일 생성과 업데이트를 지원합니다 Generate-figma es un sistema de operaciones para equipos que orquesta agentes de IA especializados a través del proceso de diseño en Figma Generate-figma est un système d''exploitation pour les équipes qui orchestre des agents d''IA spécialisés à travers le processus de conception dans Figma Generate-figma ist ein Betriebssystem für Teams, das spezialisierte KI-Agenten durch den Gestaltungsprozess in Figma orchestriert O Generate Figma é um sistema de operações para equipes que orquestra agentes de IA especializados no processo de design Generate Figma - это операционная система для команд, которая оркестрирует специализированные ИИ агенты в процессе дизайна Generate Figma هو نظام تشغيل للفرق يorchestrate وكلاء ذكاء اصطناعي متخصصين في عملية التصميم how to use generate-figma generate-figma setup guide generate-figma alternative generate-figma vs Adobe XD generate-figma install what is generate-figma generate-figma Figma Console MCP generate-figma AI agent generate-figma design automation Figma 设计自动化 generate-figma AI 工具 设计文件生成 设计文件更新 Figma Console MCP 目标文件详情 父节点 ID 捕获 ID 端点 Uses Figma Console MCP to generate or update designs Supports target file details, including file key, file URL, and parent node ID Provides capture IDs or endpoints for capture flows Resolves file keys for design generation or update Integrates with Figma files, including https://www.figma.com/file/abc123/... URLs generate-figma is an operations system for teams that automates design processes in Figma using specialized AI agents and the Figma Console MCP.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rdfitted/Claude-Code-Setup/tts', 'community', 'rdfitted', 'Claude-Code-Setup', 'rdfitted/Claude-Code-Setup', 'tts', 1, 0, 41, '2026-03-02T00:09:57Z', '2026-03-06T13:12:22.288Z', 'a75f883527c896264172ef4244f091ba20a1ff66e16c4b7d9fa789cfff254d18', '{"id":"rdfitted/Claude-Code-Setup/tts","name":"tts","description":{"en":"The tts skill synthesizes speech from text, benefiting developers who need to automate voice interactions. It uses a local TTS script and supports custom voice models.","zh":"TTS 技术允许将文本转换为语音输出，使用 ElevenLabs 和 Python 脚本实现语音合成","ja":"TTS 技術はテキストを音声出力に変換し、ElevenLabs と Python スクリプトを使用して音声合成を実現します","ko":"TTS 기술은 텍스트를 음성 출력으로 변환하고 ElevenLabs 및 Python 스크립트를 사용하여 음성 합성을 구현합니다","es":"TTS es una habilidad que permite sintetizar voz desde texto. Se utiliza ejecutando un script Python local.","fr":"TTS est une compétence qui permet de synthétiser la voix à partir du texte. Elle utilise un script Python local.","de":"TTS ist eine Fähigkeit, die die Sprachsynthese aus Text ermöglicht. Sie verwendet ein lokales Python-Skript.","pt":"O TTS é uma habilidade que permite sintetizar fala em texto. Use o script elevenlabs_tts.py para criar fala sintética.","ru":"TTS - это навык, который позволяет синтезировать речь из текста. Используйте скрипт elevenlabs_tts.py для создания синтетической речи.","ar":"TTS هو مهارة يسمح بتحويل النص إلى كلام. استخدم سكريبت elevenlabs_tts.py لإنشاء كلام اصطناعي."},"seo":{"title":{"en":"tts: Text-to-Speech Synthesis Setup Guide | AI Agent Skill","zh":"TTS 设置指南：使用 ElevenLabs 实现文本转语音","ja":"TTS Setup Guide: ElevenLabs を使用したテキストから音声への合成","ko":"TTS 설정 가이드: ElevenLabs를 사용한 텍스트 음성 합성","es":"Guía de configuración de TTS: Síntesis de voz desde texto","fr":"Guide de configuration TTS : Synthèse vocale à partir de ...","de":"TTS-Setup-Anleitung: Sprachsynthese aus Text","pt":"Guia de Configuração do TTS: Síntese de Fala em Texto","ru":"Настройка ИИ Агентов TTS: Руководство по Синтезу Речи","ar":"دليل إعداد TTS: تحويل النص إلى كلام"},"description":{"en":"Discover how to use tts for AI agents, with a step-by-step guide on text-to-speech synthesis and workflow automation. Get started now!","zh":"了解如何使用 TTS 技术和 ElevenLabs 实现文本转语音，提高 AI エージェント的交互能力","ja":"TTS 技術と ElevenLabs を使用してテキストから音声への合成を実現し、AI エージェントの対話能力を高める方法を学びます","ko":"TTS 기술과 ElevenLabs를 사용하여 텍스트를 음성으로 합성하고 AI 에이전트의 상호 작용 능력을 향상하는 방법을 알아보세요","es":"Aprende a configurar TTS para sintetizar voz desde texto con nuestra guía paso a paso","fr":"Découvrez comment configurer TTS pour synthétiser la voix à partir du texte avec notre guide étape par étape","de":"Erfahren Sie, wie Sie TTS konfigurieren, um Sprache aus Text zu synthetisieren, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o TTS para síntese de fala em texto com este guia passo a passo. Descubra como usar o script elevenlabs_tts.py para criar fala sintética.","ru":"Узнайте, как настроить ИИ Агентов TTS для синтеза речи из текста с помощью этого пошагового руководства. Откройте для себя, как использовать скрипт elevenlab...","ar":"تعرف على كيفية إعداد TTS لتحويل النص إلى كلام باستخدام هذا الدليل خطوة بخطوة. اكتشف كيفية استخدام سكريبت elevenlabs_tts.py لإنشاء كلام اصطناعي."},"definition":{"en":"tts is a text-to-speech synthesis skill that generates speech from input text using a local script and custom voice models.","zh":"TTS 是一种将文本转换为语音的技术，使用 AI エージェント实现语音交互","ja":"TTS はテキストを音声に変換する技術で、AI エージェントを使用して音声対話を実現します","ko":"TTS는 텍스트를 음성으로 변환하는 기술로 AI 에이전트를 사용하여 음성 상호 작용을 구현합니다","es":"TTS significa Síntesis de voz desde texto, una técnica para convertir texto en voz","fr":"TTS signifie Synthèse vocale à partir de texte, une technique pour convertir le texte en voix","de":"TTS bedeutet Sprachsynthese aus Text, eine Technik zur Umwandlung von Text in Sprache","pt":"TTS é uma tecnologia de síntese de fala que converte texto em fala sintética.","ru":"TTS - это технология синтеза речи, которая преобразует текст в синтетическую речь.","ar":"TTS هو تقنية لتحويل النص إلى كلام يسمح بتحويل النص إلى كلام اصطناعي."},"features":{"en":["Runs local TTS script using elevenlabs_tts.py","Supports custom voice models like eleven_v3","Creates skip marker file for workflow automation","Confirms success with a short confirmation message","Extracts text to speak from input data","Uses uv run command for script execution"],"zh":["使用 ElevenLabs 实现高质量语音合成","支持 Python 脚本和 CLI 命令","可自定义语音和模型","实现文本到语音的实时转换","支持多种语音输出格式"],"ja":["ElevenLabs を使用した高品質音声合成","Python スクリプトと CLI コマンドのサポート","音声とモデルをカスタマイズ可能","テキストから音声へのリアルタイム変換","複数の音声出力形式をサポート"],"ko":["ElevenLabs를 사용한 고품질 음성 합성","Python 스크립트와 CLI 명령어 지원","음성과 모델을 사용자 정의할 수 있음","텍스트를 음성으로 실시간 변환","여러 가지 음성 출력 형식 지원"],"es":["Síntesis de voz desde texto utilizando Python","Compatibilidad con scripts locales para personalización","Uso de la biblioteca elevenlabs_tts.py para la síntesis de voz","Creación de un archivo de marcador de salto para confirmar la ejecución","Soporte para voz personalizada con la opción --voice"],"fr":["Synthèse vocale à partir de texte en utilisant Python","Compatibilité avec les scripts locaux pour la personnalisation","Utilisation de la bibliothèque elevenlabs_tts.py pour la synthèse vocale","Création d''un fichier de marqueur de saut pour confirmer l''exécution","Prise en charge de la voix personnalisée avec l''option --voice"],"de":["Sprachsynthese aus Text mit Python","Kompatibilität mit lokalen Skripten für Anpassung","Verwendung der Bibliothek elevenlabs_tts.py für die Sprachsynthese","Erstellung einer Skip-Marker-Datei zur Bestätigung der Ausführung","Unterstützung für personalisierte Stimmen mit der Option --voice"],"pt":["Síntese de fala em texto","Uso do script elevenlabs_tts.py","Compatibilidade com o modelo eleven_v3","Criação de fala sintética personalizada","Integração com a CLI para execução do script"],"ru":["Синтез речи из текста","Использование скрипта elevenlabs_tts.py","Совместимость с моделью eleven_v3","Создание синтетической речи на заказ","Интеграция с CLI для выполнения скрипта"],"ar":["تحويل النص إلى كلام","استخدام سكريبت elevenlabs_tts.py","التكامل مع نموذج eleven_v3","إنشاء كلام اصطناعي مخصص","التكامل مع CLI لتشغيل السكريبت"]},"keywords":{"en":["how to use tts","tts setup guide","text to speech synthesis","tts alternative","tts vs google text to speech","elevenlabs tts","tts install","tts workflow automation","custom voice models for tts","ai agent tts integration"],"zh":["TTS 技术","ElevenLabs","Python 脚本","CLI 命令","语音合成","AI エージェント","文本转语音","语音交互"],"ja":["TTS 技術","ElevenLabs","Python スクリプト","CLI コマンド","音声合成","AI エージェント","テキストから音声","音声対話"],"ko":["TTS 기술","ElevenLabs","Python 스크립트","CLI 명령어","음성 합성","AI 에이전트","텍스트 음성 변환","음성 상호 작용"],"es":["TTS","Síntesis de voz","Python","Script local","elevenlabs_tts.py","Personalización de voz","Herramientas de desarrollo de voz","Tecnologías de síntesis de voz"],"fr":["TTS","Synthèse vocale","Python","Script local","elevenlabs_tts.py","Personnalisation de la voix","Outils de développement de la voix","Technologies de synthèse vocale"],"de":["TTS","Sprachsynthese","Python","Lokales Skript","elevenlabs_tts.py","Stimmpersonalisierung","Sprachentwicklungstools","Sprachsynthesetechnologien"],"pt":["tts","síntese de fala","elevenlabs_tts.py","modelo eleven_v3","kalam sintético","cli","índice de configuração","desenvolvedores de ai"],"ru":["tts","синтез речи","elevenlabs_tts.py","модель eleven_v3","синтетическая речь","cli","настройка","разработчики ИИ"],"ar":["tts","تحويل النص إلى كلام","elevenlabs_tts.py","نموذج eleven_v3","كلام اصطناعي","cli","إعداد","مطورو الذكاء الاصطناعي"]}},"owner":"rdfitted","repo":"Claude-Code-Setup","repoPath":"rdfitted/Claude-Code-Setup","stars":1,"forks":0,"updatedAt":"2026-03-02T00:09:57Z","topics":[],"category":"community","skillMd":{"name":"tts","description":"Speak text aloud using the local ElevenLabs TTS script; use when the user asks to read or speak text.","bodyPreview":"# TTS\n\n## Overview\n\nUse this skill to synthesize speech from text.\n\n## Inputs\n\n- Text to speak\n\n## Workflow\n\n1. Extract the text to speak.\n2. Run the local TTS script:\n   `uv run C:\\Users\\USERNAME\\.claude\\hooks\\utils\\tts\\elevenlabs_tts.py --voice OCIdyYxzVR7iuL9fyP9f --model eleven_v3 \"<TEXT>\"`\n3. Create the skip marker file:\n   `echo skip > C:\\Users\\USERNAME\\.claude\\hooks\\utils\\tts\\.skip_endhook`\n4. Confirm success.\n\n## Output\n\n- Short confirmation that speech ran.","body":"# TTS\n\n## Overview\n\nUse this skill to synthesize speech from text.\n\n## Inputs\n\n- Text to speak\n\n## Workflow\n\n1. Extract the text to speak.\n2. Run the local TTS script:\n   `uv run C:\\Users\\USERNAME\\.claude\\hooks\\utils\\tts\\elevenlabs_tts.py --voice OCIdyYxzVR7iuL9fyP9f --model eleven_v3 \"<TEXT>\"`\n3. Create the skip marker file:\n   `echo skip > C:\\Users\\USERNAME\\.claude\\hooks\\utils\\tts\\.skip_endhook`\n4. Confirm success.\n\n## Output\n\n- Short confirmation that speech ran.\n"},"lastSynced":"2026-03-06T13:12:22.288Z","agentAnalysis":{"suitability":{"en":"Ideal for Voice Interaction Agents requiring advanced text-to-speech synthesis capabilities.","zh":"适用于需要高级文本转语音合成功能的语音交互代理。","ja":"高度なテキストツースピーチ合成機能を必要とする音声インタラクションエージェントに適しています。","ko":"고급 텍스트 음성 합성 기능을 필요로 하는 음성 상호 작용 에이전트에 적합합니다.","es":"Ideal para agentes de interacción de voz que requieren capacidades de síntesis de texto a voz avanzadas.","fr":"Idéal pour les agents d''interaction vocale nécessitant des capacités de synthèse de texte à parole avancées.","de":"Ideal für Voice-Interaktion-Agents, die erweiterte Text-to-Speech-Synthese-Funktionen benötigen.","pt":"Ideal para Agentes de Interação de Voz que exigem capacidades avançadas de síntese de texto-para-fala.","ru":"Идеально для агентов голосового взаимодействия, требующих расширенных возможностей синтеза речи из текста.","ar":"مثالي للوكلاء التفاعل الصوتي الذين يتطلبون قدرات متقدمة من النص إلى الكلام"},"recommendation":{"en":"Empowers agents to synthesize speech from text using custom voice models and a local TTS script, leveraging Python and the elevenlabs_tts.py utility, and supporting protocols like uv run for seamless execution.","zh":"使代理能够使用自定义语音模型和本地TTS脚本合成文本为语音，利用Python和elevenlabs_tts.py实用程序，并支持像uv run的协议以实现无缝执行。","ja":"Pythonとelevenlabs_tts.pyユーティリティを利用し、uv runなどのプロトコルをサポートして無停滞実行を可能にすることで、カスタムボイスモデルとローカルのTTSスクリプトを使用してテキストから音声を合成するエージェントを可能にします。","ko":"Python과 elevenlabs_tts.py 유틸리티를 사용하여 사용자 정의 보이스 모델과 로컬 TTS 스크립트를 사용하여 텍스트를 음성으로 합성할 수 있도록 하며, uv run과 같은 프로토콜을 지원하여 무중단 실행을 가능하게 합니다.","es":"Habilita a los agentes a sintetizar el habla a partir del texto utilizando modelos de voz personalizados y un script de TTS local, aprovechando Python y la utilidad elevenlabs_tts.py, y admitiendo protocolos como uv run para una ejecución sin problemas.","fr":"Permet aux agents de synthétiser la parole à partir du texte en utilisant des modèles de voix personnalisés et un script TTS local, en exploitant Python et l''utilitaire elevenlabs_tts.py, et en prenant en charge des protocoles tels que uv run pour une exécution sans accroc.","de":"Ermächtigt die Agents, Sprache aus Text zu synthetisieren, indem sie benutzerdefinierte Sprachmodelle und ein lokales TTS-Skript verwenden, Python und die elevenlabs_tts.py-Utility nutzt und Protokolle wie uv run für eine reibungslose Ausführung unterstützt.","pt":"Habilita os agentes a sintetizar fala a partir de texto usando modelos de voz personalizados e um script TTS local, aproveitando o Python e a utilidade elevenlabs_tts.py, e suportando protocolos como uv run para execução sem interrupções.","ru":"Наделяет агентов возможностью синтезировать речь из текста с помощью индивидуальных моделей голоса и локального скрипта TTS, используя Python и утилиту elevenlabs_tts.py, и поддерживая протоколы, такие как uv run для бесперебойного выполнения.","ar":"تمكين الوكلاء من 合成 الكلام من النص باستخدام نماذج صوتية مخصصة وبرنامج نصي TTS محلي ، واستخدام Python و elevenlabs_tts.py ، ودعم بروتوكولات مثل uv run للتشغيل السلس"},"useCases":{"en":["Automating voice interactions for chatbots","Generating audio content for accessibility features","Debugging text-to-speech outputs for voice assistants"],"zh":["为聊天机器人自动化语音交互","为无障碍功能生成音频内容","为语音助手调试文本转语音输出"],"ja":["チャットボットの音声インタラクションを自動化する","アクセシビリティ機能のためにオーディオコンテンツを生成する","ボイスアシスタントのテキストツースピーチ出力をデバッグする"],"ko":["채팅봇의 음성 상호 작용 자동화","접근성 기능을 위한 오디오 콘텐츠 생성","음성助手의 텍스트 음성 출력 디버깅"],"es":["Automatizar interacciones de voz para chatbots","Generar contenido de audio para características de accesibilidad","Depurar salidas de texto a voz para asistentes de voz"],"fr":["Automatiser les interactions vocales pour les chatbots","Générer du contenu audio pour les fonctionnalités d''accessibilité","Déboguer les sorties de texte à parole pour les assistants vocaux"],"de":["Automatisieren von Sprachinteraktionen für Chatbots","Erzeugen von Audioinhalten für Zugänglichkeitsfunktionen","Debuggen von Text-to-Speech-Ausgaben für Sprachassistenten"],"pt":["Automatizar interações de voz para chatbots","Gerar conteúdo de áudio para recursos de acessibilidade","Depurar saídas de texto-para-fala para assistentes de voz"],"ru":["Автоматизация голосовых взаимодействий для чат-ботов","Генерация аудиоконтента для функций доступности","Отладка выходных данных текста в речь для голосовых помощников"],"ar":["تحويل التفاعلات الصوتية تلقائيًا للrobots المحادثة","генерация محتوى صوتي لميزات الوصول","تصحيح أخطاء إخراج النص إلى الكلام لمساعدي الصوت"]},"limitations":{"en":["Requires local TTS script installation","Needs custom voice models for personalized speech synthesis","Dependent on Python environment and uv run protocol"],"zh":["需要本地TTS脚本安装","需要自定义语音模型用于个性化语音合成","依赖Python环境和uv run协议"],"ja":["ローカルのTTSスクリプトのインストールが必要","パーソナライズされた音声合成のためにカスタムボイスモデルが必要","Python環境とuv runプロトコルに依存する"],"ko":["로컬 TTS 스크립트 설치가 필요","개인화된 음성 합성에 사용자 정의 보이스 모델이 필요","Python 환경 및 uv run 프로토콜에 의존"],"es":["Requiere la instalación de un script de TTS local","Necesita modelos de voz personalizados para la síntesis de habla personalizada","Dependiente del entorno de Python y del protocolo uv run"],"fr":["Nécessite l''installation d''un script TTS local","A besoin de modèles de voix personnalisés pour la synthèse de parole personnalisée","Dépend de l''environnement Python et du protocole uv run"],"de":["Erfordert die Installation eines lokalen TTS-Skripts","Benötigt benutzerdefinierte Sprachmodelle für die personalisierte Sprachsynthese","Hängt von der Python-Umgebung und dem uv-run-Protokoll ab"],"pt":["Exige instalação de script TTS local","Necessita de modelos de voz personalizados para síntese de fala personalizada","Dependente do ambiente Python e do protocolo uv run"],"ru":["Требует локальной установки скрипта TTS","Требует индивидуальных моделей голоса для персонализированной синтеза речи","Зависит от среды Python и протокола uv run"],"ar":["يتطلب تثبيت برنامج نصي TTS محلي","يحتاج إلى نماذج صوتية مخصصة لل合成 الصوتية المخصصة","يعتمد على بيئة Python وبروتوكول uv run"]},"version":4},"contentHash":"a75f883527c896264172ef4244f091ba20a1ff66e16c4b7d9fa789cfff254d18","qualityScore":41}');
