INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('markus41/lobbi-design-system/restapi', 'restapi', 'markus41', 'lobbi-design-system', 'community', 'restapi markus41 lobbi-design-system community The restapi skill provides comprehensive REST API design and implementation capabilities for AI Agent Fleet Platform, benefiting developers working with API endpoint design and HTTP request/response handling. REST API 技术提供了综合的 API 设计和实现能力，包括 API 端点设计、HTTP 请求/响应处理和 API 身份验证 REST API 技術は、API エンドポイント設計、HTTP リクエスト/レスポンス処理、API 認証など、包括的な API デザインと実装機能を提供します - AIエージェント REST API 기술은 API 엔드포인트 설계, HTTP 요청/응답 처리, API 인증 등을 포함한 포괄적인 API 설계 및 구현 기능을 제공합니다 - AI 에이전트 La habilidad de API REST proporciona capacidades de diseño y implementación de API REST para plataformas de gestión de miembros La compétence API REST fournit des capacités de conception et de mise en œuvre d''API REST pour les plateformes de gestion des membres Die REST-API-Fähigkeit bietet REST-API-Design- und Implementierungsfunktionen für Mitgliederverwaltungsplattformen O skill restapi fornece capacidades de design e implementação de API REST para plataformas de gerenciamento de membros. Aprenda a criar endpoints de API e lidar com solicitações HTTP. Навык restapi предоставляет возможности проектирования и реализации REST API для платформ управления членами. Узнайте, как создавать точки окончания API и обрабатывать запросы HTTP. مهارة restapi توفر إمكانيات تصميم وتنفيذ واجهات برمجة التطبيقات REST لأنظمة إدارة الأعضاء. تعرف على كيفية إنشاء نقاط النهاية واجهة برمجة التطبيقات ومعالجة الطلبات HTTP how to use restapi restapi setup guide restapi vs graphql restapi alternative restapi install what is restapi restapi best practices restapi tutorial restapi documentation REST API 设计 API 实现 HTTP 请求/响应 API 身份验证 OpenAPI 文档 API 测试 AI Agent AI 工具 API endpoint design using resource naming conventions HTTP request/response handling with support for GET, POST, PUT, and DELETE methods API authentication and authorization OpenAPI documentation generation API testing and validation restapi is a skill that provides comprehensive REST API design and implementation capabilities for the Golden Armada AI Agent Fleet Platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xqt2023-ux/Description/Sharing Skills', 'community', 'xqt2023-ux', 'Description', 'xqt2023-ux/Description', 'Sharing Skills', 0, 0, 41, '2026-02-16T04:29:25Z', '2026-03-07T03:40:46.320Z', 'c896e646f1ea27b6e897f55b732fb9e269365593df34071694d5d0ab68a2e888', '{"id":"xqt2023-ux/Description/Sharing Skills","name":"Sharing Skills","description":{"en":"The Sharing Skills AI agent skill enables developers to contribute skills from their local branch back to the upstream repository, following a workflow of branch, edit, commit, push, and PR. This skill benefits developers who want to share broadly applicable skills.","zh":"共享您的AI工具技能，提高可重用性和合作性。通过Branch、Edit/Create、Commit、Push和PR的工作流，简化技能共享","ja":"AIエージェントのスキルを共有して再利用性とコラボレーションを高めましょう。Branch、Edit/Create、Commit、Push、PRのワークフローでスキル共有を簡素化","ko":"AI 에이전트 스킬을 공유하여 재사용성과 협업을 높여보세요. Branch, Edit/Create, Commit, Push, PR의 워크플로우로 스킬 공유를 간소화","es":"Compartir habilidades en AI Agent implica contribuir a la comunidad mediante la creación y edición de habilidades","fr":"Le partage de compétences avec les outils d''IA consiste à contribuer à la communauté en créant et en éditant des compétences","de":"Das Teilen von Fähigkeiten mit KI-Tools beinhaltet die Beitrag zur Community durch die Erstellung und Bearbeitung von Fähigkeiten","pt":"Compartilhe habilidades de forma eficaz com o workflow de ramificação, edição, commit e push para repositórios upstream","ru":"Делитесь навыками эффективно с помощью рабочего процесса ветвления, редактирования, коммита и пуша в репозитории upstream","ar":"شارك المهارات بفعالية مع تدفق العمل الفرعي، التعديل، الالتزام والدفع إلى المستودعات Upstream"},"seo":{"title":{"en":"Sharing Skills: Contributing to Upstream Repository | AI ...","zh":"AI工具技能共享设置指南","ja":"AIエージェントのスキル共有ベストプラクティス","ko":"AI 에이전트 스킬 공유 가이드","es":"Guía de configuración para compartir habilidades en AI Agent","fr":"Configurer le partage de compétences avec les outils d''IA","de":"Einrichten des Skill-Sharings mit KI-Tools","pt":"Guia de Configuração de Compartilhamento de Habilidades p...","ru":"Руководство по Настройке Обмена Навыками для ИИ Агентов","ar":"دليل إعداد مشاركة المهارات لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to share your skills with the community, learn best practices for contributing to the upstream repository, and get started with our step-by-step...","zh":"了解如何共享您的AI工具技能，包括工作流、Commit和Push，提高技能的可重用性","ja":"AIエージェントのスキルを共有する方法を学び、ワークフロー、Commit、Pushを最適化してスキルの再利用性を高めましょう","ko":"AI 에이전트 스킬 공유 방법을 알아보고 워크플로우, Commit, Push를 최적화하여 스킬의 재사용성을 높여보세요","es":"Aprende a compartir habilidades en AI Agent de manera efectiva. Descubre los mejores prácticas para contribuir a la comunidad","fr":"Découvrez comment partager des compétences avec les outils d''IA pour améliorer la collaboration","de":"Erfahren Sie, wie Sie Fähigkeiten mit KI-Tools teilen, um die Zusammenarbeit zu verbessern","pt":"Aprenda a compartilhar habilidades de forma eficaz com o guia de configuração de compartilhamento de habilidades para ferramentas de IA","ru":"Узнайте, как эффективно делиться навыками с помощью руководства по настройке обмена навыками для ИИ агентов","ar":"تعلم كيفية مشاركة المهارات بفعالية مع دليل إعداد مشاركة المهارات لأدوات الذكاء الاصطناعي"},"definition":{"en":"Sharing Skills is a workflow that allows developers to contribute skills from their local branch to the upstream repository, following guidelines for sharing and documentation","zh":"技能共享是指将本地分支的技能贡献回上游仓库的过程","ja":"スキル共有とは、ローカルブランチのスキルをアップストリームリポジトリに貢献するプロセス","ko":"스킬 공유는 로컬 브랜치의 스킬을 업스트림 저장소에 기여하는 프로세스","es":"El intercambio de habilidades es el proceso de contribuir habilidades desde una rama local a un repositorio principal","fr":"Le partage de compétences est le processus de contribution de compétences depuis une branche locale à un référentiel principal","de":"Das Teilen von Fähigkeiten ist der Prozess der Beitrag von Fähigkeiten von einem lokalen Branch zu einem Hauptrepository","pt":"Compartilhamento de habilidades é o processo de contribuir habilidades locais para repositórios upstream","ru":"Обмен навыками - это процесс внесения вклада в местные навыки в репозитории upstream","ar":"مشاركة المهارات هي عملية المساهمة في المهارات المحلية إلى المستودعات Upstream"},"features":{"en":["Follows a workflow of Branch → Edit/Create skill → Commit → Push → PR","Allows sharing of skills that apply broadly, not project-specific","Enforces guidelines for well-tested and documented skills","Supports skills that follow skills/meta/writing-skills guidelines","Excludes project-specific, experimental, or unstable skills","Handles sensitive information by keeping it personal"],"zh":["通过Branch、Edit/Create、Commit、Push和PR的工作流共享技能","支持将技能应用于广泛的场景，而不仅仅是项目特定","遵循技能/meta/writing-skills指南，确保技能质量","允许保持个人技能，适用于项目特定或实验性技能","简化技能共享和协作，提高团队效率"],"ja":["Branch、Edit/Create、Commit、Push、PRのワークフローでスキルを共有","スキルをプロジェクト特有ではなく広範なシナリオに適用可能","スキル/meta/writing-skillsガイドラインに従い、スキルの品質を確保","個人用スキルを保持可能、プロジェクト特有または実験的スキルに適","スキル共有とコラボレーションを簡素化、チームの効率を高める"],"ko":["Branch, Edit/Create, Commit, Push, PR의 워크플로우로 스킬을 공유","스킬을 프로젝트 특정ではなく 광범위한 시나리오에 적용 가능","스킬/meta/writing-skills 가이드라인을 따르며, 스킬의 품질을 보장","개인용 스킬을 유지 가능, 프로젝트 특정 또는 실험적인 스킬에 적","스킬 공유와 협업을 간소화, 팀의 효율성을 높임"],"es":["Creación y edición de habilidades en una rama local","Commit y push de cambios a un repositorio principal","Creación de solicitudes de extracción (PR) para revisar y aprobar cambios","Seguimiento de las pautas de escritura de habilidades para mantener la calidad","Comprobación de que las habilidades sean ampliamente aplicables y bien documentadas"],"fr":["Création et édition de compétences dans une branche locale","Commit et push des modifications vers un référentiel principal","Création de demandes d''extraction (PR) pour examiner et approuver les modifications","Suivi des directives d''écriture de compétences pour maintenir la qualité","Vérification que les compétences soient largement applicables et bien documentées"],"de":["Erstellung und Bearbeitung von Fähigkeiten in einem lokalen Branch","Commit und Push von Änderungen an ein Hauptrepository","Erstellung von Pull-Requests (PR) zur Überprüfung und Genehmigung von Änderungen","Einhalten der Richtlinien für die Erstellung von Fähigkeiten, um die Qualität zu gewährleisten","Überprüfung, ob die Fähigkeiten breit anwendbar und gut dokumentiert sind"],"pt":["Workflow de ramificação para edição e criação de habilidades","Commit e push para repositórios upstream","Criação de pull requests para revisão e aprovação","Seguimento das diretrizes de escrita de habilidades","Compartilhamento de habilidades amplamente aplicáveis"],"ru":["Рабочий процесс ветвления для редактирования и создания навыков","Коммит и пуш в репозитории upstream","Создание запросов на вытягивание для рассмотрения и утверждения","Соблюдение руководства по написанию навыков","Обмен навыками, широко применимыми"],"ar":["تدفق العمل الفرعي لتعديل وإنشاء المهارات","الالتزام والدفع إلى المستودعات Upstream","إنشاء طلبات السحب لمراجعة والموافقة","متابعة إرشادات كتابة المهارات","مشاركة المهارات التي تطبيقها واسع"]},"keywords":{"en":["how to use Sharing Skills","what is Sharing Skills","Sharing Skills alternative","Sharing Skills vs GitHub","Sharing Skills install","Sharing Skills setup guide","contributing to upstream repository","skill sharing best practices","AI agent skill development"],"zh":["AI工具技能共享","技能共享设置指南","AI工具技能开发","技能共享工作流","Commit和Push","技能重用","AI工具协作"],"ja":["AIエージェントのスキル共有","スキル共有ベストプラクティス","AIエージェントのスキル開発","スキル共有ワークフロー","CommitとPush","スキルの再利用","AIエージェントのコラボレーション"],"ko":["AI 에이전트 스킬 공유","스킬 공유 가이드","AI 에이전트 스킬 개발","스킬 공유 워크플로우","Commit과 Push","스킬 재사용","AI 에이전트 협업"],"es":["compartir habilidades AI Agent","configurar habilidades en AI Agent","mejores prácticas para compartir habilidades","colaboración en AI Agent","creación de habilidades en AI Agent","edición de habilidades en AI Agent","contribuir a la comunidad AI Agent"],"fr":["partager des compétences avec les outils d''IA","configurer des compétences avec les outils d''IA","meilleures pratiques pour partager des compétences","collaboration avec les outils d''IA","création de compétences avec les outils d''IA","édition de compétences avec les outils d''IA","contribuer à la communauté des outils d''IA"],"de":["Fähigkeiten mit KI-Tools teilen","Fähigkeiten mit KI-Tools konfigurieren","Best Practices für das Teilen von Fähigkeiten","Zusammenarbeit mit KI-Tools","Erstellung von Fähigkeiten mit KI-Tools","Bearbeitung von Fähigkeiten mit KI-Tools","Beitrag zur Community von KI-Tools"],"pt":["compartilhamento de habilidades","ferramentas de IA","repositórios upstream","workflow de ramificação","commit e push","pull requests","diretrizes de escrita de habilidades","desenvolvimento de habilidades","IA e desenvolvimento"],"ru":["обмен навыками","ИИ агенты","репозитории upstream","рабочий процесс ветвления","коммит и пуш","запросы на вытягивание","руководство по написанию навыков","разработка навыков","ИИ и разработка"],"ar":["مشاركة المهارات","أدوات الذكاء الاصطناعي","مستودعات Upstream","تدفق العمل الفرعي","الالتزام والدفع","طلبات السحب","إرشادات كتابة المهارات","تطوير المهارات","الذكاء الاصطناعي وتطوير"]}},"owner":"xqt2023-ux","repo":"Description","repoPath":"xqt2023-ux/Description","stars":0,"forks":0,"updatedAt":"2026-02-16T04:29:25Z","topics":[],"category":"community","skillMd":{"name":"Sharing Skills","description":"Contribute skills back to upstream via branch and PR","version":"2.1.0","bodyPreview":"# Sharing Skills\n\n## Overview\n\nContribute skills from your local branch back to the upstream repository.\n\n**Workflow:** Branch → Edit/Create skill → Commit → Push → PR\n\n## When to Share\n\n**Share when:**\n- Skill applies broadly (not project-specific)\n- Pattern/technique others would benefit from\n- Well-tested and documented\n- Follows skills/meta/writing-skills guidelines\n\n**Keep personal when:**\n- Project-specific or organization-specific\n- Experimental or unstable\n- Contains sensitive informatio","body":"# Sharing Skills\n\n## Overview\n\nContribute skills from your local branch back to the upstream repository.\n\n**Workflow:** Branch → Edit/Create skill → Commit → Push → PR\n\n## When to Share\n\n**Share when:**\n- Skill applies broadly (not project-specific)\n- Pattern/technique others would benefit from\n- Well-tested and documented\n- Follows skills/meta/writing-skills guidelines\n\n**Keep personal when:**\n- Project-specific or organization-specific\n- Experimental or unstable\n- Contains sensitive information\n- Too narrow/niche for general use\n\n## Prerequisites\n\n- `gh` CLI installed and authenticated\n- Working directory is `~/.config/superpowers/skills/` (your local clone)\n- Skill has been tested (see skills/meta/writing-skills for TDD process)\n\n## Sharing Workflow\n\n### 1. Ensure You''re on Main and Synced\n\n```bash\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main  # Push to your fork\n```\n\n### 2. Create Feature Branch\n\n```bash\n# Branch name: add-skillname-skill\nskill_name=\"your-skill-name\"\ngit checkout -b \"add-${skill_name}-skill\"\n```\n\n### 3. Create or Edit Skill\n\n```bash\n# Work on your skill in skills/\n# Create new skill or edit existing one\n# Skill should be in skills/category/skill-name/SKILL.md\n```\n\n### 4. Commit Changes\n\n```bash\n# Add and commit\ngit add skills/your-skill-name/\ngit commit -m \"Add ${skill_name} skill\n\n$(cat <<''EOF''\nBrief description of what this skill does and why it''s useful.\n\nTested with: [describe testing approach]\nEOF\n)\"\n```\n\n### 5. Push to Your Fork\n\n```bash\ngit push -u origin \"add-${skill_name}-skill\"\n```\n\n### 6. Create Pull Request\n\n```bash\n# Create PR to upstream using gh CLI\ngh pr create \\\n  --repo upstream-org/upstream-repo \\\n  --title \"Add ${skill_name} skill\" \\\n  --body \"$(cat <<''EOF''\n## Summary\nBrief description of the skill and what problem it solves.\n\n## Testing\nDescribe how you tested this skill (pressure scenarios, baseline tests, etc.).\n\n## Context\nAny additional context about why this skill is needed and how it should be used.\nEOF\n)\"\n```\n\n## Complete Example\n\nHere''s a complete example of sharing a skill called \"async-patterns\":\n\n```bash\n# 1. Sync with upstream\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main\n\n# 2. Create branch\ngit checkout -b \"add-async-patterns-skill\"\n\n# 3. Create/edit the skill\n# (Work on skills/async-patterns/SKILL.md)\n\n# 4. Commit\ngit add skills/async-patterns/\ngit commit -m \"Add async-patterns skill\n\nPatterns for handling asynchronous operations in tests and application code.\n\nTested with: Multiple pressure scenarios testing agent compliance.\"\n\n# 5. Push\ngit push -u origin \"add-async-patterns-skill\"\n\n# 6. Create PR\ngh pr create \\\n  --repo upstream-org/upstream-repo \\\n  --title \"Add async-patterns skill\" \\\n  --body \"## Summary\nPatterns for handling asynchronous operations correctly in tests and application code.\n\n## Testing\nTested with multiple application scenarios. Agents successfully apply patterns to new code.\n\n## Context\nAddresses common async pitfalls like race conditions, improper error handling, and timing issues.\"\n```\n\n## After PR is Merged\n\nOnce your PR is merged:\n\n1. Sync your local main branch:\n```bash\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main\n```\n\n2. Delete the feature branch:\n```bash\ngit branch -d \"add-${skill_name}-skill\"\ngit push origin --delete \"add-${skill_name}-skill\"\n```\n\n## Troubleshooting\n\n**\"gh: command not found\"**\n- Install GitHub CLI: https://cli.github.com/\n- Authenticate: `gh auth login`\n\n**\"Permission denied (publickey)\"**\n- Check SSH keys: `gh auth status`\n- Set up SSH: https://docs.github.com/en/authentication\n\n**\"Skill already exists\"**\n- You''re creating a modified version\n- Consider different skill name or coordinate with the skill''s maintainer\n\n**PR merge conflicts**\n- Rebase on latest upstream: `git fetch upstream && git rebase upstream/main`\n- Resolve conflicts\n- Force push: `git push -f origin your-branch`\n\n## Multi-Skill Contributions\n\n**Do NOT batch multiple skills in one PR.**\n\nEach skill should:\n- Have its own feature branch\n- Have its own PR\n- Be independently reviewable\n\n**Why?** Individual skills can be reviewed, iterated, and merged independently.\n\n## Related Skills\n\n- **skills/meta/writing-skills** - How to create well-tested skills\n"},"lastSynced":"2026-03-07T03:40:46.320Z","agentAnalysis":{"suitability":{"en":"Ideal for Collaborative AI Agents like Cursor, Windsurf, and Claude Code seeking to contribute and share skills across repositories.","zh":"适合像Cursor、Windsurf和Claude Code这样的协作AI代理，旨在跨存储库贡献和共享技能。","ja":"Cursor、Windsurf、Claude CodeなどのコラボレーションAIエージェントに適しています。これらは、リポジトリ間でスキルを貢献して共有しようとします。","ko":"Cursor, Windsurf, Claude Code와 같은 협업 AI 에이전트에게 적합합니다. 이들은 저장소 간에 기술을 기여하고 공유하려고 합니다.","es":"Ideal para agentes de IA colaborativos como Cursor, Windsurf y Claude Code que buscan contribuir y compartir habilidades en varios repositorios.","fr":"Idéal pour les agents d''IA collaboratifs comme Cursor, Windsurf et Claude Code qui cherchent à contribuer et à partager des compétences à travers plusieurs référentiels.","de":"Ideal für kollaborative KI-Agents wie Cursor, Windsurf und Claude Code, die dazu beitragen und Fähigkeiten über Repositorys hinweg teilen möchten.","pt":"Ideal para Agentes de IA Colaborativos como Cursor, Windsurf e Claude Code que buscam contribuir e compartilhar habilidades em repositórios.","ru":"Идеально подходит для Коллаборативных ИИ Агентов, таких как Cursor, Windsurf и Claude Code, стремящихся внести свой вклад и поделиться навыками в репозиториях.","ar":"مثالي للوكلاء الذكاء الاصطناعي التعاوني مثل Cursor و Windsurf و Claude Code الذين يسعون للمساهمة ومشاركة المهارات عبر المستودعات."},"recommendation":{"en":"Empowers agents to contribute skills from their local branch back to the upstream repository, following a standardized workflow of branch, edit, commit, push, and PR, utilizing Git protocols and adhering to skills/meta/writing-skills guidelines.","zh":"赋予代理从其本地分支向上游存储库贡献技能的能力，遵循分支、编辑、提交、推送和PR的标准化工作流，利用Git协议并遵守skills/meta/writing-skills指南。","ja":"エージェントがローカルブランチからアップストリームリポジトリにスキルを貢献する能力を提供します。ブランチ、編集、コミット、プッシュ、PRの標準化されたワークフローに従い、Gitプロトコルを利用し、skills/meta/writing-skillsガイドラインに従います。","ko":"에이전트가 로컬 브랜치에서 업스트림 저장소로 기술을 기여할 수 있는 능력을 제공합니다. 브랜치, 편집, 커밋, 푸시, PR의 표준화된 워크플로우를 따르며 Git 프로토콜을 사용하고 skills/meta/writing-skills 가이드라인을遵守합니다.","es":"Permite a los agentes contribuir habilidades desde su rama local de vuelta al repositorio principal, siguiendo un flujo de trabajo estandarizado de rama, edición, confirmación, envío y PR, utilizando protocolos Git y ajustándose a las pautas de habilidades/meta/habilidades-de-escritura.","fr":"Permet aux agents de contribuer des compétences depuis leur branche locale vers le référentiel en amont, en suivant un workflow standardisé de branche, édition, validation, poussée et PR, en utilisant les protocoles Git et en respectant les directives de compétences/meta/compétences-d''écriture.","de":"Ermöglicht es Agents, Fähigkeiten von ihrem lokalen Branch zurück zum Hauptrepository beizutragen, indem sie einem standardisierten Workflow von Branch, Bearbeitung, Commit, Push und PR folgen, Git-Protokolle verwenden und den Richtlinien von Fähigkeiten/meta/Schreibfähigkeiten entsprechen.","pt":"Habilita os agentes a contribuir com habilidades da sua branch local de volta ao repositório upstream, seguindo um fluxo de trabalho padronizado de branch, edição, commit, push e PR, utilizando protocolos Git e seguindo as diretrizes skills/meta/writing-skills.","ru":"Наделяет агентов возможностью вносить свой вклад в навыки из их локальной ветки обратно в репозиторий upstream, следуя стандартизированному рабочему процессу создания ветки, редактирования, фиксации, отправки и создания запроса на слияние, используя протоколы Git и следуя руководящим принципам skills/meta/writing-skills.","ar":"يتمكن الوكلاء من المساهمة في المهارات من فرعهم المحلي إلى المستودع الرئيسي، متبعة عملية عمل معيارية لفرع، تحرير، تعهد، دفع ومراجعة، باستخدام بروتوكولات Git ومتوافقة مع إرشادات skills/meta/writing-skills."},"useCases":{"en":["Contributing broadly applicable skills to upstream repositories","Sharing well-tested and documented patterns or techniques with the developer community","Streamlining the workflow for editing, committing, and pushing skills to the upstream repository"],"zh":["向上游存储库贡献广泛适用的技能","与开发者社区共享经过良好测试和文档记录的模式或技术","简化编辑、提交和推送技能到上游存储库的工作流"],"ja":["アップストリームリポジトリに広く適用可能なスキルを貢献する","開発者コミュニティとよくテストされ、文書化されたパターンまたはテクニックを共有する","アップストリームリポジトリへのスキルの編集、コミット、プッシュのワークフローを簡素化する"],"ko":["업스트림 저장소에 광범위하게 적용 가능한 기술을 기여한다","개발자 커뮤니티와 잘 테스트되고 문서화된 패턴 또는 기술을 공유한다","업스트림 저장소로 기술을 편집, 커밋, 푸시하는 워크플로를简化한다"],"es":["Contribuir habilidades ampliamente aplicables a los repositorios principales","Compartir patrones o técnicas bien probados y documentados con la comunidad de desarrolladores","Optimizar el flujo de trabajo para la edición, confirmación y envío de habilidades al repositorio principal"],"fr":["Contribuer des compétences largement applicables aux référentiels en amont","Partager des modèles ou des techniques bien testés et documentés avec la communauté des développeurs","Optimiser le flux de travail pour l''édition, la validation et la poussée de compétences vers le référentiel en amont"],"de":["Beitragen von breit anwendbaren Fähigkeiten zu den Hauptrepositorys","Teilen von gut getesteten und dokumentierten Mustern oder Techniken mit der Entwicklergemeinschaft","Optimieren des Workflows für die Bearbeitung, Commit und Push von Fähigkeiten zum Hauptrepository"],"pt":["Contribuir habilidades de aplicação ampla para repositórios upstream","Compartilhar padrões ou técnicas bem testados e documentados com a comunidade de desenvolvedores","Otizar o fluxo de trabalho para edição, commit e envio de habilidades para o repositório upstream"],"ru":["Вносить свой вклад в навыки широкого применения в репозитории upstream","Делиться хорошо протестированными и задокументированными шаблонами или техниками с сообществом разработчиков","Оптимизировать рабочий процесс редактирования, фиксации и отправки навыков в репозиторий upstream"],"ar":["المساهمة في المهارات ذات التطبيق الواسع إلى المستودعات الرئيسية","مشاركة الأنماط أو التقنيات التي تم اختبارها وتوثيقها جيدًا مع مجتمع المطورين","تحسين تدفق العمل لتعديل والتعهد ودفع المهارات إلى المستودع الرئيسي"]},"limitations":{"en":["Requires adherence to skills/meta/writing-skills guidelines","Skills must be broadly applicable and not project-specific","Experimental or unstable skills should not be shared"],"zh":["需要遵守skills/meta/writing-skills指南","技能必须是广泛适用的，而不是项目特有的","实验性或不稳定的技能不应共享"],"ja":["skills/meta/writing-skillsガイドラインに従う必要がある","スキルはプロジェクト特有のものではなく、広く適用可能なものでなければならない","実験的または不安定なスキルは共有されずにすべきである"],"ko":["skills/meta/writing-skills 가이드라인을 따라야 한다","기술은 프로젝트 특有的 것이 아니라 광범위하게 적용 가능한 것이어야 한다","실험적 또는 불안정한 기술은 공유되어서는 안 된다"],"es":["Requiere la adherencia a las pautas de habilidades/meta/habilidades-de-escritura","Las habilidades deben ser ampliamente aplicables y no específicas del proyecto","Las habilidades experimentales o inestables no deben ser compartidas"],"fr":["Nécessite le respect des directives de compétences/meta/compétences-d''écriture","Les compétences doivent être largement applicables et non spécifiques au projet","Les compétences expérimentales ou instables ne doivent pas être partagées"],"de":["Erfordert die Einhaltung der Richtlinien von Fähigkeiten/meta/Schreibfähigkeiten","Fähigkeiten müssen breit anwendbar und nicht projektspezifisch sein","Experimentelle oder instabile Fähigkeiten sollten nicht geteilt werden"],"pt":["Exige aderência às diretrizes skills/meta/writing-skills","As habilidades devem ser de aplicação ampla e não específicas de projeto","As habilidades experimentais ou instáveis não devem ser compartilhadas"],"ru":["Требует соблюдения руководящих принципов skills/meta/writing-skills","Навыки должны быть широкого применения и не специфичны для проекта","Экспериментальные или нестабильные навыки не должны быть共享ены"],"ar":["يتطلب الالتزام بإرشادات skills/meta/writing-skills","المهارات يجب أن تكون ذات تطبيق واسع وليست محددة للمشروع","لا ينبغي مشاركة المهارات التجريبية أو غير المستقرة"]},"version":4},"contentHash":"c896e646f1ea27b6e897f55b732fb9e269365593df34071694d5d0ab68a2e888","qualityScore":41}');
