INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xqt2023-ux/Description/Sharing Skills', 'Sharing Skills', 'xqt2023-ux', 'Description', 'community', 'Sharing Skills xqt2023-ux Description community The Sharing Skills AI agent skill enables developers to contribute skills from their local branch back to the upstream repository, following a workflow of branch, edit, commit, push, and PR. This skill benefits developers who want to share broadly applicable skills. 共享您的AI工具技能，提高可重用性和合作性。通过Branch、Edit/Create、Commit、Push和PR的工作流，简化技能共享 AIエージェントのスキルを共有して再利用性とコラボレーションを高めましょう。Branch、Edit/Create、Commit、Push、PRのワークフローでスキル共有を簡素化 AI 에이전트 스킬을 공유하여 재사용성과 협업을 높여보세요. Branch, Edit/Create, Commit, Push, PR의 워크플로우로 스킬 공유를 간소화 Compartir habilidades en AI Agent implica contribuir a la comunidad mediante la creación y edición de habilidades Le partage de compétences avec les outils d''IA consiste à contribuer à la communauté en créant et en éditant des compétences Das Teilen von Fähigkeiten mit KI-Tools beinhaltet die Beitrag zur Community durch die Erstellung und Bearbeitung von Fähigkeiten Compartilhe habilidades de forma eficaz com o workflow de ramificação, edição, commit e push para repositórios upstream Делитесь навыками эффективно с помощью рабочего процесса ветвления, редактирования, коммита и пуша в репозитории upstream شارك المهارات بفعالية مع تدفق العمل الفرعي، التعديل، الالتزام والدفع إلى المستودعات Upstream how to use Sharing Skills what is Sharing Skills Sharing Skills alternative Sharing Skills vs GitHub Sharing Skills install Sharing Skills setup guide contributing to upstream repository skill sharing best practices AI agent skill development AI工具技能共享 技能共享设置指南 AI工具技能开发 技能共享工作流 Commit和Push 技能重用 AI工具协作 Follows a workflow of Branch → Edit/Create skill → Commit → Push → PR Allows sharing of skills that apply broadly, not project-specific Enforces guidelines for well-tested and documented skills Supports skills that follow skills/meta/writing-skills guidelines Excludes project-specific, experimental, or unstable skills Handles sensitive information by keeping it personal Sharing Skills is a workflow that allows developers to contribute skills from their local branch to the upstream repository, following guidelines for sharing and documentation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ITATA93/G_DeepResearch_Salud_Chile/Sharing Skills', 'community', 'ITATA93', 'G_DeepResearch_Salud_Chile', 'ITATA93/G_DeepResearch_Salud_Chile', 'Sharing Skills', 0, 0, 41, '2026-03-02T08:32:18Z', '2026-03-07T13:05:58.770Z', 'c896e646f1ea27b6e897f55b732fb9e269365593df34071694d5d0ab68a2e888', '{"id":"ITATA93/G_DeepResearch_Salud_Chile/Sharing Skills","name":"Sharing Skills","description":{"en":"Sharing Skills enables developers to contribute skills from their local branch to the upstream repository, following a workflow of branch, edit, commit, push, and PR. This skill benefits developers who want to share broadly applicable skills.","zh":"Sharing Skills允许开发者从本地分支向上游仓库贡献技能，遵循特定的工作流程和指南","ja":"Sharing Skillsは、開発者がローカルブランチからアップストリームリポジトリにスキルを貢献できるようにする、ワークフローとガイドラインに従った機能","ko":"Sharing Skills는 개발자가 로컬 분기에서 업스트림 저장소로 기술을 기여할 수 있는 워크플로우 및 가이드 라인을 따르는 기능","es":"Sharing Skills permite contribuir habilidades desde tu rama local al repositorio upstream. Sigue el flujo de trabajo para compartir habilidades ampliamente aplicables","fr":"Sharing Skills permet de contribuer des compétences depuis votre branche locale au référentiel upstream. Suivez le workflow pour partager des compétences largement applicables","de":"Sharing Skills ermöglicht es, Fähigkeiten von Ihrem lokalen Branch zum Upstream-Repository beizutragen. Befolgen Sie den Workflow, um weitgehend anwendbare Fähigkeiten zu teilen","pt":"Compartilhe habilidades do seu ramo local para o repositório upstream com o fluxo de trabalho Branch → Edit/Create skill → Commit → Push → PR","ru":"Обмен навыками из вашей локальной ветки с репозиторием upstream с помощью рабочего процесса Branch → Edit/Create skill → Commit → Push → PR","ar":"مشاركة المهارات من فرعك المحلي إلى المستودع الرئيسي باستخدام تدفق العمل Branch → Edit/Create skill → Commit → Push → PR"},"seo":{"t