INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ITATA93/G_DeepResearch_Salud_Chile/Sharing Skills', 'Sharing Skills', 'ITATA93', 'G_DeepResearch_Salud_Chile', 'community', 'Sharing Skills ITATA93 G_DeepResearch_Salud_Chile community Sharing Skills enables developers to contribute skills from their local branch to the upstream repository, following a workflow of branch, edit, commit, push, and PR. This skill benefits developers who want to share broadly applicable skills. Sharing Skills允许开发者从本地分支向上游仓库贡献技能，遵循特定的工作流程和指南 Sharing Skillsは、開発者がローカルブランチからアップストリームリポジトリにスキルを貢献できるようにする、ワークフローとガイドラインに従った機能 Sharing Skills는 개발자가 로컬 분기에서 업스트림 저장소로 기술을 기여할 수 있는 워크플로우 및 가이드 라인을 따르는 기능 Sharing Skills permite contribuir habilidades desde tu rama local al repositorio upstream. Sigue el flujo de trabajo para compartir habilidades ampliamente aplicables Sharing Skills permet de contribuer des compétences depuis votre branche locale au référentiel upstream. Suivez le workflow pour partager des compétences largement applicables Sharing Skills ermöglicht es, Fähigkeiten von Ihrem lokalen Branch zum Upstream-Repository beizutragen. Befolgen Sie den Workflow, um weitgehend anwendbare Fähigkeiten zu teilen Compartilhe habilidades do seu ramo local para o repositório upstream com o fluxo de trabalho Branch → Edit/Create skill → Commit → Push → PR Обмен навыками из вашей локальной ветки с репозиторием upstream с помощью рабочего процесса Branch → Edit/Create skill → Commit → Push → PR مشاركة المهارات من فرعك المحلي إلى المستودع الرئيسي باستخدام تدفق العمل Branch → Edit/Create skill → Commit → Push → PR how to use Sharing Skills what is Sharing Skills Sharing Skills alternative Sharing Skills vs GitHub Sharing Skills install Sharing Skills setup guide contribute to upstream repository skill sharing best practices AI agent skill development AIエージェント技能共享 Sharing Skills Setup Guide AI工具技能共享 技能共享工作流程 技能共享条件 技能共享指南 本地分支向上游仓库贡献技能 Follows skills/meta/writing-skills guidelines for documentation Supports branch, edit, commit, push, and PR workflow Allows sharing of skills that apply broadly, not project-specific Enables contribution of well-tested and documented skills Integrates with upstream repository for skill sharing Sharing Skills is a workflow that allows developers to contribute skills from their local branch to the upstream repository, following guidelines for sharing and documentation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ITATA93/G_Hospital_Organizador/Sharing Skills', 'community', 'ITATA93', 'G_Hospital_Organizador', 'ITATA93/G_Hospital_Organizador', 'Sharing Skills', 0, 0, 41, '2026-03-02T08:32:28Z', '2026-03-07T13:06:01.880Z', 'c896e646f1ea27b6e897f55b732fb9e269365593df34071694d5d0ab68a2e888', '{"id":"ITATA93/G_Hospital_Organizador/Sharing Skills","name":"Sharing Skills","description":{"en":"Sharing Skills enables developers to contribute skills from their local branch back to the upstream repository, benefiting the community with well-tested and documented skills","zh":"Sharing Skills允许您将本地分支的技能贡献回上游仓库，通过Branch、Edit/Create、Commit、Push和PR的工作流程","ja":"Sharing Skillsは、ローカルブランチのスキルをアップストリームリポジトリに貢献できるようにします。Branch、Edit/Create、Commit、Push、PRのワークフローを使用します","ko":"Sharing Skills를 통해 로컬 브랜치의 기술을 업스트림 저장소에 기여할 수 있습니다. 브랜치, 편집/생성, 커밋, 푸시 및 PR의 워크플로를 사용합니다","es":"Compartir habilidades permite contribuir con habilidades locales al repositorio upstream. Sigue el flujo de trabajo para compartir habilidades de manera efectiva.","fr":"Le partage de compétences permet de contribuer aux compétences locales au référentiel upstream. Suivez le flux de travail pour partager des compétences de manière efficace","de":"Das Teilen von Fähigkeiten ermöglicht es, lokale Fähigkeiten zum Upstream-Repository beizutragen. Befolgen Sie den Arbeitsfluss, um Fähigkeiten effektiv zu teilen","pt":"Compartilhe habilidades em projetos de satélite antigravidade com GEN_OS mirror e melhore a colaboração com Ferramentas de IA. Conheça o fluxo de trabalho para contribuir com habilidades para o repositório upstream.","ru":"Обменяйтесь навыками в проектах спутников с противовесом с помощью ИИ Агентов и GEN_OS mirror. Ознакомьтесь с рабочим процессом для внесения вклада в навыки в репозиторий upstream.","ar":"شارك المهارات في مشاريع الأقمار الصناعية مع المرآة GEN_OS وأدوات الإجابة الذكية. تعرف على تدفق العمل للمساهمة في المهارات في المستودع الرئيسي."},"seo":{"title":{"en":"Sharing Skills: Contribution Setup Guide | AI Agent Skill","zh":"Sharing Skills Setup Guide - AIエージェント技能共享","ja":"Sharing Skills ベストプラクティス - AIエージェントスキル共有","ko":"Sharing Skills 설정 가이드 - AI 에이전트 기술 공유","es":"Configuración de Compartir Habilidades: Guía para Agentes...","fr":"Partage de Compétences: Guide de Mise en Place pour les O...","de":"Freigabe von Fähigkeiten: Einrichtungsleitfaden für KI-Tools","pt":"Guia de Configuração do Compartilhamento de Habilidades c...","ru":"Руководство по настройке обмена навыками с помощью ИИ Аге...","ar":"دليل إعداد مشاركة المهارات مع أدوات الإجابة الذكية"},"description":{"en":"Discover how to share skills with the upstream repository, learn the workflow and best practices for contributing skills that apply broadly","zh":"了解如何共享技能以提高开发效率，包括技能共享的工作流程和最佳实践","ja":"開発効率を向上させるためにスキルを共有する方法について学びます。スキル共有のワークフローとベストプラクティスを紹介します","ko":"개발 효율을 높이기 위해 기술을 공유하는 방법에 대해 알아보세요. 기술 공유의 워크플로우와 최고의 관행을 소개합니다","es":"Aprende a compartir habilidades en proyectos de satélites antigravedad con GEN_OS mirror y mejora tu flujo de trabajo","fr":"Découvrez comment partager des compétences dans les projets de satellites antigravité avec GEN_OS mirror et améliorez votre flux de travail","de":"Erfahren Sie, wie Sie Fähigkeiten in Antigravitations-Satellitenprojekten mit GEN_OS Mirror teilen und Ihren Arbeitsfluss verbessern","pt":"Aprenda a compartilhar habilidades em projetos de satélite antigravidade com GEN_OS mirror e melhorar a colaboração com Ferramentas de IA","ru":"Узнайте, как делиться навыками в проектах спутников с противовесом с помощью ИИ Агентов и GEN_OS mirror","ar":"تعرف على كيفية مشاركة المهارات في مشاريع الأقمار الصناعية مع المرآة GEN_OS وأدوات الإجابة الذكية"},"definition":{"en":"Sharing Skills is a workflow for contributing skills to the upstream repository, following a branch, edit, commit, push, and PR process","zh":"Sharing Skills是一种技能共享机制，允许开发者共享和重用技能","ja":"Sharing Skillsは、開発者がスキルを共有して再利用できるスキル共有メカニズムです","ko":"Sharing Skills는 개발자가 기술을 공유하고 재사용할 수 있는 기술 공유 메커니즘입니다","es":"Compartir habilidades es una función que permite a los desarrolladores contribuir con habilidades locales al repositorio upstream","fr":"Le partage de compétences est une fonction qui permet aux développeurs de contribuer aux compétences locales au référentiel upstream","de":"Das Teilen von Fähigkeiten ist eine Funktion, die es Entwicklern ermöglicht, lokale Fähigkeiten zum Upstream-Repository beizutragen","pt":"Compartilhamento de habilidades é o processo de contribuir com habilidades para o repositório upstream, melhorando a colaboração em projetos de satélite antigravidade","ru":"Обмен навыками - это процесс внесения вклада в навыки в репозиторий upstream, улучшающий сотрудничество в проектах спутников с противовесом","ar":"مشاركة المهارات هي عملية المساهمة في المهارات في المستودع الرئيسي، مما يعزز التعاون في مشاريع الأقمار الصناعية"},"features":{"en":["Follows skills/meta/writing-skills guidelines for consistency","Supports sharing skills that apply broadly, not project-specific","Enables well-tested and documented skill contributions","Uses a standard workflow: Branch → Edit/Create skill → Commit → Push → PR","Helps developers share patterns and techniques that others can benefit from","Excludes project-specific, experimental, or unstable skills"],"zh":["支持Branch、Edit/Create、Commit、Push和PR的工作流程","允许开发者共享和重用技能","遵循skills/meta/writing-skills指南","支持技能的版本控制和协作","可以共享技能到上游仓库"],"ja":["Branch、Edit/Create、Commit、Push、PRのワークフローをサポート","開発者がスキルを共有して再利用できる","skills/meta/writing-skillsガイドラインに従う","スキルのバージョン管理とコラボレーションをサポート","スキルをアップストリームリポジトリに共有できる"],"ko":["브랜치, 편집/생성, 커밋, 푸시 및 PR의 워크플로를 지원","개발자가 기술을 공유하고 재사용할 수 있다","기술/메타/기술 작성 가이드라인을 따름","기술의 버전 관리와 협력을 지원","기술을 업스트림 저장소에 공유할 수 있다"],"es":["Permite contribuir con habilidades locales al repositorio upstream","Sigue el flujo de trabajo: Branch → Edit/Create skill → Commit → Push → PR","Compartir habilidades cuando son ampliamente aplicables y bien documentadas","Mantener habilidades personales cuando son específicas de un proyecto o organización","Utiliza GEN_OS mirror para migrar habilidades de AG_*","Mejora el flujo de trabajo con la función de compartir habilidades"],"fr":["Permet de contribuer aux compétences locales au référentiel upstream","Suivez le flux de travail : Branch → Edit/Create skill → Commit → Push → PR","Partager des compétences lorsqu''elles sont largement applicables et bien documentées","Conserver des compétences personnelles lorsqu''elles sont spécifiques à un projet ou une organisation","Utilisez GEN_OS mirror pour migrer des compétences de AG_*","Améliorez le flux de travail avec la fonction de partage de compétences"],"de":["Ermöglicht es, lokale Fähigkeiten zum Upstream-Repository beizutragen","Befolgen Sie den Arbeitsfluss: Branch → Edit/Create skill → Commit → Push → PR","Teilen Sie Fähigkeiten, wenn sie weitgehend anwendbar und gut dokumentiert sind","Behalten Sie Fähigkeiten persönlich, wenn sie spezifisch für ein Projekt oder eine Organisation sind","Verwenden Sie GEN_OS Mirror, um Fähigkeiten von AG_* zu migrieren","Verbessern Sie den Arbeitsfluss mit der Funktion zum Teilen von Fähigkeiten"],"pt":["Fluxo de trabalho para contribuir com habilidades","Compartilhamento de habilidades em projetos de satélite antigravidade","Uso de GEN_OS mirror para melhorar a colaboração","Seguimento das diretrizes de escrita de habilidades","Testes e documentação de habilidades","Criação de branches para edição e criação de habilidades"],"ru":["Рабочий процесс для внесения вклада в навыки","Обмен навыками в проектах спутников с противовесом","Использование GEN_OS mirror для улучшения сотрудничества","Следование руководящим принципам написания навыков","Тестирование и документация навыков","Создание веток для редактирования и создания навыков"],"ar":["تدفق العمل للمساهمة في المهارات","مشاركة المهارات في مشاريع الأقمار الصناعية","استخدام المرآة GEN_OS لتعزيز التعاون","اتباع إرشادات كتابة المهارات","اختبار ووثائق المهارات","إنشاء فروع لتعديل وإنشاء المهارات"]},"keywords":{"en":["how to use Sharing Skills","what is Sharing Skills","Sharing Skills alternative","Sharing Skills vs GitHub","Sharing Skills install","Sharing Skills setup guide","contribute to upstream repository","skill contribution workflow","Sharing Skills best practices"],"zh":["AIエージェント技能共享","技能共享机制","开发效率提升","技能重用","版本控制","协作开发","Sharing Skills","AI工具","技能共享指南"],"ja":["AIエージェントスキル共有","スキル共有メカニズム","開発効率向上","スキル再利用","バージョン管理","コラボレーション開発","Sharing Skills","AIツール","スキル共有ガイド"],"ko":["AI 에이전트 기술 공유","기술 공유 메커니즘","개발 효율 향상","기술 재사용","버전 관리","협력 개발","Sharing Skills","AI 도구","기술 공유 가이드"],"es":["compartir habilidades","agentes de inteligencia artificial","satélites antigravedad","GEN_OS mirror","flujo de trabajo","contribuir al repositorio upstream","desarrollo de habilidades","inteligencia artificial","herramientas de IA"],"fr":["partage de compétences","outils d''intelligence artificielle","satellites antigravité","GEN_OS mirror","flux de travail","contribuer au référentiel upstream","développement de compétences","intelligence artificielle","outils d''IA"],"de":["Teilen von Fähigkeiten","KI-Tools","Antigravitations-Satelliten","GEN_OS Mirror","Arbeitsfluss","Beitrag zum Upstream-Repository","Entwicklung von Fähigkeiten","Künstliche Intelligenz","KI-Tools"],"pt":["compartilhamento de habilidades","ferramentas de ia","satélite antigravidade","gen_os mirror","colaboração em projetos","fluxo de trabalho","contribuição de habilidades","repositório upstream","desenvolvimento de habilidades"],"ru":["обмен навыками","ии агенты","спутников с противовесом","gen_os mirror","сотрудничество в проектах","рабочий процесс","внесение вклада в навыки","репозиторий upstream","разработка навыков"],"ar":["مشاركة المهارات","أدوات الإجابة الذكية","الأقمار الصناعية","مرآة gen_os","التعاون في المشاريع","تدفق العمل","المساهمة في المهارات","المستودع الرئيسي","تطوير المهارات"]}},"owner":"ITATA93","repo":"G_Hospital_Organizador","repoPath":"ITATA93/G_Hospital_Organizador","stars":0,"forks":0,"updatedAt":"2026-03-02T08:32:28Z","topics":[],"category":"community","skillMd":{"name":"Sharing Skills","description":"Contribute skills back to upstream via branch and PR","version":"2.1.0","bodyPreview":"# Sharing Skills\n\n## Overview\n\nContribute skills from your local branch back to the upstream repository.\n\n**Workflow:** Branch → Edit/Create skill → Commit → Push → PR\n\n## When to Share\n\n**Share when:**\n- Skill applies broadly (not project-specific)\n- Pattern/technique others would benefit from\n- Well-tested and documented\n- Follows skills/meta/writing-skills guidelines\n\n**Keep personal when:**\n- Project-specific or organization-specific\n- Experimental or unstable\n- Contains sensitive informatio","body":"# Sharing Skills\n\n## Overview\n\nContribute skills from your local branch back to the upstream repository.\n\n**Workflow:** Branch → Edit/Create skill → Commit → Push → PR\n\n## When to Share\n\n**Share when:**\n- Skill applies broadly (not project-specific)\n- Pattern/technique others would benefit from\n- Well-tested and documented\n- Follows skills/meta/writing-skills guidelines\n\n**Keep personal when:**\n- Project-specific or organization-specific\n- Experimental or unstable\n- Contains sensitive information\n- Too narrow/niche for general use\n\n## Prerequisites\n\n- `gh` CLI installed and authenticated\n- Working directory is `~/.config/superpowers/skills/` (your local clone)\n- Skill has been tested (see skills/meta/writing-skills for TDD process)\n\n## Sharing Workflow\n\n### 1. Ensure You''re on Main and Synced\n\n```bash\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main  # Push to your fork\n```\n\n### 2. Create Feature Branch\n\n```bash\n# Branch name: add-skillname-skill\nskill_name=\"your-skill-name\"\ngit checkout -b \"add-${skill_name}-skill\"\n```\n\n### 3. Create or Edit Skill\n\n```bash\n# Work on your skill in skills/\n# Create new skill or edit existing one\n# Skill should be in skills/category/skill-name/SKILL.md\n```\n\n### 4. Commit Changes\n\n```bash\n# Add and commit\ngit add skills/your-skill-name/\ngit commit -m \"Add ${skill_name} skill\n\n$(cat <<''EOF''\nBrief description of what this skill does and why it''s useful.\n\nTested with: [describe testing approach]\nEOF\n)\"\n```\n\n### 5. Push to Your Fork\n\n```bash\ngit push -u origin \"add-${skill_name}-skill\"\n```\n\n### 6. Create Pull Request\n\n```bash\n# Create PR to upstream using gh CLI\ngh pr create \\\n  --repo upstream-org/upstream-repo \\\n  --title \"Add ${skill_name} skill\" \\\n  --body \"$(cat <<''EOF''\n## Summary\nBrief description of the skill and what problem it solves.\n\n## Testing\nDescribe how you tested this skill (pressure scenarios, baseline tests, etc.).\n\n## Context\nAny additional context about why this skill is needed and how it should be used.\nEOF\n)\"\n```\n\n## Complete Example\n\nHere''s a complete example of sharing a skill called \"async-patterns\":\n\n```bash\n# 1. Sync with upstream\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main\n\n# 2. Create branch\ngit checkout -b \"add-async-patterns-skill\"\n\n# 3. Create/edit the skill\n# (Work on skills/async-patterns/SKILL.md)\n\n# 4. Commit\ngit add skills/async-patterns/\ngit commit -m \"Add async-patterns skill\n\nPatterns for handling asynchronous operations in tests and application code.\n\nTested with: Multiple pressure scenarios testing agent compliance.\"\n\n# 5. Push\ngit push -u origin \"add-async-patterns-skill\"\n\n# 6. Create PR\ngh pr create \\\n  --repo upstream-org/upstream-repo \\\n  --title \"Add async-patterns skill\" \\\n  --body \"## Summary\nPatterns for handling asynchronous operations correctly in tests and application code.\n\n## Testing\nTested with multiple application scenarios. Agents successfully apply patterns to new code.\n\n## Context\nAddresses common async pitfalls like race conditions, improper error handling, and timing issues.\"\n```\n\n## After PR is Merged\n\nOnce your PR is merged:\n\n1. Sync your local main branch:\n```bash\ncd ~/.config/superpowers/skills/\ngit checkout main\ngit pull upstream main\ngit push origin main\n```\n\n2. Delete the feature branch:\n```bash\ngit branch -d \"add-${skill_name}-skill\"\ngit push origin --delete \"add-${skill_name}-skill\"\n```\n\n## Troubleshooting\n\n**\"gh: command not found\"**\n- Install GitHub CLI: https://cli.github.com/\n- Authenticate: `gh auth login`\n\n**\"Permission denied (publickey)\"**\n- Check SSH keys: `gh auth status`\n- Set up SSH: https://docs.github.com/en/authentication\n\n**\"Skill already exists\"**\n- You''re creating a modified version\n- Consider different skill name or coordinate with the skill''s maintainer\n\n**PR merge conflicts**\n- Rebase on latest upstream: `git fetch upstream && git rebase upstream/main`\n- Resolve conflicts\n- Force push: `git push -f origin your-branch`\n\n## Multi-Skill Contributions\n\n**Do NOT batch multiple skills in one PR.**\n\nEach skill should:\n- Have its own feature branch\n- Have its own PR\n- Be independently reviewable\n\n**Why?** Individual skills can be reviewed, iterated, and merged independently.\n\n## Related Skills\n\n- **skills/meta/writing-skills** - How to create well-tested skills\n"},"lastSynced":"2026-03-07T13:06:01.880Z","agentAnalysis":{"suitability":{"en":"Perfect for Community-Driven AI Agents needing collaborative skill development and contribution capabilities.","zh":"非常适合需要协作技能开发和贡献能力的社区驱动AI代理。","ja":"コラボレーションによるスキル開発とコントリビューション機能を必要とするコミュニティ主導のAIエージェントに最適です。","ko":"공동체 주도형 AI 에이전트가 협력형 스킬 개발 및 기여 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de IA impulsados por la comunidad que necesitan desarrollo colaborativo de habilidades y capacidades de contribución.","fr":"Parfait pour les Agents d''IA à impulsions communautaires ayant besoin de développement collaboratif de compétences et de capacités de contribution.","de":"Perfekt für communitygetriebene KI-Agents, die ein kollaboratives Skill-Entwicklung und Beitragshaltung benötigen.","pt":"Perfeito para Agentes de IA impulsionados pela comunidade que precisam de desenvolvimento de habilidades colaborativas e capacidades de contribuição.","ru":"Идеально подходит для агентов ИИ, управляемых сообществом, которым необходимы совместное развитие навыков и возможности внесения вклада.","ar":"مثالي للوكلاء الذكاء الاصطناعي الموجهة المجتمع التي تحتاج إلى تطوير المهارات التعاونية وقدرات المساهمة."},"recommendation":{"en":"Empowers agents to contribute well-tested and documented skills back to the upstream repository using Git workflow, including branching, committing, and pushing, while following skills/meta/writing-skills guidelines.","zh":"赋予代理将经过良好测试和文档化的技能贡献回上游仓库，使用Git工作流，包括分支、提交和推送，同时遵循skills/meta/writing-skills指南。","ja":"Gitワークフローを使用して、エージェントが上流リポジトリに十分にテストされ、文書化されたスキルをコントリブートできるようにし、ブランチ、コミット、プッシュを実行しながら、skills/meta/writing-skillsガイドラインに従う。","ko":"에이전트가 충분히 테스트되고 문서화된 스킬을 업스트림 저장소에 기여할 수 있도록 하며, Git 워크플로를 사용하여 브랜치, 커밋, 푸시를 thực行하면서 skills/meta/writing-skills 가이드라인을 따릅니다.","es":"Habilita a los agentes a contribuir habilidades bien probadas y documentadas de regreso al repositorio upstream utilizando el flujo de trabajo Git, incluyendo ramificación, confirmación y envío, mientras sigue las pautas de skills/meta/writing-skills.","fr":"Permet aux agents de contribuer des compétences bien testées et documentées au référentiel en amont en utilisant le workflow Git, y compris la création de branches, la validation et la publication, tout en suivant les directives de skills/meta/writing-skills.","de":"Ermächtigt Agents, gut getestete und dokumentierte Fähigkeiten an das upstream-Repository mithilfe des Git-Workflows zurückzugeben, einschließlich Branching, Committing und Pushing, während die Richtlinien von skills/meta/writing-skills befolgt werden.","pt":"Habilita os agentes a contribuir com habilidades bem testadas e documentadas para o repositório upstream usando o fluxo de trabalho Git, incluindo ramificação, confirmação e envio, seguindo as diretrizes de habilidades/meta/escrita-de-habilidades.","ru":"Наделяет агентов возможностью вносить хорошо протестированные и задокументированные навыки обратно в репозиторий upstream, используя рабочий процесс Git, включая ветвление, фиксацию и отправку, при этом следуя рекомендациям навыков/meta/написания-навыков.","ar":"يمكن للوكلاء المساهمة في المهارات التي تم اختبارها جيدًا وتوثيقها إلى المستودع الرئيسي باستخدام تدفق العمل Git ، بما في ذلك التفرع والالتزام والإرسال ، مع اتباع إرشادات المهارات / ميتا / كتابة المهارات."},"useCases":{"en":["Sharing broadly applicable skills with the community","Contributing well-documented patterns and techniques","Collaborating on skill development through pull requests"],"zh":["与社区共享广泛适用的技能","贡献良好文档的模式和技术","通过拉取请求协作开发技能"],"ja":["コミュニティと広く適用可能なスキルを共有する","十分に文書化されたパターンとテクニックをコントリブートする","プルリクエストを介したスキル開発のコラボレーション"],"ko":["공동체와 광범위하게 적용 가능한 스킬을 공유하는 것","충분히 문서화된 패턴 및 기술을 기여하는 것","풀 요청을 통한 스킬 개발 협업"],"es":["Compartir habilidades ampliamente aplicables con la comunidad","Contribuir patrones y técnicas bien documentados","Colaborar en el desarrollo de habilidades a través de solicitudes de extracción"],"fr":["Partager des compétences largement applicables avec la communauté","Contribuer des modèles et des techniques bien documentés","Collaborer au développement de compétences via des demandes d''extraction"],"de":["Breit anwendbare Fähigkeiten mit der Community teilen","Gut dokumentierte Muster und Techniken beisteuern","Bei der Entwicklung von Fähigkeiten durch Pull-Requests zusammenarbeiten"],"pt":["Compartilhamento de habilidades amplamente aplicáveis com a comunidade","Contribuição de padrões e técnicas bem documentados","Colaboração no desenvolvimento de habilidades por meio de solicitações de pull"],"ru":["Обмен навыками, широко применимыми в сообществе","Внесение хорошо задокументированных шаблонов и методов","Совместное развитие навыков посредством запросов на включение"],"ar":["مشاركة المهارات ذات التطبيق الواسع مع المجتمع","المساهمة في الأنماط والأشكال الموصى بها جيدًا","التعاون في تطوير المهارات من خلال طلبات السحب"]},"limitations":{"en":["Requires adherence to skills/meta/writing-skills guidelines","Excludes project-specific, experimental, or sensitive information","Needs Git version control system"],"zh":["需要遵守skills/meta/writing-skills指南","排除项目特定的、实验性的或敏感信息","需要Git版本控制系统"],"ja":["skills/meta/writing-skillsガイドラインに従う必要がある","プロジェクト固有の、実験的、または機密情報を除外する","Gitバージョン管理システムが必要"],"ko":["skills/meta/writing-skills 가이드라인을 따르는 것이 필요","프로젝트 고유의, 실험적이거나, 민감한 정보를 제외","Git 버전 관리 시스템이 필요"],"es":["Requiere la adhesión a las pautas de skills/meta/writing-skills","Excluye información específica del proyecto, experimental o sensible","Necesita el sistema de control de versiones Git"],"fr":["Nécessite l''adhésion aux directives de skills/meta/writing-skills","Exclut les informations spécifiques au projet, expérimentales ou sensibles","Nécessite le système de contrôle de version Git"],"de":["Erfordert die Einhaltung der Richtlinien von skills/meta/writing-skills","Schließt projektspezifische, experimentelle oder sensible Informationen aus","Benötigt das Git-Versionierungssystem"],"pt":["Exige aderência às diretrizes de habilidades/meta/escrita-de-habilidades","Exclui informações específicas do projeto, experimentais ou sensíveis","Necessita do sistema de controle de versão Git"],"ru":["Требует соблюдения рекомендаций навыков/meta/написания-навыков","Исключает проектно-специфическую, экспериментальную или конфиденциальную информацию","Требует системы контроля версий Git"],"ar":["يتطلب اتباع إرشادات المهارات / ميتا / كتابة المهارات","استبعاد المعلومات الخاصة بالمشروع أو التجريبية أو الحساسة","يحتاج إلى نظام التحكم في الإصدار Git"]},"version":4},"contentHash":"c896e646f1ea27b6e897f55b732fb9e269365593df34071694d5d0ab68a2e888","qualityScore":41}');
