INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ITATA93/G_Hospital_Organizador/Sharing Skills', 'Sharing Skills', 'ITATA93', 'G_Hospital_Organizador', 'community', 'Sharing Skills ITATA93 G_Hospital_Organizador community Sharing Skills enables developers to contribute skills from their local branch back to the upstream repository, benefiting the community with well-tested and documented skills Sharing Skills允许您将本地分支的技能贡献回上游仓库，通过Branch、Edit/Create、Commit、Push和PR的工作流程 Sharing Skillsは、ローカルブランチのスキルをアップストリームリポジトリに貢献できるようにします。Branch、Edit/Create、Commit、Push、PRのワークフローを使用します Sharing Skills를 통해 로컬 브랜치의 기술을 업스트림 저장소에 기여할 수 있습니다. 브랜치, 편집/생성, 커밋, 푸시 및 PR의 워크플로를 사용합니다 Compartir habilidades permite contribuir con habilidades locales al repositorio upstream. Sigue el flujo de trabajo para compartir habilidades de manera efectiva. Le partage de compétences permet de contribuer aux compétences locales au référentiel upstream. Suivez le flux de travail pour partager des compétences de manière efficace Das Teilen von Fähigkeiten ermöglicht es, lokale Fähigkeiten zum Upstream-Repository beizutragen. Befolgen Sie den Arbeitsfluss, um Fähigkeiten effektiv zu teilen Compartilhe habilidades em projetos de satélite antigravidade com GEN_OS mirror e melhore a colaboração com Ferramentas de IA. Conheça o fluxo de trabalho para contribuir com habilidades para o repositório upstream. Обменяйтесь навыками в проектах спутников с противовесом с помощью ИИ Агентов и GEN_OS mirror. Ознакомьтесь с рабочим процессом для внесения вклада в навыки в репозиторий upstream. شارك المهارات في مشاريع الأقمار الصناعية مع المرآة GEN_OS وأدوات الإجابة الذكية. تعرف على تدفق العمل للمساهمة في المهارات في المستودع الرئيسي. how to use Sharing Skills what is Sharing Skills Sharing Skills alternative Sharing Skills vs GitHub Sharing Skills install Sharing Skills setup guide contribute to upstream repository skill contribution workflow Sharing Skills best practices AIエージェント技能共享 技能共享机制 开发效率提升 技能重用 版本控制 协作开发 Sharing Skills AI工具 技能共享指南 Follows skills/meta/writing-skills guidelines for consistency Supports sharing skills that apply broadly, not project-specific Enables well-tested and documented skill contributions Uses a standard workflow: Branch → Edit/Create skill → Commit → Push → PR Helps developers share patterns and techniques that others can benefit from Excludes project-specific, experimental, or unstable skills Sharing Skills is a workflow for contributing skills to the upstream repository, following a branch, edit, commit, push, and PR process');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ritenoob/ridedine/vercel-deployment', 'community', 'Ritenoob', 'ridedine', 'Ritenoob/ridedine', 'vercel-deployment', 0, 0, 41, '2026-02-27T11:44:29Z', '2026-03-07T03:45:10.037Z', '1a83a88fc484bdd3d07b1b88d6065b957609ae3e28b6ba30266ad51af084699f', '{"id":"Ritenoob/ridedine/vercel-deployment","name":"vercel-deployment","description":{"en":"The Vercel-Deployment skill helps developers deploy Next.js apps to Vercel, managing separate projects, environment variables, and domain configurations. It benefits developers working on RidenDine projects.","zh":"Vercel 部署技能为 RidenDine 项目提供自动化部署和配置解决方案","ja":"Vercel デプロイメントスキルは、RidenDine プロジェクトの自動化デプロイと設定を提供します","ko":"Vercel 배포 기능은 RidenDine 프로젝트를 위한 자동화된 배포 및 설정 솔루션을 제공합니다","es":"El agente de vercel-deployment te ayuda a implementar tus aplicaciones Next.js en Vercel con facilidad. Configura variables de entorno y dominios personalizados para tus proyectos","fr":"L''outil de déploiement Vercel facilite la mise en production de vos applications Next.js sur Vercel. Configurez des variables d''environnement et des domaines personnalisés pour vos projets","de":"Das Vercel-Implementierungstool hilft Ihnen, Ihre Next.js-Anwendungen auf Vercel bereitzustellen. Konfigurieren Sie Umgebungsvariablen und benutzerdefinierte Domains für Ihre Projekte","pt":"O skill de implantação Vercel é usado para configurar a implantação de aplicativos Next.js no Vercel","ru":"ИИ Агенты для развертывания Vercel используются для настройки развертывания приложений Next.js","ar":"أداة تحكم في الإعدادات لتحديث Vercel تستخدم لضبط التطبيقات Next.js على منصة Vercel"},"seo":{"title":{"en":"Vercel-Deployment: Next.js Setup Guide | AI Agent Skill","zh":"Vercel 部署 Setup Guide - RidenDine 项目最佳实践","ja":"Vercel デプロイメントベストプラクティス - RidenDine プロジェクト AIエージェント","ko":"Vercel 배포 설정 가이드 - RidenDine 프로젝트 개발자 팁","es":"G