INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ritenoob/ridedine/vercel-deployment', 'vercel-deployment', 'Ritenoob', 'ridedine', 'community', 'vercel-deployment Ritenoob ridedine community The Vercel-Deployment skill helps developers deploy Next.js apps to Vercel, managing separate projects, environment variables, and domain configurations. It benefits developers working on RidenDine projects. Vercel 部署技能为 RidenDine 项目提供自动化部署和配置解决方案 Vercel デプロイメントスキルは、RidenDine プロジェクトの自動化デプロイと設定を提供します Vercel 배포 기능은 RidenDine 프로젝트를 위한 자동화된 배포 및 설정 솔루션을 제공합니다 El agente de vercel-deployment te ayuda a implementar tus aplicaciones Next.js en Vercel con facilidad. Configura variables de entorno y dominios personalizados para tus proyectos L''outil de déploiement Vercel facilite la mise en production de vos applications Next.js sur Vercel. Configurez des variables d''environnement et des domaines personnalisés pour vos projets Das Vercel-Implementierungstool hilft Ihnen, Ihre Next.js-Anwendungen auf Vercel bereitzustellen. Konfigurieren Sie Umgebungsvariablen und benutzerdefinierte Domains für Ihre Projekte O skill de implantação Vercel é usado para configurar a implantação de aplicativos Next.js no Vercel ИИ Агенты для развертывания Vercel используются для настройки развертывания приложений Next.js أداة تحكم في الإعدادات لتحديث Vercel تستخدم لضبط التطبيقات Next.js على منصة Vercel how to use vercel-deployment vercel-deployment setup guide next.js deployment on vercel vercel-deployment vs netlify vercel-deployment install debugging vercel-deployment build failures vercel-deployment environment variables custom domain setup with vercel-deployment vercel-deployment for ridendine projects Vercel 部署 Next.js 15 自动化部署 环境变量配置 自定义域名设置 预览部署 生产部署 构建失败调试 RidenDine 项目 Deploys Next.js 15 apps to separate Vercel projects Configures environment variables for each project Sets up custom domains for production deployments Manages preview deployments for PRs Handles production deployments on the main branch Debugs build failures for efficient troubleshooting Vercel-deployment is a skill that automates the deployment of Next.js applications to Vercel, handling tasks such as preview deployments and production deployments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ssimhan/meal-planner/frontend-ui', 'community', 'ssimhan', 'meal-planner', 'ssimhan/meal-planner', 'frontend-ui', 0, 0, 41, '2026-02-02T06:29:35Z', '2026-03-07T03:47:13.753Z', '72bf293c994b6691f7077a952e4f8e0cb0272214aeb0158a6454f0e2c68fddc6', '{"id":"ssimhan/meal-planner/frontend-ui","name":"frontend-ui","description":{"en":"The frontend-ui skill automates high-quality UI craft and strong UX thinking for React, HTML, and CSS projects, benefiting developers and designers. It enforces precise design systems and interaction models.","zh":"前端UI设计技能用于创建高质量的UI，使用React、HTML、CSS和设计系统","ja":"フロントエンドUI設計スキルは、React、HTML、CSS、デザインシステムを使用して高品質のUIを作成するために使用されます","ko":"프론트엔드 UI 설계는 React, HTML, CSS, 디자인 시스템을 사용하여 고품질의 UI를 생성하기 위해 사용됩니다","es":"El skill frontend-ui permite a los desarrolladores crear interfaces de usuario de alta calidad con tecnologías como React y HTML","fr":"Le skill frontend-ui permet aux développeurs de créer des interfaces utilisateur de haute qualité avec des technologies comme React et HTML","de":"Der frontend-ui-Skill ermöglicht es Entwicklern, Benutzeroberflächen von hoher Qualität mit Technologien wie React und HTML zu erstellen","pt":"O frontend-ui é uma habilidade que automatiza a criação de interfaces de usuário de alta qualidade com React, HTML e CSS.","ru":"Frontend-ui - это навык, который автоматизирует создание высококачественных интерфейсов пользователя с помощью React, HTML и CSS с использованием ИИ Агентов","ar":"frontend-ui هو مهارة تتيح إنشاء واجهات مستخدم عالية الجودة باستخدام React و HTML و CSS مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"frontend-ui: UI/UX Design Automation for React and HTML |...","zh":"前端UI设计最佳实践 - Meal Planning系统","ja":"フロントエンドUI設計ガイド - AIエージェントを使用したMeal Planning","ko":"프론트엔드 UI 설계 가이드 - Meal Planning 시스템","es":"Guía de configuración de frontend-ui para diseñadores","fr":"Guide de démarrage rapide pour les développeurs frontend-ui","de":"Einrichtungsleitfaden für frontend-ui-Entwickler","pt":"Guia de Configuração de frontend-ui para Desenvolvedores","ru":"Руководство по настройке frontend-ui для разработчиков с ...","ar":"دليل إعداد frontend-ui للمطورين باستخدام أدوات الذكاء الا..."},"description":{"en":"Unlock precise grid, spacing, and alignment in your frontend projects with frontend-ui. Discover how to automate UI craft and UX thinking today!","zh":"了解前端UI设计的最佳实践，使用React、HTML、CSS和设计系统创建高质量的UI","ja":"フロントエンドUI設計のベストプラクティスを学び、React、HTML、CSS、デザインシステムを使用して高品質のUIを作成する","ko":"프론트엔드 UI 설계의 최선의 방법을 알아보고 React, HTML, CSS, 디자인 시스템을 사용하여 고품질의 UI를 생성합니다","es":"Descubre cómo utilizar el skill frontend-ui para mejorar la calidad de tu UI y UX con tecnologías como React y HTML","fr":"Découvrez comment utiliser le skill frontend-ui pour améliorer la qualité de votre UI et UX avec des technologies comme React et HTML","de":"Erfahren Sie, wie Sie den frontend-ui-Skill verwenden können, um die Qualität Ihrer UI und UX mit Technologien wie React und HTML zu verbessern","pt":"Aprenda a configurar o frontend-ui com React, HTML e CSS para criar interfaces de usuário de alta qualidade","ru":"Узнайте, как настроить frontend-ui с помощью React, HTML и CSS для создания высококачественных интерфейсов пользователя с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد frontend-ui باستخدام React و HTML و CSS لإنشاء واجهات مستخدم عالية الجودة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"frontend-ui is a skill that automates UI/UX design for frontend and product-flow work, ensuring precise grid, spacing, alignment, and hierarchy in React, HTML, and CSS applications.","zh":"前端UI设计是指使用React、HTML、CSS和设计系统创建高质量的用户界面","ja":"フロントエンドUI設計とは、React、HTML、CSS、デザインシステムを使用して高品質のユーザーインターフェースを作成すること","ko":"프론트엔드 UI 설계는 React, HTML, CSS, 디자인 시스템을 사용하여 고품질의 사용자 인터페이스를 생성하는 것을 의미합니다","es":"El skill frontend-ui es una herramienta de diseño de UI/UX que ayuda a los desarrolladores a crear interfaces de usuario coherentes","fr":"Le skill frontend-ui est un outil de conception de UI/UX qui aide les développeurs à créer des interfaces utilisateur cohérentes","de":"Der frontend-ui-Skill ist ein Tool für das UI/UX-Design, das Entwicklern hilft, konsistente Benutzeroberflächen zu erstellen","pt":"Frontend-ui é uma habilidade de design de UI/UX que automatiza a criação de interfaces de usuário","ru":"Frontend-ui - это навык дизайна UI/UX, который автоматизирует создание интерфейсов пользователя","ar":"frontend-ui هو مهارة تصميم UI/UX التي تتيح إنشاء واجهات مستخدم"},"features":{"en":["Enforces precise grid, spacing, alignment, and hierarchy in React and HTML projects","Supports consistent radius and elevation in Enterprise Craft Mode","Automates UI craft and UX thinking for design systems and interaction models","Applies to React, HTML, CSS, and design systems","Selects optimal mode per project, including Enterprise Craft Mode","Ensures strong UX thinking for product surfaces and flows"],"zh":["使用React、HTML、CSS创建高质量的UI","支持设计系统和一致的radius、elevation","提供Enterprise Craft Mode和Grid、spacing、alignment、hierarchy的精确控制","适用于创建或修改UI、设计UX流程、产品表面或交互模型"],"ja":["React、HTML、CSSを使用して高品質のUIを作成","デザインシステムと一貫したradius、elevationのサポート","Enterprise Craft ModeとGrid、spacing、alignment、hierarchyの精密制御を提供","UIの作成や変更、UXフローの設計、製品サーフェスまたはインタラクションモデルの設計に適しています"],"ko":["React, HTML, CSS를 사용하여 고품질의 UI를 생성","디자인 시스템과 일관된 radius, elevation의 지원","Enterprise Craft Mode와 Grid, spacing, alignment, hierarchy의 정밀 제어를 제공","UI의 생성 또는 수정, UX 흐름의 설계, 제품 표면 또는 상호 작용 모델의 설계에 적합합니다"],"es":["Diseño de UI preciso con React y HTML","Creación de flujos de UX coherentes","Aplicación de sistemas de diseño consistentes","Uso de la técnica de grid y espaciado para una mejor alineación","Opción de modo de craft empresarial para proyectos de gran escala"],"fr":["Conception de UI précise avec React et HTML","Création de flux de UX cohérents","Application de systèmes de conception cohérents","Utilisation de la technique de grid et d''espacement pour une meilleure alignement","Option de mode de craft d''entreprise pour les projets de grande échelle"],"de":["Präzise UI-Design mit React und HTML","Erstellung konsistenter UX-Flüsse","Anwendung konsistenter Design-Systeme","Verwendung der Grid- und Abstandstechnik für eine bessere Ausrichtung","Option für den Unternehmens-Craft-Modus für große Projekte"],"pt":["Criação de interfaces de usuário com React","Desenvolvimento de UI com HTML e CSS","Design de UX com foco em grid, espaçamento e alinhamento","Modo de criação de empresas com precisão e consistência","Suporte a design systems"],"ru":["Создание интерфейсов пользователя с помощью React","Разработка UI с помощью HTML и CSS","Дизайн UX с фокусом на сетке, пространстве и выравнивании","Режим создания предприятий с точностью и последовательностью","Поддержка систем дизайна"],"ar":["إنشاء واجهات مستخدم مع React","تطوير UI مع HTML و CSS","تصميم UX مع التركيز على الشبكة والفراغ والتعيين","وضع إنشاء الشركات بدقة وثبات","دعم أنظمة التصميم"]},"keywords":{"en":["how to use frontend-ui","frontend-ui alternative","frontend-ui setup guide","what is frontend-ui","frontend-ui vs UX design tools","frontend-ui install for React","automating UI craft with frontend-ui","frontend-ui for HTML and CSS","frontend-ui design systems","frontend-ui interaction models"],"zh":["前端UI设计","React","HTML","CSS","设计系统","Enterprise Craft Mode","Grid","spacing","alignment","hierarchy"],"ja":["フロントエンドUI設計","React","HTML","CSS","デザインシステム","Enterprise Craft Mode","Grid","spacing","alignment","hierarchy","AIエージェント"],"ko":["프론트엔드 UI 설계","React","HTML","CSS","디자인 시스템","Enterprise Craft Mode","Grid","spacing","alignment","hierarchy","AIツール"],"es":["frontend-ui","diseño de UI","UX","React","HTML","sistemas de diseño","herramientas de diseño de UI","mejora de la calidad de la UI","desarrollo de frontend"],"fr":["frontend-ui","conception de UI","UX","React","HTML","systèmes de conception","outils de conception de UI","amélioration de la qualité de la UI","développement de frontend"],"de":["frontend-ui","UI-Design","UX","React","HTML","Design-Systeme","UI-Design-Tools","Verbesserung der UI-Qualität","Frontend-Entwicklung"],"pt":["frontend-ui","desenvolvimento de ui","design de ux","react","html","css","design systems","criação de interfaces de usuário"],"ru":["frontend-ui","разработка ui","дизайн ux","react","html","css","системы дизайна","создание интерфейсов пользователя","ИИ Агенты"],"ar":["frontend-ui","تطوير ui","تصميم ux","react","html","css","أنظمة التصميم","إنشاء واجهات مستخدم","أدوات الذكاء الاصطناعي"]}},"owner":"ssimhan","repo":"meal-planner","repoPath":"ssimhan/meal-planner","stars":0,"forks":0,"updatedAt":"2026-02-02T06:29:35Z","topics":[],"category":"community","skillMd":{"name":"frontend-ui","description":"Create aesthetically pleasing, visually distinctive frontend UIs using research-backed prompting strategies from Anthropics frontend aesthetics cookbook","bodyPreview":"# Claude UI/UX Design Skill\n\n## Purpose\n\nAutomatically enforce high‑quality UI craft and strong UX thinking for any frontend or product‑flow work.\n\n## Activation\n\nApply this skill when:\n\n* Creating or modifying UI (React, HTML, CSS, design systems)\n* Designing UX flows, product surfaces, or interaction models\n\n## Modes\n\nClaude selects one mode per project unless user specifies:\n\n### 1. Enterprise Craft Mode\n\n* Grid, spacing, alignment, and hierarchy must be precise\n* Consistent radius, elevation","body":"# Claude UI/UX Design Skill\n\n## Purpose\n\nAutomatically enforce high‑quality UI craft and strong UX thinking for any frontend or product‑flow work.\n\n## Activation\n\nApply this skill when:\n\n* Creating or modifying UI (React, HTML, CSS, design systems)\n* Designing UX flows, product surfaces, or interaction models\n\n## Modes\n\nClaude selects one mode per project unless user specifies:\n\n### 1. Enterprise Craft Mode\n\n* Grid, spacing, alignment, and hierarchy must be precise\n* Consistent radius, elevation, and component density\n* Predictable motion; performance‑first\n\n### 2. Aesthetic Mode\n\n* Strong visual personality\n* Theme exploration encouraged\n* Creative color, type, and layout choices\n\n## Design Direction\n\nRequired only for:\n\n* New pages\n* New product surfaces\n  Not required for minor edits or bug fixes.\n\n## Flow‑First Thinking\n\nBefore UI decisions, clarify:\n\n1. Purpose of the screen\n2. Primary user\n3. Emotional job (what should it *feel* like to succeed?)\n\n## Theme System\n\nTwo separate tracks:\n\n* Craft Track → layout, spacing, depth, hierarchy\n* Aesthetic Track → typography, palette, motion style\n\n## Typography\n\nClaude chooses fonts but must:\n\n* Match tone + audience\n* Justify the choice\n\n## Motion\n\n* Creative but quick\n* Default duration: 120–220ms\n* No distracting bounce or heavy physics\n* Always respect reduced‑motion\n\n## Brand Handling\n\nAsk for color palette if branding is desired.\nIf none is provided, proceed with a neutral system.\n\n## Output Standard\n\nEvery UI output must show:\n\n* Clear hierarchy\n* Visual intention\n* Consistent craft\n* Purposeful styling\n"},"lastSynced":"2026-03-07T03:47:13.753Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX-focused Agents needing precise design systems and interaction models for React, HTML, and CSS projects.","zh":"非常适合需要精确设计系统和交互模型的 UI/UX 集中型 Agents，用于 React、HTML 和 CSS 项目。","ja":"React、HTML、CSS プロジェクト向けに精密なデザイン システムとインタラクション モデルを必要とする UI/UX フォーカス型エージェントに最適です。","ko":"React, HTML, CSS 프로젝트를 위한 정密한 디자인 시스템과 상호 작용 모델이 필요한 UI/UX 중심 에이전트에게 적합합니다.","es":"Perfecto para agentes enfocados en UI/UX que necesitan sistemas de diseño precisos y modelos de interacción para proyectos de React, HTML y CSS.","fr":"Parfait pour les agents axés sur l''UI/UX nécessitant des systèmes de conception précis et des modèles d''interaction pour les projets React, HTML et CSS.","de":"Perfekt für UI/UX-fokussierte Agenten, die präzise Designsysteme und Interaktionsmodelle für React-, HTML- und CSS-Projekte benötigen.","pt":"Perfeito para Agentes focados em UI/UX que necessitam de sistemas de design precisos e modelos de interação para projetos React, HTML e CSS.","ru":"Идеально для агентов, ориентированных на UI/UX, которым необходимы точные системы дизайна и модели взаимодействия для проектов React, HTML и CSS.","ar":"مثالي للوكلاء الذين يركزون على UI/UX وذين يحتاجون إلى أنظمة تصميم دقيقة ونماذج تفاعل لمشاريع React و HTML و CSS."},"recommendation":{"en":"Empowers agents to enforce high-quality UI craft and strong UX thinking, utilizing precise grid, spacing, alignment, and hierarchy, as well as consistent radius and elevation for enterprise-level frontend development with React, HTML, and CSS.","zh":"赋予代理强大的 UI 设计能力和强大的 UX 思维能力，利用精密的网格、间距、对齐和层次结构，以及企业级前端开发中 React、HTML 和 CSS 的一致半径和高程。","ja":"エージェントに、高品質の UI クラフトと強力な UX 思考力を与え、正確なグリッド、スペーシング、整列、階層構造、および React、HTML、CSS を使用した企業レベルのフロントエンド開発における一貫した半径と高さを利用します。","ko":"에이전트에 고품질의 UI 공예와 강력한 UX 사고력을 부여하고, 정확한 격자, 간격, 정렬 및 계층 구조 및 React, HTML, CSS를 사용한 기업 수준의 프론트엔드 개발을 위한 일관된 반지름 및 고도를 활용합니다.","es":"Habilita a los agentes a aplicar una artesanía de UI de alta calidad y un pensamiento UX sólido, utilizando una cuadrícula precisa, espaciado, alineación y jerarquía, así como un radio y elevación consistentes para el desarrollo de frontend a nivel empresarial con React, HTML y CSS.","fr":"Permet aux agents d''appliquer un savoir-faire UI de haute qualité et une réflexion UX solide, en utilisant une grille précise, un espacement, un alignement et une hiérarchie, ainsi qu''un rayon et une élévation cohérents pour le développement frontend de niveau entreprise avec React, HTML et CSS.","de":"Ermächtigt Agenten, eine hochwertige UI-Handwerkskunst und ein starkes UX-Denken anzuwenden, indem sie eine präzise Raster, Abstand, Ausrichtung und Hierarchie sowie einen konsistenten Radius und eine Erhebung für die Unternehmensebene-frontend-Entwicklung mit React, HTML und CSS nutzen.","pt":"Habilita os agentes a impor artesanato de UI de alta qualidade e forte pensamento de UX, utilizando grade precisa, espaçamento, alinhamento e hierarquia, bem como raio e elevação consistentes para desenvolvimento de frontend de nível empresarial com React, HTML e CSS.","ru":"Наделяет агентов возможностью обеспечивать высококачественное ремесло UI и сильную мысль UX, используя точную сетку, расстояние, выравнивание и иерархию, а также постоянный радиус и высоту для разработки frontend корпоративного уровня с React, HTML и CSS.","ar":"يمنح الوكلاء القدرة على فرض حرفة UI عالية الجودة و思考 UX القوي، باستخدام شبكة دقيقة، ومسافة، وترتيب، وهرمية، بالإضافة إلى نصف قطر وارتفاع ثابتين لتطوير واجهة المستخدم الأمامية على مستوى المؤسسة مع React و HTML و CSS."},"useCases":{"en":["Automating UI design for React applications","Generating consistent design systems for HTML and CSS projects","Optimizing UX flows and interaction models for product surfaces"],"zh":["为 React 应用程序自动化 UI 设计","为 HTML 和 CSS 项目生成一致的设计系统","优化产品表面上的 UX 流程和交互模型"],"ja":["React アプリケーションの UI デザインを自動化する","HTML と CSS プロジェクト向けに一貫したデザイン システムを生成する","製品サーフェスの UX フローとインタラクション モデルを最適化する"],"ko":["React 애플리케이션의 UI 디자인 자동화","HTML 및 CSS 프로젝트를 위한 일관된 디자인 시스템 생성","제품 표면의 UX 흐름 및 상호 작용 모델 최적화"],"es":["Automatizar el diseño de UI para aplicaciones React","Generar sistemas de diseño coherentes para proyectos HTML y CSS","Optimizar flujos UX y modelos de interacción para superficies de producto"],"fr":["Automatiser la conception d''UI pour les applications React","Générer des systèmes de conception cohérents pour les projets HTML et CSS","Optimiser les flux UX et les modèles d''interaction pour les surfaces de produits"],"de":["Automatisieren des UI-Designs für React-Anwendungen","Erzeugen konsistenter Designsysteme für HTML- und CSS-Projekte","Optimieren von UX-Fluss und Interaktionsmodellen für Produktoberflächen"],"pt":["Automatizar o design de UI para aplicações React","Gerar sistemas de design consistentes para projetos HTML e CSS","Otimizar fluxos de UX e modelos de interação para superfícies de produto"],"ru":["Автоматизировать дизайн UI для приложений React","Генерировать последовательные системы дизайна для проектов HTML и CSS","Оптимизировать потоки UX и модели взаимодействия для поверхностей продукта"],"ar":["توفير تصميم واجهة المستخدم تلقائيًا لتطبيقات React","توليد أنظمة تصميم متسقة لمشاريع HTML و CSS","تحسين تدفقات UX ونماذج التفاعل لسطحيات المنتج"]},"limitations":{"en":["Requires precise design specifications","Limited to React, HTML, and CSS projects"],"zh":["需要精确的设计规格","仅限 React、HTML 和 CSS 项目"],"ja":["正確な設計仕様が必要","React、HTML、CSS プロジェクトのみに限定される"],"ko":["정확한 디자인 사양 필요","React, HTML, CSS 프로젝트에만 제한됨"],"es":["Requiere especificaciones de diseño precisas","Limitado a proyectos de React, HTML y CSS"],"fr":["Nécessite des spécifications de conception précises","Limité aux projets React, HTML et CSS"],"de":["Benötigt präzise Designspezifikationen","Begrenzt auf React-, HTML- und CSS-Projekte"],"pt":["Exige especificações de design precisas","Limitado a projetos React, HTML e CSS"],"ru":["Требует точных спецификаций дизайна","Ограничен проектами React, HTML и CSS"],"ar":["يتطلب مواصفات تصميم دقيقة","محدود بمشاريع React و HTML و CSS"]},"version":4},"contentHash":"72bf293c994b6691f7077a952e4f8e0cb0272214aeb0158a6454f0e2c68fddc6","qualityScore":41}');
