INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ssimhan/meal-planner/frontend-ui', 'frontend-ui', 'ssimhan', 'meal-planner', 'community', 'frontend-ui ssimhan meal-planner community The frontend-ui skill automates high-quality UI craft and strong UX thinking for React, HTML, and CSS projects, benefiting developers and designers. It enforces precise design systems and interaction models. 前端UI设计技能用于创建高质量的UI，使用React、HTML、CSS和设计系统 フロントエンドUI設計スキルは、React、HTML、CSS、デザインシステムを使用して高品質のUIを作成するために使用されます 프론트엔드 UI 설계는 React, HTML, CSS, 디자인 시스템을 사용하여 고품질의 UI를 생성하기 위해 사용됩니다 El skill frontend-ui permite a los desarrolladores crear interfaces de usuario de alta calidad con tecnologías como React y HTML Le skill frontend-ui permet aux développeurs de créer des interfaces utilisateur de haute qualité avec des technologies comme React et HTML Der frontend-ui-Skill ermöglicht es Entwicklern, Benutzeroberflächen von hoher Qualität mit Technologien wie React und HTML zu erstellen O frontend-ui é uma habilidade que automatiza a criação de interfaces de usuário de alta qualidade com React, HTML e CSS. Frontend-ui - это навык, который автоматизирует создание высококачественных интерфейсов пользователя с помощью React, HTML и CSS с использованием ИИ Агентов frontend-ui هو مهارة تتيح إنشاء واجهات مستخدم عالية الجودة باستخدام React و HTML و CSS مع أدوات الذكاء الاصطناعي how to use frontend-ui frontend-ui alternative frontend-ui setup guide what is frontend-ui frontend-ui vs UX design tools frontend-ui install for React automating UI craft with frontend-ui frontend-ui for HTML and CSS frontend-ui design systems frontend-ui interaction models 前端UI设计 React HTML CSS 设计系统 Enterprise Craft Mode Grid spacing alignment hierarchy Enforces precise grid, spacing, alignment, and hierarchy in React and HTML projects Supports consistent radius and elevation in Enterprise Craft Mode Automates UI craft and UX thinking for design systems and interaction models Applies to React, HTML, CSS, and design systems Selects optimal mode per project, including Enterprise Craft Mode Ensures strong UX thinking for product surfaces and flows frontend-ui is a skill that automates UI/UX design for frontend and product-flow work, ensuring precise grid, spacing, alignment, and hierarchy in React, HTML, and CSS applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('himatts/LimePipeline/package-addon', 'community', 'himatts', 'LimePipeline', 'himatts/LimePipeline', 'package-addon', 0, 0, 41, '2026-03-07T01:37:05Z', '2026-03-07T03:49:37.798Z', '4f6aea7fe92a485d4f4191a0d23cce9d2cf599d4f4febca0e18118dc786a6bb8', '{"id":"himatts/LimePipeline/package-addon","name":"package-addon","description":{"en":"The package-addon skill automates packaging of the lime_pipeline addon folder, benefiting developers by simplifying distribution and testing. It cleans source trees, runs tests, and computes hashes.","zh":"package-addon AI 工具包提供了便捷的方式来设置和部署 addon，包括清理源代码树、运行测试和打包 addon","ja":"package-addon AIエージェントは、アドオンの設定とデプロイを容易にする方法を提供します。ソースコードツリーのクリーンアップ、テストの実行、アドオンのパッケージ化など","ko":"package-addon AI 툴 패키지는 addon 설정과 배포를 쉽게 해주는 방법을 제공합니다. 소스 코드 트리 정리, 테스트 실행, addon 패키징 등","es":"Package-addon es una herramienta para empaquetar addons de manera efectiva. Permite la creación de paquetes de addons limpios y actualizados.","fr":"Package-addon est un outil pour empaqueter des addons de manière efficace. Il permet la création de paquets d''addons propres et à jour.","de":"Package-addon ist ein Tool zum Erstellen von Addon-Paketen. Es ermöglicht die Erstellung von sauberen und aktuellen Addon-Paketen.","pt":"O package-addon é uma ferramenta que ajuda a empacotar o addon de pipeline de forma eficiente","ru":"ИИ Агенты: package-addon - это инструмент, помогающий упаковывать аддон конвейера эффективно","ar":"أداة package-addon هي أداة تساعد في تغليف إضافة Pipeline بفعالية"},"seo":{"title":{"en":"package-addon: Automated Packaging Setup Guide | AI Agent...","zh":"AI工具包：package-addon.setup 指南","ja":"AIエージェント：package-addon セットアップガイド","ko":"AI 툴 패키지: package-addon 설정 가이드","es":"Configuración de package-addon: Guía de Empaquetado de Ad...","fr":"Guide de Configuration de package-addon: Bonnes Pratiques","de":"Einrichtung von package-addon: Leitfaden für Addon-Pakete","pt":"Guia de Configuração do package-addon para Desenvolvedores","ru":"ИИ Агенты: Настройка package-addon для Разработчиков","ar":"إعداد أداة package-addon للبرمجة"},"description":{"en":"Streamline your development workflow with package-addon, learn how to automate packaging and distribution of your addon folder","zh":"了解如何使用 package-addon AI 工具包进行设置和部署，包括清理源代码树、运行测试和打包 addon","ja":"package-addon AIエージェントを使用したセットアップとデプロイの方法を学びます。ソースコードツリーのクリーンアップ、テストの実行、アドオンのパッケージ化など","ko":"package-addon AI 툴 패키지를 사용하여 설정과 배포를 진행하는 방법을 알아보세요. 소스 코드 트리 정리, 테스트 실행, addon 패키징 등","es":"Aprende a configurar package-addon para empaquetar addons de manera efectiva. Descubre los pasos y las mejores prácticas.","fr":"Découvrez comment configurer package-addon pour empaqueter des addons de manière efficace. Conseils et étapes à suivre.","de":"Erfahren Sie, wie Sie package-addon einrichten, um Addon-Pakete effektiv zu erstellen. Schritte und Best Practices.","pt":"Aprenda a configurar o package-addon com nossas dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить package-addon с помощью наших советов и рекомендаций для разработчиков","ar":"تعرف على كيفية إعداد أداة package-addon باستخدام نصائح وعمليات meilleure للمطورين"},"definition":{"en":"package-addon is a skill that automates the packaging process for the lime_pipeline addon folder, ensuring version alignment and excluding unnecessary files","zh":"package-addon 是一种 AI 工具包，用于设置和部署 addon","ja":"package-addon は、アドオンの設定とデプロイに使用される AIエージェントです","ko":"package-addon은 addon 설정과 배포에 사용되는 AI 툴 패키지입니다","es":"Package-addon es una herramienta de línea de comandos que empaqueta addons de Python.","fr":"Package-addon est un outil en ligne de commande qui empaquette des addons Python.","de":"Package-addon ist ein Kommandozeilen-Tool, das Python-Addons verpackt.","pt":"O package-addon é uma ferramenta de empacotamento de código que ajuda a criar pacotes de distribuição","ru":"ИИ Агенты: package-addon - это инструмент упаковки кода, помогающий создавать пакеты распространения","ar":"أداة package-addon هي أداة تغليف للكود تساعد في إنشاء حزم التوزيع"},"features":{"en":["Cleans previous artifacts by removing stale files under dist/","Runs tests using python -m unittest discover tests -v","Packages only the addon folder into dist/lime-pipeline-<version>.zip","Excludes __pycache__, .pyc, docs, and tests from the ZIP","Computes and records hash for packaged files","Runs registration-audit before packaging if ops/ui changed"],"zh":["清理源代码树","运行测试","打包 addon","排除 __pycache__ 和 .pyc 文件","计算和记录哈希值","支持 Python 和 CLI"],"ja":["ソースコードツリーのクリーンアップ","テストの実行","アドオンのパッケージ化"," __pycache__ と .pyc ファイルの除外","ハッシュ値の計算と記録","Python と CLI のサポート"],"ko":["소스 코드 트리 정리","테스트 실행","addon 패키징"," __pycache__와 .pyc 파일 제외","해시 값 계산과 기록","Python과 CLI 지원"],"es":["Limpieza de artefactos previos","Ejecución de pruebas unitarias con Python","Empaquetado selectivo de la carpeta de addons","Exclusión de archivos __pycache__, .pyc, docs y tests","Cálculo y registro de hash"],"fr":["Nettoyage des artefacts précédents","Exécution de tests unitaires avec Python","Empaquetage sélectif du dossier d''addons","Exclusion de fichiers __pycache__, .pyc, docs et tests","Calcul et enregistrement de hash"],"de":["Bereinigung von Vorartefakten","Ausführung von Einheitstests mit Python","Selektives Paketieren des Addon-Ordners","Ausschluss von Dateien __pycache__, .pyc, Docs und Tests","Berechnung und Aufzeichnung von Hash"],"pt":["Limpeza de árvore de código-fonte","Execução de testes com Python","Empacotamento seletivo de pastas","Exclusão de arquivos desnecessários","Cálculo e registro de hash","Compatibilidade com CHANGELOG.md"],"ru":["Очистка исходного дерева кода","Выполнение тестов с помощью Python","Выборочная упаковка папок","Исключение ненужных файлов","Расчет и запись хеша","Совместимость с CHANGELOG.md"],"ar":["تنظيف شجرة الكود المصدري","تشغيل الاختبارات باستخدام Python","تغليف مجلدات اختياري","استبعاد الملفات غير الضرورية","حساب وتسجيل الهاش","التوافق مع CHANGELOG.md"]},"keywords":{"en":["how to use package-addon","package-addon setup guide","package-addon alternative","package-addon vs other packaging tools","automated packaging with package-addon","package-addon install","what is package-addon","package-addon documentation","package-addon tutorial"],"zh":["AI 工具包","package-addon","addon 设置","Python","CLI","测试","打包","哈希值","AI开发"],"ja":["AIエージェント","package-addon","アドオン設定","Python","CLI","テスト","パッケージ化","ハッシュ値","AI開発"],"ko":["AI 툴 패키지","package-addon","addon 설정","Python","CLI","테스트","패키징","해시 값","AI 개발"],"es":["package-addon","herramientas de línea de comandos","empaquetado de addons","Python","pruebas unitarias","línea de comandos","Herramientas de desarrollo","desarrollo de software","Agente de IA"],"fr":["package-addon","outils de ligne de commande","empaquetage d''addons","Python","tests unitaires","ligne de commande","Outils de développement","développement de logiciels","Outil d''IA"],"de":["package-addon","Kommandozeilen-Tools","Erstellung von Addon-Paketen","Python","Einheitstests","Kommandozeile","Entwicklertools","Software-Entwicklung","KI-Tool"],"pt":["package-addon","empacotamento de código","desenvolvimento de software","ferramentas de desenvolvimento","python","teste de unidade","CHANGELOG.md","empacotamento seletivo"],"ru":["ИИ Агенты","package-addon","упаковка кода","разработка программного обеспечения","инструменты разработки","python","юнит-тестирование","CHANGELOG.md","выборочная упаковка"],"ar":["أدوات الذكاء الاصطناعي","package-addon","تغليف الكود","تطوير البرمجيات","أدوات التطوير","python","اختبار الوحدة","CHANGELOG.md","تغليف اختياري"]}},"owner":"himatts","repo":"LimePipeline","repoPath":"himatts/LimePipeline","stars":0,"forks":0,"updatedAt":"2026-03-07T01:37:05Z","topics":[],"category":"community","skillMd":{"name":"package-addon","description":"Build an installable ZIP for the Lime Pipeline Blender add-on. Use for release candidates, QA handoff to artists, or whenever version/changelog changes must ship as a distributable artifact.","bodyPreview":"## Inputs\n- Clean source tree at repo root.\n- Target version aligned between `lime_pipeline/__init__.py` and `CHANGELOG.md`.\n\n## Steps\n1) Clean previous artifacts: remove stale files under `dist/`.\n2) Run tests: `python -m unittest discover tests -v`.\n3) If ops/ui changed, run `registration-audit` before packaging.\n4) Package only the addon folder (`lime_pipeline/`) into `dist/lime-pipeline-<version>.zip`.\n5) Exclude `__pycache__`, `.pyc`, docs, and tests from the ZIP.\n6) Compute and record hash","body":"## Inputs\n- Clean source tree at repo root.\n- Target version aligned between `lime_pipeline/__init__.py` and `CHANGELOG.md`.\n\n## Steps\n1) Clean previous artifacts: remove stale files under `dist/`.\n2) Run tests: `python -m unittest discover tests -v`.\n3) If ops/ui changed, run `registration-audit` before packaging.\n4) Package only the addon folder (`lime_pipeline/`) into `dist/lime-pipeline-<version>.zip`.\n5) Exclude `__pycache__`, `.pyc`, docs, and tests from the ZIP.\n6) Compute and record hash: `Get-FileHash dist\\\\lime-pipeline-<version>.zip -Algorithm SHA256`.\n\n## Outputs\n- Installable ZIP artifact in `dist/`.\n- SHA256 hash ready for release notes.\n"},"lastSynced":"2026-03-07T03:49:37.798Z","agentAnalysis":{"suitability":{"en":"Ideal for Python-based AI Agents requiring streamlined addon packaging and distribution, particularly those leveraging unittest and version control via CHANGELOG.md.","zh":"适用于需要简化的基于Python的AI代理的插件包装和分发，特别是那些利用unittest和通过CHANGELOG.md进行版本控制的代理。","ja":"PythonベースのAIエージェント向けに、Addonのパッケージ化と配布をストリームライン化する必要がある場合に最適です。特に、unittestとCHANGELOG.md経由のバージョン管理を利用する場合に効果的です。","ko":"파이썬 기반의 AI 에이전트가 애드온 패키징 및 배포를 간소화해야 하는 경우에 적합합니다. 특히 unittest 및 CHANGELOG.md를 통해 버전 관리를 사용하는 경우에 유용합니다.","es":"Ideal para agentes de IA basados en Python que requieren un embalaje y distribución de complementos optimizados, especialmente aquellos que utilizan unittest y control de versiones a través de CHANGELOG.md.","fr":"Idéal pour les agents IA basés sur Python nécessitant un conditionnement et une distribution de modules complémentaires rationalisés, en particulier ceux qui utilisent unittest et le contrôle de version via CHANGELOG.md.","de":"Ideal für Python-basierte KI-Agents, die ein optimiertes Addon-Verpacken und -Verteilen erfordern, insbesondere solche, die unittest und Versionskontrolle über CHANGELOG.md nutzen.","pt":"Ideal para Agentes de IA baseados em Python que exigem embalagem e distribuição de complementos otimizadas, particularmente aqueles que utilizam unittest e controle de versão via CHANGELOG.md.","ru":"Идеально для агентов ИИ на основе Python, требующих оптимизированной упаковки и распространения дополнений, особенно тех, которые используют unittest и контроль версий через CHANGELOG.md.","ar":"مثالي للوكلاء الذكاء الاصطناعي المستندة إلى Python التي تتطلب حزمة وإضافة توزيع مُيسرة، خاصة تلك التي تستخدم unittest ومراقبة الإصدار عبر CHANGELOG.md."},"recommendation":{"en":"Empowers agents to automate packaging of the lime_pipeline addon folder, compute hashes, and run tests using Python''s unittest framework, while excluding unnecessary files like __pycache__ and .pyc, ensuring a clean and efficient distribution process via .zip files.","zh":"赋予代理自动化包装lime_pipeline插件文件夹、计算哈希值、使用Python的unittest框架运行测试的能力，同时排除不必要的文件，如__pycache__和.pyc，确保通过.zip文件进行干净高效的分发过程。","ja":"エージェントに、lime_pipelineのAddonフォルダを自動的にパッケージ化し、ハッシュを計算し、Pythonのunittestフレームワークを使用してテストを実行する能力を与え、__pycache__や.pycなどの不要なファイルを除外し、.zipファイルを介したクリーンで効率的な配布プロセスを保証します。","ko":"에이전트가 lime_pipeline 애드온 폴더를 자동으로 패키징하고, 해시를 계산하고, 파이썬의 유닛테스트 프레임워크를 사용하여 테스트를 실행할 수 있는 기능을 부여하며, __pycache__ 및 .pyc와 같은 불필요한 파일을 제외하고, zip 파일을 통해 깨끗하고 효율적인 배포 프로세스를 보장합니다.","es":"Permite a los agentes automatizar el embalaje de la carpeta del complemento lime_pipeline, calcular hashes y ejecutar pruebas utilizando el marco de trabajo unittest de Python, al mismo tiempo que se excluyen archivos innecesarios como __pycache__ y .pyc, garantizando un proceso de distribución limpio y eficiente a través de archivos .zip.","fr":"Permet aux agents d''automatiser le conditionnement du dossier de module complémentaire lime_pipeline, de calculer des hashes et d''exécuter des tests à l''aide du framework unittest de Python, tout en excluant des fichiers inutiles comme __pycache__ et .pyc, garantissant un processus de distribution propre et efficace via des fichiers .zip.","de":"Ermöglicht es den Agents, das Verpacken des lime_pipeline-Addons, das Berechnen von Hashes und das Ausführen von Tests mithilfe des Python-unittest-Frameworks zu automatisieren, während unnötige Dateien wie __pycache__ und .pyc ausgeschlossen werden, um so einen sauberen und effizienten Verteilungsprozess über .zip-Dateien sicherzustellen.","pt":"Habilita os agentes a automatizar a embalagem da pasta do complemento lime_pipeline, calcular hashes e executar testes usando o framework unittest do Python, excluindo arquivos desnecessários como __pycache__ e .pyc, garantindo um processo de distribuição limpo e eficiente via arquivos .zip.","ru":"Позволяет агентам автоматизировать упаковку папки дополнения lime_pipeline, вычислять хеши и запускать тесты с помощью фреймворка unittest Python, исключая ненужные файлы, такие как __pycache__ и .pyc, обеспечивая чистый и эффективный процесс распространения через файлы .zip.","ar":"تمكّن الوكلاء من توفيرAutomation في حزمة مجلد الإضافة lime_pipeline ، وحساب الخوارزميات وتشغيل الاختبارات باستخدام إطار unittest من Python ، مع استبعاد الملفات غير الضرورية مثل __pycache__ و .pyc ، مما يضمن عملية توزيع نظيفة وفعالة عبر ملفات .zip."},"useCases":{"en":["Automating addon packaging for lime_pipeline","Running unittest discover tests for validation","Computing and recording hashes for version control"],"zh":["自动化lime_pipeline的插件包装","运行unittest发现测试以进行验证","计算和记录哈希值以进行版本控制"],"ja":["lime_pipelineのAddonのパッケージ化を自動化する","バリデーション用にunittestの発見テストを実行する","バージョン管理用にハッシュ値を計算して記録する"],"ko":["lime_pipeline 애드온의 패키징 자동화","검증을 위한 유닛테스트 발견 테스트 실행","버전 관리를 위한 해시 값 계산 및 기록"],"es":["Automatización del embalaje de complementos para lime_pipeline","Ejecución de pruebas de validación con unittest discover","Cálculo y registro de hashes para el control de versiones"],"fr":["Automatisation du conditionnement de modules pour lime_pipeline","Exécution de tests de validation avec unittest discover","Calcul et enregistrement de hashes pour le contrôle de version"],"de":["Automatisierung des Verpackens von Addons für lime_pipeline","Ausführen von Validierungstests mit unittest discover","Berechnen und Aufzeichnen von Hashes für die Versionskontrolle"],"pt":["Automatizar embalagem de complemento para lime_pipeline","Executar testes de descoberta de unittest para validação","Calcular e registrar hashes para controle de versão"],"ru":["Автоматизация упаковки дополнения для lime_pipeline","Запуск тестов unittest discover для валидации","Вычисление и запись хешей для контроля версий"],"ar":["توفيرAutomation في حزمة الإضافة lime_pipeline","تشغيل اختبارات unittest discover للتحقق","حساب وتسجيل الخوارزميات للسيطرة على الإصدارات"]},"limitations":{"en":["Requires Python environment","Limited to packaging the lime_pipeline addon folder","Dependent on version alignment between lime_pipeline/__init__.py and CHANGELOG.md"],"zh":["需要Python环境","仅限包装lime_pipeline插件文件夹","依赖于lime_pipeline/__init__.py和CHANGELOG.md之间的版本对齐"],"ja":["Python環境が必要","lime_pipelineのAddonフォルダのパッケージ化のみ","lime_pipeline/__init__.pyとCHANGELOG.mdのバージョンへの依存"],"ko":["파이썬 환경 필요","lime_pipeline 애드온 폴더의 패키징만 가능","lime_pipeline/__init__.py와 CHANGELOG.md 버전 정렬에 의존"],"es":["Requiere entorno de Python","Limitado al embalaje de la carpeta del complemento lime_pipeline","Dependiente de la alineación de versiones entre lime_pipeline/__init__.py y CHANGELOG.md"],"fr":["Nécessite un environnement Python","Limité au conditionnement du dossier de module complémentaire lime_pipeline","Dépendant de l''alignement des versions entre lime_pipeline/__init__.py et CHANGELOG.md"],"de":["Benötigt Python-Umgebung","Begrenzt auf das Verpacken des lime_pipeline-Addons","Abhängig von der Versionsabstimmung zwischen lime_pipeline/__init__.py und CHANGELOG.md"],"pt":["Exige ambiente Python","Limitado à embalagem da pasta do complemento lime_pipeline","Dependente do alinhamento de versão entre lime_pipeline/__init__.py e CHANGELOG.md"],"ru":["Требует среды Python","Ограничен упаковкой папки дополнения lime_pipeline","Зависит от выравнивания версий между lime_pipeline/__init__.py и CHANGELOG.md"],"ar":["يتطلب بيئة Python","محدود بحزمة مجلد الإضافة lime_pipeline","يعتمد على محاذاة الإصدار بين lime_pipeline/__init__.py و CHANGELOG.md"]},"version":4},"contentHash":"4f6aea7fe92a485d4f4191a0d23cce9d2cf599d4f4febca0e18118dc786a6bb8","qualityScore":41}');
