INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('himatts/LimePipeline/package-addon', 'package-addon', 'himatts', 'LimePipeline', 'community', 'package-addon himatts LimePipeline community The package-addon skill automates packaging of the lime_pipeline addon folder, benefiting developers by simplifying distribution and testing. It cleans source trees, runs tests, and computes hashes. package-addon AI 工具包提供了便捷的方式来设置和部署 addon，包括清理源代码树、运行测试和打包 addon package-addon AIエージェントは、アドオンの設定とデプロイを容易にする方法を提供します。ソースコードツリーのクリーンアップ、テストの実行、アドオンのパッケージ化など package-addon AI 툴 패키지는 addon 설정과 배포를 쉽게 해주는 방법을 제공합니다. 소스 코드 트리 정리, 테스트 실행, addon 패키징 등 Package-addon es una herramienta para empaquetar addons de manera efectiva. Permite la creación de paquetes de addons limpios y actualizados. Package-addon est un outil pour empaqueter des addons de manière efficace. Il permet la création de paquets d''addons propres et à jour. Package-addon ist ein Tool zum Erstellen von Addon-Paketen. Es ermöglicht die Erstellung von sauberen und aktuellen Addon-Paketen. O package-addon é uma ferramenta que ajuda a empacotar o addon de pipeline de forma eficiente ИИ Агенты: package-addon - это инструмент, помогающий упаковывать аддон конвейера эффективно أداة package-addon هي أداة تساعد في تغليف إضافة Pipeline بفعالية how to use package-addon package-addon setup guide package-addon alternative package-addon vs other packaging tools automated packaging with package-addon package-addon install what is package-addon package-addon documentation package-addon tutorial AI 工具包 package-addon addon 设置 Python CLI 测试 打包 哈希值 AI开发 Cleans previous artifacts by removing stale files under dist/ Runs tests using python -m unittest discover tests -v Packages only the addon folder into dist/lime-pipeline-<version>.zip Excludes __pycache__, .pyc, docs, and tests from the ZIP Computes and records hash for packaged files Runs registration-audit before packaging if ops/ui changed package-addon is a skill that automates the packaging process for the lime_pipeline addon folder, ensuring version alignment and excluding unnecessary files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('minchanpark/agent-team-simulator/design-system-keeper', 'community', 'minchanpark', 'agent-team-simulator', 'minchanpark/agent-team-simulator', 'design-system-keeper', 0, 0, 41, '2026-02-23T14:52:22Z', '2026-03-07T03:49:56.283Z', '80ce7d4b946789f417fcef55b09321b25fc634dab26ee3dcd177bcb47479f29b', '{"id":"minchanpark/agent-team-simulator/design-system-keeper","name":"design-system-keeper","description":{"en":"The design-system-keeper skill ensures design system consistency by checking and reusing existing conventions. It benefits developers by streamlining token and component management","zh":"设计系统守护者是一个检查和重用现有约定的AI工具，确保设计系统的一致性","ja":"デザインシステムキーパーは、設計システムの一貫性を保つために、既存の規則を確認し、再利用するAIエージェントです","ko":"디자인 시스템키퍼는 디자인 시스템 일관성을 유지하기 위한 기존 규칙을 확인하고 재사용하는 AI 에이전트입니다","es":"Design System Keeper es una herramienta que ayuda a mantener la consistencia en los proyectos de desarrollo mediante la reutilización de tokens y componentes existentes.","fr":"Design System Keeper est un outil qui aide à maintenir la cohérence dans les projets de développement en réutilisant les tokens et les composants existants.","de":"Design System Keeper ist ein Tool, das dabei hilft, die Konsistenz in Entwicklungsprojekten durch die Wiederverwendung von bestehenden Token und Komponenten zu gewährleisten.","pt":"O Design System Keeper é uma ferramenta que ajuda a manter a consistência do design system, reutilizando convenções existentes e melhorando a eficiência do time de desenvolvimento.","ru":"Design System Keeper — это инструмент, который помогает поддерживать последовательность системы дизайна, повторно используя существующие конвенции и повышая эффективность команды разработчиков.","ar":"DESIGN-SYSTEM-KEEPER هو أداة تساعد على الحفاظ على συνέفية نظام التصميم، بإعادة استخدام الاتفاقيات الحالية وتحسين كفاءة فريق التطوير."},"seo":{"title":{"en":"design-system-keeper: Consistency Setup Guide | AI Agent ...","zh":"设计系统守护者设置指南 - 优化设计系统的一致性","ja":"デザインシステムキーパー導入ガイド - 一貫性を保つためのベストプラクティス","ko":"디자인 시스템키퍼 설정 가이드 - 디자인 시스템 일관성 유지","es":"Guía de configuración de Design System Keeper para desarr...","fr":"Guide de mise en place de Design System Keeper pour les d...","de":"Einrichtungsleitfaden für Design System Keeper-Entwickler","pt":"Guia de Configuração do Design System Keeper para Desenvo...","ru":"ИИ Агент Design System Keeper: Руководство по Настройке","ar":"دليل إعداد DESIGN-SYSTEM-KEEPER لتقنيات الويب"},"description":{"en":"Unlock efficient design system management with design-system-keeper. Learn how to implement token naming conventions and component API rules for seamless con...","zh":"了解设计系统守护者的工作原理，优化设计系统的一致性，减少不必要的Token和组件添加","ja":"デザインシステムキーパーの役割と機能を解説します。設計システムの一貫性を保つためのワークフローを紹介します","ko":"디자인 시스템키퍼의 역할과 기능을 알아보세요. 디자인 시스템 일관성을 유지하기 위한 워크플로를 소개합니다","es":"Aprenda a implementar Design System Keeper para mantener la consistencia en sus proyectos de desarrollo. Descubra cómo reutilizar tokens y componentes existe...","fr":"Découvrez comment mettre en place Design System Keeper pour maintenir la cohérence dans vos projets de développement. Réutilisez les tokens et les composants...","de":"Erfahren Sie, wie Sie Design System Keeper implementieren, um die Konsistenz in Ihren Entwicklungsprojekten zu gewährleisten. Erfahren Sie, wie Sie bestehend...","pt":"Aprenda a configurar o Design System Keeper para manter a consistência do seu design system. Descubra como reutilizar convenções existentes e melhorar a efic...","ru":"Узнайте, как настроить Design System Keeper для поддержания последовательности вашей системы дизайна. Откройте для себя, как повторно использовать существующ...","ar":"تعلم كيفية إعداد DESIGN-SYSTEM-KEEPER لضمان συνέفية نظام التصميم الخاص بك. اكتشف كيفية إعادة استخدام الاتفاقيات الحالية وتحسين كفاءة فريق التطوير الخاص بك."},"definition":{"en":"design-system-keeper is a skill that maintains design system consistency by storing and reusing token naming conventions, component API conventions, and Do/Don''t rules","zh":"设计系统守护者是一种AI工具，负责检查和重用设计系统中的现有约定","ja":"デザインシステムキーパーは、設計システムの一貫性を保つために、既存の規則を確認し、再利用するAIエージェントの一種です","ko":"디자인 시스템키퍼는 디자인 시스템 일관성을 유지하기 위한 기존 규칙을 확인하고 재사용하는 AI 에이전트의 일종입니다","es":"Design System Keeper es una herramienta de diseño de sistemas que mantiene la consistencia en los proyectos de desarrollo.","fr":"Design System Keeper est un outil de conception de systèmes qui maintient la cohérence dans les projets de développement.","de":"Design System Keeper ist ein Tool für die Gestaltung von Systemen, das die Konsistenz in Entwicklungsprojekten gewährleistet.","pt":"O Design System Keeper é uma ferramenta de tecnologia que ajuda a manter a consistência do design system.","ru":"Design System Keeper — это инструмент технологии, который помогает поддерживать последовательность системы дизайна.","ar":"DESIGN-SYSTEM-KEEPER هو أداة تقنية تساعد على الحفاظ على συνέفية نظام التصميم."},"features":{"en":["Checks and reuses existing conventions from memory before proposing new tokens/components","Stores token naming conventions for color, spacing, and typography","Manages component API conventions including props patterns and naming","Updates memory with new rules and conventions","Proposes additions only when reuse is impossible, minimizing new token/component creation"],"zh":["检查和重用现有Token命名约定","检查和重用现有组件API约定","存储Do/Don''t规则以确保设计系统的一致性","优化设计系统的一致性，减少不必要的Token和组件添加"],"ja":["既存のトークン命名規則を確認し再利用する","既存のコンポーネントAPI規則を確認し再利用する","Do/Don''tルールを保存して設計システムの一貫性を保つ","設計システムの一貫性を保つために、不要なトークンとコンポーネントの追加を最小限に抑える"],"ko":["기존 토큰命名 규칙을 확인하고 재사용한다","기존 컴포넌트 API 규칙을 확인하고 재사용한다","Do/Don''t 규칙을 저장하여 디자인 시스템 일관성을 유지한다","디자인 시스템 일관성을 유지하기 위한 최소 추가를 통해 불필요한 토큰과 컴포넌트 추가를 줄인다"],"es":["Reutilización de tokens y componentes existentes","Verificación de convenciones de nombramiento de tokens y componentes","Actualización de la memoria con nuevos tokens y componentes","Análisis de especificaciones nuevas para proponer adiciones mínimas","Aplicación de reglas de diseño existentes"],"fr":["Réutilisation de tokens et de composants existants","Vérification des conventions de nommage de tokens et de composants","Mise à jour de la mémoire avec de nouveaux tokens et composants","Analyse de spécifications nouvelles pour proposer des ajouts minimum","Application de règles de conception existantes"],"de":["Wiederverwendung von bestehenden Token und Komponenten","Überprüfung von Namenskonventionen für Token und Komponenten","Aktualisierung des Speichers mit neuen Token und Komponenten","Analyse von neuen Spezifikationen zur Vorschlagung minimaler Ergänzungen","Anwendung bestehender Designregeln"],"pt":["Verificação de convenções existentes antes de propor novas","Reutilização de tokens e componentes","Atualização de regras de design system","Análise de especificações novas","Padronização de nomes de tokens e componentes"],"ru":["Проверка существующих конвенций перед предложением новых","Повторное использование токенов и компонентов","Обновление правил системы дизайна","Анализ новых спецификаций","Стандартизация названий токенов и компонентов"],"ar":["التحقق من الاتفاقيات الحالية قبل اقتراح جديدة","إعادة استخدام الرموز والعناصر","تحديث قواعد نظام التصميم","تحليل المواصفات الجديدة","توحيد أسماء الرموز والعناصر"]},"keywords":{"en":["how to use design-system-keeper","design-system-keeper setup guide","design system consistency","token naming conventions","component API conventions","design-system-keeper vs other design tools","design-system-keeper install","what is design-system-keeper","design-system-keeper alternative","design system management best practices"],"zh":["设计系统守护者","AI工具","设计系统一致性","Token命名约定","组件API约定","Do/Don''t规则","设计系统优化"],"ja":["デザインシステムキーパー","AIエージェント","設計システムの一貫性","トークン命名規則","コンポーネントAPI規則","Do/Don''tルール","設計システムの最適化"],"ko":["디자인 시스템키퍼","AI 에이전트","디자인 시스템 일관성","토큰명명 규칙","컴포넌트 API 규칙","Do/Don''t 규칙","디자인 시스템 최적화"],"es":["Design System Keeper","herramientas de diseño de sistemas","desarrollo de software","consistencia en el diseño","reutilización de código","tokens y componentes","convenciones de nombramiento","reglas de diseño"],"fr":["Design System Keeper","outils de conception de systèmes","développement de logiciels","cohérence dans la conception","réutilisation de code","tokens et composants","conventions de nommage","règles de conception"],"de":["Design System Keeper","Tools für die Gestaltung von Systemen","Software-Entwicklung","Konsistenz im Design","Wiederverwendung von Code","Token und Komponenten","Namenskonventionen","Designregeln"],"pt":["design system keeper","ferramenta de design system","consistência de design","reutilização de convenções","desenvolvimento de software","tecnologia de design","guias de design","padronização de design"],"ru":["ИИ Агент design system keeper","инструмент системы дизайна","последовательность дизайна","повторное использование конвенций","разработка программного обеспечения","технология дизайна","руководства по дизайну","стандартизация дизайна"],"ar":["DESIGN-SYSTEM-KEEPER","أداة نظام التصميم","التناسق في التصميم","إعادة استخدام الاتفاقيات","تطوير البرمجيات","تقنية التصميم","دليل التصميم","توحيد التصميم"]}},"owner":"minchanpark","repo":"agent-team-simulator","repoPath":"minchanpark/agent-team-simulator","stars":0,"forks":0,"updatedAt":"2026-02-23T14:52:22Z","topics":[],"category":"community","skillMd":{"name":"design-system-keeper","description":"프로젝트 디자인 시스템(토큰/컴포넌트 규칙/일관성)을 유지합니다. 기존 토큰과 컴포넌트 규칙을 우선 확인하고, 새로운 UI 요구사항을 시스템에 맞게 조정/추가할 때 사용합니다.","bodyPreview":"# Role\nDesign System Keeper — 디자인 시스템 일관성 유지\n\n# Primary rule\nCheck and reuse existing conventions from memory before proposing new tokens/components.\n\n# What to store in memory\n- Token naming conventions (color, spacing, typography)\n- Component API conventions (props 패턴, 네이밍)\n- Do/Don''t rules\n\n# Workflow\n1) Read memory first — 기존 규칙 확인\n2) Review new spec — 새 요구사항 분석\n3) Propose additions only if reuse impossible — 최소 추가\n4) Update memory — 새 규칙 기록\n\n# Output format\n- **기존 규칙 재사용**: 적용 가능한 기존 토큰/컴포넌","body":"# Role\nDesign System Keeper — 디자인 시스템 일관성 유지\n\n# Primary rule\nCheck and reuse existing conventions from memory before proposing new tokens/components.\n\n# What to store in memory\n- Token naming conventions (color, spacing, typography)\n- Component API conventions (props 패턴, 네이밍)\n- Do/Don''t rules\n\n# Workflow\n1) Read memory first — 기존 규칙 확인\n2) Review new spec — 새 요구사항 분석\n3) Propose additions only if reuse impossible — 최소 추가\n4) Update memory — 새 규칙 기록\n\n# Output format\n- **기존 규칙 재사용**: 적용 가능한 기존 토큰/컴포넌트\n- **신규 제안**: 추가 필요한 토큰/컴포넌트 (이유 포함)\n- **마이그레이션 노트**: 기존 코드 수정 필요 시 안내\n\n# Constraints\n- 기존 시스템과 충돌하는 토큰 생성 금지\n- 한국어로 작성\n"},"lastSynced":"2026-03-07T03:49:56.283Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring consistent design system management and token reuse.","zh":"适用于需要一致的设计系统管理和令牌重用的前端代理。","ja":"一貫したデザインシステムの管理とトークンの再利用を必要とするフロントエンドエージェントに適しています。","ko":"일관된 디자인 시스템 관리와 토큰 재사용이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes de Frontend que requieren una gestión de sistema de diseño consistente y reutilización de tokens.","fr":"Idéal pour les agents Frontend nécessitant une gestion de système de conception cohérente et une réutilisation de jetons.","de":"Ideal für Frontend-Agents, die eine konsistente Design-System-Verwaltung und Token-Wiederverwendung erfordern.","pt":"Ideal para Agentes Frontend que requerem gestão consistente do sistema de design e reutilização de tokens.","ru":"Идеально для агентов Frontend, требующих последовательного управления системой дизайна и повторного использования токенов.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب إدارة نظام التصميم المتسقة وإعادة استخدام الرموز."},"recommendation":{"en":"Empowers agents to streamline token and component management by reusing existing conventions, such as token naming conventions for color, spacing, and typography, and component API conventions like props patterns and naming, all while adhering to do/don''t rules and updating memory with new specs.","zh":"使代理能够通过重用现有的约定（如颜色、间距和排版的令牌命名约定，以及组件API约定，如道具模式和命名）来简化令牌和组件的管理，同时遵守do/don''t规则并用新规范更新内存。","ja":"エージェントが、色、スペーシング、タイポグラフィーのトークン命名規則やコンポーネントAPI規則（예：プロパティパターンや命名）などの既存の規約を再利用して、トークンとコンポーネントの管理をストリーミング化し、do/don''tルールに従い、新しい仕様でメモリを更新できるようにします。","ko":"에이전트가 색상, 간격, 타이포그래피의 토큰 명명 규칙이나 컴포넌트 API 규칙(예: 속성 패턴 및 명명)과 같은 기존 규칙을 재사용하여 토큰 및 컴포넌트 관리를 간소화하고, do/don''t 규칙을 준수하며 새로운 사양으로 메모리를 업데이트할 수 있도록 합니다.","es":"Permite a los agentes simplificar la gestión de tokens y componentes reutilizando convenciones existentes, como convenciones de nombres de tokens para color, espaciado y tipografía, y convenciones de API de componentes como patrones de props y nombres, todo mientras se adhiere a reglas de hacer/no hacer y se actualiza la memoria con nuevas especificaciones.","fr":"Permet aux agents de rationaliser la gestion des jetons et des composants en réutilisant les conventions existantes, telles que les conventions de dénomination des jetons pour la couleur, l''espacement et la typographie, et les conventions d''API de composant comme les modèles de props et les noms, tout en respectant les règles de faire/ne pas faire et en mettant à jour la mémoire avec de nouvelles spécifications.","de":"Ermöglicht es Agenten, die Verwaltung von Token und Komponenten zu rationalisieren, indem bestehende Konventionen wiederverwendet werden, wie z.B. Token-Benennungskonventionen für Farbe, Abstand und Typografie, und Komponenten-API-Konventionen wie Eigenschaftsmuster und Benennung, alles unter Beachtung der Regeln für Machen/Nicht-Machen und unter Aktualisierung des Speichers mit neuen Spezifikationen.","pt":"Habilita os agentes a racionalizar a gestão de tokens e componentes reutilizando convenções existentes, como convenções de nomenclatura de tokens para cor, espaçamento e tipografia, e convenções de API de componentes como padrões de props e nomenclatura, tudo isso enquanto adere às regras do faça/não faça e atualiza a memória com novas especificações.","ru":"Наделяет агентов возможностью оптимизировать управление токенами и компонентами путем повторного использования существующих конвенций, таких как конвенции наименования токенов для цвета,间距 и типографики, и конвенций API компонентов, таких как шаблоны свойств и наименование, все это при соблюдении правил делать/не делать и обновлении памяти новыми спецификациями.","ar":"يمنح الوكلاء القدرة على简化 إدارة الرموز والمكونات من خلال إعادة استخدام الاتفاقيات الحالية ، مثل اتفاقيات تسمية الرموز للألوان والتباعد والطباعة ، واتفاقيات واجهة برمجة تطبيقات المكونات مثل أنماط الخصائص والتسمية ، كل ذلك مع الالتزام بقواعد يفعل / لا يفعل وتحديث الذاكرة بمواصفات جديدة."},"useCases":{"en":["Automating design system consistency checks","Generating reusable tokens and components","Updating memory with new design system rules and conventions"],"zh":["自动化设计系统一致性检查","生成可重用的令牌和组件","使用新设计系统规则和约定更新内存"],"ja":["デザインシステムの一貫性チェックの自動化","再利用可能なトークンとコンポーネントの生成","新しいデザインシステム規則と規約でメモリを更新"],"ko":["디자인 시스템 일관성 점검 자동화","재사용 가능한 토큰 및 컴포넌트 생성","새로운 디자인 시스템 규칙 및 규약으로 메모리 업데이트"],"es":["Automatizar comprobaciones de coherencia del sistema de diseño","Generar tokens y componentes reutilizables","Actualizar la memoria con nuevas reglas y convenciones del sistema de diseño"],"fr":["Automatiser les contrôles de cohérence du système de conception","Générer des jetons et des composants réutilisables","Mettre à jour la mémoire avec de nouvelles règles et conventions de système de conception"],"de":["Automatisieren von Konsistenzprüfungen des Design-Systems","Erzeugen von wiederverwendbaren Token und Komponenten","Aktualisieren des Speichers mit neuen Regeln und Konventionen des Design-Systems"],"pt":["Automatizar verificações de consistência do sistema de design","Gerar tokens e componentes reutilizáveis","Atualizar a memória com novas regras e convenções do sistema de design"],"ru":["Автоматизировать проверки согласованности системы дизайна","Генерировать многократно используемые токены и компоненты","Обновлять память новыми правилами и конвенциями системы дизайна"],"ar":["تutomatizar عمليات فحص الاتساق لنظام التصميم","توليد رموز ومكونات قابلة لإعادة الاستخدام","تحديث الذاكرة بقواعد واتفاقيات جديدة لنظام التصميم"]},"limitations":{"en":["Requires existing design system conventions and memory","Limited to design system management and token/component reuse"],"zh":["需要现有的设计系统约定和内存","仅限设计系统管理和令牌/组件重用"],"ja":["既存のデザインシステム規約とメモリが必要","デザインシステム管理とトークン/コンポーネントの再利用のみ"],"ko":["既存의 디자인 시스템 규약 및 메모리가 필요","디자인 시스템 관리 및 토큰/컴포넌트 재사용에만 제한"],"es":["Requiere convenciones y memoria de sistema de diseño existentes","Limitado a la gestión del sistema de diseño y la reutilización de tokens/componentes"],"fr":["Nécessite des conventions et une mémoire de système de conception existantes","Limité à la gestion du système de conception et à la réutilisation de jetons/composants"],"de":["Benötigt bestehende Design-System-Konventionen und Speicher","Begrenzt auf Design-System-Verwaltung und Token/Komponenten-Wiederverwendung"],"pt":["Requer convenções e memória de sistema de design existentes","Limitado à gestão do sistema de design e reutilização de tokens/mponentes"],"ru":["Требует существующих конвенций и памяти системы дизайна","Ограничен управлением системой дизайна и повторным использованием токенов/компонентов"],"ar":["يتطلب اتفاقيات ونظام تصميم ذاكرة موجودة","محدود بإدارة نظام التصميم وإعادة استخدام الرموز / المكونات"]},"version":4},"contentHash":"80ce7d4b946789f417fcef55b09321b25fc634dab26ee3dcd177bcb47479f29b","qualityScore":41}');
