INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('minchanpark/agent-team-simulator/design-system-keeper', 'design-system-keeper', 'minchanpark', 'agent-team-simulator', 'community', 'design-system-keeper minchanpark agent-team-simulator community The design-system-keeper skill ensures design system consistency by checking and reusing existing conventions. It benefits developers by streamlining token and component management 设计系统守护者是一个检查和重用现有约定的AI工具，确保设计系统的一致性 デザインシステムキーパーは、設計システムの一貫性を保つために、既存の規則を確認し、再利用するAIエージェントです 디자인 시스템키퍼는 디자인 시스템 일관성을 유지하기 위한 기존 규칙을 확인하고 재사용하는 AI 에이전트입니다 Design System Keeper es una herramienta que ayuda a mantener la consistencia en los proyectos de desarrollo mediante la reutilización de tokens y componentes existentes. Design System Keeper est un outil qui aide à maintenir la cohérence dans les projets de développement en réutilisant les tokens et les composants existants. Design System Keeper ist ein Tool, das dabei hilft, die Konsistenz in Entwicklungsprojekten durch die Wiederverwendung von bestehenden Token und Komponenten zu gewährleisten. O Design System Keeper é uma ferramenta que ajuda a manter a consistência do design system, reutilizando convenções existentes e melhorando a eficiência do time de desenvolvimento. Design System Keeper — это инструмент, который помогает поддерживать последовательность системы дизайна, повторно используя существующие конвенции и повышая эффективность команды разработчиков. DESIGN-SYSTEM-KEEPER هو أداة تساعد على الحفاظ على συνέفية نظام التصميم، بإعادة استخدام الاتفاقيات الحالية وتحسين كفاءة فريق التطوير. how to use design-system-keeper design-system-keeper setup guide design system consistency token naming conventions component API conventions design-system-keeper vs other design tools design-system-keeper install what is design-system-keeper design-system-keeper alternative design system management best practices 设计系统守护者 AI工具 设计系统一致性 Token命名约定 组件API约定 Do/Don''t规则 设计系统优化 Checks and reuses existing conventions from memory before proposing new tokens/components Stores token naming conventions for color, spacing, and typography Manages component API conventions including props patterns and naming Updates memory with new rules and conventions Proposes additions only when reuse is impossible, minimizing new token/component creation design-system-keeper is a skill that maintains design system consistency by storing and reusing token naming conventions, component API conventions, and Do/Don''t rules');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Greenmamba29/skillsdotmd_web/access-control-manager', 'community', 'Greenmamba29', 'skillsdotmd_web', 'Greenmamba29/skillsdotmd_web', 'access-control-manager', 0, 0, 41, '2026-02-27T18:18:15Z', '2026-03-07T03:57:52.479Z', '64b777bdf3ec3033b420f233b7703806238a7ba7b80f65ec09f3f24a000bca40', '{"id":"Greenmamba29/skillsdotmd_web/access-control-manager","name":"access-control-manager","description":{"en":"The Access-Control-Manager skill reviews and cleans up access permissions, identifies over-privileged users, and enforces least-privilege access policies. It benefits tech stacks by securing access controls.","zh":"访问控制管理器AIエージェント提供生产级别的访问权限管理、过度授权账户识别和最小权限访问策略的执行","ja":"アクセス制御マネージャーAIエージェントは、生産レベルのアクセス権管理、過剰な権限を持つアカウントの識別、最小権限アクセスポリシーの実施を提供する","ko":"액세스 제어 관리자 AI 도구는 생산 수준의 액세스 권한 관리, 과도한 권한を持つ 계정 식별, 최소 권한 액세스 정책의 실행을 제공","es":"Access Control Manager es una habilidad de producción para administrar permisos de acceso en todos los entornos, identificando usuarios con demasiados privilegios y aplicando políticas de acceso mínimas","fr":"Access Control Manager est une compétence de production pour gérer les autorisations d''accès dans tous les environnements, en identifiant les utilisateurs surprivilegiés et en appliquant des politiques d''accès minimales","de":"Access Control Manager ist eine Produktionsfähigkeit zur Verwaltung von Zugriffsrechten in allen Umgebungen, um überprivilegierte Benutzer zu identifizieren und Mindestzugriffspolitiken anzuwenden","pt":"O Gerenciador de Controle de Acesso é uma habilidade de produção que ajuda a revisar e limpar permissões de acesso, identificar usuários com privilégios excessivos e aplicar políticas de acesso de privilégio mínimo","ru":"ИИ Агент для Управления Доступом - это производственная способность, которая помогает просмотреть и очистить разрешения доступа, выявить пользователей с избыточными привилегиями и внедрить политику минимальных привилегий","ar":"مسؤول التحكم في الوصول هو مهارة الإنتاج التي تساعد على مراجعة وتنظيف صلاحيات الوصول والتحقق من المستخدمين ذوي الصلاحيات الزائدة وتطبيق سياسات الوصول بسلطة أقل"},"seo":{"title":{"en":"Access-Control-Manager: Enforcement of Least-Privilege Ac...","zh":"访问控制管理器设置指南","ja":"アクセス制御マネージャー ベストプラクティス","ko":"액세스 제어 관리자 구축 가이드","es":"Guía de configuración de Access Control Manager para admi...","fr":"Guide de mise en place de Access Control Manager pour la ...","de":"Einrichtungsleitfaden für Access Control Manager zur Bere...","pt":"Guia de Configuração do Gerenciador de Controle de Acesso","ru":"Настройка ИИ Агента для Управления Доступом","ar":"دليل إعداد مسؤول التحكم في الوصول"},"description":{"en":"Discover how to review and clean up access permissions with Access-Control-Manager. Learn to identify over-privileged users and enforce least-privilege acces...","zh":"使用访问控制管理器AIエージェント，轻松管理身份提供者、枚举用户权限、识别过度授权的账户","ja":"アクセス制御マネージャーAIエージェントを利用して、アイデンティティプロバイダーへの接続、ユーザーパーミッションの列挙、過剰な権限を持つアカウントの識別を行う","ko":"액세스 제어 관리자 AI 도구를 사용하여 아이디 제공자 연결, 사용자 권한 열거, 과도한 권한を持つ 계정 식별","es":"Aprende a implementar Access Control Manager para revisar y limpiar permisos de acceso, identificar usuarios con demasiados privilegios y aplicar políticas d...","fr":"Découvrez comment mettre en œuvre Access Control Manager pour examiner et nettoyer les autorisations d''accès, identifier les utilisateurs surprivilegiés et a...","de":"Erfahren Sie, wie Sie Access Control Manager implementieren, um Zugriffsrechte zu überprüfen und zu bereinigen, überprivilegierte Benutzer zu identifizieren ...","pt":"Aprenda a configurar o Gerenciador de Controle de Acesso para revisar e limpar permissões de acesso, identificar usuários com privilégios excessivos e aplica...","ru":"Узнайте, как настроить ИИ Агент для Управления Доступом, чтобы просмотреть и очистить разрешения доступа, выявить пользователей с избыточными привилегиями и ...","ar":"تعرف على كيفية إعداد مسؤول التحكم في الوصول لمراجعة وتنظيف صلاحيات الوصول والتحقق من المستخدمين ذوي الصلاحيات الزائدة وتطبيق سياسات الوصول بسلطة أقل"},"definition":{"en":"Access-Control-Manager is a production-level skill for managing access permissions across various environments and identity providers.","zh":"访问控制管理器是一种AIエージェント，用于管理和优化访问权限","ja":"アクセス制御マネージャーは、アクセス権を管理および最適化するAIエージェントです","ko":"액세스 제어 관리자는 액세스 권한을 관리하고 최적화하는 AI 도구입니다","es":"Access Control Manager es un agente de AI que ayuda a administrar permisos de acceso y a aplicar políticas de seguridad en la nube","fr":"Access Control Manager est un agent d''IA qui aide à gérer les autorisations d''accès et à appliquer des politiques de sécurité dans le cloud","de":"Access Control Manager ist ein KI-Agent, der bei der Verwaltung von Zugriffsrechten und der Anwendung von Sicherheitsrichtlinien in der Cloud hilft","pt":"O que é Gerenciador de Controle de Acesso? É uma habilidade que gerencia permissões de acesso e identifica usuários com privilégios excessivos","ru":"Что такое ИИ Агент для Управления Доступом? Это способность, которая управляет разрешениями доступа и выявляет пользователей с избыточными привилегиями","ar":"ما هو مسؤول التحكم في الوصول؟ هو مهارة لإدارة صلاحيات الوصول والتحقق من المستخدمين ذوي الصلاحيات الزائدة"},"features":{"en":["Connects to identity providers like Okta, Auth0, AWS IAM, and Google Workspace","Enumerates all users, groups, roles, and their current permissions","Identifies over-privileged accounts and unused access rights","Flags service accounts with admin privileges for scoping down","Enforces least-privilege access policies across the tech stack"],"zh":["连接身份提供者（Okta、Auth0、AWS IAM、Google Workspace）","枚举所有用户、组、角色和其当前权限","识别过度授权的账户和未使用的访问权","标记具有管理员权限的服务账户，应将其范围降低","执行最小权限访问策略"],"ja":["アイデンティティプロバイダー（Okta、Auth0、AWS IAM、Google Workspace）への接続","すべてのユーザー、グループ、ロールとその現在の権限の列挙","過剰な権限を持つアカウントと未使用のアクセス権の識別","管理者権限を持つサービスアカウントのフラグ付け、範囲の削減","最小権限アクセスポリシーの実施"],"ko":["아이디 제공자 연결（Okta、Auth0、AWS IAM、Google Workspace）","모든 사용자, 그룹, 역할 및 현재 권한 열거","과도한 권한を持つ 계정 및 미사용 액세스 권한識別","관리자 권한を持つ 서비스 계정의 플래그 지정, 범위 축소","최소 권한 액세스 정책의 실행"],"es":["Conexión a proveedores de identidad como Okta, Auth0, AWS IAM y Google Workspace","Enumeración de todos los usuarios, grupos, roles y sus permisos actuales","Identificación de cuentas con demasiados privilegios y derechos de acceso no utilizados","Flagging de cuentas de servicio con privilegios de administrador que deben reducirse"],"fr":["Connexion aux fournisseurs d''identité tels que Okta, Auth0, AWS IAM et Google Workspace","Énumération de tous les utilisateurs, groupes, rôles et leurs autorisations actuelles","Identification des comptes surprivilegiés et des droits d''accès non utilisés","Flagging des comptes de service avec des privilèges d''administrateur qui doivent être réduits"],"de":["Verbindung zu Identitätsanbietern wie Okta, Auth0, AWS IAM und Google Workspace","Auflistung aller Benutzer, Gruppen, Rollen und ihrer aktuellen Berechtigungen","Identifizierung von überprivilegierten Konten und nicht genutzten Zugriffsrechten","Markierung von Service-Konten mit Administrator-Rechten, die eingeschränkt werden sollten"],"pt":["Conexão com provedores de identidade (Okta, Auth0, AWS IAM, Google Workspace)","Enumeração de todos os usuários, grupos, funções e permissões atuais","Identificação de contas com privilégios excessivos e direitos de acesso não utilizados","Flagração de contas de serviço com privilégios de administrador que devem ser reduzidos"],"ru":["Подключение к провайдерам идентификации (Okta, Auth0, AWS IAM, Google Workspace)","Перечисление всех пользователей, групп, ролей и текущих разрешений","Выявление учетных записей с избыточными привилегиями и неиспользуемыми правами доступа","Пометка служебных учетных записей с привилегиями администратора, которые должны быть уменьшены"],"ar":["اتصال بمزودي الهوية (Okta, Auth0, AWS IAM, Google Workspace)","قائمة جميع المستخدمين والجماعات والأدوار والصلاحيات الحالية","التحقق من الحسابات ذات الصلاحيات الزائدة والصلاحيات غير المستخدمة","توجيه الحسابات الخدمية بسلطات إدارية يجب تقليلها"]},"keywords":{"en":["how to use access-control-manager","access-control-manager setup guide","access-control-manager alternative","access-control-manager vs Okta","what is access-control-manager","access-control-manager install","enforcing least-privilege access","identifying over-privileged users","managing access permissions","access-control-manager for AI Agents"],"zh":["访问控制管理器","AIエージェント","身份提供者管理","访问权限管理","过度授权账户识别","最小权限访问策略","Okta","Auth0","AWS IAM","Google Workspace"],"ja":["アクセス制御マネージャー","AIエージェント","アイデンティティプロバイダー管理","アクセス権管理","過剰な権限を持つアカウントの識別","最小権限アクセスポリシー","Okta","Auth0","AWS IAM","Google Workspace"],"ko":["액세스 제어 관리자","AI 도구","아이디 제공자 관리","액세스 권한 관리","과도한 권한を持つ 계정 식별","최소 권한 액세스 정책","Okta","Auth0","AWS IAM","Google Workspace"],"es":["Access Control Manager","administración de permisos de acceso","seguridad en la nube","políticas de acceso mínimas","identidad y acceso","Okta","Auth0","AWS IAM","Google Workspace"],"fr":["Access Control Manager","gestion des autorisations d''accès","sécurité dans le cloud","politiques d''accès minimales","identité et accès","Okta","Auth0","AWS IAM","Google Workspace"],"de":["Access Control Manager","Zugriffsrechtsverwaltung","Sicherheit in der Cloud","Mindestzugriffspolitiken","Identität und Zugriff","Okta","Auth0","AWS IAM","Google Workspace"],"pt":["Gerenciador de Controle de Acesso","controle de acesso","segurança de acesso","políticas de acesso","privilégios de acesso","Okta","Auth0","AWS IAM","Google Workspace"],"ru":["ИИ Агент для Управления Доступом","управление доступом","безопасность доступа","политики доступа","привилегии доступа","Okta","Auth0","AWS IAM","Google Workspace"],"ar":["مسؤول التحكم في الوصول","تحكم الوصول","أمن الوصول","سياسات الوصول","صلاحيات الوصول","Okta","Auth0","AWS IAM","Google Workspace"]}},"owner":"Greenmamba29","repo":"skillsdotmd_web","repoPath":"Greenmamba29/skillsdotmd_web","stars":0,"forks":0,"updatedAt":"2026-02-27T18:18:15Z","topics":[],"category":"community","skillMd":{"name":"access-control-manager","description":"Audits and manages user access permissions across cloud services, SaaS applications, and internal systems to enforce least-privilege principles","bodyPreview":"# Access Control Manager Agent\n\n## When to use\nUse this skill to review and clean up access permissions, identify over-privileged users, and enforce least-privilege access policies across your tech stack.\n\n## Instructions\n1. Connect to identity providers (Okta, Auth0, AWS IAM, Google Workspace)\n2. Enumerate all users, groups, roles, and their current permissions\n3. Identify over-privileged accounts and unused access rights\n4. Flag service accounts with admin privileges that should be scoped down","body":"# Access Control Manager Agent\n\n## When to use\nUse this skill to review and clean up access permissions, identify over-privileged users, and enforce least-privilege access policies across your tech stack.\n\n## Instructions\n1. Connect to identity providers (Okta, Auth0, AWS IAM, Google Workspace)\n2. Enumerate all users, groups, roles, and their current permissions\n3. Identify over-privileged accounts and unused access rights\n4. Flag service accounts with admin privileges that should be scoped down\n5. Detect stale accounts (no login in 90+ days) for deprovisioning\n6. Generate access review reports for each system\n7. Produce remediation playbook with priority-ordered access changes\n\n## Environment\n- Runtime: python-3.12\n- Trigger: Scheduled\n- Category: Security & Compliance Agents\n\n## Examples\n- Audit AWS IAM roles for over-privileged policies\n- Review GitHub org permissions and remove stale contributors\n- Enforce least-privilege across a multi-cloud environment\n"},"lastSynced":"2026-03-07T03:57:52.479Z","agentAnalysis":{"suitability":{"en":"Ideal for Security Agents requiring advanced access control and permission management capabilities.","zh":"适用于需要高级访问控制和权限管理功能的安全代理。","ja":"高度なアクセス制御およびパーミッション管理機能を必要とするセキュリティエージェントに最適です。","ko":"고급 접근 제어 및 권한 관리 기능이 필요한 보안 에이전트에 적합합니다.","es":"Ideal para agentes de seguridad que requieren capacidades de control de acceso y gestión de permisos avanzadas.","fr":"Idéal pour les agents de sécurité nécessitant des fonctionnalités de contrôle d''accès et de gestion des autorisations avancées.","de":"Ideal für Sicherheitsagenten, die erweiterte Zugriffskontroll- und Berechtigungsverwaltungsfunktionen benötigen.","pt":"Ideal para Agentes de Segurança que requerem controle de acesso avançado e capacidades de gerenciamento de permissões.","ru":"Идеально для агентов безопасности, требующих расширенного контроля доступа и возможностей управления разрешениями.","ar":"مثالي للوكلاء الأمنيين الذين يحتاجون إلى تحكم متقدم في الوصول وإدارة الصلاحيات."},"recommendation":{"en":"Empowers agents to enforce least-privilege access policies, identify over-privileged users, and clean up access permissions across identity providers like Okta, Auth0, AWS IAM, and Google Workspace, utilizing protocols such as OAuth and OpenID Connect.","zh":"赋予代理人执行最小权限访问策略、识别过度特权用户以及在Okta、Auth0、AWS IAM和Google Workspace等身份提供者中清理访问权限的能力，利用OAuth和OpenID Connect等协议。","ja":"エージェントが最小権限アクセスポリシーを適用し、過度に権限を持つユーザーを特定し、Okta、Auth0、AWS IAM、Google Workspaceなどのアイデンティティプロバイダー全体でアクセス権限をクリーンアップする機能を提供し、OAuthおよびOpenID Connectなどのプロトコルを利用します。","ko":"에이전트가 최소 권한 액세스 정책을 적용하고, 과도한 권한을 가진 사용자를 식별하고, Okta, Auth0, AWS IAM 및 Google Workspace와 같은 身分 제공자에서 액세스 권한을 정리하는 기능을 제공하며, OAuth 및 OpenID Connect와 같은 프로토콜을 활용합니다.","es":"Habilita a los agentes a aplicar políticas de acceso de privilegios mínimos, identificar usuarios con demasiados privilegios y limpiar permisos de acceso en proveedores de identidad como Okta, Auth0, AWS IAM y Google Workspace, utilizando protocolos como OAuth y OpenID Connect.","fr":"Permet aux agents d''appliquer des politiques d''accès aux privilèges minimum, d''identifier les utilisateurs surprivilegiés et de nettoyer les autorisations d''accès auprès de fournisseurs d''identité tels que Okta, Auth0, AWS IAM et Google Workspace, en utilisant des protocoles tels que OAuth et OpenID Connect.","de":"Ermächtigt Agenten, Richtlinien für den Mindestzugriff zu erzwingen, überprivilegierte Benutzer zu identifizieren und Zugriffsberechtigungen bei Identitätsanbietern wie Okta, Auth0, AWS IAM und Google Workspace zu bereinigen, unter Verwendung von Protokollen wie OAuth und OpenID Connect.","pt":"Habilita os agentes a impor políticas de acesso de privilégio mínimo, identificar usuários com privilégios excessivos e limpar permissões de acesso em provedores de identidade como Okta, Auth0, AWS IAM e Google Workspace, utilizando protocolos como OAuth e OpenID Connect.","ru":"Наделяет агентов возможностью реализовывать политики минимальных привилегий, выявлять пользователей с избыточными привилегиями и очищать разрешения доступа в поставщиках идентификации, таких как Okta, Auth0, AWS IAM и Google Workspace, используя протоколы, такие как OAuth и OpenID Connect.","ar":"تمكّن الوكلاء من فرض سياسات الوصول إلى أقل الامتيازات، وتحديد المستخدمين ذوي الامتيازات الزائدة، وتنظيف صلاحيات الوصول عبر مزودي الهوية مثل Okta و Auth0 و AWS IAM و Google Workspace، باستخدام بروتوكولات مثل OAuth و OpenID Connect."},"useCases":{"en":["Automating access permission reviews","Identifying and flagging over-privileged service accounts","Enforcing least-privilege access policies across tech stacks"],"zh":["自动执行访问权限审查","识别和标记过度特权的服务帐户","在技术栈中执行最小权限访问策略"],"ja":["アクセス権限レビューの自動化","過度に権限を持つサービスアカウントの特定とフラグ付け","テクノロジースタック全体で最小権限アクセスポリシーの適用"],"ko":["액세스 권한 검토 자동화","과도한 권한을 가진 서비스 계정 식별 및 플래그 설정","기술 스택 전반에 걸친 최소 권한 액세스 정책 적용"],"es":["Automatizar las revisiones de permisos de acceso","Identificar y marcar cuentas de servicio con demasiados privilegios","Aplicar políticas de acceso de privilegios mínimos en varias pilas tecnológicas"],"fr":["Automatiser les examens des autorisations d''accès","Identifier et signaler les comptes de service surprivilegiés"," Appliquer des politiques d''accès aux privilèges minimum sur plusieurs stacks technologiques"],"de":["Automatisieren von Zugriffsberechtigungsprüfungen","Identifizieren und markieren von Servicekonten mit übermäßigen Berechtigungen","Durchsetzen von Mindestzugriffsrichtlinien in verschiedenen Technologie-Stacks"],"pt":["Automatizar revisões de permissões de acesso","Identificar e sinalizar contas de serviço com privilégios excessivos","Impor políticas de acesso de privilégio mínimo em pilhas de tecnologia"],"ru":["Автоматизация обзоров разрешений доступа","Выявление и пометка сервисных аккаунтов с избыточными привилегиями","Реализация политик минимальных привилегий в технологических стэках"],"ar":["تأتمت化 استعراضات صلاحيات الوصول","تحديد وتحويل حسابات الخدمة ذات الصلاحيات الزائدة","فرض سياسات الوصول إلى أقل الامتيازات عبر عوادم التكنولوجيا"]},"limitations":{"en":["Requires connection to identity providers","Limited to supported identity providers (Okta, Auth0, AWS IAM, Google Workspace)"],"zh":["需要连接到身份提供者","仅限支持的身份提供者（Okta、Auth0、AWS IAM、Google Workspace）"],"ja":["アイデンティティプロバイダーへの接続が必要","サポートされているアイデンティティプロバイダー（Okta、Auth0、AWS IAM、Google Workspace）のみ"],"ko":["身份 제공자에 대한 연결이 필요합니다","지원되는 身分 제공자(Okta, Auth0, AWS IAM, Google Workspace)로 제한됨"],"es":["Requiere conexión a proveedores de identidad","Limitado a proveedores de identidad admitidos (Okta, Auth0, AWS IAM, Google Workspace)"],"fr":["Nécessite une connexion aux fournisseurs d''identité","Limité aux fournisseurs d''identité pris en charge (Okta, Auth0, AWS IAM, Google Workspace)"],"de":["Erfordert Verbindung zu Identitätsanbietern","Begrenzt auf unterstützte Identitätsanbieter (Okta, Auth0, AWS IAM, Google Workspace)"],"pt":["Requer conexão com provedores de identidade","Limitado a provedores de identidade suportados (Okta, Auth0, AWS IAM, Google Workspace)"],"ru":["Требует подключения к поставщикам идентификации","Ограничен поставщиками идентификации, которые поддерживаются (Okta, Auth0, AWS IAM, Google Workspace)"],"ar":["يتطلب الاتصال بمزودي الهوية","محدود بمزودي الهوية المدعومين (Okta و Auth0 و AWS IAM و Google Workspace)"]},"version":4},"contentHash":"64b777bdf3ec3033b420f233b7703806238a7ba7b80f65ec09f3f24a000bca40","qualityScore":41}');
