INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Greenmamba29/skillsdotmd_web/access-control-manager', 'access-control-manager', 'Greenmamba29', 'skillsdotmd_web', 'community', 'access-control-manager Greenmamba29 skillsdotmd_web community The Access-Control-Manager skill reviews and cleans up access permissions, identifies over-privileged users, and enforces least-privilege access policies. It benefits tech stacks by securing access controls. 访问控制管理器AIエージェント提供生产级别的访问权限管理、过度授权账户识别和最小权限访问策略的执行 アクセス制御マネージャーAIエージェントは、生産レベルのアクセス権管理、過剰な権限を持つアカウントの識別、最小権限アクセスポリシーの実施を提供する 액세스 제어 관리자 AI 도구는 생산 수준의 액세스 권한 관리, 과도한 권한を持つ 계정 식별, 최소 권한 액세스 정책의 실행을 제공 Access Control Manager es una habilidad de producción para administrar permisos de acceso en todos los entornos, identificando usuarios con demasiados privilegios y aplicando políticas de acceso mínimas Access Control Manager est une compétence de production pour gérer les autorisations d''accès dans tous les environnements, en identifiant les utilisateurs surprivilegiés et en appliquant des politiques d''accès minimales Access Control Manager ist eine Produktionsfähigkeit zur Verwaltung von Zugriffsrechten in allen Umgebungen, um überprivilegierte Benutzer zu identifizieren und Mindestzugriffspolitiken anzuwenden O Gerenciador de Controle de Acesso é uma habilidade de produção que ajuda a revisar e limpar permissões de acesso, identificar usuários com privilégios excessivos e aplicar políticas de acesso de privilégio mínimo ИИ Агент для Управления Доступом - это производственная способность, которая помогает просмотреть и очистить разрешения доступа, выявить пользователей с избыточными привилегиями и внедрить политику минимальных привилегий مسؤول التحكم في الوصول هو مهارة الإنتاج التي تساعد على مراجعة وتنظيف صلاحيات الوصول والتحقق من المستخدمين ذوي الصلاحيات الزائدة وتطبيق سياسات الوصول بسلطة أقل how to use access-control-manager access-control-manager setup guide access-control-manager alternative access-control-manager vs Okta what is access-control-manager access-control-manager install enforcing least-privilege access identifying over-privileged users managing access permissions access-control-manager for AI Agents 访问控制管理器 AIエージェント 身份提供者管理 访问权限管理 过度授权账户识别 最小权限访问策略 Okta Auth0 AWS IAM Google Workspace Connects to identity providers like Okta, Auth0, AWS IAM, and Google Workspace Enumerates all users, groups, roles, and their current permissions Identifies over-privileged accounts and unused access rights Flags service accounts with admin privileges for scoping down Enforces least-privilege access policies across the tech stack Access-Control-Manager is a production-level skill for managing access permissions across various environments and identity providers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jahnvi-maddila/monadblitzdenver/monad-development', 'community', 'jahnvi-maddila', 'monadblitzdenver', 'jahnvi-maddila/monadblitzdenver', 'monad-development', 0, 0, 41, '2026-02-17T22:18:55Z', '2026-03-07T04:00:10.517Z', '812e2be9ea275f6b8bfe17c37b011722d69aad9471efaadb2c1e7542a55c5afa', '{"id":"jahnvi-maddila/monadblitzdenver/monad-development","name":"monad-development","description":{"en":"Monad Development is a skill that enables AI agents to deploy contracts on Ethereum testnet and mainnet using Foundry framework. It benefits developers who need to verify contracts after deployment.","zh":"Monad开发是一个使用Foundry框架的开发工具，支持testnet和mainnet网络","ja":"Monad開発はFoundryフレームワークを使用した開発ツールで、testnetとmainnetネットワークをサポートしています","ko":"Monad 개발은 Foundry 프레임워크를 사용하는 개발 도구로 testnet와 mainnet 네트워크를 지원합니다","es":"Monad-development es un framework para el desarrollo de contratos inteligentes que utiliza Foundry y testnet. Ofrece funcionalidades como verificación de contratos y persistencia de wallets","fr":"Monad-development est un framework pour le développement de contrats intelligents qui utilise Foundry et testnet. Il offre des fonctionnalités telles que la vérification de contrats et la persistance de wallets","de":"Monad-development ist ein Framework für die Entwicklung von Smart Contracts, das Foundry und testnet verwendet. Es bietet Funktionen wie Vertragsverifizierung und Wallet-Persistenz","pt":"O Monad Development é uma ferramenta para desenvolvedores que fornece uma configuração padrão para redes e verificação de contratos. Utiliza o framework Foundry e testnet por padrão.","ru":"Monad Development - это инструмент для разработчиков, который предоставляет стандартную настройку для сетей и проверки контрактов. Использует фреймворк Foundry и testnet по умолчанию.","ar":"Monad Development هو أداة للمطورين توفر إعدادًا افتراضيًا للشبكات والتحقق من العقود. يستخدم إطار العمل Foundry و testnet افتراضيًا."},"seo":{"title":{"en":"Monad Development: Foundry Framework Setup Guide | AI Age...","zh":"Monad开发设置指南 - AI工具","ja":"Monad開発ベストプラクティス - AIエージェント","ko":"Monad 개발 가이드 - AI 에이전트","es":"Guía de configuración de monad-development para desarroll...","fr":"Guide de mise en place de monad-development pour les déve...","de":"Einrichtungsleitfaden für monad-development für Entwickler","pt":"Guia de Configuração do Monad Development para Desenvolve...","ru":"Руководство по настройке Monad Development для разработчиков","ar":"دليل إعداد Monad Development لالمطورين"},"description":{"en":"Unlock the full potential of Monad Development with our expert guide. Learn how to deploy contracts on testnet and mainnet with ease.","zh":"了解Monad开发的技术细节，包括网络、验证和框架设置","ja":"Monad開発のテクニカルな詳細を確認しよう - ネットワーク、検証、フレームワーク","ko":"Monad 개발의 기술 세부 정보를 확인하세요 - 네트워크, 검증, 프레임워크","es":"Aprende a configurar monad-development con Foundry y testnet. Descubre las mejores prácticas para el desarrollo de contratos inteligentes","fr":"Découvrez comment configurer monad-development avec Foundry et testnet. Apprenez les meilleures pratiques pour le développement de contrats intelligents","de":"Erfahren Sie, wie Sie monad-development mit Foundry und testnet konfigurieren. Entdecken Sie die besten Praktiken für die Entwicklung von Smart Contracts","pt":"Aprenda a configurar o Monad Development com nossa guia passo a passo, incluindo redes, verificação de contratos e framework Foundry","ru":"Узнайте, как настроить Monad Development с нашей пошаговой инструкцией, включая сети, проверку контрактов и фреймворк Foundry","ar":"تعلم كيفية إعداد Monad Development مع دليلنا خطوة بخطوة، بما في ذلك الشبكات والتحقق من العقود وإطار العمل Foundry"},"definition":{"en":"Monad Development is a technical skill that provides a set of defaults and guidelines for developing on the Ethereum blockchain using Foundry framework.","zh":"Monad开发是一个基于Foundry的开发工具，用于构建和部署智能合约","ja":"Monad開発はFoundryに基づく開発ツールで、スマートコントラクトの構築とデプロイに使用されます","ko":"Monad 개발은 Foundry 기반의 개발 도구로 스마트 계약의 구축과 배포에 사용됩니다","es":"Monad-development es un conjunto de herramientas para desarrolladores que necesitan crear y desplegar contratos inteligentes de manera eficiente","fr":"Monad-development est un ensemble d''outils pour les développeurs qui ont besoin de créer et de déployer des contrats intelligents de manière efficace","de":"Monad-development ist ein Satz von Tools für Entwickler, die Smart Contracts effizient erstellen und bereitstellen müssen","pt":"Monad Development é uma ferramenta de desenvolvimento que fornece configurações padrão para redes e verificação de contratos","ru":"Monad Development - это инструмент разработки, который предоставляет стандартные настройки для сетей и проверки контрактов","ar":"Monad Development هو أداة تطوير توفر إعدادات افتراضية للشبكات والتحقق من العقود"},"features":{"en":["Deploys contracts on Ethereum testnet (chain ID 10143) by default","Verifies contracts after deployment unless user specifies not to","Uses Foundry framework for development and deployment","Generates and persists wallets for secure transaction management","Supports deployment on mainnet when user specifies"],"zh":["使用Foundry框架进行开发","支持testnet和mainnet网络","自动验证智能合约","Wallet持久化功能","链ID10143的testnet网络支持"],"ja":["Foundryフレームワークを使用した開発","testnetとmainnetネットワークのサポート","スマートコントラクトの自動検証","ウォレットの永続化機能","チェーンID10143のtestnetネットワークサポート"],"ko":["Foundry 프레임워크를 사용한 개발","testnet과 mainnet 네트워크 지원","스마트 계약의 자동 검증","ウォレット의 영속화 기능","체인 ID 10143의 testnet 네트워크 지원"],"es":["Utiliza Foundry como framework de desarrollo","Soporte para testnet y mainnet","Verificación de contratos después de la implementación","Persistencia de wallets generadas","Uso de RPC para la comunicación con la red"],"fr":["Utilise Foundry comme framework de développement","Prise en charge de testnet et mainnet","Vérification de contrats après la mise en œuvre","Persistance des wallets générées","Utilisation de RPC pour la communication avec le réseau"],"de":["Verwendung von Foundry als Entwicklungsumgebung","Unterstützung für testnet und mainnet","Verifizierung von Verträgen nach der Bereitstellung","Persistenz von generierten Wallets","Verwendung von RPC für die Kommunikation mit dem Netzwerk"],"pt":["Utiliza testnet por padrão (chain ID 10143)","Verificação de contratos após implantação","Utiliza o framework Foundry","Geração de carteiras com persistência","Suporte a redes personalizadas"],"ru":["Использует testnet по умолчанию (chain ID 10143)","Проверка контрактов после развертывания","Использует фреймворк Foundry","Генерация кошельков с сохранением","Поддержка настраиваемых сетей"],"ar":["يستخدم testnet افتراضيًا (chain ID 10143)","التحقق من العقود بعد النشر","يستخدم إطار العمل Foundry","إنشاء محافظ مع الحفظ","دعم الشبكات المخصصة"]},"keywords":{"en":["how to use monad development","monad development setup guide","foundry framework tutorial","ethereum testnet deployment","monad development vs hardhat","monad development install","what is monad development","monad development best practices","ethereum mainnet deployment with foundry"],"zh":["Monad开发","Foundry框架","testnet网络","mainnet网络","智能合约开发","AI工具","开发设置指南"],"ja":["Monad開発","Foundryフレームワーク","testnetネットワーク","mainnetネットワーク","スマートコントラクト開発","AIエージェント","開発ベストプラクティス"],"ko":["Monad 개발","Foundry 프레임워크","testnet 네트워크","mainnet 네트워크","스마트 계약 개발","AI 에이전트","개발 가이드"],"es":["desarrollo de contratos inteligentes","monad-development","Foundry","testnet","verificación de contratos","persistencia de wallets","RPC","desarrollo de blockchain","herramientas de desarrollo"],"fr":["développement de contrats intelligents","monad-development","Foundry","testnet","vérification de contrats","persistance de wallets","RPC","développement de blockchain","outils de développement"],"de":["Entwicklung von Smart Contracts","monad-development","Foundry","testnet","Verifizierung von Verträgen","Persistenz von Wallets","RPC","Entwicklung von Blockchain","Entwicklungstools"],"pt":["Monad Development","desenvolvimento de blockchain","testnet","verificação de contratos","framework Foundry","geração de carteiras","persistência de dados"],"ru":["Monad Development","разработка блокчейна","testnet","проверка контрактов","фреймворк Foundry","генерация кошельков","сохранение данных"],"ar":["Monad Development","تطوير البلوكشين","testnet","التحقق من العقود","إطار العمل Foundry","إنشاء محافظ","الحفظ البيانات"]}},"owner":"jahnvi-maddila","repo":"monadblitzdenver","repoPath":"jahnvi-maddila/monadblitzdenver","stars":0,"forks":0,"updatedAt":"2026-02-17T22:18:55Z","topics":[],"category":"community","skillMd":{"name":"monad-development","description":"Builds dapps on Monad blockchain. Use when deploying contracts, setting up frontends with viem/wagmi, or verifying contracts on Monad testnet or mainnet.","version":"1.0.0","bodyPreview":"# Monad Development\n\nFor questions not covered here, fetch https://docs.monad.xyz/llms.txt\n\n## Quick Reference\n\n### Defaults\n- **Network:** Always use **testnet** (chain ID 10143) unless user says \"mainnet\"\n- **Verification:** Always verify contracts after deployment unless user says not to\n- **Framework:** Use Foundry (not Hardhat)\n- **Wallet:** If you generate a wallet, MUST persist it (see Wallet Persistence section)\n\n### Networks\n\n| Network | Chain ID | RPC |\n|---------|----------|-----|\n| T","body":"# Monad Development\n\nFor questions not covered here, fetch https://docs.monad.xyz/llms.txt\n\n## Quick Reference\n\n### Defaults\n- **Network:** Always use **testnet** (chain ID 10143) unless user says \"mainnet\"\n- **Verification:** Always verify contracts after deployment unless user says not to\n- **Framework:** Use Foundry (not Hardhat)\n- **Wallet:** If you generate a wallet, MUST persist it (see Wallet Persistence section)\n\n### Networks\n\n| Network | Chain ID | RPC |\n|---------|----------|-----|\n| Testnet | 10143 | https://testnet-rpc.monad.xyz |\n| Mainnet | 143 | https://rpc.monad.xyz |\n\nDocs: https://docs.monad.xyz\n\n### Explorers\n\n| Explorer | Testnet | Mainnet |\n|----------|---------|---------|\n| Socialscan | https://monad-testnet.socialscan.io | https://monad.socialscan.io |\n| MonadVision | https://testnet.monadvision.com | https://monadvision.com |\n| Monadscan | https://testnet.monadscan.com | https://monadscan.com |\n\n### Agent APIs\n\n**IMPORTANT:** Do NOT use a browser. Use these APIs directly with curl.\n\n**Faucet (Testnet Funding):**\n```bash\ncurl -X POST https://agents.devnads.com/v1/faucet \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"chainId\": 10143, \"address\": \"0xYOUR_ADDRESS\"}''\n```\n\nReturns: `{\"txHash\": \"0x...\", \"amount\": \"1000000000000000000\", \"chain\": \"Monad Testnet\"}`\n\n**Fallback (official faucet):** https://faucet.monad.xyz\nIf the agent faucet fails, ask the user to fund via the official faucet (do not use a browser yourself).\n\n**Verification (All Explorers):**\n\nALWAYS use the verification API first. It verifies on all 3 explorers (MonadVision, Socialscan, Monadscan) with one call. Do NOT use `forge verify-contract` as first choice.\n\n```bash\n# 1. Get verification data\nforge verify-contract <ADDR> <CONTRACT> \\\n  --chain 10143 \\\n  --show-standard-json-input > /tmp/standard-input.json\n\ncat out/<Contract>.sol/<Contract>.json | jq ''.metadata'' > /tmp/metadata.json\nCOMPILER_VERSION=$(jq -r ''.metadata | fromjson | .compiler.version'' out/<Contract>.sol/<Contract>.json)\n\n# 2. Call verification API\nSTANDARD_INPUT=$(cat /tmp/standard-input.json)\nFOUNDRY_METADATA=$(cat /tmp/metadata.json)\n\ncat > /tmp/verify.json << EOF\n{\n  \"chainId\": 10143,\n  \"contractAddress\": \"0xYOUR_CONTRACT_ADDRESS\",\n  \"contractName\": \"src/MyContract.sol:MyContract\",\n  \"compilerVersion\": \"v${COMPILER_VERSION}\",\n  \"standardJsonInput\": $STANDARD_INPUT,\n  \"foundryMetadata\": $FOUNDRY_METADATA\n}\nEOF\n\ncurl -X POST https://agents.devnads.com/v1/verify \\\n  -H \"Content-Type: application/json\" \\\n  -d @/tmp/verify.json\n```\n\n**With constructor arguments:** Add `constructorArgs` (ABI-encoded, WITHOUT 0x prefix):\n```bash\nARGS=$(cast abi-encode \"constructor(string,string,uint256)\" \"MyToken\" \"MTK\" 1000000000000000000000000)\nARGS_NO_PREFIX=${ARGS#0x}\n# Add to request: \"constructorArgs\": \"$ARGS_NO_PREFIX\"\n```\n\n**Manual verification fallback (if API fails):**\n```bash\nforge verify-contract <ADDR> <CONTRACT> --chain 10143 \\\n  --verifier sourcify \\\n  --verifier-url \"https://sourcify-api-monad.blockvision.org/\"\n```\n\n## Wallet Persistence\n\n**CRITICAL for agents:** If you generate a wallet for the user, you MUST persist it for future use.\n\nWhen generating a new wallet:\n1. Create wallet: `cast wallet new`\n2. **Immediately save** the address and private key to a secure location\n3. Inform the user where the wallet details are stored\n4. Fund the wallet via faucet before deployment\n\n**Storage options:**\n- Write to `~/.monad-wallet` with chmod 600\n- Store in a project-specific `.env` file (add to .gitignore)\n- Return credentials to user and ask them to save securely\n\n**Why this matters:** Users need access to their wallet to:\n- Deploy additional contracts\n- Interact with deployed contracts\n- Manage funds\n- Verify ownership\n\n## Deployment Workflow\n\nUse `forge script` for deployments:\n\n```bash\nforge script script/Deploy.s.sol:DeployScript \\\n  --rpc-url https://testnet-rpc.monad.xyz \\\n  --private-key $PRIVATE_KEY \\\n  --broadcast\n```\n\n**Deploy script template:**\n\n```solidity\n// SPDX-License-Identifier: MIT\npragma solidity ^0.8.27;\nimport \"forge-std/Script.sol\";\nimport \"../src/MyContract.sol\";\n\ncontract DeployScript is Script {\n    function run() external {\n        vm.startBroadcast();\n        MyContract contract = new MyContract();\n        console.log(\"Contract deployed at:\", address(contract));\n        vm.stopBroadcast();\n    }\n}\n```\n\n## Technical Details\n\n### EVM Version (Critical)\n\nAlways set `evmVersion: \"prague\"`. Requires Solidity 0.8.27+.\n\n**Foundry** (`foundry.toml`):\n```toml\n[profile.default]\nevm_version = \"prague\"\nsolc_version = \"0.8.28\"\n```\n\n### Foundry Tips\n\n**Flags that don''t exist (don''t use):**\n- `--no-commit` - not a valid flag for `forge init` or `forge install`\n\n**Deployment - use `forge script`, NOT `forge create`:**\n\n`forge create --broadcast` is buggy and often ignored. Use `forge script` instead.\n\n```bash\nforge script script/Deploy.s.sol:DeployScript \\\n  --rpc-url https://testnet-rpc.monad.xyz \\\n  --private-key $PRIVATE_KEY \\\n  --broadcast\n```\n\n**Deploy script must NOT hardcode addresses:**\n\n```solidity\n// ✅ Correct - reads private key from --private-key flag\nfunction run() external {\n    vm.startBroadcast();\n    new MyContract();\n    vm.stopBroadcast();\n}\n\n// ❌ Wrong - hardcodes address, causes \"No associated wallet\" error\nfunction run() external {\n    vm.startBroadcast(0x1234...);\n}\n```\n\n### Frontend\n\nImport from `viem/chains`. Do NOT define custom chain:\n\n```ts\nimport { monadTestnet } from \"viem/chains\";\n```\n\nUse with wagmi:\n\n```ts\nimport { createConfig, http } from ''wagmi''\nimport { monadTestnet } from ''viem/chains''\n\nconst config = createConfig({\n  chains: [monadTestnet],\n  transports: {\n    [monadTestnet.id]: http()\n  }\n})\n```\n\n## Example: Deploy ERC20\n\n**1. Create project:**\n```bash\nforge init my-token\ncd my-token\n```\n\n**2. Configure `foundry.toml`:**\n```toml\n[profile.default]\nsrc = \"src\"\nout = \"out\"\nlibs = [\"lib\"]\nevm_version = \"prague\"\nsolc_version = \"0.8.28\"\n```\n\n**3. Create contract `src/MyToken.sol`:**\n```solidity\n// SPDX-License-Identifier: MIT\npragma solidity ^0.8.27;\n\nimport \"@openzeppelin/contracts/token/ERC20/ERC20.sol\";\n\ncontract MyToken is ERC20 {\n    constructor(uint256 initialSupply) ERC20(\"MyToken\", \"MTK\") {\n        _mint(msg.sender, initialSupply);\n    }\n}\n```\n\n**4. Install dependencies:**\n```bash\nforge install OpenZeppelin/openzeppelin-contracts --no-commit\n```\n\n**5. Create deploy script `script/Deploy.s.sol`:**\n```solidity\n// SPDX-License-Identifier: MIT\npragma solidity ^0.8.27;\nimport \"forge-std/Script.sol\";\nimport \"../src/MyToken.sol\";\n\ncontract DeployScript is Script {\n    function run() external {\n        vm.startBroadcast();\n        MyToken token = new MyToken(1000000 * 10**18);\n        console.log(\"Token deployed at:\", address(token));\n        vm.stopBroadcast();\n    }\n}\n```\n\n**6. Deploy:**\n```bash\nforge script script/Deploy.s.sol:DeployScript \\\n  --rpc-url https://testnet-rpc.monad.xyz \\\n  --private-key $PRIVATE_KEY \\\n  --broadcast\n```\n\n**7. Verify:**\n```bash\n# Use verification API (verifies on all explorers)\nSTANDARD_INPUT=$(forge verify-contract <TOKEN_ADDRESS> src/MyToken.sol:MyToken --chain 10143 --show-standard-json-input)\nCOMPILER_VERSION=$(jq -r ''.metadata | fromjson | .compiler.version'' out/MyToken.sol/MyToken.json)\n\ncurl -X POST https://agents.devnads.com/v1/verify \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\n    \\\"chainId\\\": 10143,\n    \\\"contractAddress\\\": \\\"<TOKEN_ADDRESS>\\\",\n    \\\"contractName\\\": \\\"src/MyToken.sol:MyToken\\\",\n    \\\"compilerVersion\\\": \\\"v${COMPILER_VERSION}\\\",\n    \\\"standardJsonInput\\\": $STANDARD_INPUT,\n    \\\"constructorArgs\\\": \\\"$(cast abi-encode ''constructor(uint256)'' 1000000000000000000000000 | sed ''s/0x//'')\\\"\n  }\"\n```\n"},"lastSynced":"2026-03-07T04:00:10.517Z","agentAnalysis":{"suitability":{"en":"Perfect for Ethereum-focused AI Agents needing seamless smart contract deployment and verification on testnet and mainnet using the Foundry framework.","zh":"非常适合需要在测试网和主网上使用Foundry框架进行无缝智能合约部署和验证的以太坊专注的AI代理。","ja":"Ethereumに焦点を当てたAIエージェントに適しており、Foundryフレームワークを使用してテストネットとメインネット上でシームレスなスマートコントラクトのデプロイと検証が可能です。","ko":"이더리움에 중점을 둔 AI 에이전트에게 적합하며, Foundry 프레임워크를 사용하여 테스트 네트와 메인 네트에서 무장애 스마트 계약 배포 및 검증이 가능합니다.","es":"Perfecto para agentes de inteligencia artificial centrados en Ethereum que necesitan una implementación y verificación de contratos inteligentes sin problemas en testnet y mainnet utilizando el framework Foundry.","fr":"Parfait pour les agents d''intelligence artificielle axés sur Ethereum nécessitant un déploiement et une vérification de contrats intelligents sans heurts sur testnet et mainnet en utilisant le framework Foundry.","de":"Perfekt für Ethereum-fokussierte KI-Agents, die eine nahtlose Bereitstellung und Überprüfung von Smart Contracts auf Testnet und Mainnet mit dem Foundry-Framework benötigen.","pt":"Perfeito para agentes de IA focados em Ethereum que necessitam de implantação e verificação de contrato inteligente sem problemas no testnet e mainnet usando o framework Foundry.","ru":"Идеально для агентов ИИ, ориентированных на Ethereum, которым требуется бесшовное развертывание и верификация умных контрактов на тестовой сети и основной сети с использованием фреймворка Foundry.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يركزون على Ethereum والذين يحتاجون إلى نشر وتصديق عقود ذكية دون مشاكل على شبكة الاختبار وشبكة الرئيسية باستخدام إطار Foundry."},"recommendation":{"en":"Empowers agents to deploy contracts on Ethereum testnet and mainnet, leveraging the Foundry framework for efficient deployment and verification, while ensuring contract integrity through automatic verification unless explicitly disabled, utilizing chain IDs like 10143 for testnet interactions.","zh":"赋予代理在Ethereum测试网和主网上部署合约的能力，利用Foundry框架实现高效的部署和验证，同时通过自动化验证确保合约的完整性，除非显式禁用，并且可以利用链ID（如10143）进行测试网交互。","ja":"Ethereumテストネットとメインネット上でコントラクトをデプロイするエージェントを可能にし、Foundryフレームワークを使用して効率的なデプロイと検証を行い、明示的に無効にしない限り自動検証によってコントラクトの完全性を確保し、チェーンID（例：10143）を使用してテストネットのやり取りを行うことができます。","ko":"에이전트가 이더리움 테스트 네트와 메인 네트에서 계약을 배포할 수 있도록 하며, Foundry 프레임워크를 사용하여 효율적인 배포 및 검증을 수행하며, 명시적으로 비활성화하지 않는 한 자동 검증을 통해 계약의 무결성을 보장하며, 체인 ID(예: 10143)를 사용하여 테스트 네트워크 상호 작용을 수행할 수 있습니다.","es":"Habilita a los agentes a implementar contratos en la red de prueba de Ethereum y en mainnet, aprovechando el framework Foundry para una implementación y verificación eficientes, al mismo tiempo que garantiza la integridad del contrato a través de la verificación automática a menos que se deshabilite explícitamente, utilizando IDs de cadena como 10143 para las interacciones en la red de prueba.","fr":"Permet aux agents de déployer des contrats sur le testnet Ethereum et le mainnet, en exploitant le framework Foundry pour un déploiement et une vérification efficaces, tout en garantissant l''intégrité du contrat via une vérification automatique à moins qu''elle ne soit explicitement désactivée, en utilisant des IDs de chaîne comme 10143 pour les interactions sur le testnet.","de":"Ermächtigt Agents, Verträge auf dem Ethereum-Testnet und dem Mainnet bereitzustellen, indem das Foundry-Framework für eine effiziente Bereitstellung und Überprüfung genutzt wird, während gleichzeitig die Vertragsintegrität durch automatische Überprüfung gewährleistet wird, es sei denn, sie wird explizit deaktiviert, wobei Chain-IDs wie 10143 für Testnet-Interaktionen verwendet werden.","pt":"Habilita os agentes a implantar contratos no testnet e mainnet do Ethereum, aproveitando o framework Foundry para implantação e verificação eficientes, garantindo a integridade do contrato por meio de verificação automática, a menos que explicitamente desabilitada, utilizando IDs de corrente como 10143 para interações de testnet.","ru":"Наделяет агентов возможностью развертывать контракты на тестовой сети и основной сети Ethereum, используя фреймворк Foundry для эффективного развертывания и верификации, обеспечивая целостность контракта посредством автоматической верификации, если не отключено явно, используя идентификаторы цепи, такие как 10143, для взаимодействия с тестовой сетью.","ar":"يمنح الوكلاء القدرة على نشر العقود على شبكة الاختبار وشبكة الرئيسية لشركة Ethereum، مستخدمًا إطار Foundry لنشر وتصديق فعال، ويضمن سلامة العقد من خلال التحقق التلقائي، ما لم يتم تعطيله صراحة، باستخدام معرّفات السلسلة مثل 10143 للتفاعلات مع شبكة الاختبار."},"useCases":{"en":["Deploying smart contracts on Ethereum testnet for testing purposes","Verifying contracts after deployment to ensure integrity and correctness","Generating and persisting wallets for secure transaction management"],"zh":["在以太坊测试网上部署智能合约以进行测试目的","部署后验证合约以确保其完整性和正确性","生成和持久化钱包以进行安全的事务管理"],"ja":["テスト目的のためにEthereumテストネット上でスマートコントラクトをデプロイする","デプロイ後にコントラクトを検証して完全性と正確性を確保する","安全なトランザクション管理のためにウォレットを生成して永続化する"],"ko":["테스트 목적으로 이더리움 테스트 네트에서 스마트 계약을 배포한다","배포 후 계약의 무결성 및 올바름을 보장하기 위해 계약을 검증한다","안전한 트랜잭션 관리를 위해 지갑을 생성하고 영속화한다"],"es":["Implementar contratos inteligentes en la red de prueba de Ethereum para fines de prueba","Verificar contratos después de la implementación para garantizar la integridad y la corrección","Generar y persistir billeteras para una gestión de transacciones seguras"],"fr":["Déployer des contrats intelligents sur le testnet Ethereum à des fins de test","Vérifier les contrats après déploiement pour garantir l''intégrité et la correction","Générer et persister des portefeuilles pour une gestion de transactions sécurisée"],"de":["Bereitstellung von Smart Contracts auf dem Ethereum-Testnet für Testzwecke","Überprüfung von Verträgen nach der Bereitstellung, um Integrität und Richtigkeit sicherzustellen","Generieren und Persistieren von Wallets für eine sichere Transaktionsverwaltung"],"pt":["Implantação de contratos inteligentes no testnet do Ethereum para fins de teste","Verificação de contratos após implantação para garantir integridade e correção","Geração e persistência de carteiras para gerenciamento de transações seguro"],"ru":["Развертывание умных контрактов на тестовой сети Ethereum для целей тестирования","Верификация контрактов после развертывания для обеспечения целостности и правильности","Генерация и сохранение кошельков для безопасного управления транзакциями"],"ar":["نشر العقود الذكية على شبكة الاختبار لشركة Ethereum لأغراض الاختبار","التحقق من العقود بعد النشر لضمان السلامة والدقة","_GENERATING والاستمرار في الحافظة للأمن إدارة المعاملات"]},"limitations":{"en":["Requires Foundry framework installation and configuration","Limited to Ethereum testnet and mainnet deployments","Wallet persistence necessary for secure wallet management"],"zh":["需要安装和配置Foundry框架","仅限以太坊测试网和主网部署","钱包持久化对于安全的钱包管理是必要的"],"ja":["Foundryフレームワークのインストールと設定が必要","Ethereumテストネットとメインネットのデプロイのみ","ウォレットの永続化は安全なウォレット管理に必要"],"ko":["Foundry 프레임워크의 설치 및 구성이 필요합니다","이더리움 테스트 네트와 메인 네트의 배포만 가능합니다","지갑의 영속화는 안전한 지갑 관리에 필요합니다"],"es":["Requiere la instalación y configuración del framework Foundry","Limitado a las implementaciones de testnet y mainnet de Ethereum","La persistencia de la billetera es necesaria para una gestión de billeteras seguras"],"fr":["Nécessite l''installation et la configuration du framework Foundry","Limité aux déploiements sur le testnet et le mainnet Ethereum","La persistance du portefeuille est nécessaire pour une gestion de portefeuille sécurisée"],"de":["Benötigt die Installation und Konfiguration des Foundry-Frameworks","Begrenzt auf Bereitstellungen im Ethereum-Testnet und im Mainnet","Die Persistenz der Wallet ist erforderlich für eine sichere Wallet-Verwaltung"],"pt":["Requer instalação e configuração do framework Foundry","Limitado a implantações no testnet e mainnet do Ethereum","Persistência de carteira necessária para gerenciamento de carteira seguro"],"ru":["Требует установки и настройки фреймворка Foundry","Ограничен развертыванием на тестовой сети и основной сети Ethereum","Необходимо сохранение кошелька для безопасного управления кошельком"],"ar":["يتطلب تثبيت وتكوين إطار Foundry","محدود بنشر على شبكة الاختبار وشبكة الرئيسية لشركة Ethereum","الاستمرار في الحافظة ضروري لإدارة الحافظة الآمنة"]},"version":4},"contentHash":"812e2be9ea275f6b8bfe17c37b011722d69aad9471efaadb2c1e7542a55c5afa","qualityScore":41}');
