INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RyanL2/privamarket/monad-development', 'monad-development', 'RyanL2', 'privamarket', 'community', 'monad-development RyanL2 privamarket community Monad-development is a technical skill for AI agents that streamlines contract deployment and verification on testnet. It benefits developers working with Foundry and wallet persistence. Monad开发是一个使用Foundry和testnet的开发框架，提供网络、验证和_wallet持久化等功能。 Monad開発は、Foundryとtestnetを使用した開発フレームワークで、ネットワーク、検証、ウォレット永続化などの機能を提供します。 Monad 개발은 Foundry와 testnet를 사용하는 개발 프레임워크로, 네트워크, 검증, 지갑 持久化 등의 기능을 제공합니다. Monad-development es un framework para desarrolladores que utiliza Foundry y testnet. Ofrece características como verificación de contratos y persistencia de wallets Monad-development est un framework pour les développeurs qui utilise Foundry et testnet. Il offre des fonctionnalités telles que la vérification de contrats et la persistance de wallets Monad-development ist ein Framework für Entwickler, das Foundry und testnet verwendet. Es bietet Funktionen wie Vertragsverifizierung und Wallet-Persistenz O Monad Development é uma ferramenta para desenvolvedores que fornece uma configuração padrão para testnet e mainnet, com verificação de contratos e framework Foundry Monad Development — это инструмент для разработчиков, предоставляющий стандартную настройку для testnet и mainnet, с верификацией контрактов и фреймворком Foundry для ИИ Агентов Monad Development هو أداة للبرمجة توفر إعدادات افتراضية لشبكات اختبار والشبكات الرئيسية، مع التحقق من العقود وإطار العمل Foundry how to use monad-development monad-development setup guide what is monad-development monad-development vs hardhat monad-development install monad-development tutorial for AI agents foundry framework integration testnet contract deployment Monad开发 AIエージェント工具 Foundry框架 testnet开发 合约验证 Wallet持久化 Monad开发设置 AI开发工具 Deploys contracts on testnet with chain ID 10143 Verifies contracts after deployment by default Utilizes Foundry framework for development Persists generated wallets for secure management Supports mainnet deployment when specified by the user Fetches additional documentation from https://docs.monad.xyz/llms.txt monad-development is a specialized skill for AI agents that facilitates contract deployment, verification, and wallet management on blockchain testnets');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('accountbelongstox/core_node/project-characteristics', 'community', 'accountbelongstox', 'core_node', 'accountbelongstox/core_node', 'project-characteristics', 0, 0, 41, '2026-03-07T01:49:01.657Z', '2026-03-07T02:25:12.484Z', 'a939ca4ad8bd97c0165e85ac544696aba993000557a89b3f1626df850fddfefb', '{"id":"accountbelongstox/core_node/project-characteristics","name":"project-characteristics","description":{"en":"The project-characteristics skill outlines pycore''s framework and development conventions, benefiting developers working on pycore_module_caller, callmodule, and native_ui projects.","zh":"Pycore 项目特性描述了 Pycore 的要求与约定，包括框架与开发规范，用于快速开发和修改代码","ja":"Pycore プロジェクト特性は、Pycore の要求と約定を記述したもので、フレームワークと開発規約が含まれています","ko":"Pycore 프로젝트 특성은 Pycore의 요구와 약정을 설명하며, 프레임워크와 개발 규약을 포함합니다","es":"El proyecto pycore se basa en un conjunto de características y convenciones que definen su estructura y comportamiento","fr":"Le projet pycore repose sur un ensemble de caractéristiques et de conventions qui définissent sa structure et son comportement","de":"Das pycore-Projekt basiert auf einer Reihe von Merkmalen und Konventionen, die seine Struktur und sein Verhalten definieren","pt":"O projeto pycore requer configuração específica para desenvolver ou modificar código. Aprenda a configurar as características do projeto pycore.","ru":"Проект pycore требует специальной настройки для разработки или изменения кода. Узнайте, как настроить характеристики проекта pycore.","ar":"يحتاج مشروع pycore إلى إعداد محدد لتنمية أو تعديل الكود. تعرف على كيفية إعداد سمات مشروع pycore."},"seo":{"title":{"en":"project-characteristics: Setup Guide for pycore Developer...","zh":"Pycore 项目特性设置指南","ja":"Pycore プロジェクト特性のベストプラクティス - AIエージェント","ko":"Pycore 프로젝트 특성 설정 가이드 - AI 도구","es":"Guía de configuración de pycore: características del proy...","fr":"Guide de configuration pycore : caractéristiques du projet","de":"pycore-Konfigurationsleitfaden: Projektmerkmale","pt":"Guia de Configuração de Características de Projeto pycore","ru":"Настройка Характеристик Проекта pycore: ИИ Агенты","ar":"دليل إعداد سمات المشروع pycore مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient pycore development with project-characteristics. Learn how to navigate pycore_module_caller, ServiceLauncher, and THREAD_BUS for seamless in...","zh":"了解 Pycore 项目特性的要求与约定，包括框架与开发规范，快速开发和修改代码","ja":"Pycore プロジェクト特性の要求と約定を理解して、コードの開発と変更を迅速化する - AIエージェント","ko":"Pycore 프로젝트 특성의 요구와 약정을 이해하여 코드 개발과 수정을 신속하게 수행하는 방법 - AI 도구","es":"Aprende a configurar pycore según sus características de proyecto, incluyendo el módulo de llamada y el lanzador de servicios","fr":"Découvrez comment configurer pycore en fonction de ses caractéristiques de projet, y compris le module d''appel et le lanceur de services","de":"Erfahren Sie, wie Sie pycore nach seinen Projektmerkmalen konfigurieren, einschließlich des Moduls für den Aufruf und des Dienstlaunchers","pt":"Aprenda a configurar as características do projeto pycore para desenvolver ou modificar código com eficiência","ru":"Узнайте, как настроить характеристики проекта pycore для эффективного развития или изменения кода с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد سمات مشروع pycore لتنمية أو تعديل الكود بفعالية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"project-characteristics is a set of guidelines and requirements for developing and modifying pycore code, ensuring consistency and best practices.","zh":"Pycore 项目特性是 Pycore 的框架与开发规范的要求与约定","ja":"Pycore プロジェクト特性は、Pycore のフレームワークと開発規約の要求と約定です","ko":"Pycore 프로젝트 특성은 Pycore의 프레임워크와 개발 규약의 요구와 약정입니다","es":"Características del proyecto que definen la estructura y el comportamiento de pycore","fr":"Caractéristiques du projet qui définissent la structure et le comportement de pycore","de":"Projektmerkmale, die die Struktur und das Verhalten von pycore definieren","pt":"As características do projeto pycore são um conjunto de requisitos e convenções para desenvolver ou modificar código","ru":"Характеристики проекта pycore - это набор требований и соглашений для разработки или изменения кода","ar":"سمات مشروع pycore هي مجموعة من المتطلبات والاتفاقيات لتنمية أو تعديل الكود"},"features":{"en":["Utilizes pycore_module_caller.py as the root entry point","Leverages ServiceLauncher for configuring and starting services","Interacts with THREAD_BUS for efficient communication","Supports modification of tray, startup, and main window behavior","Integrates with build_launcher_config() for streamlined configuration"],"zh":["包括 pycore_module_caller、callmodule、pylauncher、pythreadpool 和 native_ui","支持添加服务、更改托盘/启动/主窗口行为","支持 THREAD_BUS、launcher 和 config","根入口为 pycore_module_caller.py","使用 build_launcher_config() 和 ServiceLauncher(config).start()","注册和启动服务"],"ja":["pycore_module_caller、callmodule、pylauncher、pythreadpool、native_ui を含む","サービス追加、トレイ/起動/メインウィンドウの動作変更をサポート","THREAD_BUS、launcher、config をサポート","ルートエントリは pycore_module_caller.py","build_launcher_config() と ServiceLauncher(config).start() を使用","サービス登録と起動"],"ko":["pycore_module_caller, callmodule, pylauncher, pythreadpool, native_ui를 포함","서비스 추가, 트레이/시작/메인 창 동작 변경을 지원","THREAD_BUS, launcher, config를 지원","루트 엔트리는 pycore_module_caller.py","build_launcher_config()와 ServiceLauncher(config).start()를 사용","서비스 등록과 시작"],"es":["Módulo de llamada pycore (pycore_module_caller)","Lanzador de servicios (ServiceLauncher)","Configuración de lanzamiento (build_launcher_config)","Gestión de hilos (THREAD_BUS)","Interfaz de usuario nativa (native_ui)"],"fr":["Module d''appel pycore (pycore_module_caller)","Lanceur de services (ServiceLauncher)","Configuration de lancement (build_launcher_config)","Gestion des threads (THREAD_BUS)","Interface utilisateur native (native_ui)"],"de":["Aufrufmodul pycore (pycore_module_caller)","Dienstlauncher (ServiceLauncher)","Startkonfiguration (build_launcher_config)","Thread-Verwaltung (THREAD_BUS)","Native Benutzeroberfläche (native_ui)"],"pt":["Utilização do pycore_module_caller.py como entrada","Configuração do ServiceLauncher com build_launcher_config()","Integração com THREAD_BUS e launcher","Modificação do comportamento da janela principal e da bandeja de sistema","Utilização do pythreadpool para gerenciamento de threads"],"ru":["Использование pycore_module_caller.py в качестве входной точки","Настройка ServiceLauncher с помощью build_launcher_config()","Интеграция с THREAD_BUS и launcher","Изменение поведения главного окна и системной панели","Использование pythreadpool для управления потоками"],"ar":["استخدام pycore_module_caller.py كمدخل","إعداد ServiceLauncher باستخدام build_launcher_config()","التكامل مع THREAD_BUS و launcher","تعديل سلوك النافذة الرئيسية و شريط الحالة","استخدام pythreadpool لإدارة الخيوط"]},"keywords":{"en":["how to use project-characteristics","project-characteristics setup guide","pycore development best practices","project-characteristics vs pycore alternatives","project-characteristics install for pycore_module_caller","what is project-characteristics in pycore development"],"zh":["Pycore 项目特性","Pycore 框架","Pycore 开发规范","AI工具","Python 开发","代码开发","代码修改","pycore_module_caller","callmodule","pylauncher","pythreadpool","native_ui"],"ja":["Pycore プロジェクト特性","Pycore フレームワーク","Pycore 開発規約","AIエージェント","Python 開発","コード開発","コード変更","pycore_module_caller","callmodule","pylauncher","pythreadpool","native_ui"],"ko":["Pycore 프로젝트 특성","Pycore 프레임워크","Pycore 개발 규약","AI 도구","Python 개발","코드 개발","코드 수정","pycore_module_caller","callmodule","pylauncher","pythreadpool","native_ui"],"es":["pycore configuración","características del proyecto pycore","módulo de llamada pycore","lanzador de servicios pycore","THREAD_BUS pycore","interfaz de usuario nativa pycore","desarrollo de software con pycore"],"fr":["configuration pycore","caractéristiques du projet pycore","module d''appel pycore","lanceur de services pycore","THREAD_BUS pycore","interface utilisateur native pycore","développement de logiciels avec pycore"],"de":["pycore-Konfiguration","Projektmerkmale pycore","Aufrufmodul pycore","Dienstlauncher pycore","THREAD_BUS pycore","native Benutzeroberfläche pycore","Softwareentwicklung mit pycore"],"pt":["pycore","desenvolvimento de código","configuração de projeto","pycore_module_caller.py","ServiceLauncher","THREAD_BUS","launcher","pythreadpool"],"ru":["pycore","разработка кода","настройка проекта","pycore_module_caller.py","ServiceLauncher","THREAD_BUS","launcher","pythreadpool","ИИ Агенты"],"ar":["pycore","تنمية الكود","إعداد المشروع","pycore_module_caller.py","ServiceLauncher","THREAD_BUS","launcher","pythreadpool","أدوات الذكاء الاصطناعي"]}},"owner":"accountbelongstox","repo":"core_node","repoPath":"accountbelongstox/core_node","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.657Z","topics":[],"category":"community","skillMd":{"name":"project-characteristics","description":"Describes pycore (Python core library of core_node) requirements, conventions, and architecture. Use when developing or modifying code under pycore (pycore_module_caller, callmodule, pylauncher, pythreadpool, native_ui). Enforces three-layer separation, THREAD_BUS-only cross-thread communication, step-based native_ui, and shutdown priority. This skill defines pycore requirements only.","bodyPreview":"# pycore 项目特性（框架与约定）\n\n本 skill 描述的是 **pycore** 的要求与约定（项目特性即 pycore 的框架与开发规范），不涉及项目其他部分。\n\n## When to Use\n\n- Use this skill when developing or modifying code under **pycore** (pycore_module_caller, callmodule, pylauncher, pythreadpool, native_ui).\n- Use when adding services, changing tray/startup/main window behavior, or touching THREAD_BUS / launcher / config.\n\n## Instructions\n\n### 入口与三层职责\n\n- **根入口**：`pycore_module_caller.py` → `build_launcher_config()` → `ServiceLauncher(config).start()` → `regis","body":"# pycore 项目特性（框架与约定）\n\n本 skill 描述的是 **pycore** 的要求与约定（项目特性即 pycore 的框架与开发规范），不涉及项目其他部分。\n\n## When to Use\n\n- Use this skill when developing or modifying code under **pycore** (pycore_module_caller, callmodule, pylauncher, pythreadpool, native_ui).\n- Use when adding services, changing tray/startup/main window behavior, or touching THREAD_BUS / launcher / config.\n\n## Instructions\n\n### 入口与三层职责\n\n- **根入口**：`pycore_module_caller.py` → `build_launcher_config()` → `ServiceLauncher(config).start()` → `register_event_handlers()`；主循环等 `THREAD_BUS.is_shutdown_requested()` 后 `launcher.stop()`。\n- **callmodule**：只做配置与事件注册（`config.build_launcher_config`、`event_handlers.register_event_handlers`），不启动线程。\n- **pylauncher**：单例检测 + 按 `config.services` 调用 pythreadpool 的 starter；不实现具体服务逻辑。\n- **pythreadpool**：`SERVICE_STARTERS[name](config)` 启动各服务线程（heartbeat / rpc_v2 / ui / tray），并注册 `register_shutdown_handler`；关机时发 `tray.request_stop`、`{app_id}.close` 等事件。\n\n### THREAD_BUS 通信\n\n- 线程间**不直接调用**，全部通过 THREAD_BUS：`trigger_event`、`register_event_handler`、`signal`/`wait_signal`、`set_thread_state`、`register_shutdown_handler`、`request_shutdown`。\n- 事件命名带命名空间（如 `ui.tray.show`、`app.close`、`tray.request_stop`）；需要时 event_data 带 `source`。\n- 关机按 `THREAD_REGISTRY` 的 `shutdown_priority` 逆序执行（数字小的先关）。\n\n### Native UI 结构（step0–step10）\n\n- 对外只通过 `pycore.pyutils.native_ui` 的 `__init__.py` 暴露；内部按 step 绝对引用。\n- **step0_i18n**：国际化。**step1_config**：NativeUIConfig、TrayConfig。**step2_port_url**：端口与 URL。**step3_launcher**：`launch_native_app`、`launcher_with_startup`。**step4_startup**：TkinterStartupThread（唯一 tk 引导窗）。**step5_main_ui**：PySide6 主窗、WebView、托盘。**step6_tray**：pystray、AppIndicator（Ubuntu）。**step7_managers**：thread_bus_manager、shutdown_manager 等。**step9_frontend**：前端进程。\n\n### 启动顺序（含 UI 时）\n\n1. 先起 TkinterStartupThread（tk 引导），发 `TkinterStartup_ready`。\n2. UI 线程内 `wait_signal(''TkinterStartup_ready'')` 后再 `get_third_package_pyside6()`，再创建 PySide6Framework 与主窗口。\n3. 引导结束后可发 `STARTUP_REQUEST_CLOSE` 关 tk；若启用托盘则进 tray（pystray 或 AppIndicator）。\n4. 关机：`request_shutdown` → 执行 shutdown handler（如 stop_ui 发 `{app_id}.close`，stop_tray 发 `tray.request_stop`）。\n\n### 平台与托盘\n\n- **platform_adapter**：根据 OS、X11、`XDG_CURRENT_DESKTOP` 给出 `recommended_tray_backend`（APPINDICATOR / PYSTRAY / PYSIDE6 / NONE）。\n- Ubuntu/GNOME 桌面优先用 AppIndicator，不可用时退回 pystray。Linux 无 X11 则无托盘。\n- `start_tray()` 与 `_run_tray_mode()` 根据推荐后端选择 AppIndicatorSystemTrayThread 或 TkinterSystemTrayThread；菜单用 `build_appindicator_menu_items` 或 `_build_tray_menu_items` 从 TrayConfig 生成。\n\n### 关键文件\n\n- 配置：`pycore/callmodule/config.py`。事件：`pycore/callmodule/event_handlers.py`。\n- 启动器：`pycore/pylauncher/launcher.py`。starter 与 registry：`pycore/pythreadpool/starters.py`、`registry.py`。\n- THREAD_BUS：`pycore/pyfoundations/thread_bus.py`。Native UI 入口：`pycore/pyutils/native_ui/step3_launcher/launch_native_app.py`。\n- tk 引导：`pycore/pyutils/native_ui/step4_startup/startup_window_thread.py`。主窗：`step5_main_ui/pyside6/framework.py`。平台：`pycore/pyutils/native_ui/platform_adapter.py`。\n\n### 开发约定\n\n- 新增服务：在 `registry.py` 的 THREAD_REGISTRY 加条目并设 `shutdown_priority`，在 `starters.py` 中实现 starter 并注册到 SERVICE_STARTERS；关机通过 THREAD_BUS 事件或 shutdown handler，不直接调其他线程。\n- 修改托盘/引导/主窗：保持「tk 先于 PySide6」「THREAD_BUS 关窗/关托盘」；Ubuntu 桌面优先 AppIndicator，失败再 pystray。\n"},"lastSynced":"2026-03-07T02:25:12.484Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing to understand pycore framework conventions and development standards.","zh":"非常适合需要了解pycore框架约定和开发标准的Python开发代理。","ja":"pycoreフレームワークの規約と開発標準を理解する必要があるPython開発エージェントに最適です。","ko":"pycore 프레임워크 규약과 개발 표준을 이해해야 하는 Python 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de Python que necesitan comprender las convenciones y los estándares de desarrollo del framework pycore.","fr":"Idéal pour les agents de développement Python ayant besoin de comprendre les conventions et les normes de développement du framework pycore.","de":"Perfekt für Python-Entwicklungsagenten, die die pycore-Framework-Konventionen und -Entwicklungsstandards verstehen müssen.","pt":"Perfeito para Agentes de Desenvolvimento Python que precisam entender convenções e padrões de desenvolvimento do framework pycore.","ru":"Идеально подходит для агентов разработки Python, которым необходимо понимать соглашения и стандарты разработки фреймворка pycore.","ar":"مثالي للوكلاء الذين يحتاجون إلى فهم اتفاقيات وأساليب تطوير إطار عمل pycore."},"recommendation":{"en":"Empowers agents to navigate and modify pycore_module_caller, callmodule, and native_ui projects with confidence, utilizing pycore''s framework and development conventions, including THREAD_BUS, launcher, and config services.","zh":"赋予代理能够自信地导航和修改pycore_module_caller、callmodule和native_ui项目，利用pycore的框架和开发约定，包括THREAD_BUS、launcher和config服务。","ja":"エージェントがpycore_module_caller、callmodule、native_uiプロジェクトを自信を持ってナビゲートおよび変更できるようにし、pycoreのフレームワークと開発規約（THREAD_BUS、launcher、configサービスなど）を利用できる。","ko":"에이전트가 pycore_module_caller, callmodule, native_ui 프로젝트를 자신감 있게 탐색하고 수정할 수 있도록 하며, pycore의 프레임워크와 개발 규약(THREAD_BUS, launcher, config 서비스 등)을 활용할 수 있습니다.","es":"Habilita a los agentes a navegar y modificar proyectos pycore_module_caller, callmodule y native_ui con confianza, utilizando el framework y las convenciones de desarrollo de pycore, incluidos THREAD_BUS, launcher y servicios de configuración.","fr":"Permet aux agents de naviguer et de modifier les projets pycore_module_caller, callmodule et native_ui avec confiance, en utilisant le framework et les conventions de développement de pycore, y compris THREAD_BUS, launcher et services de configuration.","de":"Ermöglicht es den Agenten, pycore_module_caller-, callmodule- und native_ui-Projekte mit Zuversicht zu navigieren und zu modifizieren, indem sie das pycore-Framework und die Entwicklungskonventionen nutzen, einschließlich THREAD_BUS, launcher und Konfigurationsdienste.","pt":"Habilita os agentes a navegar e modificar projetos pycore_module_caller, callmodule e native_ui com confiança, utilizando o framework e as convenções de desenvolvimento do pycore, incluindo THREAD_BUS, launcher e serviços de configuração.","ru":"Наделяет агентов возможностью ориентироваться и изменять проекты pycore_module_caller, callmodule и native_ui с уверенностью, используя фреймворк и соглашения разработки pycore, включая THREAD_BUS, launcher и сервисы конфигурации.","ar":"يمكّن الوكلاء من التنقل وتعديل مشاريع pycore_module_caller و callmodule و native_ui بثقة، مستخدمين إطار العمل pycore وأساليب التطوير، بما في ذلك THREAD_BUS و launcher وخدمات التكوين."},"useCases":{"en":["Developing and modifying pycore_module_caller code","Adding services to pycore projects","Debugging THREAD_BUS and launcher configurations"],"zh":["开发和修改pycore_module_caller代码","向pycore项目添加服务","调试THREAD_BUS和launcher配置"],"ja":["pycore_module_callerコードの開発と変更","pycoreプロジェクトへのサービス追加","THREAD_BUSとlauncher構成のデバッグ"],"ko":["pycore_module_caller 코드 개발 및 수정","pycore 프로젝트에 서비스 추가","THREAD_BUS 및 launcher 구성 디버깅"],"es":["Desarrollar y modificar el código de pycore_module_caller","Agregar servicios a proyectos pycore","Depurar configuraciones de THREAD_BUS y launcher"],"fr":["Développer et modifier le code de pycore_module_caller","Ajouter des services aux projets pycore","Déboguer les configurations de THREAD_BUS et launcher"],"de":["pycore_module_caller-Code entwickeln und modifizieren","Dienste zu pycore-Projekten hinzufügen","THREAD_BUS- und launcher-Konfigurationen debuggen"],"pt":["Desenvolver e modificar código pycore_module_caller","Adicionar serviços a projetos pycore","Depurar configurações THREAD_BUS e launcher"],"ru":["Разрабатывать и изменять код pycore_module_caller","Добавлять сервисы в проекты pycore","Отлаживать конфигурации THREAD_BUS и launcher"],"ar":["تطوير وتعديل رمز pycore_module_caller","إضافة خدمات إلى مشاريع pycore","تصحيح أخطاء في تكوينات THREAD_BUS و launcher"]},"limitations":{"en":["Specific to pycore projects only","Requires knowledge of pycore framework and development conventions"],"zh":["仅限pycore项目","需要了解pycore框架和开发约定"],"ja":["pycoreプロジェクトのみ","pycoreフレームワークと開発規約の知識が必要"],"ko":["pycore 프로젝트만 해당","pycore 프레임워크와 개발 규약에 대한 지식이 필요"],"es":["Específico para proyectos pycore solo","Requiere conocimiento del framework y las convenciones de desarrollo de pycore"],"fr":["Spécifique aux projets pycore uniquement","Nécessite une connaissance du framework et des conventions de développement de pycore"],"de":["Spezifisch für pycore-Projekte nur","Benötigt Kenntnisse des pycore-Frameworks und der Entwicklungskonventionen"],"pt":["Específico para projetos pycore apenas","Requer conhecimento do framework pycore e convenções de desenvolvimento"],"ru":["Конкретно для проектов pycore","Требует знания фреймворка pycore и соглашений разработки"],"ar":["محدود لمشاريع pycore فقط","يتطلب معرفة إطار العمل pycore وأساليب التطوير"]},"version":4},"contentHash":"a939ca4ad8bd97c0165e85ac544696aba993000557a89b3f1626df850fddfefb","qualityScore":41}');
