INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('accountbelongstox/core_node/project-characteristics', 'project-characteristics', 'accountbelongstox', 'core_node', 'community', 'project-characteristics accountbelongstox core_node community The project-characteristics skill outlines pycore''s framework and development conventions, benefiting developers working on pycore_module_caller, callmodule, and native_ui projects. Pycore 项目特性描述了 Pycore 的要求与约定，包括框架与开发规范，用于快速开发和修改代码 Pycore プロジェクト特性は、Pycore の要求と約定を記述したもので、フレームワークと開発規約が含まれています Pycore 프로젝트 특성은 Pycore의 요구와 약정을 설명하며, 프레임워크와 개발 규약을 포함합니다 El proyecto pycore se basa en un conjunto de características y convenciones que definen su estructura y comportamiento Le projet pycore repose sur un ensemble de caractéristiques et de conventions qui définissent sa structure et son comportement Das pycore-Projekt basiert auf einer Reihe von Merkmalen und Konventionen, die seine Struktur und sein Verhalten definieren O projeto pycore requer configuração específica para desenvolver ou modificar código. Aprenda a configurar as características do projeto pycore. Проект pycore требует специальной настройки для разработки или изменения кода. Узнайте, как настроить характеристики проекта pycore. يحتاج مشروع pycore إلى إعداد محدد لتنمية أو تعديل الكود. تعرف على كيفية إعداد سمات مشروع pycore. how to use project-characteristics project-characteristics setup guide pycore development best practices project-characteristics vs pycore alternatives project-characteristics install for pycore_module_caller what is project-characteristics in pycore development Pycore 项目特性 Pycore 框架 Pycore 开发规范 AI工具 Python 开发 代码开发 代码修改 pycore_module_caller callmodule pylauncher pythreadpool native_ui Utilizes pycore_module_caller.py as the root entry point Leverages ServiceLauncher for configuring and starting services Interacts with THREAD_BUS for efficient communication Supports modification of tray, startup, and main window behavior Integrates with build_launcher_config() for streamlined configuration project-characteristics is a set of guidelines and requirements for developing and modifying pycore code, ensuring consistency and best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mouayadakel/flixCamFinal/api-response-compressor', 'community', 'mouayadakel', 'flixCamFinal', 'mouayadakel/flixCamFinal', 'api-response-compressor', 0, 0, 41, '2026-02-23T23:38:31Z', '2026-03-07T04:13:37.157Z', '9a1aefba31dbd9943b0b21e2417d97b607e286106a635d5397fe82cf7dff9d61', '{"id":"mouayadakel/flixCamFinal/api-response-compressor","name":"api-response-compressor","description":{"en":"The api-response-compressor skill optimizes API responses by selecting only needed fields, enforcing pagination, and enabling compression. It benefits developers working with large API responses and high-traffic endpoints.","zh":"API响应压缩器是一种优化API性能的工具，通过选择性返回字段、分页、压缩和缓存控制等功能，减少响应大小，提高用户体验","ja":"APIレスポンス圧縮ツールは、APIのパフォーマンスを最適化するためのツールです。フィールドの選択、ページネーション、圧縮、キャッシュ制御などの機能を提供します","ko":"API 응답 압축기는 API 성능을 최적화하는 도구로, 필드 선택, 페이징, 압축, 캐시 제어 등의 기능을 통해 응답 크기를 줄이고 성능을 개선합니다","es":"La herramienta API Response Compressor reduce el tamaño de las respuestas de API y mejora el rendimiento. Aprenda a configurarla para optimizar sus endpoints","fr":"L''outil API Response Compressor réduit la taille des réponses de l''API et améliore les performances. Découvrez comment le configurer pour optimiser vos endpoints","de":"Das Tool API Response Compressor reduziert die Größe der API-Antworten und verbessert die Leistung. Erfahren Sie, wie Sie es einrichten, um Ihre Endpunkte zu optimieren","pt":"O compressor de respostas de API é uma ferramenta que ajuda a reduzir o tamanho das respostas de API, melhorando o desempenho e a eficiência","ru":"Сжатие ответов API - это инструмент, который помогает уменьшить размер ответов API, улучшая производительность и эффективность","ar":"ضغط استجابة واجهة برمجة التطبيقات هو أداة تساعد على تقليل حجم استجابات واجهة برمجة التطبيقات، وتحسين الأداء والكفاءة"},"seo":{"title":{"en":"api-response-compressor: Compression Setup Guide | AI Age...","zh":"API响应压缩器Setup Guide - 优化API性能","ja":"APIレスポンス圧縮ツール - ベストプラクティス","ko":"API 응답 압축기 설정 가이드 - 최적의 성능","es":"Guía de configuración de API Response Compressor para des...","fr":"Guide de mise en place de l''outil API Response Compressor","de":"Leitfaden zur Einrichtung von API Response Compressor für...","pt":"Guia de Configuração do API Response Compressor","ru":"Настройка Сжатия Ответов API: Лучшие Практики","ar":"دليل ضغط استجابة واجهة برمجة التطبيقات"},"description":{"en":"Discover how to optimize API responses with api-response-compressor. Learn how to reduce response size and improve performance. Get started now!","zh":"了解API响应压缩器的工作原理，优化API性能，减少响应大小，提高用户体验","ja":"APIレスポンス圧縮ツールの使い方をマスターし、パフォーマンスを最適化する","ko":"API 응답 압축기를 사용하여 응답 크기를 줄이고 성능을 개선하는 방법을 알아보세요","es":"Optimice las respuestas de su API con la herramienta de compresión de respuestas API. Aprenda a reducir el tamaño de las respuestas y mejorar el rendimiento","fr":"Optimisez les réponses de votre API avec l''outil de compression de réponses API. Découvrez comment réduire la taille des réponses et améliorer les performances","de":"Optimieren Sie die Antworten Ihrer API mit dem API-Antworten-Komprimierungstool. Erfahren Sie, wie Sie die Antwortgröße reduzieren und die Leistung verbessern","pt":"Aprenda a otimizar respostas de API com o compressor de respostas de API, reduzindo o tamanho e melhorando o desempenho","ru":"Узнайте, как сжать ответы API с помощью сжатия ответов API, уменьшив размер и улучшая производительность","ar":"تعلم كيفية تحسين استجابات واجهة برمجة التطبيقات باستخدام ضغط استجابة واجهة برمجة التطبيقات، وتقليل الحجم وتحسين الأداء"},"definition":{"en":"api-response-compressor is a skill that reduces API response size by applying techniques like Prisma select, pagination, gzip/brotli compression, and cache control.","zh":"API响应压缩器是一种工具，用于优化API响应的大小和性能","ja":"APIレスポンス圧縮ツールは、APIレスポンスのサイズとパフォーマンスを最適化するためのツールです","ko":"API 응답 압축기는 API 응답의 크기와 성능을 최적화하는 도구입니다","es":"API Response Compressor es una herramienta que reduce el tamaño de las respuestas de API para mejorar el rendimiento y reducir el tráfico","fr":"API Response Compressor est un outil qui réduit la taille des réponses de l''API pour améliorer les performances et réduire le trafic","de":"API Response Compressor ist ein Tool, das die Größe der API-Antworten reduziert, um die Leistung zu verbessern und den Datenverkehr zu reduzieren","pt":"O que é um compressor de respostas de API? É uma ferramenta que reduz o tamanho das respostas de API","ru":"Что такое сжатие ответов API? Это инструмент, который уменьшает размер ответов API","ar":"ما هو ضغط استجابة واجهة برمجة التطبيقات؟ هو أداة لتقليل حجم استجابات واجهة برمجة التطبيقات"},"features":{"en":["Selects only needed fields using Prisma select to reduce response size","Enforces pagination with limit and offset/cursor to improve performance","Enables gzip/brotli compression in Next.js or hosting to reduce response size","Sets Cache-Control headers for cacheable responses to improve performance"],"zh":["选择性返回字段（Prisma select）","分页（limit和offset/cursor）","压缩（gzip/brotli）","缓存控制（Cache-Control）"],"ja":["フィールドの選択（Prisma select）","ページネーション（limitとoffset/cursor）","圧縮（gzip/brotli）","キャッシュ制御（Cache-Control）"],"ko":["필드 선택（Prisma select）","페이징（limit와 offset/cursor）","압축（gzip/brotli）","캐시 제어（Cache-Control）"],"es":["Selección de campos necesarios con Prisma select","Paginación con límite y desplazamiento/cursor","Compresión con gzip/brotli en Next.js o hosting","Encabezados de caché con Cache-Control para respuestas cacheables"],"fr":["Sélection de champs nécessaires avec Prisma select","Pagination avec limite et déplacement/cursor","Compression avec gzip/brotli dans Next.js ou l''hébergement","En-têtes de cache avec Cache-Control pour les réponses cacheables"],"de":["Auswahl der benötigten Felder mit Prisma select","Paginierung mit Limit und Offset/Cursor","Komprimierung mit gzip/brotli in Next.js oder Hosting","Cache-Header mit Cache-Control für cachebare Antworten"],"pt":["Seleção de campos necessários com Prisma select"," Paginação com limite e offset/cursor","Ativação do gzip/brotli no Next.js ou hospedagem","Definição de Cache-Control para respostas cacheáveis"],"ru":["Выбор необходимых полей с помощью Prisma select","Пагинация с ограничением и смещением/курсором","Включение gzip/brotli в Next.js или хостинге","Определение Cache-Control для кэшируемых ответов"],"ar":["اختيار الحقول الضرورية مع Prisma select","تنقلة الصفحات مع الحد والffset/مؤشر","تفعيل gzip/brotli في Next.js أو الاستضافة","تحديد Cache-Control للاستجابات القابلة للتخزين المؤقت"]},"keywords":{"en":["how to use api-response-compressor","api-response-compressor setup guide","api response compression techniques","Prisma select optimization","gzip/brotli compression in Next.js","api-response-compressor vs other compression tools","install api-response-compressor","api response optimization best practices"],"zh":["API响应压缩","API性能优化","Prisma select","gzip压缩","brotli压缩","缓存控制","API工具","AIエージェント"],"ja":["APIレスポンス圧縮","APIパフォーマンス最適化","Prisma select","gzip圧縮","brotli圧縮","キャッシュ制御","APIツール","AIエージェント"],"ko":["API 응답 압축","API 성능 최적화","Prisma select","gzip 압축","brotli 압축","캐시 제어","API 도구","AI 에이전트"],"es":["API Response Compressor","compresión de respuestas API","optimización de API","Prisma select","paginación API","compresión gzip/brotli","Cache-Control","herramientas de desarrollo"],"fr":["API Response Compressor","compression de réponses API","optimisation de l''API","Prisma select","pagination API","compression gzip/brotli","Cache-Control","outils de développement"],"de":["API Response Compressor","Komprimierung von API-Antworten","API-Optimierung","Prisma select","API-Paginierung","Komprimierung gzip/brotli","Cache-Control","Entwicklungstools"],"pt":["compressor de respostas de API","otimização de API","redução de tamanho de respostas","melhoria de desempenho","Prisma select","paginação de API"],"ru":["сжатие ответов API","оптимизация API","уменьшение размера ответов","улучшение производительности","Prisma select","пагинация API"],"ar":["ضغط استجابة واجهة برمجة التطبيقات","تحسين واجهة برمجة التطبيقات","تقليل حجم الاستجابات","تحسين الأداء","Prisma select","تنقلة صفحات واجهة برمجة التطبيقات"]}},"owner":"mouayadakel","repo":"flixCamFinal","repoPath":"mouayadakel/flixCamFinal","stars":0,"forks":0,"updatedAt":"2026-02-23T23:38:31Z","topics":[],"category":"community","skillMd":{"name":"api-response-compressor","description":"Reduces API payload size via select/pagination, compression, and caching headers. Use when responses are large (>100KB) or high-traffic.","bodyPreview":"# API Response Compressor\n\n## When to Trigger\n\n- Large API responses (>100 KB)\n- High-traffic endpoints\n- \"Optimize API\"\n\n## What to Do\n\n1. **Select**: Return only needed fields (Prisma select); avoid deep include of unused relations.\n2. **Pagination**: Enforce limit and offset/cursor; return meta (total, page, hasMore).\n3. **Compression**: Enable gzip/brotli in Next.js or hosting; set Content-Encoding when applicable.\n4. **Headers**: Cache-Control for cacheable responses (e.g. s-maxage, stale-w","body":"# API Response Compressor\n\n## When to Trigger\n\n- Large API responses (>100 KB)\n- High-traffic endpoints\n- \"Optimize API\"\n\n## What to Do\n\n1. **Select**: Return only needed fields (Prisma select); avoid deep include of unused relations.\n2. **Pagination**: Enforce limit and offset/cursor; return meta (total, page, hasMore).\n3. **Compression**: Enable gzip/brotli in Next.js or hosting; set Content-Encoding when applicable.\n4. **Headers**: Cache-Control for cacheable responses (e.g. s-maxage, stale-while-revalidate).\n\nDon’t break existing clients; add fields optionally (e.g. ?fields=) if needed. Measure response size before/after.\n"},"lastSynced":"2026-03-07T04:13:37.157Z","agentAnalysis":{"suitability":{"en":"Ideal for API-focused Agents requiring efficient data transfer and optimization techniques.","zh":"适用于需要高效数据传输和优化技术的API专注代理。","ja":"API に焦点を当てたエージェントが効率的なデータ転送と最適化技術を必要とする場合に適しています。","ko":"효율적인 데이터 전송 및 최적화 기술이 필요한 API 중심 에이전트에 적합합니다.","es":"Ideal para agentes enfocados en API que requieren una transferencia de datos eficiente y técnicas de optimización.","fr":"Idéal pour les agents axés sur l''API nécessitant un transfert de données efficace et des techniques d''optimisation.","de":"Ideal für API-fokussierte Agenten, die eine effiziente Datenübertragung und Optimierungstechniken erfordern.","pt":"Ideal para Agentes focados em API que exigem transferência de dados eficiente e técnicas de otimização.","ru":"Идеально подходит для агентов, ориентированных на API, требующих эффективной передачи данных и методов оптимизации.","ar":"مثالي للوكلاء المعنيين بالموتمر API الذين يتطلبون نقل بيانات فعالا وتقنيات تحسين الأداء."},"recommendation":{"en":"Empowers agents to streamline API responses by selectively returning needed fields via Prisma select, enforcing pagination with limit and offset/cursor, and leveraging gzip/brotli compression in Next.js or hosting environments, ultimately enhancing performance and reducing latency.","zh":"通过 Prisma 选择仅返回所需字段、通过限制和偏移/光标强制分页以及在 Next.js 或托管环境中利用 gzip/brotli 压缩来增强性能和降低延迟，赋予代理简化 API 响应的能力。","ja":"Prisma 選択を使用して必要なフィールドのみを返し、制限とオフセット/カーソルを使用してページ付けを強制し、Next.js またはホスティング環境で gzip/brotli圧縮を利用することで、エージェントに API 応答を簡素化する能力を与え、パフォーマンスを向上させ、待ち時間を短縮します。","ko":"Prisma 선택을 통해 필요한 필드만 반환하고, 제한과 오프셋/커서를 사용하여 페이징을 강제하고, Next.js 또는 호스팅 환경에서 gzip/brotli 압축을 활용하여 에이전트가 API 응답을 최적화하도록 하여 성능을 향상시키고 대기 시간을 줄입니다.","es":"Habilita a los agentes a optimizar las respuestas de API al devolver selectivamente los campos necesarios a través de Prisma select, aplicar paginación con límite y desplazamiento/puntero, y aprovechar la compresión gzip/brotli en Next.js o entornos de hosting, mejorando en última instancia el rendimiento y reduciendo la latencia.","fr":"Permet aux agents d''optimiser les réponses API en renvoyant sélectivement les champs nécessaires via Prisma select, en appliquant la pagination avec une limite et un décalage/curseur, et en exploitant la compression gzip/brotli dans Next.js ou les environnements d''hébergement, améliorant ainsi les performances et réduisant la latence.","de":"Ermächtigt die Agenten, API-Antworten zu optimieren, indem sie die erforderlichen Felder über Prisma select selektiv zurückgeben, Paginierung mit Limit und Offset/Cursor erzwingen und die gzip/brotli-Komprimierung in Next.js oder Hosting-Umgebungen nutzen, wodurch letztendlich die Leistung verbessert und die Latenz reduziert wird.","pt":"Permite que os agentes otimizem as respostas da API, retornando seletivamente os campos necessários via Prisma select, aplicando paginação com limit e offset/cursor e utilizando compressão gzip/brotli em Next.js ou ambientes de hospedagem, melhorando assim o desempenho e reduzindo a latência.","ru":"Позволяет агентам оптимизировать ответы API, выборочно возвращая необходимые поля через Prisma select, реализуя постраничную разбивку с помощью limit и offset/курсор и используя сжатие gzip/brotli в Next.js или средах хостинга, тем самым повышая производительность и снижая задержку.","ar":"تمكن الوكلاء من تحسين استجابات API عن طريق إرجاع الحقول المطلوبة بشكل انتقائي عبر Prisma select وفرض التصفح مع حد و إزاحة/منصر و الاستفادة من ضغط gzip/brotli في Next.js أو بيئات الاستضافة، مما يحسن الأداء ويقلل من التأخير في النهاية."},"useCases":{"en":["Optimizing large API responses exceeding 100 KB","Enhancing high-traffic endpoints with efficient data retrieval","Implementing cache control mechanisms like Cache-Control headers for cacheable responses"],"zh":["优化超过 100 KB 的大型 API 响应","使用高效的数据检索来增强高流量端点","实施缓存控制机制，例如缓存响应的 Cache-Control 头"],"ja":["100 KB を超える大きな API 応答を最適化する","効率的なデータの取得を使用して高トラフィックのエンドポイントを強化する","キャッシュ可能な応答の Cache-Control ヘッダーなどのキャッシュ制御メカニズムを実装する"],"ko":["100KB 이상의 대형 API 응답 최적화","효율적인 데이터 검색을 통해 고트래픽 엔드포인트 강화","캐시 가능한 응답을 위한 Cache-Control 헤더와 같은 캐시 제어 메커니즘 구현"],"es":["Optimizar respuestas de API grandes que superan los 100 KB","Mejorar los puntos finales de alto tráfico con recuperación de datos eficiente","Implementar mecanismos de control de caché como encabezados Cache-Control para respuestas que se pueden cachear"],"fr":["Optimiser les réponses API de grande taille dépassant 100 Ko","Améliorer les points de terminaison à trafic élevé avec une récupération de données efficace","Mettre en œuvre des mécanismes de contrôle de cache tels que les en-têtes Cache-Control pour les réponses pouvant être mises en cache"],"de":["Optimieren von großen API-Antworten, die 100 KB überschreiten","Verbessern von hochfrequenten Endpunkten mit effizienter Datenrückgewinnung","Implementieren von Cache-Steuerungsmechanismen wie Cache-Control-Headern für cachebare Antworten"],"pt":["Otimizando respostas de API grandes que excedem 100 KB","Melhorando pontos finais de alto tráfego com recuperação de dados eficiente","Implementando mecanismos de controle de cache como cabeçalhos Cache-Control para respostas em cache"],"ru":["Оптимизация крупных ответов API, превышающих 100 КБ","Улучшение высокообъемных конечных точек с эффективным извлечением данных","Реализация механизмов контроля кэша, таких как заголовки Cache-Control для кэшируемых ответов"],"ar":["تحسين استجابات API الكبيرة التي تتجاوز 100 كيلو بايت","تحسين نقاط النهاية ذات الحركة المرورية الكبيرة مع استرجاع البيانات الفعال","تنفيذ آلياتควบคلة الذاكرة المؤقتة مثل رؤوس Cache-Control للاستجابات القابلة للتخزين المؤقت"]},"limitations":{"en":["Requires API response sizes over 100 KB for significant optimization impact","Beneficial primarily for high-traffic endpoints or when ''Optimize API'' is explicitly required"],"zh":["需要 API 响应大小超过 100 KB 才能显著优化","主要适用于高流量端点或显式要求 ''优化 API'' 的情况"],"ja":["100 KB を超える API 応答サイズが必要な場合にのみ有意な最適化の影響","主に高トラフィックのエンドポイントまたは ''API を最適化'' が明示的に必要な場合に有益"],"ko":["의미 있는 최적화 영향을 위해 API 응답 크기가 100KB 이상이어야 함","주로 고트래픽 엔드포인트 또는 ''API 최적화''가 명시적으로 필요한 경우에 유용"],"es":["Requiere tamaños de respuestas de API superiores a 100 KB para un impacto de optimización significativo","Beneficioso principalmente para puntos finales de alto tráfico o cuando se requiere explícitamente ''Optimizar API''"],"fr":["Nécessite des tailles de réponses API supérieures à 100 Ko pour un impact d''optimisation significatif","Bénéfique principalement pour les points de terminaison à trafic élevé ou lorsque ''Optimiser l''API'' est explicitement requis"],"de":["Erfordert API-Antwortgrößen über 100 KB für einen signifikanten Optimierungseffekt","Vor allem für hochfrequentierte Endpunkte oder wenn ''API optimieren'' explizit erforderlich ist, vorteilhaft"],"pt":["Exige tamanhos de respostas de API acima de 100 KB para um impacto de otimização significativo","É benéfico principalmente para pontos finais de alto tráfego ou quando ''Otimizar API'' é explicitamente necessário"],"ru":["Требует размеров ответов API более 100 КБ для значительного влияния на оптимизацию","Преимущественно полезен для высокообъемных конечных точек или когда явно требуется ''Оптимизировать API''"],"ar":["يتطلب أحجام استجابات API أكبر من 100 كيلو بايت لتأثير تحسين كبير","يفيد في المقام الأول نقاط النهاية ذات الحركة المرورية الكبيرة أو عند الحاجة الصريحة إلى ''تحسين API''"]},"version":4},"contentHash":"9a1aefba31dbd9943b0b21e2417d97b607e286106a635d5397fe82cf7dff9d61","qualityScore":41}');
