INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mouayadakel/flixCamFinal/api-response-compressor', 'api-response-compressor', 'mouayadakel', 'flixCamFinal', 'community', 'api-response-compressor mouayadakel flixCamFinal community The api-response-compressor skill optimizes API responses by selecting only needed fields, enforcing pagination, and enabling compression. It benefits developers working with large API responses and high-traffic endpoints. API响应压缩器是一种优化API性能的工具，通过选择性返回字段、分页、压缩和缓存控制等功能，减少响应大小，提高用户体验 APIレスポンス圧縮ツールは、APIのパフォーマンスを最適化するためのツールです。フィールドの選択、ページネーション、圧縮、キャッシュ制御などの機能を提供します API 응답 압축기는 API 성능을 최적화하는 도구로, 필드 선택, 페이징, 압축, 캐시 제어 등의 기능을 통해 응답 크기를 줄이고 성능을 개선합니다 La herramienta API Response Compressor reduce el tamaño de las respuestas de API y mejora el rendimiento. Aprenda a configurarla para optimizar sus endpoints L''outil API Response Compressor réduit la taille des réponses de l''API et améliore les performances. Découvrez comment le configurer pour optimiser vos endpoints Das Tool API Response Compressor reduziert die Größe der API-Antworten und verbessert die Leistung. Erfahren Sie, wie Sie es einrichten, um Ihre Endpunkte zu optimieren O compressor de respostas de API é uma ferramenta que ajuda a reduzir o tamanho das respostas de API, melhorando o desempenho e a eficiência Сжатие ответов API - это инструмент, который помогает уменьшить размер ответов API, улучшая производительность и эффективность ضغط استجابة واجهة برمجة التطبيقات هو أداة تساعد على تقليل حجم استجابات واجهة برمجة التطبيقات، وتحسين الأداء والكفاءة how to use api-response-compressor api-response-compressor setup guide api response compression techniques Prisma select optimization gzip/brotli compression in Next.js api-response-compressor vs other compression tools install api-response-compressor api response optimization best practices API响应压缩 API性能优化 Prisma select gzip压缩 brotli压缩 缓存控制 API工具 AIエージェント Selects only needed fields using Prisma select to reduce response size Enforces pagination with limit and offset/cursor to improve performance Enables gzip/brotli compression in Next.js or hosting to reduce response size Sets Cache-Control headers for cacheable responses to improve performance api-response-compressor is a skill that reduces API response size by applying techniques like Prisma select, pagination, gzip/brotli compression, and cache control.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aerkn1/lang-tutor/create_word_tree', 'community', 'aerkn1', 'lang-tutor', 'aerkn1/lang-tutor', 'create_word_tree', 0, 0, 41, '2026-03-01T20:57:07Z', '2026-03-07T04:16:29.326Z', 'ab6b7d6404e883a55d91647ddb26209dbb40ae85db0d4029f0739dd1089c5e44', '{"id":"aerkn1/lang-tutor/create_word_tree","name":"create_word_tree","description":{"en":"The create_word_tree skill is a language tutor that generates word trees based on daily notes. It benefits language learners and educators by providing a structured approach to vocabulary building.","zh":"create_word_tree技能用于创建单词树，通过读取vocab/daily/daily-notes-YYYY-MM-DD.md文件来提取单词","ja":"ワードツリーを作成するcreate_word_treeスキルは、vocab/daily/daily-notes-YYYY-MM-DD.mdファイルから単語を抽出します","ko":"create_word_tree 스킬은 단어 트리를 생성하기 위해 vocab/daily/daily-notes-YYYY-MM-DD.md 파일을 읽어 단어를 추출합니다","es":"Create_word_tree es una habilidad que utiliza el directorio actual para generar un árbol de palabras para el aprendizaje de lenguas","fr":"Create_word_tree est une compétence qui utilise le répertoire actuel pour générer un arbre de mots pour l''apprentissage des langues","de":"Create_word_tree ist eine Fähigkeit, die das aktuelle Verzeichnis verwendet, um einen Wortbaum für das Sprachenlernen zu erstellen","pt":"O create_word_tree é uma habilidade que cria uma árvore de palavras para ajudar no aprendizado de idiomas. Ele usa o CLI e Python para processar arquivos de notas diárias","ru":"Create_word_tree - это навык, который создает дерево слов для помощи в изучении языков. Он использует CLI и Python для обработки файлов дневных заметок","ar":"create_word_tree هو مهارة تقوم بإنشاء شجرة من الكلمات لمساعدة في تعلم اللغة. يستخدم CLI و Python لمعالجة ملفات الملاحظات اليومية"},"seo":{"title":{"en":"create_word_tree: Setup Guide for AI Agents | Language Tutor","zh":"创建单词树指南 - AI智能工具","ja":"ワードツリー作成ベストプラクティス - AIエージェント","ko":"단어 트리 생성 설정 가이드 - AI 에이전트","es":"Guía de configuración de create_word_tree para agentes de...","fr":"Configurer create_word_tree pour les outils d''intelligenc...","de":"Einrichtungsleitfaden für create_word_tree in Sprachordnern","pt":"Guia de Configuração do create_word_tree para Desenvolved...","ru":"Руководство по созданию create_word_tree с помощью ИИ Аге...","ar":"دليل إنشاء create_word_tree باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of create_word_tree, a language tutor skill that generates word trees. Learn how to set it up and get started with our expert guide.","zh":"了解如何使用create_word_tree技能创建单词树，包括工作流程和技术细节","ja":"ワードツリーを作成するためのcreate_word_treeスキルの使い方を紹介します","ko":"create_word_tree 스킬을 사용하여 단어 트리를 생성하는 방법에 대한 정보","es":"Aprende a utilizar create_word_tree para mejorar tus habilidades lingüísticas con agentes de lenguaje","fr":"Découvrez comment configurer create_word_tree pour améliorer vos compétences linguistiques avec les outils d''IA","de":"Erfahren Sie, wie Sie create_word_tree einrichten, um Ihre Sprachkenntnisse mit KI-Tools zu verbessern","pt":"Aprenda a configurar o create_word_tree para melhorar a experiência de aprendizado de idiomas com tecnologias como CLI e Python","ru":"Узнайте, как создать create_word_tree с помощью ИИ Агентов и mejorar эффективность обучения языкам с использованием CLI и Python","ar":"اكتشف كيفية إنشاء create_word_tree باستخدام أدوات الذكاء الاصطناعي و تحسين تجربة تعلم اللغة مع تكنولوجيا CLI و Python"},"definition":{"en":"create_word_tree is a skill that generates word trees from daily notes in a language folder, using commands like date +%F to determine the target date.","zh":"create_word_tree是AI智能工具中的一个技能，用于创建单词树","ja":"create_word_treeはAIエージェントのスキルの一つで、ワードツリーを作成する","ko":"create_word_tree는 AI 에이전트의 스킬 중 하나로 단어 트리를 생성합니다","es":"Create_word_tree es una habilidad de inteligencia artificial que genera un árbol de palabras","fr":"Create_word_tree est une compétence d''IA qui génère un arbre de mots","de":"Create_word_tree ist eine KI-Fähigkeit, die einen Wortbaum generiert","pt":"O create_word_tree é uma ferramenta que cria uma árvore de palavras a partir de notas diárias para auxiliar no aprendizado de idiomas","ru":"Create_word_tree - это инструмент, который создает дерево слов из дневных заметок для помощи в изучении языков","ar":"create_word_tree هو أداة تقوم بإنشاء شجرة من الكلمات من الملاحظات اليومية لتسهيل تعلم اللغة"},"features":{"en":["Determines target date using date +%F command","Confirms presence of vocab/ directory in current working directory","Reads source notes from vocab/daily/daily-notes-YYYY-MM-DD.md files","Extracts usable words from source notes, ignoring headings and blank lines","Treats source as empty if it only contains placeholder lines like -"],"zh":["确定目标日期","读取vocab/daily/daily-notes-YYYY-MM-DD.md文件","提取单词","支持CLI命令","使用date +%F命令获取当前日期"],"ja":["対象日付の決定","vocab/daily/daily-notes-YYYY-MM-DD.mdファイルの読み取り","単語の抽出","CLIコマンドのサポート","date +%Fコマンドを使用して現在の日付を取得"],"ko":["대상 날짜 결정","vocab/daily/daily-notes-YYYY-MM-DD.md 파일 읽기","단어 추출","CLI 명령어 지원","date +%F 명령어를 사용하여 현재 날짜 가져오기"],"es":["Determina la fecha objetivo utilizando `date +%F`","Confirma la existencia del directorio `vocab/`","Lee la nota de origen desde `vocab/daily/daily-notes-YYYY-MM-DD.md`","Extrae palabras del texto utilizando técnicas de procesamiento de lenguaje natural","Trata el texto como vacío si solo contiene encabezados, líneas en blanco o líneas de marcador de posición"],"fr":["Détermine la date cible en utilisant `date +%F`","Confirme l''existence du répertoire `vocab/`","Lit la note de source à partir de `vocab/daily/daily-notes-YYYY-MM-DD.md`","Extrait des mots du texte en utilisant des techniques de traitement automatique des langues","Traite le texte comme vide si celui-ci ne contient que des en-têtes, des lignes vides ou des lignes de marqueur de position"],"de":["Bestimmt das Zieldatum mithilfe von `date +%F`","Überprüft die Existenz des Verzeichnisses `vocab/`","Liest die Quellennotiz aus `vocab/daily/daily-notes-YYYY-MM-DD.md`","Extrahiert Wörter aus dem Text mithilfe von Techniken der natürlichen Sprachverarbeitung","Behandelt den Text als leer, wenn er nur Überschriften, leere Zeilen oder Platzhalterzeilen enthält"],"pt":["Processamento de arquivos de notas diárias com CLI","Extração de palavras com Python","Criação de árvore de palavras para aprendizado de idiomas","Compatibilidade com pastas de idiomas como ''german''","Uso de data e hora atuais com `date +%F`"],"ru":["Обработка файлов дневных заметок с помощью CLI","Извлечение слов с помощью Python","Создание дерева слов для изучения языков","Совместимость с папками языков как ''german''","Использование текущей даты и времени с `date +%F`"],"ar":["معالجة ملفات الملاحظات اليومية باستخدام CLI","استخراج الكلمات باستخدام Python","إنشاء شجرة من الكلمات لتعلم اللغة","التوافق مع مجلدات اللغة مثل ''german''","استخدام التاريخ والوقت الحاليين مع `date +%F`"]},"keywords":{"en":["how to use create_word_tree","create_word_tree setup guide","create_word_tree alternative","create_word_tree vs language learning apps","what is create_word_tree","create_word_tree install","create_word_tree for language tutors","create_word_tree workflow","create_word_tree and vocabulary building"],"zh":["create_word_tree","AI智能工具","单词树","vocab/daily/daily-notes-YYYY-MM-DD.md","CLI命令","date +%F","AIエージェント","自然语言处理"],"ja":["create_word_tree","AIエージェント","ワードツリー","vocab/daily/daily-notes-YYYY-MM-DD.md","CLIコマンド","date +%F","AIツール","自然言語処理"],"ko":["create_word_tree","AI 에이전트","단어 트리","vocab/daily/daily-notes-YYYY-MM-DD.md","CLI 명령어","date +%F","AI 도구","자연어 처리"],"es":["create_word_tree","agentes de lenguaje","aprendizaje de lenguas","procesamiento de lenguaje natural","generación de árboles de palabras","configuración de create_word_tree","herramientas de inteligencia artificial"],"fr":["create_word_tree","outils d''intelligence artificielle","apprentissage des langues","traitement automatique des langues","génération d''arbres de mots","configuration de create_word_tree","compétences d''IA"],"de":["create_word_tree","KI-Tools","Sprachenlernen","natürliche Sprachverarbeitung","Wortbaumgenerierung","Einrichtung von create_word_tree","KI-Fähigkeiten"],"pt":["create_word_tree","aprendizado de idiomas","CLI","Python","árvore de palavras","pastas de idiomas","notas diárias","desenvolvimento de habilidades","ferramentas de IA"],"ru":["create_word_tree","изучение языков","CLI","Python","дерево слов","папки языков","дневные заметки","разработка навыков","ИИ Агенты"],"ar":["create_word_tree","تعلم اللغة","CLI","Python","شجرة من الكلمات","مجلدات اللغة","ملاحظات يومية","تطوير المهارات","أدوات الذكاء الاصطناعي"]}},"owner":"aerkn1","repo":"lang-tutor","repoPath":"aerkn1/lang-tutor","stars":0,"forks":0,"updatedAt":"2026-03-01T20:57:07Z","topics":[],"category":"community","skillMd":{"name":"create_word_tree","description":"Build CEFR-split word tree markdown files from the dated daily vocab note in the current language folder. Use this when the user wants to read `vocab/daily/daily-notes-YYYY-MM-DD.md`, organize every vocab item by part of speech, expand each item with usable grammar details, verify CEFR level through web search, rewrite the daily vocab note into the normalized word-tree schema, write dated `vocab-CEFR-YYYY-MM-DD.md` files inside per-level `daily/` folders, and update the cumulative CEFR vocab files.","bodyPreview":"# Create Word Tree\n\nUse this skill when the current working directory is a language folder such as `german`.\n\n## Workflow\n\n1. Determine the target date.\n   Default to today using `date +%F` unless the user names a specific date.\n2. Confirm the current directory contains `vocab/`.\n3. Read the source note:\n   `vocab/daily/daily-notes-YYYY-MM-DD.md`\n4. Treat the source as empty when it is missing or when it only contains headings, blank lines, or placeholder lines such as `-`.\n5. Extract every usab","body":"# Create Word Tree\n\nUse this skill when the current working directory is a language folder such as `german`.\n\n## Workflow\n\n1. Determine the target date.\n   Default to today using `date +%F` unless the user names a specific date.\n2. Confirm the current directory contains `vocab/`.\n3. Read the source note:\n   `vocab/daily/daily-notes-YYYY-MM-DD.md`\n4. Treat the source as empty when it is missing or when it only contains headings, blank lines, or placeholder lines such as `-`.\n5. Extract every usable vocab item from the file. Treat each non-empty study line, bullet, numbered item, inline comma-separated item, or short phrase as a candidate entry.\n6. Normalize each entry into a readable lemma:\n   keep the original German form, remove list markers, and preserve short fixed phrases when the source note uses a phrase instead of a single word.\n7. Classify each entry into the best-fit part of speech:\n   noun, verb, adjective, adverb, pronoun, conjunction, preposition, article, phrase, or other.\n8. Add the correct article first whenever the entry is a noun and the article can be stated or reliably inferred.\n9. Expand each entry with grammar details that actually exist for that type:\n   verbs: `ich`, `du`, `er/sie/es`, `wir`, `ihr`, `sie/Sie`, plus simple past and past participle (`v2-v3` style forms)\n   nouns and noun phrases: singular and plural when available, plus nominative, accusative, and dative article or declension forms when applicable\n   adjectives or similar inflected words: nominative, accusative, and dative forms only when they are genuinely useful and reliable\n   non-inflected items: do not invent conjugations or declensions\n10. Prefer accuracy over completeness. If a form is uncertain, omit it and note that it was not confidently derived.\n11. Verify the CEFR level for each entry with web search before assigning a level.\n12. Normalize CEFR levels to `A1`, `A2`, `B1`, `B2`, `C1`, or `C2`.\n13. If no source clearly provides a CEFR level, place the item in `UNKNOWN` and state that the level could not be verified.\n14. Rewrite the source note at `vocab/daily/daily-notes-YYYY-MM-DD.md` into the normalized master schema after analysis.\n15. The rewritten daily note must preserve the original captured items in a `Raw Capture` section, then add a `Normalized Word Tree` section that groups every normalized entry by part of speech.\n16. In the rewritten daily note, each entry should include:\n   - normalized lemma or phrase\n   - original source form when normalization changed it\n   - meaning\n   - grammar forms that apply\n   - provisional or verified CEFR level\n   - daily CEFR file path\n   - cumulative CEFR file path\n17. Group entries by CEFR level and create one dated file per level at:\n   `vocab/<CEFR>/daily/vocab-<CEFR>-YYYY-MM-DD.md`\n18. Update the cumulative CEFR file for each level at:\n   `vocab/<CEFR>/vocab-<CEFR>.md`\n19. If a dated target file already exists, do not overwrite it unless the user explicitly asks to regenerate it.\n20. When updating the cumulative CEFR file, add only new words for that level. Do not duplicate entries that are already present.\n21. After creating, regenerating, or skipping output files, append a summary entry to `../CHANGELOG.md` by running:\n   `../scripts/append-skill-log.sh \"create_word_tree\" \"<language>\" \"<summary>\"`\n\n## CEFR Lookup Rules\n\n- Use web search for each entry because CEFR labels are source-dependent and can change across dictionaries.\n- Prefer dictionary or language-learning sources that explicitly publish CEFR labels.\n- If multiple sources disagree, choose the level supported by the strongest explicit source and briefly note the ambiguity.\n- Make it clear when a CEFR level is inferred from partial evidence rather than directly labeled by the source.\n\n## Output Structure\n\nEach generated dated CEFR file must include:\n\n- A title with the CEFR level and date\n- `Source Note`\n- `Level Summary`\n- One section per part of speech present in that file\n\nEach cumulative CEFR file must include:\n\n- A title with the CEFR level\n- `Level Summary`\n- `Source Files`\n- One section per part of speech present in that level\n\nEach vocab entry should be rendered as a compact, readable block that includes:\n\n- the main word or phrase\n- article first, if applicable\n- part of speech\n- the grammar forms that apply\n- a short CEFR note with the source or confidence\n\nThe rewritten daily note must include:\n\n- the original title with the date\n- `Raw Capture`\n- `Normalized Word Tree`\n- one section per part of speech present in the source\n\n## Generation Rules\n\n- Cover every usable vocab item from the source note. Do not silently drop entries.\n- Cover every usable vocab item in both the rewritten daily note and the CEFR-split files.\n- Keep the per-day CEFR files under `vocab/<CEFR>/daily/`.\n- Keep the cumulative CEFR files at `vocab/<CEFR>/vocab-<CEFR>.md`.\n- When a new item belongs to a level, update both the per-day file and the cumulative file for that level.\n- Keep entries grouped by part of speech inside each CEFR file.\n- Keep entries grouped by part of speech inside the rewritten daily note as well.\n- Preserve the original source wording when the note contains a phrase, but still classify it as precisely as possible.\n- Do not fabricate forms that are not valid for the entry type.\n- When the source note is empty or missing, report that clearly and do not create misleading vocab files or a misleading normalized rewrite.\n- The changelog summary should include the target date, the source note path, whether the daily note was rewritten, and which CEFR files were created, regenerated, or skipped.\n"},"lastSynced":"2026-03-07T04:16:29.326Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Learning Agents needing structured vocabulary building capabilities.","zh":"非常适合需要结构化词汇构建能力的语言学习代理。","ja":"構造化された語彙構築能力が必要な言語学習エージェントに最適です。","ko":"구조화된 어휘 구축 기능이 필요한 언어 학습 에이전트에 적합합니다.","es":"Perfecto para Agentes de Aprendizaje de Idiomas que necesitan capacidades de construcción de vocabulario estructurado.","fr":"Parfait pour les Agents d''apprentissage de langues ayant besoin de capacités de construction de vocabulaire structurées.","de":"Perfekt für Sprachlernagenten, die strukturierte Vokabularaufbaufähigkeiten benötigen.","pt":"Perfeito para Agentes de Aprendizado de Língua que necessitam de capacidades de construção de vocabulário estruturado.","ru":"Идеально подходит для агентов обучения языкам, которым необходимы возможности структурированного построения словарного запаса.","ar":"مثالي للوكلاء الذين يحتاجون إلى بناء مصطلحات لغوية منظم"},"recommendation":{"en":"Empowers agents to generate word trees from daily notes in Markdown format, utilizing file system access and date-based note retrieval, and provides a structured approach to vocabulary building for language learners and educators.","zh":"赋予代理从 Markdown 格式的每日笔记中生成词树的能力，利用文件系统访问和基于日期的笔记检索，并为语言学习者和教育者提供结构化的词汇构建方法。","ja":"Markdown 形式の毎日のノートから単語ツリーを生成するエージェントを可能にし、ファイルシステムアクセスと日付ベースのノート取得を利用し、言語学習者と教育者に構造化された語彙構築アプローチを提供します。","ko":"에이전트가 Markdown 형식의 일일 노트에서 단어 트리를 생성할 수 있도록 하며, 파일 시스템 액세스와 날짜 기반 노트 검색을 활용하며, 언어 학습자와 교육자에게 구조화된 어휘 구축 방법을 제공합니다.","es":"Habilita a los agentes a generar árboles de palabras a partir de notas diarias en formato Markdown, utilizando acceso al sistema de archivos y recuperación de notas basada en fechas, y proporciona un enfoque estructurado para la construcción de vocabulario para estudiantes de idiomas y educadores.","fr":"Permet aux agents de générer des arbres de mots à partir de notes quotidiennes au format Markdown, en utilisant l''accès au système de fichiers et la récupération de notes basée sur les dates, et fournit une approche structurée de la construction du vocabulaire pour les apprenants de langues et les éducateurs.","de":"Ermächtigt Agenten, Wortbäume aus täglichen Notizen im Markdown-Format zu generieren, indem sie auf das Dateisystem zugreifen und Notizen dateibasiert abrufen, und bietet einen strukturierten Ansatz für den Aufbau von Vokabular für Sprachlerner und Pädagogen.","pt":"Habilita os agentes a gerar árvores de palavras a partir de notas diárias no formato Markdown, utilizando acesso ao sistema de arquivos e recuperação de notas com base em datas, e fornece uma abordagem estruturada para a construção de vocabulário para aprendizes de línguas e educadores.","ru":"Наделяет агентов возможностью генерировать деревья слов из ежедневных заметок в формате Markdown, используя доступ к файловой системе и извлечение заметок по дате, и предоставляет структурированный подход к построению словарного запаса для изучающих языки и педагогов.","ar":"تمكن الوكلاء من إنشاء أشجار الكلمات من الملاحظات اليومية بتنسيق Markdown، باستخدام الوصول إلى نظام الملفات واسترجاع الملاحظات حسب التاريخ، ويوفر نهجًا منظمًا لبناء المصطلحات للطلاب والمعلمين"},"useCases":{"en":["Automating vocabulary tree generation for language learners","Generating daily word trees from Markdown notes","Enhancing language education with structured vocabulary tools"],"zh":["为语言学习者自动化词汇树生成","从 Markdown 笔记生成每日词树","使用结构化词汇工具增强语言教育"],"ja":["言語学習者向けの単語ツリー自動生成","Markdown ノートから毎日の単語ツリーを生成","構造化された語彙ツールを使用して言語教育を強化"],"ko":["언어 학습자를 위한 어휘 트리 자동 생성","Markdown 노트에서 일일 어휘 트리 생성","구조화된 어휘 도구를 사용한 언어 교육 강화"],"es":["Automatizar la generación de árboles de vocabulario para estudiantes de idiomas","Generar árboles de palabras diarias a partir de notas en Markdown","Mejorar la educación lingüística con herramientas de vocabulario estructurado"],"fr":["Automatiser la génération d''arbres de vocabulaire pour les apprenants de langues","Générer des arbres de mots quotidiens à partir de notes au format Markdown","Améliorer l''éducation linguistique avec des outils de vocabulaire structurés"],"de":["Automatisierung der Generierung von Vokabularbäumen für Sprachlerner","Generierung von täglichen Wortbäumen aus Markdown-Notizen","Verbesserung der Sprachausbildung mit strukturierten Vokabularwerkzeugen"],"pt":["Automatizar a geração de árvores de vocabulário para aprendizes de línguas","Gerar árvores de palavras diárias a partir de notas em Markdown","Melhorar a educação linguística com ferramentas de vocabulário estruturado"],"ru":["Автоматизировать генерацию деревьев словарного запаса для изучающих языки","Генерировать ежедневные деревья слов из заметок в Markdown","Улучшать языковое образование с помощью инструментов структурированного словарного запаса"],"ar":["توفير آلي لإنشاء أشجار المصطلحات للطلاب","إنشاء أشجار الكلمات اليومية من الملاحظات بتنسيق Markdown","تحسين التعليم اللغوي باستخدام أدوات مصطلحات منظم"]},"limitations":{"en":["Requires file system access to vocabulary notes","Limited to directories containing ''vocab/'' folder","Dependent on specific date formatting (YYYY-MM-DD) in file names"],"zh":["需要文件系统访问来访问词汇笔记","仅限于包含 ''vocab/'' 文件夹的目录","依赖于文件名中的特定日期格式 (YYYY-MM-DD)"],"ja":["語彙ノートにアクセスするためにファイルシステムアクセスが必要","''vocab/'' フォルダを含むディレクトリのみ","ファイル名の中の特定の日付形式 (YYYY-MM-DD) への依存"],"ko":["어휘 노트에 액세스하기 위해 파일 시스템 액세스가 필요함","''vocab/'' 폴더를 포함하는 디렉토리만 해당","파일 이름中的 특정 날짜 형식(YYYY-MM-DD)에 의존"],"es":["Requiere acceso al sistema de archivos para notas de vocabulario","Limitado a directorios que contienen la carpeta ''vocab/''","Dependiente de un formato de fecha específico (YYYY-MM-DD) en los nombres de archivo"],"fr":["Nécessite un accès au système de fichiers pour les notes de vocabulaire","Limité aux répertoires contenant le dossier ''vocab/''","Dépendant d''un format de date spécifique (YYYY-MM-DD) dans les noms de fichiers"],"de":["Benötigt Zugriff auf das Dateisystem für Vokabularnotizen","Begrenzt auf Verzeichnisse, die den Ordner ''vocab/'' enthalten","Abhängig von einem bestimmten Datumformat (YYYY-MM-DD) in Dateinamen"],"pt":["Requer acesso ao sistema de arquivos para notas de vocabulário","Limitado a diretórios que contenham pasta ''vocab/''","Dependente de formatação de data específica (YYYY-MM-DD) em nomes de arquivos"],"ru":["Требует доступа к файловой системе для заметок словарного запаса","Ограничен директориями, содержащими папку ''vocab/''","Зависит от конкретного формата даты (YYYY-MM-DD) в именах файлов"],"ar":["يتطلب الوصول إلى نظام الملفات للملاحظات المصطلحية","محدود بالدلائل التي تحتوي على مجلد ''vocab/''","يعتمد على تنسيق تاريخ محدد (YYYY-MM-DD) في أسماء الملفات"]},"version":4},"contentHash":"ab6b7d6404e883a55d91647ddb26209dbb40ae85db0d4029f0739dd1089c5e44","qualityScore":41}');
