INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aerkn1/lang-tutor/create_word_tree', 'create_word_tree', 'aerkn1', 'lang-tutor', 'community', 'create_word_tree aerkn1 lang-tutor community The create_word_tree skill is a language tutor that generates word trees based on daily notes. It benefits language learners and educators by providing a structured approach to vocabulary building. create_word_tree技能用于创建单词树，通过读取vocab/daily/daily-notes-YYYY-MM-DD.md文件来提取单词 ワードツリーを作成するcreate_word_treeスキルは、vocab/daily/daily-notes-YYYY-MM-DD.mdファイルから単語を抽出します create_word_tree 스킬은 단어 트리를 생성하기 위해 vocab/daily/daily-notes-YYYY-MM-DD.md 파일을 읽어 단어를 추출합니다 Create_word_tree es una habilidad que utiliza el directorio actual para generar un árbol de palabras para el aprendizaje de lenguas Create_word_tree est une compétence qui utilise le répertoire actuel pour générer un arbre de mots pour l''apprentissage des langues Create_word_tree ist eine Fähigkeit, die das aktuelle Verzeichnis verwendet, um einen Wortbaum für das Sprachenlernen zu erstellen O create_word_tree é uma habilidade que cria uma árvore de palavras para ajudar no aprendizado de idiomas. Ele usa o CLI e Python para processar arquivos de notas diárias Create_word_tree - это навык, который создает дерево слов для помощи в изучении языков. Он использует CLI и Python для обработки файлов дневных заметок create_word_tree هو مهارة تقوم بإنشاء شجرة من الكلمات لمساعدة في تعلم اللغة. يستخدم CLI و Python لمعالجة ملفات الملاحظات اليومية how to use create_word_tree create_word_tree setup guide create_word_tree alternative create_word_tree vs language learning apps what is create_word_tree create_word_tree install create_word_tree for language tutors create_word_tree workflow create_word_tree and vocabulary building create_word_tree AI智能工具 单词树 vocab/daily/daily-notes-YYYY-MM-DD.md CLI命令 date +%F AIエージェント 自然语言处理 Determines target date using date +%F command Confirms presence of vocab/ directory in current working directory Reads source notes from vocab/daily/daily-notes-YYYY-MM-DD.md files Extracts usable words from source notes, ignoring headings and blank lines Treats source as empty if it only contains placeholder lines like - create_word_tree is a skill that generates word trees from daily notes in a language folder, using commands like date +%F to determine the target date.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JustAGhosT/agentkit-forge/cost-centres', 'community', 'JustAGhosT', 'agentkit-forge', 'JustAGhosT/agentkit-forge', 'cost-centres', 0, 0, 41, '2026-03-05T17:40:46Z', '2026-03-07T04:18:42.783Z', '8393e87aa4a4833c853f047891fcc351acf5cf46c9a62490b9b50d2f51e201cd', '{"id":"JustAGhosT/agentkit-forge/cost-centres","name":"cost-centres","description":{"en":"The cost-centres skill provides cost centre management for cloud infrastructure, benefiting FinOps teams. It manages budget allocations, resource group mappings, tag compliance, and spend tracking.","zh":"Cost-Centres 是一种 Windows-first 的 polyglot AI-orchestration 模板，用于管理云基础设施的预算分配、资源分组映射和标签合规性","ja":"Cost-Centres は、クラウドインフラストラクチャーのコスト管理とリソースグループマッピングを行う Windows-first の polyglot AI-orchestration テンプレートです","ko":"Cost-Centres는 클라우드 인프라 비용 관리와 리소스 그룹 매핑을 수행하는 Windows-first polyglot AI-orchestration 템플릿입니다","es":"Cost-centres es una plantilla de orquestación de AI políglota para proyectos reales que gestiona la asignación de presupuestos y el seguimiento de gastos en la nube","fr":"Cost-centres est un modèle d''orchestration d''AI polyglotte pour des projets réels qui gère l''allocation de budgets et le suivi des dépenses dans le cloud","de":"Cost-centres ist eine polyglotte AI-Orchestrierungsvorlage für reale Projekte, die die Budgetzuweisung und die Ausgabenverfolgung in der Cloud verwaltet","pt":"Cost-Centres é um modelo de orquestração de IA para gerenciamento de infraestrutura em nuvem, incluindo alocações orçamentárias e mapeamento de grupos de recursos.","ru":"Cost-Centres — это шаблон оркестрации ИИ для управления облачной инфраструктурой, включая бюджетные выделения и сопоставление групп ресурсов.","ar":"Cost-Centres هو نموذج أوركسترا اصطناعي لادارة البنية التحتية السحابية، بما في ذلك التخصيصات المالية وتحديد مجموعات الموارد."},"seo":{"title":{"en":"cost-centres: Polyglot AI-Orchestration Template Setup Gu...","zh":"Cost-Centres 设置指南：云基础设施预算管理","ja":"Cost-Centres のベストプラクティス：AIエージェントを使用したクラウドインフラストラクチャーのコスト管理","ko":"Cost-Centres 구축 가이드: 클라우드 인프라 비용 관리를 위한 AI 툴","es":"Guía de configuración de cost-centres para gestión de cos...","fr":"Guide de configuration de cost-centres pour la gestion de...","de":"Konfigurationsleitfaden für cost-centres zur Kostenverwal...","pt":"Guia de Configuração de Cost-Centres para Infraestrutura ...","ru":"Настройка ИИ Агентов Cost-Centres для Облачной Инфраструк...","ar":"دليل إعداد مراكز التكلفة لبيئات الحوسبة السحابية"},"description":{"en":"Discover how to manage cloud infrastructure costs with cost-centres. Learn to invoke this skill for budget allocations, resource group mappings, and spend tr...","zh":"了解 Cost-Centres 技术，掌握云基础设施预算管理和资源分组映射的方法，实现 FinOps 启用","ja":"Cost-Centres を使用してクラウドインフラストラクチャーのコストを管理し、FinOps を活用する方法を学びます","ko":"Cost-Centres를 사용하여 클라우드 인프라 비용을 관리하고 FinOps를 활성화하는 방법에 대해 알아보세요","es":"Descubre cómo configurar cost-centres para gestionar presupuestos, asignaciones de grupos de recursos y seguimiento de gastos en la nube","fr":"Découvrez comment configurer cost-centres pour gérer les budgets, les affectations de groupes de ressources et le suivi des dépenses dans le cloud","de":"Erfahren Sie, wie Sie cost-centres konfigurieren, um Budgets, Ressourcengruppenzuordnungen und Ausgabenverfolgung in der Cloud zu verwalten","pt":"Aprenda a gerenciar alocações orçamentárias e recursos em nuvem com o modelo de orquestração de IA Cost-Centres","ru":"Узнайте, как управлять бюджетными выделениями и ресурсами в облаке с помощью шаблона оркестрации ИИ Cost-Centres","ar":"تعرف على كيفية إدارة التخصيصات المالية والموارد السحابية باستخدام نموذج الأوركسترا الاصطناعي Cost-Centres"},"definition":{"en":"cost-centres is a Windows-first, polyglot AI-orchestration template for managing cloud infrastructure costs and resources.","zh":"Cost-Centres 是一种用于管理云基础设施预算和资源的 AI-orchestration 技术","ja":"Cost-Centres は、クラウドインフラストラクチャーのコストとリソースを管理する AI-orchestration 技術です","ko":"Cost-Centres는 클라우드 인프라 비용과 리소스를 관리하는 AI-orchestration 기술입니다","es":"Cost-centres es una herramienta de gestión de costos de infraestructura en la nube que administra presupuestos y seguimiento de gastos","fr":"Cost-centres est un outil de gestion des coûts d''infrastructure cloud qui administre les budgets et le suivi des dépenses","de":"Cost-centres ist ein Tool für die Kostenverwaltung von Cloud-Infrastrukturen, das Budgets und Ausgabenverfolgung verwaltet","pt":"Cost-Centres é um modelo de orquestração de IA que gerencia alocações orçamentárias e recursos em nuvem.","ru":"Cost-Centres — это шаблон оркестрации ИИ, который управляет бюджетными выделениями и ресурсами в облаке.","ar":"Cost-Centres هو نموذج أوركسترا اصطناعي يدير التخصيصات المالية والموارد السحابية."},"features":{"en":["Manages budget allocations for cloud infrastructure","Supports resource group mappings for organized cost tracking","Enforces tag compliance for accurate cost attribution","Provides spend tracking for real-time cost monitoring","Requires a FinOps-enabled overlay (finops rule domain) for seamless integration","Invokes cost tracking for AI sessions using the /cost command"],"zh":["预算分配管理","资源分组映射","标签合规性检查","FinOps 启用支持","AI 会话成本跟踪"],"ja":["コスト管理","リソースグループマッピング","タグコンプライアンスチェック","FinOps 有効化サポート","AI セッションコストトラッキング"],"ko":["비용 할당 관리","리소스 그룹 매핑","태그 컴플라이언스 검사","FinOps 활성화 지원","AI 세션 비용 추적"],"es":["Gestión de presupuestos y asignaciones de grupos de recursos","Seguimiento de gastos y cumplimiento de etiquetas","Requiere una superposición habilitada para FinOps (dominio de reglas FinOps)","Integración con tecnologías de orquestación de AI","Soporte para proyectos reales con infraestructura en la nube","Compatibilidad con múltiples tecnologías y lenguajes de programación"],"fr":["Gestion des budgets et des affectations de groupes de ressources","Suivi des dépenses et conformité des étiquettes","Nécessite une superposition 