INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JustAGhosT/agentkit-forge/cost-centres', 'cost-centres', 'JustAGhosT', 'agentkit-forge', 'community', 'cost-centres JustAGhosT agentkit-forge community The cost-centres skill provides cost centre management for cloud infrastructure, benefiting FinOps teams. It manages budget allocations, resource group mappings, tag compliance, and spend tracking. Cost-Centres 是一种 Windows-first 的 polyglot AI-orchestration 模板，用于管理云基础设施的预算分配、资源分组映射和标签合规性 Cost-Centres は、クラウドインフラストラクチャーのコスト管理とリソースグループマッピングを行う Windows-first の polyglot AI-orchestration テンプレートです Cost-Centres는 클라우드 인프라 비용 관리와 리소스 그룹 매핑을 수행하는 Windows-first polyglot AI-orchestration 템플릿입니다 Cost-centres es una plantilla de orquestación de AI políglota para proyectos reales que gestiona la asignación de presupuestos y el seguimiento de gastos en la nube Cost-centres est un modèle d''orchestration d''AI polyglotte pour des projets réels qui gère l''allocation de budgets et le suivi des dépenses dans le cloud Cost-centres ist eine polyglotte AI-Orchestrierungsvorlage für reale Projekte, die die Budgetzuweisung und die Ausgabenverfolgung in der Cloud verwaltet Cost-Centres é um modelo de orquestração de IA para gerenciamento de infraestrutura em nuvem, incluindo alocações orçamentárias e mapeamento de grupos de recursos. Cost-Centres — это шаблон оркестрации ИИ для управления облачной инфраструктурой, включая бюджетные выделения и сопоставление групп ресурсов. Cost-Centres هو نموذج أوركسترا اصطناعي لادارة البنية التحتية السحابية، بما في ذلك التخصيصات المالية وتحديد مجموعات الموارد. how to use cost-centres cost-centres alternative cost-centres setup guide what is cost-centres cost-centres vs finops cost-centres install polyglot ai-orchestration cloud infrastructure cost management finops-enabled overlay Cost-Centres 云基础设施预算管理 AI-orchestration FinOps 资源分组映射 标签合规性 AI 会话成本跟踪 Manages budget allocations for cloud infrastructure Supports resource group mappings for organized cost tracking Enforces tag compliance for accurate cost attribution Provides spend tracking for real-time cost monitoring Requires a FinOps-enabled overlay (finops rule domain) for seamless integration Invokes cost tracking for AI sessions using the /cost command cost-centres is a Windows-first, polyglot AI-orchestration template for managing cloud infrastructure costs and resources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aidbox/aidbox-hl7v2-example/ai-review', 'community', 'Aidbox', 'aidbox-hl7v2-example', 'Aidbox/aidbox-hl7v2-example', 'ai-review', 0, 0, 41, '2026-03-06T10:56:35Z', '2026-03-07T13:11:41.652Z', '39f8b3ba1dddeb4a9c5b104d60527bd52c729d88eb2743723389732a39b66411', '{"id":"Aidbox/aidbox-hl7v2-example/ai-review","name":"ai-review","description":{"en":"The ai-review skill enables meticulous code review, ensuring completeness and code style compliance. It benefits developers by streamlining the review process.","zh":"AI审查工具是一种代码审查工具，用于评估代码的完整性和代码风格合规性","ja":"AIエージェントはコードの完全性とコードスタイルの準拠性を評価するコードレビューツールです","ko":"AI 리뷰어는 코드의 완전성과 코드 스타일 규격성을 평가하는 코드 리뷰 도구입니다","es":"ai-review es una herramienta para evaluar el cumplimiento de los requisitos y el estilo de código en proyectos de desarrollo de IA","fr":"ai-review est un outil pour évaluer la conformité aux exigences et au style de code dans les projets de développement d''IA","de":"ai-review ist ein Tool zur Bewertung der Einhaltung von Anforderungen und Code-Stil in KI-Entwicklungsprojekten","pt":"O ai-review é uma ferramenta de revisão de código que ajuda a garantir a conformidade com as diretrizes de estilo de código, permitindo uma revisão eficaz do código","ru":"ИИ Агент ai-review является инструментом для обзора кода, помогающим обеспечить соответствие руководящим принципам кодирования, позволяя эффективно просматривать код","ar":"وحدة ai-review هي أداة لمراجعة الكود تساعد على ضمان امتثاله للقواعد النمطية، مما يسمح بمراجعة فعالة للكود"},"seo":{"title":{"en":"ai-review: Code Review Setup Guide | AI Agent Skill","zh":"AI审查工具设置指南","ja":"AIエージェントのレビューガイド","ko":"AI 리뷰어 설정 가이드","es":"Guía de Configuración de ai-review para Agentes de Inteli...","fr":"Guide de Mise en Place de ai-review pour Outils d''Intelli...","de":"Einrichtungsanleitung für ai-review bei KI-Agents","pt":"Guia de Configuração do ai-review: Melhores Práticas para...","ru":"Настройка ИИ Агентов: ai-review Руководство по Обзору Кодa","ar":"دليل إعداد ai-review: أفضل الممارسات لمراجعة الكود"},"description":{"en":"Master AI-driven code reviews with ai-review! Discover how to evaluate completeness, code style compliance, and more. Get started now!","zh":"了解AI审查工具的关键特性和设置步骤，优化代码审查流程","ja":"AIエージェントのレビュー機能と設定方法をご紹介します","ko":"AI 리뷰어의 주요 기능과 설정 방법을 알아보세요","es":"Aprende a configurar ai-review para evaluar el cumplimiento de los requisitos y el estilo de código en proyectos de desarrollo de IA","fr":"Découvrez comment configurer ai-review pour évaluer la conformité aux exigences et au style de code dans les projets de développement d''IA","de":"Erfahren Sie, wie Sie ai-review einrichten, um die Einhaltung von Anforderungen und Code-Stil in KI-Entwicklungsprojekten zu bewerten","pt":"Aprenda a configurar e utilizar o ai-review para revisar códigos de forma eficaz, garantindo a conformidade com as diretrizes de estilo de código","ru":"Узнайте, как настроить и использовать ai-review для эффективного обзора кода, обеспечивая соответствие руководящим принципам кодирования","ar":"تعرف على كيفية إعداد واستخدام ai-review لمراجعة الكود بفعالية، وضمان امتثاله للقواعد النمطية"},"definition":{"en":"ai-review is a skill that critically evaluates code against specific criteria, including completeness and adherence to .claude/code-style.md guidelines.","zh":"AI审查工具是一种自动化代码审查工具，用于评估代码质量","ja":"AIエージェントはコード品質を評価する自動化コードレビューツールです","ko":"AI 리뷰어는 코드 품질을 평가하는 자동화 코드 리뷰 도구입니다","es":"ai-review es una herramienta de revisión de código que evalúa la completitud y el estilo de código en proyectos de IA","fr":"ai-review est un outil de révision de code qui évalue la complétude et le style de code dans les projets d''IA","de":"ai-review ist ein Code-Review-Tool, das die Vollständigkeit und den Code-Stil in KI-Projekten bewertet","pt":"O que é ai-review? É uma ferramenta de revisão de código que avalia a completude e o estilo de código","ru":"Что такое ИИ Агент ai-review? Это инструмент для обзора кода, оценивающий полноту и стиль кода","ar":"ما هي وحدة ai-review؟ هي أداة لمراجعة الكود تقييم الإكمال ونمط الكود"},"features":{"en":["Evaluates code completeness based on problem statement requirements","Enforces code style compliance with .claude/code-style.md guidelines","Identifies missing components or flows in code","Detects hidden complexities not addressed in code","Reviews code against specific criteria, including completeness and code style"],"zh":["代码完整性评估","代码风格合规性检查","对齐代码风格指南(.claude/code-style.md)","隐藏复杂性检测","代码流程评估"],"ja":["コードの完全性評価","コードスタイルの準拠性チェック","コードスタイルガイド(.claude/code-style.md)に準拠","隠れた複雑性の検出","コードフローの評価"],"ko":["코드의 완전성 평가","코드 스타일 규격성 확인","코드 스타일 가이드(.claude/code-style.md) 준수","숨겨진 복잡성 탐지","코드 흐름 평가"],"es":["Evaluación de la completitud de los requisitos","Verificación del estilo de código según las pautas de .claude/code-style.md","Detección de componentes y flujos faltantes","Análisis de complejidades ocultas no abordadas"],"fr":["Évaluation de la complétude des exigences","Vérification du style de code selon les directives de .claude/code-style.md","Détection de composants et de flux manquants","Analyse de complexités cachées non abordées"],"de":["Bewertung der Vollständigkeit von Anforderungen","Überprüfung des Code-Stils gemäß den Richtlinien von .claude/code-style.md","Erkennung fehlender Komponenten und Flüsse","Analyse von versteckten Komplexitäten, die nicht behandelt werden"],"pt":["Avaliação da completude do código","Verificação da conformidade com as diretrizes de estilo de código","Análise de complexidades ocultas","Suporte à revisão de código de forma eficaz"],"ru":["Оценка полноты кода","Проверка соответствия руководящим принципам кодирования","Анализ скрытых сложностей","Поддержка эффективного обзора кода"],"ar":["تقييم إكمال الكود","فحص امتثاله للقواعد النمطية","تحليل التعقيدات الخفية","دعم مراجعة الكود بفعالية"]},"keywords":{"en":["how to use ai-review","ai-review setup guide","what is ai-review","ai-review alternative","ai-review vs code review tools","ai-review install","code review best practices with ai-review"],"zh":["AI审查工具","代码审查","代码风格","代码质量","自动化代码审查","代码完整性","代码风格合规性"],"ja":["AIエージェント","コードレビュー","コードスタイル","コード品質","自動化コードレビュー","コードの完全性","コードスタイルの準拠性"],"ko":["AI 리뷰어","코드 리뷰","코드 스타일","코드 품질","자동화 코드 리뷰","코드의 완전성","코드 스타일 규격성"],"es":["ai-review","agentes de inteligencia artificial","evaluación de código","estilo de código","desarrollo de IA","herramientas de IA","revisión de código","cumplimiento de requisitos"],"fr":["ai-review","outils d''intelligence artificielle","évaluation de code","style de code","développement d''IA","outils d''IA","révision de code","conformité aux exigences"],"de":["ai-review","KI-Agents","Code-Bewertung","Code-Stil","KI-Entwicklung","KI-Tools","Code-Review","Einhaltung von Anforderungen"],"pt":["ai-review","revisão de código","diretrizes de estilo de código","desenvolvimento de software","ferramentas de revisão de código","melhores práticas de codificação"],"ru":["ИИ Агент ai-review","обзор кода","руководящие принципы кодирования","разработка программного обеспечения","инструменты обзора кода","лучшие практики кодирования"],"ar":["وحدة ai-review","مراجعة الكود","قواعد نمطية","تطوير البرمجيات","أدوات مراجعة الكود","أفضل ممارسات الترميز"]}},"owner":"Aidbox","repo":"aidbox-hl7v2-example","repoPath":"Aidbox/aidbox-hl7v2-example","stars":0,"forks":0,"updatedAt":"2026-03-06T10:56:35Z","topics":[],"category":"community","skillMd":{"name":"ai-review","description":"Review design or implementation of a feature or a fix","bodyPreview":"# AI Reviewer\n\nYou are a meticulous ai reviewer. You need to critically review a piece of work made by someone else.\n\n## Review Criteria\n\nEvaluate against these criteria:\n\n### 1. Completeness\n- Are all requirements from the problem statement addressed?\n- Are there missing components or flows?\n- Are there hidden complexities not addressed?\n\n### 2. Code Style Compliance (HIGHEST PRIORITY)\n- Does it follow ALL guidelines from `.claude/code-style.md`? Read it before reviewing.\n- **The code style gui","body":"# AI Reviewer\n\nYou are a meticulous ai reviewer. You need to critically review a piece of work made by someone else.\n\n## Review Criteria\n\nEvaluate against these criteria:\n\n### 1. Completeness\n- Are all requirements from the problem statement addressed?\n- Are there missing components or flows?\n- Are there hidden complexities not addressed?\n\n### 2. Code Style Compliance (HIGHEST PRIORITY)\n- Does it follow ALL guidelines from `.claude/code-style.md`? Read it before reviewing.\n- **The code style guide overrides existing codebase patterns.** If existing code violates the style guide, that''s a pre-existing problem — new code must NOT copy the violation.\n- Never dismiss a style guide violation because \"the codebase already does it this way.\" Flag it as an issue.\n\n### 3. Consistency with Codebase\n- Does it follow existing patterns found in the codebase?\n- Does it use established conventions?\n- If existing patterns conflict with `code-style.md`, flag both: the new code must follow the style guide, and note the pre-existing inconsistency.\n\n### 4. Clean Architecture\n- Is there clear separation of concerns?\n- Are dependencies pointing in the right direction?\n- Is the design testable?\n\n### 5. Best Practices\n- Does it follow SOLID principles?\n- Is error handling appropriate?\n- Are edge cases considered?\n\n### 6. Simpler Alternatives\n- Is there a simpler approach that would work?\n- Is the design over-engineered for the problem?\n\n### 7. Test Coverage\n- Are the test cases comprehensive?\n- Is the unit vs integration split appropriate?\n- Are edge cases covered by tests?\n\n## Output Format\n\nYour review must contain:\n1. Descriptive design review\n2. List of issues sorted by severity\n3. Your recommendation on improving the design/implementation\n\n### Output Location\n\nDefault: Write review findings in **## AI Review Notes** of the ticket file.\n\nIMPORTANT: If the caller prompt clearly defined a different output location, use that location instead.\n"},"lastSynced":"2026-03-07T13:11:41.652Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing meticulous code review and compliance with .claude/code-style.md guidelines.","zh":"非常适合需要细致代码审查和遵守.claude/code-style.md 指南的代码分析代理。","ja":"コード分析エージェントが厳密なコードレビューと.claude/code-style.md ガイドラインへの準拠を必要とする場合に最適です。","ko":"코드 분석 에이전트가 세부적인 코드 리뷰와 .claude/code-style.md 지침을 준수해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan una revisión de código meticulosa y cumplimiento con las directrices de .claude/code-style.md.","fr":"Parfait pour les agents d''analyse de code nécessitant une révision de code minutieuse et un respect des directives de .claude/code-style.md.","de":"Perfekt für Code-Analyse-Agents, die eine sorgfältige Code-Überprüfung und Einhaltung der Richtlinien von .claude/code-style.md benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de revisão minuciosa do código e conformidade com as diretrizes .claude/code-style.md.","ru":"Идеально подходит для агентов анализа кода, требующих тщательного обзора кода и соблюдения руководящих принципов .claude/code-style.md.","ar":"مثالي للوكلاء الذين يحتاجون إلى مراجعة دقيقة للرمز البرمجي والامتثال للمبادئ التوجيهية .claude/code-style.md."},"recommendation":{"en":"Empowers agents to enforce code style compliance, ensuring adherence to specific guidelines and streamlining the review process using protocols like completeness checks and hidden complexity analysis, while prioritizing code style compliance as the highest priority.","zh":"赋予代理人强制代码风格的权限，确保遵守特定的指南，并通过完整性检查和隐藏复杂性分析等协议简化审查流程，同时将代码风格的遵守作为最高优先级。","ja":"エージェントがコードスタイルの遵守を強制できるようにし、特定のガイドラインに従い、完了性の確認や隠れた複雑性の分析などのプロトコルを使用してレビューのプロセスをストリームライン化し、コードスタイルの遵守を最高の優先順位として優先します。","ko":"에이전트가 코드 스타일을 강제로 지키게 하여 특정 지침을 준수하고 완성도 확인 및 숨겨진 복잡성 분석 등의 프로토콜을 사용하여 검토 프로세스를 간소화하며 코드 스타일의 준수를 최우선으로 합니다.","es":"Habilita a los agentes a hacer cumplir el cumplimiento del estilo de código, asegurando el cumplimiento de directrices específicas y simplificando el proceso de revisión utilizando protocolos como controles de completitud y análisis de complejidad oculta, al mismo tiempo que prioriza el cumplimiento del estilo de código como la máxima prioridad.","fr":"Permet aux agents d''assurer le respect des normes de style de code, en garantissant le respect de directives spécifiques et en simplifiant le processus de révision en utilisant des protocoles tels que des contrôles de complétude et une analyse de complexité cachée, tout en donnant la priorité au respect des normes de style de code comme priorité absolue.","de":"Ermächtigt Agents, die Einhaltung von Code-Stil-Richtlinien durchzusetzen, indem sie sicherstellen, dass bestimmte Richtlinien eingehalten werden und den Überprüfungsprozess mithilfe von Protokollen wie Vollständigkeitsprüfungen und Analyse versteckter Komplexität vereinfachen, während sie gleichzeitig die Einhaltung von Code-Stil-Richtlinien als höchste Priorität priorisieren.","pt":"Habilita os agentes a impor a conformidade com o estilo de código, garantindo a adesão a diretrizes específicas e simplificando o processo de revisão usando protocolos como verificações de completude e análise de complexidade oculta, priorizando a conformidade com o estilo de código como prioridade mais alta.","ru":"Наделяет агентов возможностью обеспечивать соблюдение стиля кода, гарантируя соблюдение конкретных руководящих принципов и упрощая процесс обзора с использованием протоколов, таких как проверки полноты и анализ скрытой сложности, отводя приоритет соблюдению стиля кода как высшему приоритету.","ar":"يمكّن الوكلاء من فرض الامتثال لأسلوب الكود، وضمان الالتزام بالمبادئ التوجيهية المحددة، وبذلك يُبسط عملية المراجعة باستخدام بروتوكولات مثل التحقق من الإكمال وتحليل التعقيد الخفي، مع جعل الامتثال لأسلوب الكود هو الأولوية الأعلى."},"useCases":{"en":["Evaluating completeness of code submissions","Enforcing code style guidelines from .claude/code-style.md","Identifying hidden complexities in code flows"],"zh":["评估代码提交的完整性","强制执行.claude/code-style.md 中的代码风格指南","识别代码流中的隐藏复杂性"],"ja":["コード提出の完全性を評価する",".claude/code-style.md に記載されたコードスタイルガイドラインを適用する","コードフローの隠れた複雑性を特定する"],"ko":["코드 제출의 완성도를 평가한다",".claude/code-style.md에記載された 코드 스타일 지침을 적용한다","코드 흐름中的 숨겨진 복잡성을 식별한다"],"es":["Evaluación de la completitud de las presentaciones de código","Aplicación de las directrices de estilo de código de .claude/code-style.md","Identificación de complejidades ocultas en flujos de código"],"fr":["Évaluation de l''exhaustivité des soumissions de code","Application des directives de style de code de .claude/code-style.md","Identification de complexités cachées dans les flux de code"],"de":["Bewertung der Vollständigkeit von Code-Eingaben","Anwendung der Code-Stil-Richtlinien von .claude/code-style.md","Identifizierung versteckter Komplexitäten in Code-Flüssen"],"pt":["Avaliando a completude das submissões de código","Impondo diretrizes de estilo de código de .claude/code-style.md","Identificando complexidades ocultas nos fluxos de código"],"ru":["Оценивание полноты кодовых подач","Принудительное соблюдение руководящих принципов стиля кода .claude/code-style.md","Определение скрытых сложностей в потоках кода"],"ar":["تقييم إكمال إرسال الكود","فرض المبادئ التوجيهية لأسلوب الكود من .claude/code-style.md","تحديد التعقيدات الخفية في تدفقات الكود"]},"limitations":{"en":["Requires access to .claude/code-style.md guidelines","Limited to code review and compliance checking"],"zh":["需要访问.claude/code-style.md 指南","仅限代码审查和合规性检查"],"ja":[".claude/code-style.md ガイドラインへのアクセスが必要","コードレビューおよびコンプライアンスチェックに限定される"],"ko":[".claude/code-style.md 지침에 접근해야 함","코드 리뷰 및 컴플라이언스 확인에만 제한됨"],"es":["Requiere acceso a las directrices de .claude/code-style.md","Limitado a la revisión y comprobación de cumplimiento de código"],"fr":["Nécessite un accès aux directives de .claude/code-style.md","Limité à la révision et à la vérification de conformité du code"],"de":["Benötigt Zugriff auf die Richtlinien von .claude/code-style.md","Begrenzt auf Code-Überprüfung und -Konformitätsprüfung"],"pt":["Requer acesso às diretrizes .claude/code-style.md","Limitado à revisão e verificação de conformidade do código"],"ru":["Требует доступа к руководящим принципам .claude/code-style.md","Ограничен обзором и проверкой соответствия кода"],"ar":["يتطلب الوصول إلى المبادئ التوجيهية .claude/code-style.md","محدود بالمراجعة واختبار الامتثال للكود"]},"version":4},"contentHash":"39f8b3ba1dddeb4a9c5b104d60527bd52c729d88eb2743723389732a39b66411","qualityScore":41}');
