INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aidbox/aidbox-hl7v2-example/ai-review', 'ai-review', 'Aidbox', 'aidbox-hl7v2-example', 'community', 'ai-review Aidbox aidbox-hl7v2-example community The ai-review skill enables meticulous code review, ensuring completeness and code style compliance. It benefits developers by streamlining the review process. AI审查工具是一种代码审查工具，用于评估代码的完整性和代码风格合规性 AIエージェントはコードの完全性とコードスタイルの準拠性を評価するコードレビューツールです AI 리뷰어는 코드의 완전성과 코드 스타일 규격성을 평가하는 코드 리뷰 도구입니다 ai-review es una herramienta para evaluar el cumplimiento de los requisitos y el estilo de código en proyectos de desarrollo de IA ai-review est un outil pour évaluer la conformité aux exigences et au style de code dans les projets de développement d''IA ai-review ist ein Tool zur Bewertung der Einhaltung von Anforderungen und Code-Stil in KI-Entwicklungsprojekten O ai-review é uma ferramenta de revisão de código que ajuda a garantir a conformidade com as diretrizes de estilo de código, permitindo uma revisão eficaz do código ИИ Агент ai-review является инструментом для обзора кода, помогающим обеспечить соответствие руководящим принципам кодирования, позволяя эффективно просматривать код وحدة ai-review هي أداة لمراجعة الكود تساعد على ضمان امتثاله للقواعد النمطية، مما يسمح بمراجعة فعالة للكود how to use ai-review ai-review setup guide what is ai-review ai-review alternative ai-review vs code review tools ai-review install code review best practices with ai-review AI审查工具 代码审查 代码风格 代码质量 自动化代码审查 代码完整性 代码风格合规性 Evaluates code completeness based on problem statement requirements Enforces code style compliance with .claude/code-style.md guidelines Identifies missing components or flows in code Detects hidden complexities not addressed in code Reviews code against specific criteria, including completeness and code style ai-review is a skill that critically evaluates code against specific criteria, including completeness and adherence to .claude/code-style.md guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jkenney47/Finance-App-audit-snapshot-20260306-074853/adapt', 'community', 'jkenney47', 'Finance-App-audit-snapshot-20260306-074853', 'jkenney47/Finance-App-audit-snapshot-20260306-074853', 'adapt', 0, 0, 41, '2026-03-06T12:50:05Z', '2026-03-07T13:13:29.040Z', 'ec7e4368269f071ca1c0f7601bcd6bd4c8c2b8041ec9abd1c6820af038a0bb9e', '{"id":"jkenney47/Finance-App-audit-snapshot-20260306-074853/adapt","name":"adapt","description":{"en":"The Adapt skill generates temporary one-commit public audit snapshots of Finance-App, helping developers adapt existing designs for effective use across various screen sizes and devices.","zh":"Adapt是一种跨屏适配解决方案，能够根据目标环境和使用上下文调整设计和行为","ja":"Adaptは、ターゲット環境と使用状況に応じてデザインと動作を調整する、レスポンシブ設計ツールです","ko":"Adapt는 대상 환경과 사용 상황에 따라 디자인과 동작을 조정하는 반응형 디자인 도구입니다","es":"Adaptar diseños para diferentes contextos y dispositivos, incluyendo pantallas, routas y componentes","fr":"Adapter les conceptions pour différents contextes et appareils, y compris les écrans, les routes et les composants","de":"Anpassen von Designs für verschiedene Kontexte und Geräte, einschließlich Bildschirmen, Routen und Komponenten","pt":"O Adapt é uma ferramenta que ajuda a adaptar designs para trabalhar efetivamente em diferentes tamanhos de tela, dispositivos e plataformas. Ele oferece suporte a contextos de uso variados.","ru":"Адапт - это инструмент, который помогает адаптировать дизайны для эффективной работы на различных размерах экрана, устройствах и платформах. Он поддерживает различные контексты использования.","ar":"التكيف هو أداة تساعد على تكييف التصاميم للعمل بشكل فعال على أحجام شاشات و أجهزة و منصات مختلفة. كما يدعم سياقات استخدام مختلفة."},"seo":{"title":{"en":"Adapt: Temporary Public Audit Snapshot Setup Guide | AI A...","zh":"Adapt Setup Guide: 跨屏适配解决方案","ja":"Adapt ベストプラクティス: AIエージェントによるレスポンシブ設計","ko":"Adapt 구현 가이드: 반응형 디자인을 위한 AI 도구","es":"Guía de configuración de adaptación para desarrolladores","fr":"Guide de mise en place de l''adaptation pour les développeurs","de":"Einrichtungsleitfaden für Anpassung für Entwickler","pt":"Guia de Configuração do Adapt: Otimização de Design para ...","ru":"Настройка Адапт: Руководство по оптимизации дизайна для И...","ar":"دليل ضبط التكيف: تحسين التصميم لفوائل الذكاء الاصطناعي"},"description":{"en":"Discover how to use Adapt for temporary one-commit public audit snapshots of Finance-App. Learn to adapt existing designs across screens and devices now!","zh":"了解Adapt的技术细节，实现跨屏适配和响应式设计，适用于移动、平板、桌面和打印环境","ja":"Adaptの機能を利用して、レスポンシブ設計を実現し、モバイル、タブレット、デスクトップ、プリンタ環境で最適化する","ko":"Adapt를 사용하여 반응형 디자인을 구현하고 모바일, 태블릿, 데스크탑, 프린트 환경에서 최적화하는 방법을 알아보세요","es":"Aprende a adaptar diseños para funcionar en diferentes tamaños de pantalla, dispositivos y plataformas con comportamientos contextuales","fr":"Découvrez comment adapter les conceptions pour fonctionner sur différents tailles d''écran, appareils et plateformes avec des comportements contextuels","de":"Erfahren Sie, wie Sie Designs anpassen, um auf verschiedenen Bildschirmgrößen, Geräten und Plattformen mit kontextbezogenem Verhalten zu funktionieren","pt":"Aprenda a configurar o Adapt para melhorar a experiência do usuário em diferentes dispositivos e plataformas com Ferramentas de IAs","ru":"Узнайте, как настроить Адапт для улучшения пользовательского опыта на различных устройствах и платформах с ИИ Агентами","ar":"تعرف على كيفية ضبط التكيف لتحسين تجربة المستخدم على أجهزة و منصات مختلفة مع فوائل الذكاء الاصطناعي"},"definition":{"en":"Adapt is a skill that enables temporary public audit snapshots of Finance-App, adapting designs to work effectively across different screens, devices, and platforms.","zh":"Adapt是一种AI驱动的跨屏适配技术，用于实现响应式设计和用户体验优化","ja":"Adaptは、AIエージェントによるレスポンシブ設計とユーザーエクスペリエンス最適化を実現する技術です","ko":"Adapt는 AI 도구를 이용한 반응형 디자인과 사용자 경험 최적화를 위한 기술입니다","es":"La adaptación es el proceso de ajustar diseños para funcionar en diferentes entornos y contextos","fr":"L''adaptation est le processus d''ajustement des conceptions pour fonctionner dans différents environnements et contextes","de":"Die Anpassung ist der Prozess der Anpassung von Designs, um in verschiedenen Umgebungen und Kontexten zu funktionieren","pt":"O Adapt é uma técnica de design que visa adaptar interfaces para diferentes dispositivos e plataformas","ru":"Адапт - это техника дизайна, направленная на адаптацию интерфейсов для различных устройств и платформ","ar":"التكيف هو تقنية تصميم تهدف إلى تكييف الواجهات لأجهزة و منصات مختلفة"},"features":{"en":["Supports adaptation of existing designs for various screen sizes and devices","Allows specification of target page, route, feature, or component to adapt","Enables inference of the most likely target from the request if inputs are omitted","Supports adaptation for different destination environments, such as mobile, tablet, or desktop"],"zh":["支持多种目标环境，包括移动、平板、桌面和打印","根据使用上下文调整设计和行为","自动检测和适配不同屏幕尺寸和设备","支持多种开发框架和技术"],"ja":["モバイル、タブレット、デスクトップ、プリンタ環境を含む多くのターゲット環境をサポート","使用状況に応じてデザインと動作を調整","自動的に異なる画面サイズとデバイスを検出して適応","多くの開発フレームワークと技術をサポート"],"ko":["모바일, 태블릿, 데스크탑, 프린트 환경을 포함한 다양한 대상 환경을 지원","사용 상황에 따라 디자인과 동작을 조정","자동으로 다른 화면 크기와 디바이스를 감지하고 적응","다양한 개발 프레임워크와 기술을 지원"],"es":["Adaptación de diseños para diferentes tamaños de pantalla y dispositivos","Compatibilidad con contextos de uso variados, como móviles, tabletas y escritorios","Opción de especificar un objetivo de adaptación, como una página o un componente","Inferencia del objetivo de adaptación más probable si no se proporciona","Soporte para adaptación de comportamientos contextuales"],"fr":["Adaptation des conceptions pour différents tailles d''écran et appareils","Compatibilité avec des contextes d''utilisation variés, tels que les mobiles, les tablettes et les bureaux","Option de spécifier un objectif d''adaptation, comme une page ou un composant","Inférence de l''objectif d''adaptation le plus probable si non fourni","Prise en charge de l''adaptation des comportements contextuels"],"de":["Anpassung von Designs für verschiedene Bildschirmgrößen und Geräte","Kompatibilität mit verschiedenen Nutzungscontexten, wie z.B. Mobilgeräten, Tablets und Desktops","Option, ein Anpassungsziel zu spezifizieren, wie z.B. eine Seite oder ein Komponente","Ableitung des wahrscheinlichsten Anpassungsziels, wenn nicht angegeben","Unterstützung für die Anpassung von kontextbezogenem Verhalten"],"pt":["Suporte a diferentes tamanhos de tela e dispositivos","Adaptação de designs para contextos de uso variados","Compatibilidade com diversas plataformas","Otimização da experiência do usuário em diferentes ambientes","Suporte a inferência de destino quando os inputs são omitidos"],"ru":["Поддержка различных размеров экрана и устройств","Адаптация дизайнов для различных контекстов использования","Совместимость с различными платформами","Оптимизация пользовательского опыта в различных средах","Поддержка вывода destinations при отсутствии входных данных"],"ar":["دعم لأحجام شاشات و أجهزة مختلفة","تكييف التصاميم لسياقات استخدام مختلفة","التوافق مع منصات مختلفة","تحسين تجربة المستخدم في بيئات مختلفة","دعم استنتاج الوجهة عند省略 المدخلات"]},"keywords":{"en":["how to use adapt","what is adapt","adapt alternative","adapt vs responsive design","adapt install","adapt setup guide","adapt for finance app","adapt temporary public audit snapshot"],"zh":["Adapt","跨屏适配","响应式设计","AI驱动","用户体验优化","移动开发","平板开发","桌面开发","打印开发"],"ja":["Adapt","レスポンシブ設計","AIエージェント","ユーザーエクスペリエンス最適化","モバイル開発","タブレット開発","デスクトップ開発","プリンタ開発"],"ko":["Adapt","반응형 디자인","AI 도구","사용자 경험 최적화","모바일 개발","태블릿 개발","데스크탑 개발","프린트 개발"],"es":["adaptación de diseños","desarrollo de aplicaciones móviles","desarrollo web responsivo","adaptación de comportamientos contextuales","Herramientas de adaptación de AI","Agentes de adaptación de IA"],"fr":["adaptation de conceptions","développement d''applications mobiles","développement web réactif","adaptation de comportements contextuels","Outils d''adaptation d''IA","Agents d''adaptation d''IA"],"de":["Anpassung von Designs","Entwicklung von mobilen Anwendungen","responsive Webentwicklung","Anpassung von kontextbezogenem Verhalten","AI-Anpassungstools","IA-Anpassungsagenten"],"pt":["Adapt para Ferramentas de IAs","otimização de design para dispositivos móveis","desenvolvimento de interfaces de usuário","compatibilidade de plataforma","experiência do usuário em diferentes ambientes","inferência de destino","configuração do Adapt"],"ru":["Адапт для ИИ Агентов","оптимизация дизайна для мобильных устройств","разработка пользовательских интерфейсов","совместимость платформ","пользовательский опыт в различных средах","вывод destinations","настройка Адапт"],"ar":["التكيف لفوائل الذكاء الاصطناعي","تحسين التصميم لأجهزة المحمول","تطوير واجهات المستخدم","توافق المنصات","تجربة المستخدم في بيئات مختلفة","استنتاج الوجهة","ضبط التكيف"]}},"owner":"jkenney47","repo":"Finance-App-audit-snapshot-20260306-074853","repoPath":"jkenney47/Finance-App-audit-snapshot-20260306-074853","stars":0,"forks":0,"updatedAt":"2026-03-06T12:50:05Z","topics":[],"category":"community","skillMd":{"name":"adapt","description":"Adapt existing interface designs for new contexts such as mobile, tablet, desktop, print, email, or alternative input/connection constraints while preserving core outcomes and usability. Use when a feature must work consistently across devices, platforms, or usage environments that differ from the original design assumptions.","bodyPreview":"# Adapt\n\n## Goal\n\nAdapt existing designs to work effectively across screen sizes, devices, platforms, and usage contexts with context-appropriate behavior.\n\n## Input\n\n- `target` (optional): page, route, feature, or component to adapt.\n- `context` (optional): destination environment (for example mobile, tablet, desktop, print, email).\n- If inputs are omitted, infer the most likely target from the request and confirm if ambiguous.\n\n## Assess Adaptation Challenge\n\nUnderstand what needs adaptation a","body":"# Adapt\n\n## Goal\n\nAdapt existing designs to work effectively across screen sizes, devices, platforms, and usage contexts with context-appropriate behavior.\n\n## Input\n\n- `target` (optional): page, route, feature, or component to adapt.\n- `context` (optional): destination environment (for example mobile, tablet, desktop, print, email).\n- If inputs are omitted, infer the most likely target from the request and confirm if ambiguous.\n\n## Assess Adaptation Challenge\n\nUnderstand what needs adaptation and why.\n\n### 1) Identify Source Context\n\n- What was the current design built for?\n- What assumptions exist (screen size, pointer input, network quality)?\n- What currently works well and must be preserved?\n\n### 2) Understand Target Context\n\n- device class and form factor\n- input method (touch, mouse, keyboard, voice, gamepad)\n- screen constraints (size, density, orientation)\n- connection constraints (fast, slow, intermittent, offline)\n- usage context (quick glance vs focused task)\n- platform expectations and native conventions\n\n### 3) Identify Adaptation Challenges\n\n- what does not fit\n- what interaction patterns break\n- what patterns are context-inappropriate\n\nAdaptation is not simple scaling; reframe the experience for the destination context.\n\n## Plan Adaptation Strategy\n\nChoose a context-specific strategy.\n\n### Mobile (Desktop -> Mobile)\n\n- single-column layouts over dense multi-column layouts\n- vertical stacking and full-width component flow\n- touch-first controls (44x44px targets minimum)\n- progressive disclosure for secondary information\n- concise content and stronger prioritization\n- mobile-appropriate navigation (bottom nav, drawer, compact header)\n\n### Tablet (Hybrid)\n\n- two-column patterns and master-detail layouts\n- orientation-aware adaptations\n- support both touch and pointer usage\n- balanced density between phone and desktop\n\n### Desktop (Mobile -> Desktop)\n\n- use horizontal space with multi-column composition\n- persistent side navigation where useful\n- richer information density and simultaneous panels\n- hover affordances, keyboard shortcuts, advanced interactions\n- constrain max-widths for readability on very large screens\n\n### Print (Screen -> Print)\n\n- remove interactive/navigation chrome\n- enforce print-safe pagination and margins\n- include metadata (title, date, pagination)\n- ensure chart/table variants are print legible\n\n### Email (Web -> Email)\n\n- narrow single-column structure (about 600px max)\n- inline CSS and email-safe layout patterns\n- strong CTA clarity\n- deep-link complex actions back to web/app flows\n\n## Implement Adaptations\n\nApply changes systematically.\n\n### Responsive and Context Rules\n\n- define meaningful breakpoints (content-driven when possible)\n- use grid/flex/container-query patterns for adaptive reflow\n- use fluid sizing via `clamp()` where appropriate\n- use media queries and conditional visibility with clear rationale\n\n### Touch and Input Adaptation\n\n- ensure touch targets and spacing for touch contexts\n- remove hover-only dependencies in touch-first experiences\n- add tactile feedback states for taps/presses\n- account for thumb reach and ergonomics on phones\n\n### Content Adaptation\n\n- preserve core information and functionality\n- adjust disclosure depth per context\n- use lazy loading and progressive enhancement where useful\n- use responsive media assets (`srcset`, `picture`)\n\n### Navigation Adaptation\n\n- transform complex navigation into context-appropriate patterns\n- preserve IA consistency across contexts\n- keep orientation and back-navigation predictable\n\nDo not hide critical functionality; make it workable in-context.\n\n## Non-Negotiables\n\n- Do not remove core functionality just to fit small screens.\n- Do not break platform conventions for primary interactions.\n- Do not diverge information architecture across contexts without clear reason.\n- Do not rely on generic breakpoints when content-driven breakpoints are required.\n- Do not ignore landscape and hybrid input scenarios.\n\n## Verify Adaptations\n\nValidate across real-world environments:\n\n- real devices (not emulation only)\n- portrait and landscape orientation\n- major browsers and operating systems\n- multiple input methods (touch, mouse, keyboard)\n- edge screens (very small and very large)\n- constrained network scenarios\n\nEnsure each adapted experience feels native to its context while preserving brand and task continuity.\n"},"lastSynced":"2026-03-07T13:13:29.040Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing responsive design adaptation across various screen sizes and devices.","zh":"非常适合需要在不同屏幕尺寸和设备上进行响应式设计适配的前端代理。","ja":"さまざまな画面サイズとデバイスに対するレスポンシブデザインの適応が必要なフロントエンドエージェントに最適です。","ko":"다양한 화면 크기와 장치에 대한 반응형 디자인 적응이 필요한 프런트엔드 에이전트에게 완벽합니다.","es":"Perfecto para agentes Frontend que necesitan adaptación de diseño receptivo en varios tamaños de pantalla y dispositivos.","fr":"Parfait pour les agents Frontend nécessitant une adaptation de conception réactive à travers différentes tailles d''écran et appareils.","de":"Perfekt für Frontend-Agents, die eine anpassbare Gestaltung über verschiedene Bildschirmgrößen und Geräte benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de adaptação de design responsivo em diferentes tamanhos e dispositivos de tela.","ru":"Идеально подходит для агентов Frontend, которым требуется адаптация отзывчивого дизайна для различных размеров и устройств экрана.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى تكييف تصميم مستجيب عبر أحجام شاشات وأجهزة مختلفة."},"recommendation":{"en":"Empowers agents to generate context-appropriate behavior for effective use across different platforms, including mobile, tablet, and desktop, using temporary one-commit public audit snapshots of Finance-App.","zh":"赋予代理生成上下文相关行为的能力，以便在包括移动设备、平板电脑和桌面在内的不同平台上有效使用 Finance-App 的临时一键式公开审计快照。","ja":"エージェントが、モバイル、タブレット、デスクトップを含むさまざまなプラットフォームで効果的に使用できる、コンテキストに適した動作を生成する機能を提供します。Finance-App の一時的な 1 つのコミットによるパブリック監査スナップショットを使用します。","ko":"에이전트가 모바일, 태블릿, 데스크톱을 포함한 다양한 플랫폼에서 효과적으로 사용할 수 있는 컨텍스트 관련 동작을 생성할 수 있는 기능을 제공합니다. Finance-App의 임시 1회 커밋 공개 감사 스냅샷을 사용합니다.","es":"Habilita a los agentes a generar comportamientos apropiados al contexto para un uso efectivo en diferentes plataformas, incluyendo móviles, tabletas y de escritorio, utilizando instantáneas públicas temporales de una sola confirmación de Finance-App.","fr":"Permet aux agents de générer des comportements appropriés au contexte pour une utilisation efficace sur différentes plateformes, notamment mobiles, tablettes et de bureau, en utilisant des instantanés d''audit publics temporaires d''un seul engagement de Finance-App.","de":"Ermächtigt die Agenten, kontextangepasste Verhaltensweisen für eine effektive Nutzung auf verschiedenen Plattformen zu generieren, einschließlich mobiler Geräte, Tablets und Desktops, unter Verwendung temporärer öffentlicher Prüfungsschnappschüsse von Finance-App.","pt":"Permite que os agentes gerem comportamentos apropriados ao contexto para uso eficaz em diferentes plataformas, incluindo dispositivos móveis, tablet e desktop, usando instantâneos de auditoria pública temporários de um commit do Finance-App.","ru":"Позволяет агентам генерировать контекстно-адекватное поведение для эффективного использования на различных платформах, включая мобильные устройства, планшеты и настольные компьютеры, используя временные публичные аудиторские снимки Finance-App.","ar":"يمكن للعميل توليد سلوكيات مناسبة للسياق لاستخدام فعال عبر منصات مختلفة، بما في ذلك الأجهزة المحمولة واللوحية وأجهزة الكمبيوتر المكتبية، باستخدام لحظات مراجعة عامة مؤقتة من Finance-App."},"useCases":{"en":["Adapting existing designs for mobile devices","Generating responsive layouts for tablet screens","Optimizing feature components for desktop usage"],"zh":["为移动设备适配现有设计","为平板电脑屏幕生成响应式布局","为桌面使用优化功能组件"],"ja":["モバイルデバイス用の既存のデザインを適応させる","タブレットスクリーン用のレスポンシブレイアウトを生成する","デスクトップ使用のための機能コンポーネントを最適化する"],"ko":["모바일 장치용 기존 디자인 적응","태블릿 화면용 반응형 레이아웃 생성","데스크톱 사용을 위한 기능 컴포넌트 최적화"],"es":["Adaptar diseños existentes para dispositivos móviles","Generar diseños receptivos para pantallas de tabletas","Optimizar componentes de características para uso de escritorio"],"fr":["Adapter les conceptions existantes pour les appareils mobiles","Générer des dispositions réactives pour les écrans de tablettes","Optimiser les composants de fonctionnalités pour l''utilisation de bureau"],"de":["Vorhandene Designs für mobile Geräte anpassen","Reaktive Layouts für Tablet-Bildschirme generieren","Funktionkomponenten für Desktop-Nutzung optimieren"],"pt":["Adaptar projetos de design existentes para dispositivos móveis","Gerar layouts responsivos para telas de tablet","Otimizar componentes de recursos para uso em desktop"],"ru":["Адаптировать существующие проекты дизайна для мобильных устройств","Генерировать отзывчивые компоновки для экранов планшета","Оптимизировать компоненты функций для использования на настольном компьютере"],"ar":["تكييف تصاميم موجودة لأجهزة محمولة","توليد تخطيطات مستجيبة لأجهزة لوحية","تحسين مكونات الميزات لاستخدام الكمبيوتر المكتبية"]},"limitations":{"en":["Requires Finance-App access","Limited to screen size and device adaptations"],"zh":["需要 Finance-App 访问","仅限屏幕尺寸和设备适配"],"ja":["Finance-App へのアクセスが必要","画面サイズとデバイスの適応のみ"],"ko":["Finance-App 액세스가 필요합니다.","화면 크기 및 장치 적응만"],"es":["Requiere acceso a Finance-App","Limitado a adaptaciones de tamaño de pantalla y dispositivo"],"fr":["Nécessite un accès à Finance-App","Limité aux adaptations de taille d''écran et d''appareil"],"de":["Benötigt Zugriff auf Finance-App","Begrenzt auf Anpassungen von Bildschirmgröße und Gerät"],"pt":["Requer acesso ao Finance-App","Limitado a adaptações de tamanho e dispositivo de tela"],"ru":["Требуется доступ к Finance-App","Ограничен адаптацией размера и устройства экрана"],"ar":["يتطلب الوصول إلى Finance-App","محدود بالتحسين لحجم الشاشة وأداة العرض"]},"version":4},"contentHash":"ec7e4368269f071ca1c0f7601bcd6bd4c8c2b8041ec9abd1c6820af038a0bb9e","qualityScore":41}');
