INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jkenney47/Finance-App-audit-snapshot-20260306-074853/adapt', 'adapt', 'jkenney47', 'Finance-App-audit-snapshot-20260306-074853', 'community', 'adapt jkenney47 Finance-App-audit-snapshot-20260306-074853 community The Adapt skill generates temporary one-commit public audit snapshots of Finance-App, helping developers adapt existing designs for effective use across various screen sizes and devices. Adapt是一种跨屏适配解决方案，能够根据目标环境和使用上下文调整设计和行为 Adaptは、ターゲット環境と使用状況に応じてデザインと動作を調整する、レスポンシブ設計ツールです Adapt는 대상 환경과 사용 상황에 따라 디자인과 동작을 조정하는 반응형 디자인 도구입니다 Adaptar diseños para diferentes contextos y dispositivos, incluyendo pantallas, routas y componentes Adapter les conceptions pour différents contextes et appareils, y compris les écrans, les routes et les composants Anpassen von Designs für verschiedene Kontexte und Geräte, einschließlich Bildschirmen, Routen und Komponenten O Adapt é uma ferramenta que ajuda a adaptar designs para trabalhar efetivamente em diferentes tamanhos de tela, dispositivos e plataformas. Ele oferece suporte a contextos de uso variados. Адапт - это инструмент, который помогает адаптировать дизайны для эффективной работы на различных размерах экрана, устройствах и платформах. Он поддерживает различные контексты использования. التكيف هو أداة تساعد على تكييف التصاميم للعمل بشكل فعال على أحجام شاشات و أجهزة و منصات مختلفة. كما يدعم سياقات استخدام مختلفة. how to use adapt what is adapt adapt alternative adapt vs responsive design adapt install adapt setup guide adapt for finance app adapt temporary public audit snapshot Adapt 跨屏适配 响应式设计 AI驱动 用户体验优化 移动开发 平板开发 桌面开发 打印开发 Supports adaptation of existing designs for various screen sizes and devices Allows specification of target page, route, feature, or component to adapt Enables inference of the most likely target from the request if inputs are omitted Supports adaptation for different destination environments, such as mobile, tablet, or desktop Adapt is a skill that enables temporary public audit snapshots of Finance-App, adapting designs to work effectively across different screens, devices, and platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nakafaai/nakafa.com/nakafa-content', 'community', 'nakafaai', 'nakafa.com', 'nakafaai/nakafa.com', 'nakafa-content', 75, 15, 41, '2026-02-24T20:42:15Z', '2026-03-06T06:33:29.207Z', 'aa4a0c9d0dad65787fd8060d738dfe55caf25411d98e9af145f745b4770906c5', '{"id":"nakafaai/nakafa.com/nakafa-content","name":"nakafa-content","description":{"en":"nakafa-content is an AI native platform for creating high-quality learning materials. It benefits students, teachers, and experts in the education community by providing a comprehensive curriculum.","zh":"Nakafa Content是一个AI原生免费的高质量学习平台，支持K-12到大学的教育内容","ja":"Nakafa Contentは、AIエージェントを使用した無料の高品質学習プラットフォームです","ko":"Nakafa Content는 AI 기반의 무료 고급 학습 플랫폼으로, 초등에서 대학교까지의 교육 콘텐츠를 지원합니다","es":"Nakafa Content es una plataforma de aprendizaje de inteligencia artificial que ofrece contenido educativo de alta calidad para estudiantes de K-12 a universitarios","fr":"Nakafa Content est une plateforme d''apprentissage par intelligence artificielle qui propose du contenu éducatif de haute qualité pour les étudiants de la maternelle à l''université","de":"Nakafa Content ist eine KI-basierte Lernplattform, die hochwertigen Bildungsinhalt für Schüler von der Grundschule bis zur Universität bietet","pt":"O Nakafa-Content é uma plataforma de aprendizado de IA que oferece recursos educacionais personalizados para estudantes de K-12 a universitário, com currículo e exercícios em indonésio","ru":"Nakafa-Content - это ИИ платформа для обучения, предлагающая индивидуальные образовательные ресурсы для студентов от К-12 до университета, с учебной программой и упражнениями на индонезийском языке","ar":"Nakafa-Content هي منصة تعلم ذكية تقدم موارد تعليمية مخصصة للطلاب من المرحلة الابتدائية إلى الجامعة، مع مناهج وتمارين باللغة الإندونيسية"},"seo":{"title":{"en":"nakafa-content: AI-Powered Learning Platform Setup Guide ...","zh":"Nakafa Content创建指南：AI原生学习平台","ja":"Nakafa Contentセットアップガイド：AIエージェントによる教育プラットフォーム","ko":"Nakafa Content 설정 가이드: AI 기반 학습 플랫폼","es":"Guía de Configuración de Nakafa Content: Plataforma de Ap...","fr":"Guide de Configuration de Nakafa Content: Plateforme d''Ap...","de":"Einrichtungsleitfaden für Nakafa Content: KI-basierte Ler...","pt":"Guia de Configuração do Nakafa-Content: Plataforma de Apr...","ru":"ИИ Агенты: Настройка Nakafa-Content для Обучения","ar":"دليل إعداد Nakafa-Content: منصة تعلم ذكية باللغة العربية"},"description":{"en":"Discover how to create engaging educational content with nakafa-content. Learn to leverage AI for K-12 to university learning and get started with our expert...","zh":"了解Nakafa Content的技术细节，包括创建指南、语言支持和MDX文件格式","ja":"Nakafa Contentの技術的な詳細を学ぶ：セットアップガイド、言語サポート、MDXファイル形式","ko":"Nakafa Content의 기술 세부 사항 알아보기: 설정 가이드, 언어 지원, MDX 파일 형식","es":"Descubre cómo configurar Nakafa Content, una plataforma de aprendizaje de inteligencia artificial para estudiantes de K-12 a universitarios","fr":"Découvrez comment configurer Nakafa Content, une plateforme d''apprentissage par intelligence artificielle pour les étudiants de la maternelle à l''université","de":"Erfahren Sie, wie Sie Nakafa Content einrichten, eine KI-basierte Lernplattform für Schüler von der Grundschule bis zur Universität","pt":"Aprenda a configurar o Nakafa-Content, uma plataforma de aprendizado de IA para educação de K-12 a universitário, com recursos de currículo e exercícios pers...","ru":"Узнайте, как настроить Nakafa-Content, ИИ платформу для обучения от К-12 до университета, с индивидуальными образовательными ресурсами","ar":"تعلم كيفية إعداد Nakafa-Content، منصة تعلم ذكية للتعليم من المرحلة الابتدائية إلى الجامعة، مع موارد مناهج وتمارين مخصصة"},"definition":{"en":"nakafa-content is an AI-driven educational platform designed for K-12 to university learning, offering a community-driven approach to content creation.","zh":"Nakafa Content是AI驱动的教育内容创建平台","ja":"Nakafa ContentはAIエージェントを使用した教育コンテンツ作成プラットフォームです","ko":"Nakafa Content는 AI 기반의 교육 콘텐츠 생성 플랫폼입니다","es":"Nakafa Content es una plataforma de aprendizaje de inteligencia artificial que proporciona contenido educativo personalizado","fr":"Nakafa Content est une plateforme d''apprentissage par intelligence artificielle qui propose du contenu éducatif personnalisé","de":"Nakafa Content ist eine KI-basierte Lernplattform, die personalisierten Bildungsinhalt bietet","pt":"O que é Nakafa-Content? É uma plataforma de aprendizado de IA que fornece recursos educacionais personalizados para estudantes","ru":"Что такое Nakafa-Content? Это ИИ платформа для обучения, предоставляющая индивидуальные образовательные ресурсы для студентов","ar":"ما هو Nakafa-Content؟ هو منصة تعلم ذكية تقدم موارد تعليمية مخصصة للطلاب"},"features":{"en":["Supports creation of educational content in Indonesian (id.mdx) with proper grammar and engaging tone","Utilizes MDX files for content creation, allowing for interactive and immersive learning experiences","Employs a community-driven approach, engaging readers with ''kita'' (we) and ''kalian'' (you all) tone","Provides guidelines for creating exercises and educational materials for the Nakafa platform","Facilitates learning for students, teachers, and experts through a comprehensive curriculum"],"zh":["支持Indonesian（id.mdx）语言","使用MDX文件格式","提供清晰、直截了当的文档","采用自然、吸引人的语气","使用\"kita\"（我们）和\"kalian\"（你们）来吸引读者"],"ja":["Indonesian（id.mdx）言語をサポート","MDXファイル形式を使用","明確で簡潔なドキュメントを提供","自然で魅力的なトーンを採用","「私たち」と「あなたたち」を使用して読者を引き付ける"],"ko":["인도네시아어(id.mdx) 언어 지원","MDX 파일 형식 사용","명확하고 간결한 문서 제공","자연스럽고 매력적인语气採用","「우리」と「너희」を 사용하여 독자를 끌어들이기"],"es":["Contenido educativo de alta calidad para estudiantes de K-12 a universitarios","Plataforma de aprendizaje de inteligencia artificial con ejercicio y evaluación","Soporte para MDX Files en indonesio (id.mdx)","Uso de gramática indonesia adecuada con tono natural y atractivo","Capacidad para personalizar el contenido con ''kita'' (nosotros) y ''kalian'' (ustedes)"],"fr":["Contenu éducatif de haute qualité pour les étudiants de la maternelle à l''université","Plateforme d''apprentissage par intelligence artificielle avec exercice et évaluation","Prise en charge des fichiers MDX en indonésien (id.mdx)","Utilisation de la grammaire indonésienne appropriée avec un ton naturel et attractif","Capacité à personnaliser le contenu avec ''kita'' (nous) et ''kalian'' (vous)"],"de":["Hochwertiger Bildungsinhalt für Schüler von der Grundschule bis zur Universität","KI-basierte Lernplattform mit Übungen und Bewertung","Unterstützung für MDX-Dateien in indonesischer Sprache (id.mdx)","Verwendung der indonesischen Grammatik mit natürlichem und ansprechendem Ton","Fähigkeit, den Inhalt mit ''kita'' (wir) und ''kalian'' (ihr) zu personalisieren"],"pt":["Recursos educacionais personalizados para estudantes de K-12 a universitário","Currículo e exercícios em indonésio","Plataforma de aprendizado de IA para educação","Recursos de comunidade e fóruns para discussão","Suporte a MDX files para criação de conteúdo"],"ru":["Индивидуальные образовательные ресурсы для студентов от К-12 до университета","Учебная программа и упражнения на индонезийском языке","ИИ платформа для обучения для образования","Ресурсы сообщества и форумы для обсуждения","Поддержка MDX файлов для создания контента"],"ar":["موارد تعليمية مخصصة للطلاب من المرحلة الابتدائية إلى الجامعة","مناهج وتمارين باللغة الإندونيسية","منصة تعلم ذكية للتعليم","موارد المجتمع والمناقشات","دعم ملفات MDX لإنشاء المحتوى"]},"keywords":{"en":["how to use nakafa-content","nakafa-content setup guide","what is nakafa-content","nakafa-content alternative","nakafa-content vs traditional learning platforms","nakafa-content install for AI agents","creating educational content with nakafa-content","nakafa-content for K-12 learning","nakafa-content for university education","AI-powered learning with nakafa-content"],"zh":["AI学习平台","Nakafa Content创建指南","MDX文件格式","Indonesian语言支持","AI驱动教育","高质量学习平台"],"ja":["AIエージェント","Nakafa Contentセットアップガイド","MDXファイル形式","Indonesian言語サポート","AI駆動教育","高品質学習プラットフォーム"],"ko":["AI 학습 플랫폼","Nakafa Content 설정 가이드","MDX 파일 형식","인도네시아어 언어 지원","AI 기반 교육","고급 학습 플랫폼"],"es":["Nakafa Content","plataforma de aprendizaje de inteligencia artificial","contenido educativo de alta calidad","estudiantes de K-12 a universitarios","MDX Files","indonesio","gramática indonesia","personalización de contenido"],"fr":["Nakafa Content","plateforme d''apprentissage par intelligence artificielle","contenu éducatif de haute qualité","étudiants de la maternelle à l''université","fichiers MDX","indonésien","grammaire indonésienne","personnalisation de contenu"],"de":["Nakafa Content","KI-basierte Lernplattform","hochwertiger Bildungsinhalt","Schüler von der Grundschule bis zur Universität","MDX-Dateien","indonesische Sprache","indonesische Grammatik","Inhaltspersonalisierung"],"pt":["Nakafa-Content","plataforma de aprendizado de IA","educação de K-12 a universitário","recursos educacionais personalizados","currículo e exercícios em indonésio","MDX files","comunidade e fóruns"],"ru":["Nakafa-Content","ИИ платформа для обучения","образование от К-12 до университета","индивидуальные образовательные ресурсы","учебная программа и упражнения на индонезийском языке","MDX файлы","ресурсы сообщества и форумы"],"ar":["Nakafa-Content","منصة تعلم ذكية","تعليم من المرحلة الابتدائية إلى الجامعة","موارد تعليمية مخصصة","مناهج وتمارين باللغة الإندونيسية","ملفات MDX","موارد المجتمع والمناقشات"]}},"owner":"nakafaai","repo":"nakafa.com","repoPath":"nakafaai/nakafa.com","stars":75,"forks":15,"updatedAt":"2026-02-24T20:42:15Z","topics":["agent","ai","community","curriculum","education","experts","indonesia","learn","students","study","teachers"],"category":"community","skillMd":{"name":"nakafa-content","description":"Create educational content (MDX) and exercises for Nakafa platform. Use when creating or editing subject materials, exercises, questions, answers/explanations, or any educational content in MDX format.","bodyPreview":"# Nakafa Content Creation\n\nGuidelines for creating educational content and exercises for the Nakafa platform.\n\n## Language\n\n### For This Skill (Documentation)\nUse normal English - clear and straightforward.\n\n### For Actual Content (MDX Files)\n- **Indonesian (id.mdx)**: Use proper Indonesian grammar with natural, engaging tone\n  - Use \"kita\" (we) and \"kalian\" (you all) to engage readers\n  - Write like you''re explaining to a friend, but keep it educational\n  - Example: \"Mari kita mulai dengan...\",","body":"# Nakafa Content Creation\n\nGuidelines for creating educational content and exercises for the Nakafa platform.\n\n## Language\n\n### For This Skill (Documentation)\nUse normal English - clear and straightforward.\n\n### For Actual Content (MDX Files)\n- **Indonesian (id.mdx)**: Use proper Indonesian grammar with natural, engaging tone\n  - Use \"kita\" (we) and \"kalian\" (you all) to engage readers\n  - Write like you''re explaining to a friend, but keep it educational\n  - Example: \"Mari kita mulai dengan...\", \"Pernahkah kalian memperhatikan...\"\n  \n- **English (en.mdx)**: Use proper English grammar with natural, engaging tone\n  - Write clearly and conversationally\n  - Keep it educational but not stiff\n\n## Content Types\n\n### 1. Subject Content (`packages/contents/subject/`)\n\nEducational materials organized by level:\n\n```\nsubject/\n├── high-school/\n│   ├── 10/mathematics/{topic}/\n│   ├── 11/mathematics/{topic}/\n│   └── 12/mathematics/{topic}/\n└── university/\n    └── bachelor/\n        └── ai-ds/\n```\n\nEach topic contains:\n- `id.mdx`: Indonesian version (Source of Truth) - natural, engaging tone\n- `en.mdx`: English translation - natural, engaging tone\n- `graph.tsx`: Shared graph component (if needed)\n\n### 2. Exercises (`packages/contents/exercises/`)\n\n```\nexercises/\n├── high-school/\n│   ├── tka/mathematics/{material}/{set}/{number}/\n│   └── snbt/{subject}/{material}/{set}/{number}/\n└── middle-school/\n```\n\nExercise structure per number:\n```\n{number}/\n├── _question/\n│   ├── id.mdx\n│   └── en.mdx\n├── _answer/\n│   ├── id.mdx\n│   └── en.mdx\n└── choices.ts\n```\n\n## MDX Components\n\n### Auto-Imported (No Import Required)\n\nAvailable in all MDX files without importing:\n\n```mdx\n<BlockMath math=\"x^2 + y^2 = r^2\" />\n\n<InlineMath math=\"5\" />\n\n<MathContainer>\n  <BlockMath math=\"a = b\" />\n  <BlockMath math=\"c = d\" />\n</MathContainer>\n\n<CodeBlock\n  data={[\n    { language: \"typescript\", filename: \"example.ts\", code: \"const x = 1;\" },\n  ]}\n/>\n\n<Mermaid chart=\"graph TD; A-->B;\" />\n```\n\n### Content Components (Import Required)\n\nFrom `@repo/design-system/components/contents/*`:\n\n```typescript\nimport { LineEquation } from \"@repo/design-system/components/contents/line-equation\";\nimport { NumberLine } from \"@repo/design-system/components/contents/number-line\";\nimport { Triangle } from \"@repo/design-system/components/contents/triangle\";\nimport { UnitCircle } from \"@repo/design-system/components/contents/unit-circle\";\nimport { Vector3d } from \"@repo/design-system/components/contents/vector-3d\";\nimport { VectorChart } from \"@repo/design-system/components/contents/vector-chart\";\nimport { Inequality } from \"@repo/design-system/components/contents/inequality\";\nimport { FunctionChart } from \"@repo/design-system/components/contents/function-chart\";\nimport { ScatterDiagram } from \"@repo/design-system/components/contents/scatter-diagram\";\nimport { BarChart } from \"@repo/design-system/components/contents/bar-chart\";\nimport { AnimationBacterial } from \"@repo/design-system/components/contents/animation-bacterial\";\n```\n\n### Color System\n\nAlways use `getColor()` for deterministic colors:\n\n```typescript\nimport { getColor } from \"@repo/design-system/lib/color\";\n\n// Available colors: RED, ORANGE, AMBER, YELLOW, LIME, GREEN, EMERALD,\n// TEAL, CYAN, SKY, BLUE, INDIGO, VIOLET, PURPLE, FUCHSIA, PINK, ROSE\n\n<LineEquation\n  data={[{\n    points: Array.from({ length: 100 }, (_, i) => {\n      const x = -5 + (i / 99) * 10;\n      return { x, y: x * x, z: 0 };\n    }),\n    color: getColor(\"INDIGO\"),\n    smooth: true,\n    showPoints: false,\n  }]}\n/>\n```\n\n**Never use default RED, GREEN, or BLUE for lines.**\n\n## Math Formatting Rules\n\n### Components\n\n- **Inline math**: `<InlineMath math=\"x + y\" />`\n- **Block math**: `<BlockMath math=\"x^2 + y^2 = r^2\" />`\n- **Multiple blocks**: Wrap with `<MathContainer>`\n\n### Numbers\n\n- Use `<InlineMath math=\"5\" />` for numbers in text (not plain `5`)\n- Use `<InlineMath math=\"(1)\" />` for numbered references\n- Units: `<InlineMath math=\"5 \\text{ cm}\" />`\n\n### Variables in Text\n\nItalicize variables: *x*, *y*, *f(x)*\n\n### Decimals (Indonesian)\n\nUse comma: `3,14` (not `3.14`)\n\n### Backslash Escaping\n\n**MDX files (InlineMath/BlockMath)**: Use single backslash\n```mdx\n<InlineMath math=\"\\frac{a}{b}\" />\n<BlockMath math=\"\\sqrt{x}\" />\n```\n\n**choices.ts (TypeScript strings)**: Use escaped double backslash\n```typescript\n{ label: \"$$\\\\frac{a}{b}$$\", value: true }\n```\n\n## Writing Guidelines\n\n### Headings\n\n- Start at h2 (`##`)\n- Maximum depth: h4 (`####`)\n- Descriptive titles (NOT \"Step 1\")\n- **NO symbols or math** in headings\n- **NO parentheses** in headings (use \"Analysis 1\" not \"Analysis (1)\")\n\n**Correct:**\n```md\n## Finding the Value of x\n\n#### Analysis 1\n```\n\n**Incorrect:**\n```md\n## Step 1: Finding <InlineMath math=\"x\" />\n\n#### Analysis (1)\n```\n\n### Lists\n\nUse hyphens `-`:\n\n```md\n- First item\n- Second item\n- Third item\n```\n\nNo nested lists. No blank lines between items.\n\n### Be Creative and Concise\n\n- **Be Creative**: Use various Markdown formatting and LaTeX math syntax creatively to present content engagingly\n- **NO Bloated Explanations**: Get straight to the point. Avoid unnecessary introductory text\n- **NO Excessive Lists**: Lists are okay but don''t overuse them. **NEVER use nested lists**\n- **Images are Reference Only**: If you find errors in questions or calculations from source images, fix them directly. The source is just a reference for the calculation method, not absolute truth\n- **Provide Context**: Explain the reasoning and context so students understand WHY, not just WHAT\n\n### Paragraphs and Math\n\nAlways add blank line between text and math:\n\n```mdx\nSome text here.\n\n<BlockMath math=\"x = 5\" />\n\nMore text here.\n```\n\n## Exercise Creation\n\n### Question File (`_question/id.mdx`)\n\n```mdx\nexport const metadata = {\n  title: \"Soal 1\",\n  authors: [{ name: \"Author Name\" }],\n  date: \"06/11/2025\",  // MM/DD/YYYY format\n};\n\nDiketahui <InlineMath math=\"a = 5\" /> dan <InlineMath math=\"b = 3\" />.\n\nHitunglah nilai dari <InlineMath math=\"a + b\" />.\n```\n\n### Answer File (`_answer/id.mdx`)\n\n```mdx\nexport const metadata = {\n  title: \"Pembahasan Soal 1\",\n  authors: [{ name: \"Author Name\" }],\n  date: \"06/11/2025\",\n};\n\n#### Analisis Soal\n\nDiketahui <InlineMath math=\"a = 5\" /> dan <InlineMath math=\"b = 3\" />.\n\n<MathContainer>\n  <BlockMath math=\"a + b = 5 + 3\" />\n  <BlockMath math=\"a + b = 8\" />\n</MathContainer>\n\nJadi, nilai <InlineMath math=\"a + b\" /> adalah <InlineMath math=\"8\" />.\n```\n\n### Choices File (`choices.ts`)\n\n```typescript\nimport type { ExercisesChoices } from \"@repo/contents/_types/exercises/choices\";\n\nconst choices: ExercisesChoices = {\n  id: [\n    { label: \"$$7$$\", value: false },\n    { label: \"$$8$$\", value: true },   // correct answer\n    { label: \"$$9$$\", value: false },\n    { label: \"$$10$$\", value: false },\n    { label: \"Tidak ada jawaban\", value: false },  // plain text\n  ],\n  en: [\n    { label: \"$$7$$\", value: false },\n    { label: \"$$8$$\", value: true },\n    { label: \"$$9$$\", value: false },\n    { label: \"$$10$$\", value: false },\n    { label: \"No answer\", value: false },\n  ],\n};\n\nexport default choices;\n```\n\n**Math in choices:** Use `$$...$$` for math expressions and numbers, plain text for normal labels.\n\n**Important:** In TypeScript strings, backslashes must be escaped with an additional backslash. For example:\n\n```typescript\n// CORRECT - escape the backslash\n{ label: \"$$\\\\frac{a}{b}$$\", value: true }\n{ label: \"$$\\\\sqrt{x}$$\", value: false }\n{ label: \"$$\\\\infty$$\", value: false }\n\n// WRONG - unescaped backslash causes error\n{ label: \"$$\\frac{a}{b}$$\", value: true }\n```\n\n### Key Rules for Exercises\n\n1. **Date Format**: Must be `MM/DD/YYYY` (e.g., \"06/11/2025\")\n2. **Clarity**: Explanations must be clear and unambiguous\n3. **NO Option Letters**: Never refer to (A), (B), (C) in explanations\n4. **Consistent Math**: Use same notation in question and answer\n5. **Numbered References**: Use `<InlineMath math=\"(1)\" />` not `(1)`\n\n## 3D Visualization Patterns\n\n### Generating Points\n\n**Never hard-code points**. Use `Array.from()` with math calculations:\n\n```typescript\n// For a parabola y = x^2 from x=-5 to x=5\npoints: Array.from({ length: 100 }, (_, i) => {\n  const x = -5 + (i / 99) * 10;  // Range from -5 to 5\n  const y = x * x;\n  return { x, y, z: 0 };\n})\n\n// For a circle\npoints: Array.from({ length: 100 }, (_, i) => {\n  const angle = (i / 99) * 2 * Math.PI;\n  const x = Math.cos(angle);\n  const y = Math.sin(angle);\n  return { x, y, z: 0 };\n})\n```\n\n### 2D Graph Settings\n\nFor 2D visualizations:\n\n```tsx\n<LineEquation\n  title={<>Graph of f(x)</>}\n  description=\"Visualization of the function\"\n  showZAxis={false}\n  cameraPosition={[0, 0, 15]}  // Perpendicular to plane\n  data={[{\n    points: [...],\n    color: getColor(\"TEAL\"),\n    smooth: true,\n    showPoints: false,\n  }]}\n/>\n```\n\n### Labels\n\nEnsure labels don''t overlap:\n\n```tsx\nlabels: [\n  { text: \"y = x²\", at: 50, offset: [1, 0.5, 0] }\n]\n```\n\n## Code vs Math\n\n- **Programming code**: Use inline code (`` `const x = 5` ``)\n- **Math values**: Use `<InlineMath math=\"5\" />`\n- **Math functions**: Use `<InlineMath math=\"f(x)\" />`\n- **Programming functions**: Use inline code (`` `function()` ``)\n\n## Quality Checklist\n\nBefore submitting content:\n\n- [ ] Math notation consistent between question and answer\n- [ ] All numbers use `<InlineMath />`\n- [ ] Headings don''t contain math or symbols\n- [ ] Date format is MM/DD/YYYY\n- [ ] Colors use `getColor()` not hard-coded values\n- [ ] 3D points generated via `Array.from()`, not hard-coded\n- [ ] No option letters (A, B, C) in explanations\n- [ ] Explanations are clear and unambiguous\n- [ ] Graph descriptions end with period\n- [ ] Run `pnpm lint` before submitting\n"},"lastSynced":"2026-03-06T06:33:29.207Z","agentAnalysis":{"suitability":{"en":"Ideal for Educational Agents requiring comprehensive curriculum creation and Indonesian language support.","zh":"适合需要全面课程创建和印尼语支持的教育代理。","ja":"教育エージェントが包括的なカリキュラムの作成とインドネシア語のサポートを必要とする場合に適しています。","ko":"포괄적인 커리큘럼 생성과 인도네시아어 지원이 필요한 교육 에이전트에게 적합합니다.","es":"Ideal para Agentes Educativos que requieren creación de currículum integral y soporte de idioma indonesio.","fr":"Idéal pour les agents éducatifs nécessitant une création de cursus complet et un support de la langue indonésienne.","de":"Ideal für Bildungsagenten, die eine umfassende Curriculum-Erstellung und Unterstützung für die indonesische Sprache erfordern.","pt":"Ideal para Agentes Educacionais que requerem criação de currículo abrangente e suporte à língua indonésia.","ru":"Идеально подходит для образовательных агентов, требующих создания всестороннего учебного плана и поддержки индонезийского языка.","ar":"مثالي لワكلاء التعليم الذين يتطلبون إنشاء مناهج دراسية شاملة ودعم اللغة الإندونيسية."},"recommendation":{"en":"Empowers agents to generate high-quality learning materials with MDX files, utilizing proper Indonesian grammar and engaging tone, while providing a comprehensive curriculum for students, teachers, and experts in the education community.","zh":"赋予代理生成高质量的学习材料的能力，使用MDX文件，利用适当的印尼语法和吸引人的语气，同时为学生、教师和教育社区的专家提供全面课程。","ja":"エージェントがMDXファイルを使用して、高品質の学習材料を生成する能力を付与し、適切なインドネシア語の文法と魅力的な口調を提供し、学生、教師、教育コミュニティの専門家のための包括的なカリキュラムを提供します。","ko":"에이전트가 MDX 파일을 사용하여 높은 품질의 학습 자료를 생성할 수 있는 능력을 부여하며, 적절한 인도네시아어 문법과 매력적인 тон을 제공하며, 학생, 교사, 교육 커뮤니티 전문가를 위한 포괄적인 커리큘럼을 제공합니다.","es":"Habilita a los agentes a generar materiales de aprendizaje de alta calidad con archivos MDX, utilizando gramática indonesia adecuada y un tono atractivo, al tiempo que proporciona un currículum integral para estudiantes, maestros y expertos en la comunidad educativa.","fr":"Permet aux agents de générer des matériaux d''apprentissage de haute qualité avec des fichiers MDX, en utilisant une grammaire indonésienne appropriée et un ton engageant, tout en fournissant un cursus complet pour les étudiants, les enseignants et les experts de la communauté éducative.","de":"Ermöglich es den Agenten, hochwertige Lernmaterialien mit MDX-Dateien zu generieren, wobei sie eine angemessene indonesische Grammatik und einen ansprechenden Ton verwenden, während sie gleichzeitig ein umfassendes Curriculum für Schüler, Lehrer und Experten in der Bildungsgemeinschaft bereitstellen.","pt":"Habilita agentes a gerar materiais de aprendizado de alta qualidade com arquivos MDX, utilizando gramática indonésia apropriada e tom atraente, ao mesmo tempo em que fornece um currículo abrangente para estudantes, professores e especialistas na comunidade educacional.","ru":"Наделяет агентов возможностью генерировать материалы для обучения высокого качества с использованием файлов MDX, правильной индонезийской грамматики и привлекательного тона, а также предоставляет всесторонний учебный план для студентов, преподавателей и экспертов в области образования.","ar":"يمنح الوكلاء القدرة على إنشاء مواد تعليمية عالية الجودة باستخدام ملفات MDX، مع استخدام قواعد اللغة الإندونيسية المناسبة وطريقة جذابة، وفي الوقت نفسه يقدم مناهج دراسية شاملة للطلاب والمعلمين والخبراء في المجتمع التعليمي."},"useCases":{"en":["Creating interactive educational content","Developing Indonesian language courses","Generating comprehensive curriculum for students and teachers"],"zh":["创建交互式教育内容","开发印尼语课程","为学生和教师生成全面课程"],"ja":["インタラクティブな教育コンテンツの作成","インドネシア語コースの開発","学生と教師のための包括的なカリキュラムの生成"],"ko":["대화형 교육 콘텐츠 생성","인도네시아어 과정 개발","학생과 교사를 위한 포괄적인 커리큘럼 생성"],"es":["Creación de contenido educativo interactivo","Desarrollo de cursos de idioma indonesio","Generación de un currículum integral para estudiantes y maestros"],"fr":["Création de contenu éducatif interactif","Développement de cours de langue indonésienne","Génération d''un cursus complet pour les étudiants et les enseignants"],"de":["Erstellung von interaktivem Bildungsinhalt","Entwicklung von Indonesisch-Sprachkursen","Generierung eines umfassenden Curriculum für Schüler und Lehrer"],"pt":["Criação de conteúdo educacional interativo","Desenvolvimento de cursos de língua indonésia","Geração de currículo abrangente para estudantes e professores"],"ru":["Создание интерактивного образовательного контента","Разработка индонезийских языковых курсов","Генерация всестороннего учебного плана для студентов и преподавателей"],"ar":["إنشاء محتوى تعليمي تفاعلي","تطوير دورات اللغة الإندونيسية","إنشاء مناهج دراسية شاملة للطلاب والمعلمين"]},"limitations":{"en":["Requires understanding of MDX file format","Primarily designed for Indonesian language support","Limited to educational content creation"],"zh":["需要理解MDX文件格式","主要设计用于印尼语支持","仅限教育内容创建"],"ja":["MDXファイル形式の理解が必要","主にインドネシア語サポートのために設計されています","教育コンテンツの作成のみ"],"ko":["MDX 파일 형식에 대한 이해가 필요합니다","주로 인도네시아어 지원을 위해 설계되었습니다","교육 콘텐츠 생성에만 제한됨"],"es":["Requiere comprensión del formato de archivo MDX","Diseñado principalmente para soporte de idioma indonesio","Limitado a la creación de contenido educativo"],"fr":["Nécessite une compréhension du format de fichier MDX","Conçu principalement pour le support de la langue indonésienne","Limité à la création de contenu éducatif"],"de":["Benötigt Verständnis für das MDX-Dateiformat","Hauptsächlich für die Unterstützung der indonesischen Sprache konzipiert","Begrenzt auf die Erstellung von Bildungsinhalten"],"pt":["Exige compreensão do formato de arquivo MDX","Projetado principalmente para suporte à língua indonésia","Limitado à criação de conteúdo educacional"],"ru":["Требует понимания формата файла MDX","В основном предназначен для поддержки индонезийского языка","Ограничен созданием образовательного контента"],"ar":["يتطلب فهم تنسيق ملف MDX","تم تصميمه في الأساس لدعم اللغة الإندونيسية","محدود بإنشاء المحتوى التعليمي"]},"version":4},"contentHash":"aa4a0c9d0dad65787fd8060d738dfe55caf25411d98e9af145f745b4770906c5","qualityScore":41}');
