INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('The-Skyy-Rose-Collection-LLC/DevSkyy/Open-Source Intelligence', 'Open-Source Intelligence', 'The-Skyy-Rose-Collection-LLC', 'DevSkyy', 'community', 'Open-Source Intelligence The-Skyy-Rose-Collection-LLC DevSkyy community Open-Source Intelligence helps developers discover and integrate open-source resources from GitHub and other platforms, using targeted search strategies and APIs. 开源情报是一种使用 GitHub API 进行开源资源搜索和集成的技术，支持 WordPress 和 React 项目 オープンソースインテリジェンスは、GitHub API を使用してオープンソースリソースを検索および統合する技術です。WordPress および React プロジェクトをサポートしています 오픈소스 인텔리전스는 GitHub API를 사용하여 오픈소스 리소스를 검색 및 통합하는 기술입니다. WordPress 및 React 프로젝트를 지원합니다 La Inteligencia de Código Abierto es una habilidad que permite a los desarrolladores descubrir, evaluar e integrar recursos de código abierto de manera efectiva L''Intelligence Open-Source est une compétence qui permet aux développeurs de découvrir, d''évaluer et d''intégrer des ressources open-source de manière efficace Die Open-Source-Intelligence ist eine Fähigkeit, die es Entwicklern ermöglicht, Open-Source-Ressourcen effektiv zu entdecken, zu bewerten und zu integrieren Nossa ferramenta de inteligência de código aberto é especializada em descobrir e integrar recursos de código aberto de plataformas como GitHub e WordPress.org Наш ИИ Агент для открытой интеллекта умеет обнаруживать и интегрировать открытые ресурсы с платформ như GitHub и WordPress.org أداة ذكاء مفتوح المصدر لدينا متخصصة في اكتشاف وتكامل الموارد مفتوحة المصدر من منصات مثل GitHub و WordPress.org how to use Open-Source Intelligence what is Open-Source Intelligence Open-Source Intelligence alternative Open-Source Intelligence vs GitHub Search Open-Source Intelligence install Open-Source Intelligence setup guide GitHub API search open-source resource discovery targeted search strategy AI agent for open-source integration 开源情报 GitHub API 开源资源搜索 WordPress 主题 React 项目 CLI 搜索 开源平台 开源资源集成 目标搜索 多语言支持 Utilizes GitHub API for targeted searches with specific parameters Supports search queries with multiple filters, such as language and star count Enables discovery of specific tech stacks using commands like curl Facilitates integration of open-source resources from GitHub, npm, and WordPress.org Executes searches using bash commands for precise results Leverages sorting and filtering options, such as sorting by star count Open-Source Intelligence is a skill that enables the discovery, evaluation, and integration of open-source resources from various platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('1Shot-Labs/elite-skills-library-plugin/elite-skills-library', 'community', '1Shot-Labs', 'elite-skills-library-plugin', '1Shot-Labs/elite-skills-library-plugin', 'elite-skills-library', 0, 0, 41, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:25.934Z', '6170fe40bec770ad4340bc37e9eea9b91d4753872eddb96182ed5ab624c300c3', '{"id":"1Shot-Labs/elite-skills-library-plugin/elite-skills-library","name":"elite-skills-library","description":{"en":"The Elite Skills Library plugin provides access to a curated collection of skills for Claude Code users. It fetches skills dynamically based on subscription status and request quota.","zh":"Elite Skills Library 插件为 Claude Code 提供了访问 270+ 个专业级别的技能的功能，支持 Free 和 Professional 订阅","ja":"Elite Skills Library プラグインは、Claude Code に 270 個以上のプロフェッショナルグレードのスキルにアクセスする機能を提供し、Free と Professional のサブスクリプションをサポートします","ko":"Elite Skills Library 플러그인은 Claude Code에 270개 이상의 전문가급 스킬에 액세스할 수 있는 기능을 제공하며 Free 및 Professional 구독을 지원합니다","es":"La biblioteca de habilidades elite es un conjunto de más de 270 habilidades profesionales para Claude Code. Se puede configurar mediante la API y el comando /elite-skills:configure","fr":"La bibliothèque de compétences élite est un ensemble de plus de 270 compétences professionnelles pour Claude Code. Elle peut être configurée via l''API et la commande /elite-skills:configure","de":"Die Elite-Skills-Bibliothek ist eine Sammlung von über 270 professionellen Fähigkeiten für Claude Code. Sie kann über die API und den Befehl /elite-skills:configure konfiguriert werden","pt":"O Elite Skills Library é uma coleção de habilidades profissionais que fornece acesso a 270+ habilidades em várias áreas, com autenticação via API e gerenciamento de quotas.","ru":"Elite Skills Library — это коллекция профессиональных навыков, предоставляющая доступ к 270+ навыкам в различных областях, с аутентификацией через API и управлением квотами.","ar":"المكتبة الاحترافية للمهارات هي مجموعة من المهارات الاحترافية التي توفر وصولاً إلى 270+ مهارة في مجالات متعددة، مع مصادقة عبر واجهة برمجة التطبيقات وإدارة الحصص"},"seo":{"title":{"en":"Elite Skills Library: Premium Skill Distribution Setup Gu...","zh":"Elite Skills Library 插件配置指南 - Claude Code AIエージェント","ja":"Elite Skills Library プラグイン設定ガイド - Claude Code AIエージェント","ko":"Elite Skills Library 플러그인 설정 가이드 - Claude Code AI 에이전트","es":"Guía de configuración de la biblioteca de habilidades eli...","fr":"Guide d''installation de la bibliothèque de compétences él...","de":"Einrichtungsanleitung für die Elite-Skills-Bibliothek für...","pt":"Guia de Configuração do Elite Skills Library para Ferrame...","ru":"Настройка Elite Skills Library для ИИ Агентов","ar":"دليل إعداد المكتبة الاحترافية للمهارات للوكلاء الذكاء الا..."},"description":{"en":"Unlock 270+ professional-grade skills with the Elite Skills Library plugin. Learn how to configure and use the Elite Skills API for Claude Code today!","zh":"了解如何配置 Elite Skills Library 插件，访问 270+ 个专业级别的技能，并通过 Claude Code 实现 AI 解决方案","ja":"Elite Skills Library プラグインの設定方法を学び、270 個以上のプロフェッショナルグレードのスキルにアクセスし、Claude Code を使用した AI ソリューションを実現する","ko":"Elite Skills Library 플러그인 설정 방법을 알아보고 270개 이상의 전문가급 스킬에 액세스하여 Claude Code를 사용한 AI 솔루션을 구현하세요","es":"Accede a más de 270 habilidades profesionales con la biblioteca de habilidades elite. Conoce cómo funciona y cómo configurarla con Claude Code","fr":"Accédez à plus de 270 compétences professionnelles avec la bibliothèque de compétences élite. Découvrez comment elle fonctionne et comment la configurer avec...","de":"Greifen Sie auf über 270 professionelle Fähigkeiten mit der Elite-Skills-Bibliothek zu. Erfahren Sie, wie sie funktioniert und wie Sie sie mit Claude Code ko...","pt":"Aprenda a configurar o Elite Skills Library para acessar 270+ habilidades profissionais em várias áreas, incluindo autenticação via API e gerenciamento de qu...","ru":"Узнайте, как настроить Elite Skills Library для доступа к 270+ профессиональным навыкам в различных областях, включая аутентификацию через API и управление к...","ar":"تعرف على كيفية ضبط المكتبة الاحترافية للمهارات للحصول على وصول إلى 270+ مهارة احترافية في مجالات متعددة، بما في ذلك المصادقة عبر واجهة برمجة التطبيقات وإدارة..."},"definition":{"en":"Elite Skills Library is a plugin providing access to a curated collection of 270+ professional-grade skills across multiple domains for Claude Code.","zh":"Elite Skills Library 是一个为 Claude Code 提供专业级别的技能的插件","ja":"Elite Skills Library は、Claude Code にプロフェッショナルグレードのスキルを提供するプラグインです","ko":"Elite Skills Library는 Claude Code에 전문가급 스킬을 제공하는 플러그인입니다","es":"La biblioteca de habilidades elite es una colección de habilidades profesionales para AI Agentes que se puede acceder mediante una suscripción","fr":"La bibliothèque de compétences élite est une collection de compétences professionnelles pour les outils d''IA qui peut être accédée via un abonnement","de":"Die Elite-Skills-Bibliothek ist eine Sammlung von professionellen Fähigkeiten für KI-Tools, die über ein Abonnement zugänglich ist","pt":"O que é Elite Skills Library? É uma biblioteca de habilidades profissionais que fornece acesso a habilidades em várias áreas via API.","ru":"Что такое Elite Skills Library? Это библиотека профессиональных навыков, предоставляющая доступ к навыкам в различных областях через API.","ar":"ما هي المكتبة الاحترافية للمهارات؟ هي مكتبة من المهارات الاحترافية التي توفر وصولاً إلى مهارات في مجالات متعددة عبر واجهة برمجة التطبيقات"},"features":{"en":["Fetches skills dynamically from the Elite Skills API","Supports subscription-based access with Free and Professional tiers","Configurable via the `/elite-skills:configure` command","Stores API key in `.claude/.elite-skills.local` file","Enforces monthly request quota for skills usage","Requires API key for authentication"],"zh":["支持 Free 和 Professional 订阅","动态获取技能从 Elite Skills API","基于用户订阅状态和月度请求配额的技能访问","需要 API 密钥配置","支持 `/elite-skills:configure` 命令"],"ja":["Free と Professional のサブスクリプションをサポート","Elite Skills API からスキルを動的に取得","ユーザーのサブスクリプション状態と月度リクエストクォータに基づくスキルアクセス","API キー構成が必要"," `/elite-skills:configure` コマンドをサポート"],"ko":["Free 및 Professional 구독 지원","Elite Skills API에서 스킬을 동적으로 가져옴","사용자 구독 상태 및 월별 요청 할당량에 따라 스킬 액세스","API 키 구성 필요"," `/elite-skills:configure` 명령 지원"],"es":["Acceso a más de 270 habilidades profesionales","Configuración mediante la API y el comando /elite-skills:configure","Autenticación mediante clave API","Gestión de cuotas de solicitudes mensuales","Compatibilidad con Claude Code"],"fr":["Accès à plus de 270 compétences professionnelles","Configuration via l''API et la commande /elite-skills:configure","Authentification via clé API","Gestion des quotas de requêtes mensuels","Compatibilité avec Claude Code"],"de":["Zugriff auf über 270 professionelle Fähigkeiten","Konfiguration über die API und den Befehl /elite-skills:configure","Authentifizierung über API-Schlüssel","Verwaltung von monatlichen Anfragekontingenten","Kompatibilität mit Claude Code"],"pt":["Acesso a 270+ habilidades profissionais em várias áreas","Autenticação via API","Gerenciamento de quotas de requisição","Configuração via comando `/elite-skills:configure`","Armazenamento de chaves de API em `.claude/.elite-skills.loc`"],"ru":["Доступ к 270+ профессиональным навыкам в различных областях","Аутентификация через API","Управление квотами запросов","Настройка через команду `/elite-skills:configure`","Хранение ключей API в `.claude/.elite-skills.loc`"],"ar":["الوصول إلى 270+ مهارة احترافية في مجالات متعددة","المصادقة عبر واجهة برمجة التطبيقات","إدارة حصص الطلبات","التحكم عبر الأمر `/elite-skills:configure`","تخزين مفاتيح واجهة برمجة التطبيقات في `.claude/.elite-skills.loc`"]},"keywords":{"en":["how to use elite-skills-library","elite-skills-library setup guide","elite-skills-library alternative","elite-skills-library vs claude code skills","elite-skills-library install","what is elite-skills-library","elite-skills-library api documentation","elite-skills-library subscription plans","configuring elite-skills-library for claude code"],"zh":["Elite Skills Library","Claude Code","AI 插件","专业级别的技能","Free 订阅","Professional 订阅","API 密钥","动态获取技能"],"ja":["Elite Skills Library","Claude Code","AI プラグイン","プロフェッショナルグレードのスキル","Free サブスクリプション","Professional サブスクリプション","API キー","スキルの動的取得"],"ko":["Elite Skills Library","Claude Code","AI 플러그인","전문가급 스킬","Free 구독","Professional 구독","API 키","스킬 동적 가져오기"],"es":["biblioteca de habilidades elite","AI Agentes","Claude Code","configuración de API","autenticación de clave API","gestión de cuotas de solicitudes","desarrollo de habilidades profesionales"],"fr":["bibliothèque de compétences élite","outils d''IA","Claude Code","configuration d''API","authentification de clé API","gestion des quotas de requêtes","développement de compétences professionnelles"],"de":["Elite-Skills-Bibliothek","KI-Tools","Claude Code","API-Konfiguration","API-Schlüssel-Authentifizierung","Verwaltung von Anfragekontingenten","Entwicklung von professionellen Fähigkeiten"],"pt":["Elite Skills Library","Ferramentas de IA","Habilidades profissionais","Autenticação via API","Gerenciamento de quotas","Configuração de habilidades","Desenvolvimento de IA","Tecnologias de IA"],"ru":["Elite Skills Library","ИИ Агенты","Профессиональные навыки","Аутентификация через API","Управление квотами","Настройка навыков","Разработка ИИ","Технологии ИИ"],"ar":["المكتبة الاحترافية للمهارات","الوكلاء الذكاء الاصطناعي","المهارات الاحترافية","المصادقة عبر واجهة برمجة التطبيقات","إدارة الحصص","ضبط المهارات","تطوير الذكاء الاصطناعي","تكنولوجيا الذكاء الاصطناعي"]}},"owner":"1Shot-Labs","repo":"elite-skills-library-plugin","repoPath":"1Shot-Labs/elite-skills-library-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"elite-skills-library","description":"Premium subscription-based skills library with 270+ professional-grade skills. Use when advanced domain expertise is needed. Skills are fetched from API based on users subscription.","bodyPreview":"# Elite Skills Library\n\nThis plugin provides access to the Elite Skills Library - a curated collection of 270+ professional-grade skills across multiple domains.\n\n## How It Works\n\nSkills are fetched dynamically from the Elite Skills API based on:\n1. User''s subscription status (Free or Professional)\n2. Available monthly request quota\n3. Specific skill requested by Claude\n\n## Authentication\n\nAPI key required. Configured via `/elite-skills:configure` command.\n\nStored in: `.claude/.elite-skills.loca","body":"# Elite Skills Library\n\nThis plugin provides access to the Elite Skills Library - a curated collection of 270+ professional-grade skills across multiple domains.\n\n## How It Works\n\nSkills are fetched dynamically from the Elite Skills API based on:\n1. User''s subscription status (Free or Professional)\n2. Available monthly request quota\n3. Specific skill requested by Claude\n\n## Authentication\n\nAPI key required. Configured via `/elite-skills:configure` command.\n\nStored in: `.claude/.elite-skills.local.md` (gitignored, project-scoped)\n\n## Subscription Plans\n\n- **Free:** 1 API key, 100 requests/month, access to all skills\n- **Professional:** 5 API keys, unlimited requests, priority support\n\n## API Integration\n\nSkills are fetched from: `https://skills.1shotlabs.com/api/skills/{slug}`\n\nAuthentication: Bearer token in Authorization header\n\n## Categories\n\nThe Elite Skills Library includes skills in:\n- Software Architecture & System Design\n- Cloud & Infrastructure\n- Database & Data Engineering\n- Security & DevOps\n- AI/ML & Data Science\n- Testing & Quality Assurance\n- Programming Languages & Frameworks\n- Business & Product\n- And many more...\n\n## Usage\n\nSkills automatically load when Claude determines they''re relevant. No manual invocation needed.\n\n**Note:** This is a meta-skill that enables the plugin. Individual skills are fetched from the API based on context.\n"},"lastSynced":"2026-03-08T02:00:25.934Z","agentAnalysis":{"suitability":{"en":"Perfect for Claude Code Agents needing access to a vast library of professional-grade skills across multiple domains.","zh":"非常适合需要访问大量专业级技能库的 Claude Code Agents，跨多个领域。","ja":"Claude Code エージェントが複数のドメインの膨大なプロフェッショナルグレードのスキルライブラリにアクセスする必要がある場合に最適です。","ko":"다중 도메인에 걸친 방대한 전문급 스킬 라이브러리에 액세스해야 하는 Claude Code 에이전트에 적합합니다.","es":"Perfecto para los agentes de Claude Code que necesitan acceder a una vasta biblioteca de habilidades de clase profesional en múltiples dominios.","fr":"Parfait pour les agents Claude Code ayant besoin d''accéder à une vaste bibliothèque de compétences de niveau professionnel dans plusieurs domaines.","de":"Perfekt für Claude Code-Agents, die Zugriff auf eine umfangreiche Bibliothek professioneller Fähigkeiten in mehreren Bereichen benötigen.","pt":"Perfeito para Agentes de Código Claude que necessitam de acesso a uma vasta biblioteca de habilidades de nível profissional em vários domínios.","ru":"Идеально для агентов Claude Code, которым требуется доступ к обширной библиотеке профессиональных навыков в нескольких областях.","ar":"مثالي لعميل كلود كود الذي يحتاج إلى الوصول إلى مكتبة شاملة من المهارات الاحترافية عبر مجالات متعددة."},"recommendation":{"en":"Empowers agents to dynamically fetch skills from the Elite Skills API based on subscription status, request quota, and specific skill requests, utilizing API keys for secure authentication and supporting over 270 skills.","zh":"使得代理可以根据订阅状态、请求配额和特定技能请求动态地从 Elite Skills API 中获取技能，利用 API 密钥进行安全认证，并支持超过 270 个技能。","ja":"エージェントがサブスクリプションの状態、リクエストクォータ、特定のスキルリクエストに基づいて Elite Skills API からスキルを動的に取得できるようにし、API キーを使用してセキュアな認証を行い、270 を超えるスキルをサポートします。","ko":"에이전트가 구독 상태, 요청 할당량 및 특정 스킬 요청에 따라 Elite Skills API에서 스킬을 동적으로 가져올 수 있도록 하며, API 키를 사용하여 보안 인증을 수행하고 270개 이상의 스킬을 지원합니다.","es":"Habilita a los agentes a recuperar habilidades de forma dinámica desde la Elite Skills API en función del estado de suscripción, cuota de solicitudes y solicitudes de habilidades específicas, utilizando claves de API para la autenticación segura y soportando más de 270 habilidades.","fr":"Permet aux agents de récupérer dynamiquement des compétences à partir de l''API Elite Skills en fonction du statut d''abonnement, de la quote-part des demandes et des demandes de compétences spécifiques, en utilisant des clés API pour une authentification sécurisée et en prenant en charge plus de 270 compétences.","de":"Ermöglicht es den Agents, Fähigkeiten dynamisch aus der Elite Skills API abzurufen, basierend auf Abonnementsstatus, Anfragekontingent und spezifischen Fähigkeitsanfragen, unter Verwendung von API-Schlüsseln für sichere Authentifizierung und unterstützt über 270 Fähigkeiten.","pt":"Permite que os agentes busquem dinamicamente habilidades da Elite Skills API com base no status de assinatura, cota de solicitação e solicitações de habilidades específicas, utilizando chaves de API para autenticação segura e suportando mais de 270 habilidades.","ru":"Позволяет агентам динамически получать навыки из Elite Skills API на основе статуса подписки, квоты запросов и конкретных запросов навыков, используя ключи API для безопасной аутентификации и поддерживая более 270 навыков.","ar":"يمنح الوكلاء القدرة على الحصول ديناميكيًا على المهارات من Elite Skills API بناءً على حالة الاشتراك وحد الكمية المطلوبة وطلبات المهارات النوعية، باستخدام مفاتيح API للتحقق الآمن ودعم أكثر من 270 مهارة."},"useCases":{"en":["Automating skill selection based on user subscription status","Generating dynamic skill requests within monthly quota limits","Integrating professional-grade skills into Claude Code workflows"],"zh":["基于用户订阅状态自动选择技能","在每月配额限制内生成动态技能请求","将专业级技能集成到 Claude Code 工作流中"],"ja":["ユーザーのサブスクリプション状態に基づいてスキルを自動的に選択する","毎月のクォータ制限内で動的なスキルリクエストを生成する","プロフェッショナルグレードのスキルを Claude Code ワークフローに統合する"],"ko":["사용자의 구독 상태에 따라 스킬을 자동으로 선택하는 것","월 할당량 제한 내에서 동적 스킬 요청을 생성하는 것","전문급 스킬을 Claude Code 워크플로에 통합하는 것"],"es":["Automatizar la selección de habilidades en función del estado de suscripción del usuario","Generar solicitudes de habilidades dinámicas dentro de los límites de la cuota mensual","Integrar habilidades de clase profesional en flujos de trabajo de Claude Code"],"fr":["Automatiser la sélection de compétences en fonction du statut d''abonnement de l''utilisateur","Générer des demandes de compétences dynamiques dans les limites de la quote-part mensuelle","Intégrer des compétences de niveau professionnel dans les flux de travail Claude Code"],"de":["Automatisieren der Fähigkeitsauswahl basierend auf dem Abonnementsstatus des Benutzers","Erzeugen dynamischer Fähigkeitsanfragen innerhalb der monatlichen Kontingentgrenzen","Integrieren professioneller Fähigkeiten in Claude Code-Workflows"],"pt":["Automatizar a seleção de habilidades com base no status de assinatura do usuário","Gerar solicitações de habilidades dinâmicas dentro dos limites de quota mensal","Integrar habilidades de nível profissional nos fluxos de trabalho do Claude Code"],"ru":["Автоматизировать выбор навыков на основе статуса подписки пользователя","Генерировать динамические запросы навыков в пределах месячных лимитов квоты","Интегрировать профессиональные навыки в рабочие процессы Claude Code"],"ar":["توفير تحديد المهارات تلقائيًا بناءً على حالة اشتراك المستخدم","توليد طلبات ديناميكية للمهارات في حدود الكميات الشهرية المسموح بها","دمج المهارات الاحترافية في سير عمل كلود كود"]},"limitations":{"en":["Requires Elite Skills API key for authentication","Dependent on user''s subscription status and available request quota"],"zh":["需要 Elite Skills API 密钥进行认证","依赖于用户的订阅状态和可用请求配额"],"ja":["認証に Elite Skills API キーが必要","ユーザーのサブスクリプション状態と使用可能なリクエストクォータに依存する"],"ko":["인증을 위해 Elite Skills API 키가 필요합니다.","사용자의 구독 상태 및 사용 가능한 요청 할당량에 의존합니다."],"es":["Requiere una clave de API de Elite Skills para la autenticación","Dependiente del estado de suscripción del usuario y de la cuota de solicitudes disponible"],"fr":["Nécessite une clé API Elite Skills pour l''authentification","Dépend du statut d''abonnement de l''utilisateur et de la quote-part de demandes disponible"],"de":["Benötigt einen Elite Skills API-Schlüssel für die Authentifizierung","Abhängig vom Abonnementsstatus des Benutzers und der verfügbaren Anfragequote"],"pt":["Exige chave de API da Elite Skills para autenticação","Dependente do status de assinatura do usuário e da cota de solicitação disponível"],"ru":["Требует ключа API Elite Skills для аутентификации","Зависит от статуса подписки пользователя и доступной квоты запросов"],"ar":["يتطلب مفتاح Elite Skills API للتحقق","يعتمد على حالة اشتراك المستخدم والكمية المتاحة من الطلبات"]},"version":4},"contentHash":"6170fe40bec770ad4340bc37e9eea9b91d4753872eddb96182ed5ab624c300c3","qualityScore":41}');
