INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('superlucky84/lithent/lithent', 'lithent', 'superlucky84', 'lithent', 'community', 'lithent superlucky84 lithent community Lithent is a lightweight virtual DOM library for predictable UIs, benefiting developers with its 4KB core and closure-based state management. Lithent是一个轻量级的虚拟DOM库，提供可预测的UI和基于闭包的状态管理 Lithentは軽量仮想DOMライブラリで、予測可能なUIとクロージャベースの状態管理を提供します Lithent는 가벼운 가상 DOM 라이브러리로서 예측 가능한 UI와 클로저 기반 상태 관리를 제공합니다 Lithent es una biblioteca de DOM virtual ligera que ofrece una administración de estado predictiva y control explícito Lithent est une bibliothèque de DOM virtuel légère qui offre une gestion d''état prévisible et un contrôle explicite Lithent ist eine leichte virtuelle DOM-Bibliothek, die eine vorhersehbare Zustandsverwaltung und eine explizite Kontrolle bietet O Lithent é uma biblioteca virtual DOM leve de 4KB com gerenciamento de estado baseado em closure para UIs previsíveis Lithent - лёгкая виртуальная DOM-библиотека размером 4КБ с управлением состояния на основе замыкания для предсказуемых UI Lithent هي مكتبة DOM افتراضية خفيفة الحجم 4KB مع إدارة الحالة القائمة على الإغلاق لإنشاء واجهات مستخدم متوقعة how to use lithent lithent vs react lithent install what is lithent lithent alternative lithent setup guide jsx virtual dom closure-based state management lightweight ui library Lithent 轻量级虚拟DOM 基于闭包的状态管理 JSX React 虚拟DOM库 轻量级核心 Manual Mode Light API Mode Offers two component modes: Manual Mode (mount) and Light API Mode (lmount) Provides explicit control with renew() function in Manual Mode Supports auto-reactive state management with lstate/lstore in Light API Mode Utilizes a 4KB core for efficient UI updates Leverages JSX for seamless UI rendering Allows for closure-based state management Lithent is a lightweight JSX-based virtual DOM library with closure-based state management, offering Manual and Light API modes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('siviter-xyz/dot-agent/psi', 'community', 'siviter-xyz', 'dot-agent', 'siviter-xyz/dot-agent', 'psi', 0, 0, 41, '2026-03-08T01:57:15.281Z', '2026-03-08T02:00:51.195Z', 'b9e814607af13fc53b0c340de10be60ca2249b5482529d3ed30bbc3a7086b4ca', '{"id":"siviter-xyz/dot-agent/psi","name":"psi","description":{"en":"psi is a curated collection of agent skills designed to enhance the workflows of Software Engineers through a structured approach. It follows a Plan Spec Implement workflow, ensuring documentation stays up-to-date.","zh":"PSI 是一个结构化的工作流，用于规划、指定和实现变化，采用文档优先的方法","ja":"PSI は、計画、仕様、実装の変更にドキュメント優先のアプローチを使用する構造化ワークフローです","ko":"PSI는 계획, 사양 및 구현의 변경에 문서 우선 접근 방식을 사용하는 구조化 된 워크 플로우입니다","es":"psi es un flujo de trabajo estructurado para planificar, especificar e implementar cambios con un enfoque de documentación primero, diseñado para mejorar los flujos de trabajo de los ingenieros de software","fr":"psi est un workflow structuré pour planifier, spécifier et mettre en œuvre des changements avec une approche de documentation première, conçu pour améliorer les flux de travail des ingénieurs logiciels","de":"psi ist ein strukturierter Workflow zum Planen, Spezifizieren und Implementieren von Änderungen mit einem dokumentationsbasierten Ansatz, entwickelt um die Arbeitsabläufe von Software-Ingenieuren zu verbessern","pt":"O PSI é uma ferramenta de fluxo de trabalho que ajuda os engenheiros de software a planejar, especificar e implementar alterações com uma abordagem de documentação primeiro.","ru":"PSI - это инструмент для планирования и реализации изменений, который помогает разработчикам планировать, специфицировать и реализовывать изменения с подходом документации primero","ar":"PSI هو أداة تدفق عمل تساعد منDevelopers على التخطيط والتحديد والتنفيذ للتغييرات مع نهج الوثائق أولاً"},"seo":{"title":{"en":"psi: Structured Workflow Setup Guide | AI Agent Skill","zh":"PSI 工作流设置指南 - AI 工具","ja":"PSI ワークフローのベストプラクティス - AIエージェント","ko":"PSI 구현 가이드 - AI 에이전트","es":"Guía de Configuración de psi: Flujo de Trabajo Estructura...","fr":"Guide de Configuration de psi : Workflow Structuré pour l...","de":"psi-Setup-Leitfaden: Strukturierter Workflow für Software...","pt":"Guia de Configuração do PSI - Ferramenta de Fluxo de Trab...","ru":"Настройка PSI - Инструмент для планирования и реализации ...","ar":"دليل إعداد PSI - أداة تدفق عمل لمنDevelopers"},"description":{"en":"Discover how psi streamlines software engineering workflows with a documentation-first approach. Learn how to implement psi in your projects today!","zh":"了解 PSI 的核心工作流和关键原则，优化您的软件开发工作流","ja":"PSI のワークフローと原則を理解して、ソフトウェア開発の生産性を向上させる","ko":"PSI 의 핵심 워크플ロー와 주요 원칙을 학습하여 소프트웨어 개발 생산성을 높이세요","es":"Aprende a implementar psi en tus proyectos de software con nuestra guía de configuración y mejora tus flujos de trabajo con un enfoque de documentación primero","fr":"Découvrez comment mettre en œuvre psi dans vos projets de logiciel avec notre guide de configuration et améliorez vos flux de travail avec une approche de do...","de":"Erfahren Sie, wie Sie psi in Ihre Software-Projekte implementieren können, mit unserem Setup-Leitfaden und verbessern Sie Ihre Arbeitsabläufe mit einem dokum...","pt":"Aprenda a configurar o PSI, uma ferramenta de fluxo de trabalho para engenheiros de software que melhora a produtividade com uma abordagem de documentação pr...","ru":"Узнайте, как настроить PSI, инструмент для планирования и реализации изменений, который повышает производительность разработчиков с помощью подхода документа...","ar":"تعرف على كيفية إعداد PSI، أداة تدفق عمل لمنDevelopers التي تحسن الإنتاجية من خلال نهج الوثائق أولاً"},"definition":{"en":"psi is a structured workflow for planning, specifying, and implementing changes with a documentation-first approach, designed for coding agents.","zh":"PSI 是一个用于软件工程的结构化工作流","ja":"PSI はソフトウェアエンジニアリング用の構造化ワークフローです","ko":"PSI는 소프트웨어 엔지니어링을 위한 구조화된 워크플로우입니다","es":"psi es una colección curada de habilidades de agente de codificación para ingenieros de software que sigue un flujo de trabajo estructurado de planificación, especificación e implementación","fr":"psi est une collection curatée de compétences d''agent de codage pour les ingénieurs logiciels qui suit un workflow structuré de planification, spécification et mise en œuvre","de":"psi ist eine kuratierte Sammlung von Fähigkeiten für Codierungsagenten für Software-Ingenieure, die einem strukturierten Workflow für Planung, Spezifizierung und Implementierung folgt","pt":"O que é PSI? Uma ferramenta de fluxo de trabalho para engenheiros de software que segue a abordagem de documentação primeiro","ru":"Что такое PSI? Инструмент для планирования и реализации изменений для разработчиков с подходом документации primero","ar":"ما هو PSI؟ أداة تدفق عمل لمنDevelopers التي تتبع نهج الوثائق أولاً"},"features":{"en":["Follows a Plan Spec Implement core workflow","Ensures documentation stays up-to-date across independent phases","References project AGENTS.md file for explicit direction","Supports opt-in workflow, not automatic implementation","Allows starting with any phase, including Plan, Spec, or Implement"],"zh":["计划、指定和实现的独立阶段","文档优先的方法","核心工作流包括 Plan、Spec 和 Implement","可选的工作流，不是默认设置","需要用户明确指令或在项目 AGENTS.md 文件中提及"],"ja":["計画、仕様、実装の独立したフェーズ","ドキュメント優先のアプローチ","コアワークフローには Plan、Spec、Implement が含まれる","オプトインのワークフロー、デフォルトではありません","ユーザーの明示的な指示またはプロジェクトの AGENTS.md ファイルへの参照が必要"],"ko":["계획, 사양 및 구현의 독립적인 단계","문서 우선 접근 방식","코어 워크플로는 Plan, Spec 및 Implement를 포함","선택적 워크플로우, 기본 설정이 아님","사용자의 명시적인 지시 또는 프로젝트의 AGENTS.md 파일에 대한 참조가 필요"],"es":["Flujo de trabajo estructurado de planificación, especificación e implementación","Enfoque de documentación primero para garantizar la actualización de la documentación","Fases independientes para una mayor flexibilidad","Compatibilidad con AGENTS.md para una integración sin problemas","Opt-in workflow para un control total sobre el proceso"],"fr":["Workflow structuré de planification, spécification et mise en œuvre","Approche de documentation première pour garantir la mise à jour de la documentation","Phases indépendantes pour une plus grande flexibilité","Compatibilité avec AGENTS.md pour une intégration sans problème","Workflow opt-in pour un contrôle total sur le processus"],"de":["Strukturierter Workflow für Planung, Spezifizierung und Implementierung","Dokumentationsbasierte Approche, um die Aktualisierung der Dokumentation zu gewährleisten","Unabhängige Phasen für eine größere Flexibilität","Kompatibilität mit AGENTS.md für eine reibungslose Integration","Opt-in-Workflow für eine vollständige Kontrolle über den Prozess"],"pt":["Fluxo de trabalho estruturado para planejar, especificar e implementar alterações","Abordagem de documentação primeiro para garantir a atualização da documentação","Fases independentes para permitir a flexibilidade no processo de desenvolvimento","Integração com o arquivo AGENTS.md para direcionar a utilização da ferramenta","Suporte à implementação de alterações com garantia de documentação atualizada"],"ru":["Структурированный рабочий процесс для планирования, спецификации и реализации изменений","Подход документации primero для обеспечения актуальности документации","Независимые фазы для обеспечения гибкости в процессе разработки","Интеграция с файлом AGENTS.md для направления использования инструмента","Поддержка реализации изменений с гарантией актуальной документации"],"ar":["تدفق عمل منظم لالتخطيط والتحديد والتنفيذ للتغييرات","نهج الوثائق أولاً لضمان تحديث الوثائق","مراحل مستقلة لتمكين المرونة في عملية التطوير","التكامل مع ملف AGENTS.md لتوجيه استخدام الأداة","دعم التنفيذ للتغييرات مع ضمان الوثائق المحدثة"]},"keywords":{"en":["how to use psi","psi setup guide","psi alternative","psi vs other workflows","psi install","what is psi","psi documentation-first approach","psi for software engineers"],"zh":["PSI 工作流","AI 工具","软件开发","结构化工作流","文档优先","计划、指定和实现","独立阶段","可选工作流"],"ja":["PSI ワークフロー","AIエージェント","ソフトウェア開発","構造化ワークフロー","ドキュメント優先","計画、仕様、実装","独立したフェーズ","オプトインワークフロー"],"ko":["PSI 워크플로우","AI 에이전트","소프트웨어 개발","구조화된 워크플로우","문서 우선","계획, 사양 및 구현","독립적인 단계","선택적 워크플로우"],"es":["psi","flujo de trabajo estructurado","documentación primera","ingenieros de software"," AGENTS.md","opt-in workflow","planificación de software","especificación de software","implementación de software"],"fr":["psi","workflow structuré","documentation première","ingénieurs logiciels","AGENTS.md","workflow opt-in","planification de logiciel","spécification de logiciel","mise en œuvre de logiciel"],"de":["psi","strukturierter Workflow","Dokumentationsbasierte Approache","Software-Ingenieure","AGENTS.md","Opt-in-Workflow","Software-Planung","Software-Spezifizierung","Software-Implementierung"],"pt":["PSI","ferramenta de fluxo de trabalho","engenheiros de software","documentação primeiro","planejamento de alterações","especificação de alterações","implementação de alterações","AGENTS.md","desenvolvimento de software"],"ru":["PSI","инструмент для планирования и реализации изменений","разработчики","документация primero","планирование изменений","спецификация изменений","реализация изменений","AGENTS.md","разработка программного обеспечения"],"ar":["PSI","أداة تدفق عمل","منDevelopers","الوثائق أولاً","التخطيط للتغييرات","التحديد للتغييرات","التنفيذ للتغييرات","AGENTS.md","تطوير البرمجيات"]}},"owner":"siviter-xyz","repo":"dot-agent","repoPath":"siviter-xyz/dot-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.281Z","topics":[],"category":"community","skillMd":{"name":"psi","description":"Plan-spec-implement workflow for structured development. Only use when explicitly directed by user or when mentioned in project AGENTS.md file. Generates ephemeral plans in ~/.dot-agent/, applies specs to project docs, then implements test-first.","bodyPreview":"# PSI - Plan Spec Implement\n\nStructured workflow for planning, specifying, and implementing changes with documentation-first approach.\n\n## When to Use\n\n**Only use when:**\n- Explicitly directed by the user\n- Mentioned in project `AGENTS.md` file\n\n**Do not use automatically** - this is an opt-in workflow, not a default.\n\n## Core Workflow\n\n**Plan → Spec → Implement**\n\nPhases are **independent** - you can start with any phase, but all must ensure documentation stays up-to-date.\n\n## Key Principles\n\n1","body":"# PSI - Plan Spec Implement\n\nStructured workflow for planning, specifying, and implementing changes with documentation-first approach.\n\n## When to Use\n\n**Only use when:**\n- Explicitly directed by the user\n- Mentioned in project `AGENTS.md` file\n\n**Do not use automatically** - this is an opt-in workflow, not a default.\n\n## Core Workflow\n\n**Plan → Spec → Implement**\n\nPhases are **independent** - you can start with any phase, but all must ensure documentation stays up-to-date.\n\n## Key Principles\n\n1. **Ephemeral planning** - Plans stored in `~/.dot-agent/` (not committed)\n2. **Documentation-first** - Specs applied to project docs/READMEs/AGENTS.md\n3. **Test-first implementation** - Tests for docs/user journeys before code\n4. **Design/review embedded** - Design and review integrated into Plan/Spec phases\n5. **Phase independence** - Each phase can work standalone, all update docs\n\n## Phase Overview\n\n### Plan Phase\n- Generates detailed plans in `~/.dot-agent/repo/YYYY-MM-work-name.plan.md`\n- Research stored in `~/.dot-agent/working-dir/repo/YYYY-MM-work-name.research.md`\n- Embeds design considerations\n- Includes review before proceeding\n\n### Spec Phase\n- Generates specs for: API schemas, interfaces, DTOs, database models, config, env vars, architecture, user journeys, package structure, tech choices\n- Embeds design considerations\n- Reviews specs before applying\n- Applies to: `docs/`, README.md files, AGENTS.md files\n\n### Implement Phase\n- Test-first: tests for docs/user journeys before code\n- CI verification: verify types, tests, lint pass before committing\n- Atomic commits: group related changes with tests\n- Updates docs, README.md, AGENTS.md as code evolves\n- Can work independently if specs exist in docs\n\n## Research Management\n\nDetects phrases like:\n- \"looking at your research\" → Loads research file\n- \"refine your research\" → Updates research file, narrows focus\n\n## Documentation Structure\n\n- **README.md**: Aim for < 1000 lines (not hard rule), can be longer if needed\n- **AGENTS.md**: < 200 lines, inline at root/packages/modules/code level\n- **docs/**: Architecture, roadmap, tech-choices, setup/, user-journeys/, design/\n\n## References\n\nFor detailed protocols, see:\n- `references/plan-phase.md` - Plan generation with embedded design/review\n- `references/spec-phase.md` - Spec generation and application\n- `references/implement-phase.md` - Test-first implementation\n- `references/review-protocol.md` - Reviewing plans/specs/design\n- `references/research-management.md` - Research file handling\n- `references/docs-structure.md` - Documentation organization rules\n- `references/file-paths.md` - Storage paths and conventions\n"},"lastSynced":"2026-03-08T02:00:51.195Z","agentAnalysis":{"suitability":{"en":"Ideal for Software Engineer Agents requiring a structured approach to planning, specifying, and implementing changes with up-to-date documentation.","zh":"适用于需要结构化方法来规划、指定和实施更改的软件工程代理，并提供最新的文档。","ja":"計画、仕様の作成、変更の実施に構造化されたアプローチを必要とするソフトウェアエンジニアエージェントに適しています。また、最新のドキュメントを提供します。","ko":"계획, 지정, 변경을 구현하기 위한 구조화된 접근 방식을 필요로 하는 소프트웨어 엔지니어 에이전트에게 적합하며 최신 문서를 제공합니다.","es":"Ideal para Agentes de Ingeniero de Software que requieren un enfoque estructurado para planificar, especificar e implementar cambios con documentación actualizada.","fr":"Idéal pour les agents d''ingénieur de logiciel nécessitant une approche structurée pour planifier, spécifier et mettre en œuvre des modifications avec une documentation à jour.","de":"Ideal für Software Engineer Agenten, die einen strukturierten Ansatz für die Planung, Spezifikation und Implementierung von Änderungen mit aktueller Dokumentation benötigen.","pt":"Ideal para Agentes de Engenheiro de Software que exigem uma abordagem estruturada para planejar, especificar e implementar alterações com documentação atualizada.","ru":"Идеально для агентов-инженеров программного обеспечения, требующих структурированного подхода к планированию, спецификации и реализации изменений с актуальной документацией.","ar":"مثالي لعميل مهندس البرمجيات الذي يتطلب منه نهجًا منظمًا للتخطيط والتحديد والتنفيذ للتغييرات مع توثيق محدث."},"recommendation":{"en":"Empowers agents to follow a documentation-first approach using the Plan Spec Implement workflow, ensuring seamless project management through phases like Plan, Spec, and Implement, all while maintaining current documentation.","zh":"赋予代理以文档优先的方法，使用 Plan Spec Implement 工作流，确保项目管理的各个阶段（如计划、指定、实施）顺利进行，同时保持当前的文档。","ja":"エージェントに、Plan Spec Implement ワークフローを使用して文書優先のアプローチを提供し、計画、仕様作成、実施などの各段階でプロジェクト管理を円滑に行い、同時に最新の文書を維持します。","ko":"에이전트에게 Plan Spec Implement 워크플로를 사용하여 문서 우선 접근 방식을 제공하여 계획, 사양, 구현 등의 프로젝트 관리 단계를 원활하게 진행하며 동시에 최신 문서를 유지합니다.","es":"Habilita a los agentes a seguir un enfoque de documentación primero utilizando el flujo de trabajo Plan Spec Implement, garantizando una gestión de proyectos sin problemas a través de fases como Plan, Spec e Implement, manteniendo al mismo tiempo la documentación actual.","fr":"Permet aux agents de suivre une approche de documentation première en utilisant le workflow Plan Spec Implement, assurant une gestion de projet sans accroc à travers les phases Plan, Spec et Implement, tout en maintenant la documentation à jour.","de":"Ermächtigt die Agenten, einen dokumentationsbasierten Ansatz zu verfolgen, indem sie den Plan Spec Implement-Workflow verwenden, der eine nahtlose Projektverwaltung durch Phasen wie Plan, Spec und Implement ermöglicht, während gleichzeitig die aktuelle Dokumentation aufrechterhalten wird.","pt":"Habilita os agentes a seguir uma abordagem de documentação em primeiro lugar usando o fluxo de trabalho Plan Spec Implement, garantindo uma gestão de projetos sem interrupções em fases como Plan, Spec e Implement, mantendo sempre a documentação atualizada.","ru":"Наделяет агентов возможностью следовать подходу документации в первую очередь, используя рабочий процесс Plan Spec Implement, обеспечивая бесперебойное управление проектами на этапах, таких как Plan, Spec и Implement, при этом поддерживая актуальную документацию.","ar":"يمنح الوكلاء القدرة على اتباع نهج التوثيق أولاً باستخدام تدفق عمل Plan Spec Implement ، مما يضمن إدارة مشروع دون انقطاع خلال مراحل مثل Plan و Spec و Implement ، مع الحفاظ على توثيق محدث في جميع الأوقات."},"useCases":{"en":["Automating workflow planning with explicit user direction","Generating project specifications with mention in AGENTS.md files","Implementing changes with real-time documentation updates"],"zh":["使用明确的用户方向自动执行工作流规划","在 AGENTS.md 文件中提及生成项目规格","使用实时文档更新来实施更改"],"ja":["明確なユーザーの指示でワークフローの計画を自動化する","AGENTS.md ファイルで言及してプロジェクトの仕様を生成する","リアルタイムのドキュメント更新で変更を実施する"],"ko":["명확한 사용자 지시에 따라 워크플로 계획을 자동화하는 것","AGENTS.md 파일에서 언급하여 프로젝트 사양을 생성하는 것","실시간 문서 업데이트로 변경 사항을 구현하는 것"],"es":["Automatización de la planificación de flujo de trabajo con dirección de usuario explícita","Generación de especificaciones de proyecto con mención en archivos AGENTS.md","Implementación de cambios con actualizaciones de documentación en tiempo real"],"fr":["Automatisation de la planification du flux de travail avec direction utilisateur explicite","Génération de spécifications de projet avec mention dans les fichiers AGENTS.md","Mise en œuvre de modifications avec mises à jour de documentation en temps réel"],"de":["Automatisierung der Workflow-Planung mit expliziter Benutzerrichtung","Generierung von Projektspezifikationen mit Erwähnung in AGENTS.md-Dateien","Implementierung von Änderungen mit Echtzeit-Dokumentationsaktualisierungen"],"pt":["Automatizar o planejamento do fluxo de trabalho com direção explícita do usuário","Gerar especificações de projeto com menção em arquivos AGENTS.md","Implementar alterações com atualizações de documentação em tempo real"],"ru":["Автоматизировать планирование рабочего процесса с явным указанием пользователя","Генерировать спецификации проекта с упоминанием в файлах AGENTS.md","Реализовывать изменения с обновлениями документации в режиме реального времени"],"ar":["التحكم الآلي في تخطيط سير العمل بإرشاد المستخدم الصريح","توليد مواصفات المشروع مع ذكرها في ملفات AGENTS.md","تنفيذ التغييرات مع تحديثات التوثيق في الوقت الفعلي"]},"limitations":{"en":["Requires explicit user direction or mention in project AGENTS.md file","Not intended for automatic use","Must adhere to the Plan Spec Implement workflow"],"zh":["需要明确的用户方向或在项目 AGENTS.md 文件中提及","不适用于自动使用","必须遵循 Plan Spec Implement 工作流"],"ja":["明確なユーザーの指示、またはプロジェクトの AGENTS.md ファイルでの言及が必要","自動使用には適していない","Plan Spec Implement ワークフローに従わなければならない"],"ko":["명확한 사용자 지시 또는 프로젝트의 AGENTS.md 파일에서 언급이 필요함","자동 사용에는 적합하지 않음","Plan Spec Implement 워크플로우에 따라야 함"],"es":["Requiere dirección de usuario explícita o mención en el archivo de proyecto AGENTS.md","No está destinado para uso automático","Debe adherirse al flujo de trabajo Plan Spec Implement"],"fr":["Nécessite une direction utilisateur explicite ou une mention dans le fichier de projet AGENTS.md","N''est pas destiné à une utilisation automatique","Doit se conformer au workflow Plan Spec Implement"],"de":["Benötigt explizite Benutzerrichtung oder Erwähnung in der Projekt-AGENTS.md-Datei","Ist nicht für automatisierte Verwendung bestimmt","Muss dem Plan Spec Implement-Workflow entsprechen"],"pt":["Exige direção explícita do usuário ou menção em arquivo de projeto AGENTS.md","Não é destinado para uso automático","Deve aderir ao fluxo de trabalho Plan Spec Implement"],"ru":["Требует явного указания пользователя или упоминания в файле проекта AGENTS.md","Не предназначен для автоматического использования","Должен следовать рабочему процессу Plan Spec Implement"],"ar":["يتطلب توجيهًا صريحًا من المستخدم أو ذكرًا في ملف مشروع AGENTS.md","لا يتم استخدامه تلقائيًا","يجب اتباع تدفق العمل Plan Spec Implement"]},"version":4},"contentHash":"b9e814607af13fc53b0c340de10be60ca2249b5482529d3ed30bbc3a7086b4ca","qualityScore":41}');
